    const normalizedIds = new Set(uniqueIds.map(normalizeText));
    const isSelectedId = value => normalizedIds.has(normalizeText(value));
    const labelMap = {
      kelas: "kelas",
      jurusan: "jurusan",
      guru: "guru",
