      Karyawan: "karyawan",
      mapel: "mapel",
      ruangan: "ruangan",
      beban: "beban"
    };
    if (!Object.prototype.hasOwnProperty.call(labelMap, type)) {
      showNotification("Jenis data ini belum didukung untuk hapus massal.", "error");
      return;
    }
    if (options.confirm !== false) {
