/**
 * AdminMobileNav — Fixed bottom navigation bar untuk layar kecil.
 * Extracted dari AdminApp.jsx untuk mengurangi ukuran file utama.
 */
export default function AdminMobileNav({
  activeTab,
  setActiveTab,
  activeUserRole,
  activeUserDivision,
  currentUser,
  hasFeature,
  isMobileMenuOpen,
  setIsMobileMenuOpen,
  hasPiket,
}) {
  const getTabColorConfig = () => ({
    activeColor: 'text-primary',
    activeBg: 'bg-primary/10',
    iconColor: 'var(--ui-primary)',
  });

  const isMenuOpen = isMobileMenuOpen;

  const getRoleTabs = () => {
    if (activeUserRole === 'guru') {
      const tabs = [
        { id: 'generate',          icon: Calendar,      label: 'Jadwal' },
      ];
      tabs.push({ id: 'jurnal_harian', icon: BookOpen, label: 'Jurnal' });
      tabs.push(
        currentUser?.isWalas
          ? { id: 'walas_report', icon: FileText,  label: 'Laporan' }
          : { id: 'modul_ajar',  icon: BookOpen,  label: 'Modul Ajar', featureKey: 'teacherSyllabus' }
      );
      tabs.push({ id: 'absensiguru', icon: CheckCircle2, label: 'Absen', featureKey: 'attendance' });
      return tabs;
    }

    if (activeUserRole === 'tu' || activeUserRole === 'tata_usaha') {
      return [
        { id: 'siswa',    icon: GraduationCap, label: 'Siswa' },
        { id: 'guru',     icon: Users,         label: 'Guru' },
        { id: 'karyawan', icon: Briefcase,      label: 'Karyawan' },
      ];
    }

    if (activeUserRole === 'karyawan') {
      return [{ id: 'absensiguru', icon: CheckCircle2, label: 'Absen', featureKey: 'attendance' }];
    }

    if (activeUserRole === 'kepsek') {
      return [
        { id: 'generate',      icon: Calendar, label: 'Jadwal' },
        { id: 'pkl_dashboard', icon: Briefcase, label: 'PKL', featureKey: 'pkl_dashboard' },
      ];
    }

    if (activeUserRole === 'waka') {
      if (activeUserDivision === 'hubin') {
        return [
          { id: 'pkl_dashboard',       icon: Briefcase,  label: 'PKL',  featureKey: 'pkl_dashboard' },
          { id: 'pkl_data_perusahaan', icon: Building2,  label: 'DUDI' },
        ];
      }
      if (activeUserDivision === 'kesiswaan') {
        return [
          { id: 'absensi',             icon: CheckCircle2, label: 'Rekap Absensi' },
          { id: 'kedisiplinan_piket',  icon: UserPlus,     label: 'Jadwal Piket' },
        ];
      }
      return [
        { id: 'generate', icon: Calendar,     label: 'Jadwal' },
        { id: 'guru',     icon: BookOpenText, label: 'Guru' },
      ];
    }

    if (isSuperAdminRole(activeUserRole)) {
      return [
        { id: 'siswa', icon: Users,        label: 'Siswa' },
        { id: 'guru',  icon: BookOpenText, label: 'Guru' },
      ];
    }

    return [];
  };

  const allTabs = [
    { id: 'dashboard', icon: LayoutDashboard, label: 'Beranda' },
    ...getRoleTabs(),
  ].filter(tab => !tab.featureKey || hasFeature(tab.featureKey));

  return (
    <div className="lg:hidden fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-slate-100 flex justify-around items-center px-2 py-2 shadow-[0_-4px_20px_-4px_rgba(0,0,0,0.06)] z-40 w-full overflow-hidden pb-[calc(8px+env(safe-area-inset-bottom))]">
      {allTabs.map(tab => {
        const isActive = activeTab === tab.id;
        const config = getTabColorConfig(tab.id);
        return (
          <button
            key={tab.id}
            onClick={() => {
              setActiveTab(tab.id);
              if (tab.id !== 'dashboard') setIsMobileMenuOpen(false);
            }}
            className={`flex-1 flex flex-col items-center justify-center h-11 gap-0.5 rounded-xl transition-all duration-200 border-none cursor-pointer bg-transparent px-1 min-w-0 ${
              isActive ? `${config.activeColor} scale-105` : 'text-slate-400 hover:text-slate-600'
            }`}
          >
            <div className={`p-1.5 rounded-xl transition-all duration-200 ${
              isActive ? `${config.activeBg} shadow-sm scale-110` : 'bg-transparent hover:bg-slate-50'
            }`}>
              <tab.icon
                size={18}
                style={{ color: isActive ? config.iconColor : 'inherit' }}
                className={`shrink-0 ${isActive ? 'stroke-[2.5]' : 'stroke-[2]'}`}
              />
            </div>
            <span className={`text-[8.5px] font-black tracking-tight truncate w-full text-center ${
              isActive ? 'opacity-100 font-black' : 'opacity-60 font-semibold'
            }`}>
              {tab.label}
            </span>
          </button>
        );
      })}

      {activeUserRole !== 'guru' && (
        <button
          onClick={() => setIsMobileMenuOpen(!isMenuOpen)}
          className={`flex-1 flex flex-col items-center justify-center h-11 gap-0.5 rounded-xl transition-all duration-200 border-none cursor-pointer bg-transparent px-1 min-w-0 ${
            isMenuOpen ? 'text-primary scale-105 font-bold' : 'text-slate-400 hover:text-slate-600'
          }`}
        >
          <div className={`p-1.5 rounded-xl transition-all duration-200 ${
            isMenuOpen ? 'bg-primary/10 shadow-sm scale-110' : 'bg-transparent hover:bg-slate-50'
          }`}>
            <MoreVertical
              size={18}
              style={{ color: isMenuOpen ? 'var(--ui-primary)' : 'inherit' }}
              className={`shrink-0 ${isMenuOpen ? 'stroke-[2.5]' : 'stroke-[2]'}`}
            />
          </div>
          <span className={`text-[8.5px] font-black tracking-tight truncate w-full text-center ${
            isMenuOpen ? 'opacity-100 font-black' : 'opacity-60 font-semibold'
          }`}>
            Menu
          </span>
        </button>
      )}
    </div>
  );
}

import React, { useRef, useState, useEffect } from 'react';
import { cn } from '@/lib/utils';
import { Calendar, CalendarDays, Users, BookOpen, LayoutDashboard, Settings, MessageSquare, History, SlidersHorizontal, Clock, FileText, FileSpreadsheet, DoorOpen, User, UserPlus, AppWindow, PieChart, Wand2, MonitorSmartphone, CheckCircle2, FolderOpen, Phone, Briefcase, Shield, ShieldAlert, Activity, HardDrive, GraduationCap, Building2, DatabaseBackup, UserCog, ClipboardList, Trophy, UserMinus } from 'lucide-react';
import { ChevronDown, X, RefreshCw, LogOut } from 'lucide-react';


export default function AdminSidebar({
  isMobileMenuOpen, setIsMobileMenuOpen,
  isSidebarCollapsed, toggleSidebar,
  appSettings, currentUser, uiFontClass,
  activeTab, setActiveTab,
  renderNavItem,
  hasAnyConfigAccess,
  handleLogout,
  expandedGroups,
  toggleGroup,
  isSuperAdminRole,
  activeUserRole,
  handleBackupExport,
  isBackingUp,
  sidebarScrollRef,
  sidebarScrollPos
}) {

  const isCollapsed = isSidebarCollapsed && !isMobileMenuOpen;
  const fallbackScrollRef = useRef(null);
  const fallbackScrollPos = useRef(0);
  const refToUse = sidebarScrollRef || fallbackScrollRef;
  const posToUse = sidebarScrollPos || fallbackScrollPos;
  const [hasPiket, setHasPiket] = useState(false);

  // Restore scroll position on mount
  useEffect(() => {
    const savedPos = sessionStorage.getItem("admin_sidebar_scroll_top");
    if (savedPos && refToUse.current) {
      refToUse.current.scrollTop = parseInt(savedPos, 10);
    }
  }, [refToUse]);

  // Scroll active item into view on mount or tab change
  useEffect(() => {
    if (refToUse.current) {
      const timer = setTimeout(() => {
        if (!refToUse.current) return;
        const activeEl = refToUse.current.querySelector(".bg-primary\\/10, .bg-accent\\/15");
        if (activeEl) {
          activeEl.scrollIntoView({ block: "nearest", behavior: "smooth" });
        }
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [activeTab, refToUse]);

  useEffect(() => {
    if (activeUserRole === "guru" && (currentUser?.code || currentUser?.id)) {
      const storageSession = localStorage.getItem('school_schedule_session_v1') || sessionStorage.getItem('school_schedule_session_v1');
      if (storageSession) {
        try {
          const session = JSON.parse(storageSession);
          const authToken = session?.authToken;
          if (authToken) {
            const controller = new AbortController();
            fetch('/api/kedisiplinan/jadwal', {
              headers: { 'Authorization': `Bearer ${authToken}` },
              signal: controller.signal
            })
            .then(r => r.json())
            .then(res => {
              if (res.ok && Array.isArray(res.data)) {
                const teacherCode = currentUser.code || currentUser.id;
                const hasSched = res.data.some(s => {
                  let ids = s.guru_ids;
                  if (typeof ids === "string") {
                    try { ids = JSON.parse(ids); } catch { }
                  }
                  return Array.isArray(ids) && ids.some(id => String(id).trim().toLowerCase() === String(teacherCode).trim().toLowerCase());
                });
                setHasPiket(hasSched);
              }
            })
            .catch(err => { if (err.name !== 'AbortError') console.error(err); });
            return () => controller.abort();
          }
        } catch (e) {
          console.error(e);
        }
      }
    }
  }, [activeUserRole, currentUser]);


  const activeUserDivision = (currentUser?.division || "kurikulum").toLowerCase();
  const SidebarSection = ({ label }) => {
    if (isCollapsed) return null;
    return (
      <div className="mt-2.5 mb-1 px-3 flex items-center">
        <span className="text-[9px] font-semibold text-muted-foreground uppercase tracking-[0.15em]">
          {label}
        </span>
      </div>
    );
  };

  const SidebarGroup = ({ label, icon: Icon, isOpen, onToggle, children }) => {
    return (
      <div className="mb-1 w-full">
        <button
          onClick={onToggle}
          type="button"
          className={cn(
            "group relative mb-1 flex w-full items-center justify-between rounded-md border-none",
            "px-2.5 py-1.5 text-xs font-semibold text-muted-foreground transition-all cursor-pointer",
            "hover:bg-muted hover:text-foreground"
          )}
        >
          <div className="flex items-center gap-2.5">
            {Icon && <Icon size={15} className="text-muted-foreground group-hover:text-foreground transition-colors" />}
            <span>{label}</span>
          </div>
          <ChevronDown
            size={14}
            className={cn("text-muted-foreground group-hover:text-foreground transition-transform duration-200", isOpen ? "rotate-0" : "-rotate-90")}
          />
        </button>
        <div
          className="overflow-hidden transition-[max-height,opacity,margin] duration-300 ease-in-out ml-5.5 pl-3 border-l border-slate-200/60 flex flex-col gap-1 sidebar-submenus"
          style={{
            maxHeight: isOpen ? "1000px" : "0px",
            opacity: isOpen ? 1 : 0,
            pointerEvents: isOpen ? "auto" : "none",
            marginTop: isOpen ? "2px" : "0px",
            marginBottom: isOpen ? "2px" : "0px",
          }}
        >
          {React.Children.map(children, (child) => {
            if (React.isValidElement(child)) {
              return React.cloneElement(child, { isSubMenu: true });
            }
            return child;
          })}
        </div>
      </div>
    );
  };

  return (
    <aside
      className={cn(
