                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">Default: {div.label}</label>
                    <input 
                      type="text" 
                      value={formData[key] || div.label} 
                      onChange={(e) => setFormData({ ...formData, [key]: e.target.value })} 
                      placeholder={div.label}
                      className="w-full border-none bg-slate-50 p-3.5 rounded-[var(--ui-radius-small)] text-sm font-bold focus:bg-white focus:outline-[var(--ui-primary)]" 
                    />
                  </div>
                );
              })}
            </div>
          )}
          {modalConfig.type === "waktu" && (
            <>
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">Pengaturan Jam Pelajaran Pintar</label>
                {(() => {
                  const labelParts = (formData.label || "07.00 - 00.00").split(" - ");
                  const sTime = (labelParts[0]?.trim() || "").replace('.', ':');
                  const eTime = (labelParts[1]?.trim() || "").replace('.', ':');
                  const jpCount = formData.jpCount || 1;
                  const minsPerJp = formData.minsPerJp || 45;

                  const handleAutoCalc = (start, jp, mins) => {
                    if (!start || start.length !== 5) return start;
                    const [h, m] = start.split(':').map(Number);
                    const totalMins = h * 60 + m + (jp * mins);
                    const newH = Math.floor(totalMins / 60) % 24;
                    const newM = totalMins % 60;
                    return `${String(newH).padStart(2, '0')}:${String(newM).padStart(2, '0')}`;
                  };
                  return (
                    <div className="space-y-4">
                      {!formData.isBreak && (
                        <div className="grid grid-cols-2 gap-4 bg-[var(--ui-accent)]/10 p-4 rounded-[var(--ui-radius-small)] border border-[var(--ui-accent)]/20">
                           <div>
                             <label className="text-[10px] font-black text-[var(--ui-primary)] uppercase block mb-1">Jumlah JP</label>
                             <input type="text" inputMode="numeric" value={jpCount} onChange={(e) => {
                               const newVal = parseInt(e.target.value.replace(/[^0-9]/g, '')) || 1;
                               const newEnd = handleAutoCalc(sTime, newVal, minsPerJp);
                               setFormData({ ...formData, jpCount: newVal, label: `${sTime.replace(':', '.')} - ${newEnd.replace(':', '.')}` });
                             }} className="w-full border border-[var(--ui-primary)]/20 bg-white p-2 rounded-[var(--ui-radius-small)] text-sm font-bold text-center" />
                           </div>
                           <div>
                             <label className="text-[10px] font-black text-[var(--ui-primary)] uppercase block mb-1">Menit per JP</label>
                             <input type="text" inputMode="numeric" value={minsPerJp} onChange={(e) => {
                               const newVal = parseInt(e.target.value.replace(/[^0-9]/g, '')) || 45;
                               const newEnd = handleAutoCalc(sTime, jpCount, newVal);
                               setFormData({ ...formData, minsPerJp: newVal, label: `${sTime.replace(':', '.')} - ${newEnd.replace(':', '.')}` });
                             }} className="w-full border border-[var(--ui-primary)]/20 bg-white p-2 rounded-[var(--ui-radius-small)] text-sm font-bold text-center" />
                           </div>
                        </div>
                      )}

                      <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-[var(--ui-radius-small)] border-none">
                        <input 
                          type="time" 
                          value={sTime.length === 5 ? sTime : ""} 
                          onChange={(ev) => {
                            const newStart = ev.target.value;
                            const newEnd = formData.isBreak ? eTime : handleAutoCalc(newStart, jpCount, minsPerJp);
                            setFormData({ ...formData, label: `${newStart.replace(':', '.')} - ${newEnd.replace(':', '.')}` });
                          }}
                          className="p-3 border-none rounded-[var(--ui-radius-small)] text-sm font-bold flex-1 focus:bg-white"
                          required={!formData.isBreak}
                        />
                        <span className="font-bold text-slate-400">-</span>
                        <input 
                          type="time" 
                          value={eTime.length === 5 ? eTime : ""} 
                          onChange={(ev) => setFormData({ ...formData, label: `${sTime.replace(':', '.')} - ${ev.target.value.replace(':', '.')}` })}
                          className="p-3 border-none rounded-[var(--ui-radius-small)] text-sm font-bold flex-1 focus:bg-white"
                          required={!formData.isBreak}
                        />
                      </div>
                    </div>
                  );
                })()}
              </div>
              <div className="flex items-center gap-3 bg-orange-50 p-4 border border-orange-100 rounded-[var(--ui-radius-small)] cursor-pointer"><input type="checkbox" id="break" checked={formData.isBreak || false} onChange={(e) => setFormData({ ...formData, isBreak: e.target.checked })} className="w-5 h-5 accent-orange-600 cursor-pointer" /><label htmlFor="break" className="text-sm font-bold text-orange-900 cursor-pointer">Tandai Sebagai Kegiatan / Non-Pelajaran</label></div>
              {formData.isBreak && (<div><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">Nama Kegiatan Opsional</label><input type="text" value={formData.labelBreak || ""} onChange={(e) => setFormData({ ...formData, labelBreak: e.target.value })} className="w-full border-none bg-slate-50 p-3.5 rounded-[var(--ui-radius-small)] text-sm font-bold focus:bg-white focus:outline-[var(--ui-primary)]" placeholder="Contoh: UPACARA BENDERA / ISTIRAHAT" /></div>)}
            </>
          )}
          <div className="sticky bottom-0 z-20 -mx-3.5 sm:-mx-4 -mb-3.5 sm:-mb-4 mt-5 flex justify-end gap-3 border-t border-slate-200 bg-white/95 px-3.5 sm:px-4 py-3 shadow-[0_-12px_28px_rgba(15,23,42,0.06)] backdrop-blur"><Button type="button" variant="secondary" onClick={closeModal} disabled={isSavingModal}>Batal</Button><Button type="submit" disabled={isClassMajorMismatch || isSavingModal}>{isSavingModal ? "Menyimpan..." : modalConfig.type === "silabus" ? "Simpan Pertemuan" : "Simpan Data"}</Button></div>
        </form>
      </Modal>
    </>
  );
}

import { useState, useEffect } from 'react';
import { ROLE_OPTIONS, normalizeUserRole } from '../../utils/constants.js';
import { MENU_REGISTRY, normalizeText } from '../../utils/adminHelpers.js';
import { Edit2, Trash2 } from 'lucide-react';
import { Modal } from '../ui.jsx';
import { Button } from '../monitoring/ui/index.js';


const CustomRolesModal = ({
  isOpen,
  onClose,
  appSettings,
  setAppSettings,
  showNotification,
  teachers
}) => {
  const [roles, setRoles] = useState(appSettings.customRoles || []);
  const [editingRole, setEditingRole] = useState(null);
  const [formData, setFormData] = useState({
    value: "",
    label: "",
    shortLabel: "",
    description: "",
    permissions: []
  });
  useEffect(() => {
    if (isOpen) {
      setRoles(appSettings.customRoles || []);
      setEditingRole(null);
      setFormData({
        value: "",
        label: "",
        shortLabel: "",
        description: "",
        permissions: []
      });
    }
  }, [isOpen, appSettings.customRoles]);
  const togglePermission = menuId => {
    setFormData(prev => ({
      ...prev,
      permissions: prev.permissions.includes(menuId) ? prev.permissions.filter(id => id !== menuId) : [...prev.permissions, menuId]
    }));
  };
  const handleSave = e => {
    e.preventDefault();
    if (!formData.label || !formData.shortLabel) {
      showNotification("Nama Role dan Singkatan wajib diisi", "warning");
      return;
    }
    const roleValue = formData.value || normalizeText(formData.label).replace(/\s+/g, "_");
    if (ROLE_OPTIONS.some(r => r.value === roleValue)) {
      showNotification("Nama role ini bertabrakan dengan role sistem.", "warning");
      return;
    }
    let newRoles;
    if (editingRole) {
      newRoles = roles.map(r => r.value === editingRole.value ? {
        ...formData,
        value: roleValue
      } : r);
    } else {
      if (roles.some(r => r.value === roleValue)) {
        showNotification("Role ini sudah ada.", "warning");
        return;
      }
      newRoles = [...roles, {
        ...formData,
        value: roleValue,
        badgeClass: "bg-slate-50 text-slate-700 border-slate-200"
      }];
    }
    setRoles(newRoles);
    setAppSettings({
      ...appSettings,
      customRoles: newRoles
    });
    showNotification("Role berhasil disimpan.", "success");
    setEditingRole(null);
    setFormData({
      value: "",
      label: "",
      shortLabel: "",
      description: "",
      permissions: []
    });
  };
  const handleDelete = roleValue => {
    const isUsed = teachers.some(t => normalizeUserRole(t.role) === roleValue);
    if (isUsed) {
      showNotification("Role tidak dapat dihapus karena sedang digunakan oleh pengguna.", "error");
      return;
    }
    const newRoles = roles.filter(r => r.value !== roleValue);
    setRoles(newRoles);
    setAppSettings({
      ...appSettings,
      customRoles: newRoles
    });
    showNotification("Role berhasil dihapus.", "success");
  };
  if (!isOpen) return null;
  return <Modal isOpen={isOpen} onClose={onClose} title="Manajemen Role & Jabatan Tambahan" maxWidth="max-w-4xl">
      <div className="flex flex-col md:flex-row gap-6">
        <div className="flex-1 space-y-4">
          <h3 className="text-sm font-black text-slate-800">
            Daftar Role Custom
          </h3>
          {roles.length === 0 ? <div className="text-xs text-slate-500 bg-slate-50 p-6 rounded-[var(--ui-radius-small)] text-center font-medium border-none">
              Belum ada role tambahan.
              <br />
              Gunakan form di samping untuk membuat role baru.
            </div> : <div className="space-y-3">
              {roles.map(r => <div key={r.value} className="bg-white border-none p-4 rounded-[var(--ui-radius-card)] flex items-center justify-between shadow-sm">
                  <div>
                    <div className="font-black text-sm text-slate-800">
                      {r.label}{" "}
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded-[var(--ui-radius-small)] ml-2">
                        {r.shortLabel}
                      </span>
                    </div>
                    <div className="text-xs text-slate-500 font-medium mt-1">
                      {r.description || "Tidak ada deskripsi"}
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => {
                setEditingRole(r);
                setFormData(r);
              }} className="p-2 text-slate-400 hover:text-[var(--ui-primary)] bg-slate-50 hover:bg-[var(--ui-primary)]/10 rounded-[var(--ui-radius-small)] transition-colors">
                      <Edit2 size={14} />
                    </button>
                    <button onClick={() => handleDelete(r.value)} className="p-2 text-slate-400 hover:text-red-500 bg-slate-50 hover:bg-red-50 rounded-[var(--ui-radius-small)] transition-colors">
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>)}
            </div>}
        </div>
        <div className="w-full md:w-[450px] shrink-0 bg-slate-50/50 p-5 rounded-[var(--ui-radius-small)] border-none flex flex-col max-h-[80vh] overflow-hidden">
          <h3 className="text-sm font-black text-slate-800 mb-4">
            {editingRole ? "Edit Role" : "Tambah Role Baru"}
          </h3>
          <form onSubmit={handleSave} className="flex flex-col h-full gap-4 overflow-hidden">
            <div className="space-y-4 overflow-y-auto custom-scrollbar flex-1 pr-2">
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                  Nama Role / Jabatan
                </label>
                <input type="text" required value={formData.label} onChange={e => setFormData({
                ...formData,
                label: e.target.value
              })} className="w-full border-none bg-white p-3 rounded-[var(--ui-radius-card)] text-sm font-bold focus:outline-[var(--ui-primary)] shadow-sm" placeholder="Misal: Kepala Tata Usaha" />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                  Singkatan / Level
                </label>
                <input type="text" required value={formData.shortLabel} onChange={e => setFormData({
                ...formData,
                shortLabel: e.target.value
              })} className="w-full border-none bg-white p-3 rounded-[var(--ui-radius-card)] text-sm font-bold focus:outline-[var(--ui-primary)] shadow-sm" placeholder="Misal: Level 5" />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                  Deskripsi
                </label>
                <textarea value={formData.description} onChange={e => setFormData({
                ...formData,
                description: e.target.value
              })} className="w-full border-none bg-white p-3 rounded-[var(--ui-radius-card)] text-sm font-medium focus:outline-[var(--ui-primary)] shadow-sm min-h-[60px]" placeholder="Deskripsi hak akses..." />
              </div>

              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-3 block">
                  Hak Akses Menu (Permissions)
                </label>
                <div className="bg-white border-none rounded-[var(--ui-radius-card)] p-3 shadow-sm space-y-4">
                  {Array.from(new Set(MENU_REGISTRY.map(m => m.category))).map(category => <div key={category}>
                      <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2">
                        {category}
                      </div>
                      <div className="grid grid-cols-1 gap-2">
                        {MENU_REGISTRY.filter(m => m.category === category).map(menu => <label key={menu.id} className="flex items-center gap-2 cursor-pointer p-1.5 hover:bg-slate-50 rounded-[var(--ui-radius-small)] transition-colors border-none hover:border-slate-100">
                            <input type="checkbox" className="rounded-[var(--ui-radius-small)] border-slate-300 text-[var(--ui-primary)] focus:ring-[var(--ui-primary)] cursor-pointer" checked={(formData.permissions || []).includes(menu.id)} onChange={() => togglePermission(menu.id)} />
                            <span className="text-xs font-medium text-slate-700">
                              {menu.label}
                            </span>
                          </label>)}
                      </div>
                    </div>)}
                </div>
              </div>
            </div>

            <div className="pt-3 flex gap-3 shrink-0 border-t border-slate-200 bg-slate-50/50 pb-1 mt-1">
              {editingRole && <Button type="button" variant="secondary" onClick={() => {
              setEditingRole(null);
              setFormData({
                value: "",
                label: "",
                shortLabel: "",
                description: "",
                permissions: []
              });
            }} className="flex-1">
                  Batal
                </Button>}
              <Button type="submit" className="flex-1">
                {editingRole ? "Simpan Perubahan" : "Buat Role"}
              </Button>
            </div>
          </form>
        </div>
      </div>
    </Modal>;
};

export default CustomRolesModal;

import { useState, useEffect } from 'react';
import { Clock, Wand2, Lock } from 'lucide-react';
import { Modal } from '../ui.jsx';
import { Button } from '../monitoring/ui/index.js';


export default function SystemModals({
  modalConfig,
  closeModal,
  formData,
  setFormData,
  isSavingModal,
  selectedDaySetting,
  handleGenerateSlots,
  handleSave,
  footerInfoModal,
  closeFooterInfo,
  currentUser,
  showNotification,
  adminUser,
  teachers,
  staffs
}) {
  const [nonAdminPassword, setNonAdminPassword] = useState("");
  const [nonAdminConfirm, setNonAdminConfirm] = useState("");
  const [localSaving, setLocalSaving] = useState(false);
  const [pwError, setPwError] = useState("");

  useEffect(() => {
    if (!modalConfig.isOpen) {
      setNonAdminPassword("");
      setNonAdminConfirm("");
      setPwError("");
    }
  }, [modalConfig.isOpen]);

  useEffect(() => {
    const checkPasswordPolicy = async () => {
      const pw = (modalConfig.type === "admin" || currentUser?.role === "admin") 
        ? (formData.password || "") 
        : nonAdminPassword;

      if (!pw) {
        setPwError("");
        return;
      }

      // 1. Length rule: 6 to 12 characters
      if (pw.length < 6 || pw.length > 12) {
        setPwError("Panjang password harus antara 6 hingga 12 karakter!");
        return;
      }

      // 2. Uniqueness rule: not same as previous
      let currentPasswordHash = "";
      if (currentUser?.role === "admin" || currentUser?.role === "superadmin") {
        currentPasswordHash = adminUser?.password || "";
      } else {
        const matchedTeacher = teachers?.find((t) => t.code === currentUser?.code);
        if (matchedTeacher) {
          currentPasswordHash = matchedTeacher.password || "";
        } else {
          const matchedStaff = staffs?.find((s) => s.code === currentUser?.code);
          if (matchedStaff) {
            currentPasswordHash = matchedStaff.password || "";
          }
        }
      }

      if (currentPasswordHash) {
        try {
          const { verifyPassword } = await import("../../utils/auth.js");
          const isSame = await verifyPassword(pw, currentPasswordHash);
          if (isSame) {
            setPwError("Tidak boleh menggunakan password yang sama dengan sebelumnya!");
            return;
          }
        } catch (err) {
          console.error("Error verifying password hash in real-time:", err);
        }
      }

      setPwError("");
    };

    checkPasswordPolicy();
  }, [formData.password, nonAdminPassword, modalConfig.type, currentUser, adminUser, teachers, staffs]);

  const handleNonAdminSubmit = async (e) => {
    e.preventDefault();
    if (!nonAdminPassword) {
      if (showNotification) showNotification("Kata sandi baru tidak boleh kosong!", "warning");
      return;
    }
    if (nonAdminPassword.length < 6 || nonAdminPassword.length > 12) {
      if (showNotification) showNotification("Panjang password harus antara 6 hingga 12 karakter!", "warning");
      return;
    }
    if (nonAdminPassword !== nonAdminConfirm) {
      if (showNotification) showNotification("Konfirmasi kata sandi tidak cocok!", "warning");
      return;
    }

    setLocalSaving(true);
    try {
      const response = await fetch("/api/auth/change-password", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${currentUser?.authToken}`
        },
        body: JSON.stringify({ newPassword: nonAdminPassword })
      });
      const data = await response.json();
      if (data.ok) {
        if (showNotification) showNotification(data.message || "Kata sandi berhasil diperbarui!", "success");
        setNonAdminPassword("");
        setNonAdminConfirm("");
        closeModal();
      } else {
        if (showNotification) showNotification(data.message || "Gagal memperbarui kata sandi.", "error");
      }
    } catch (err) {
      console.error(err);
      if (showNotification) showNotification("Kesalahan jaringan saat memperbarui kata sandi.", "error");
    }
    setLocalSaving(false);
  };

  return (
    <>
      {/* Modal Auto-Generate Waktu */}
      <Modal
        isOpen={modalConfig.isOpen && modalConfig.type === "generate_slots"}
        onClose={closeModal}
        title={`Generate Waktu Otomatis`}
      >
        <form onSubmit={handleGenerateSlots} className="space-y-5">
          <div className="bg-[var(--ui-accent)]/20 p-4 rounded-[var(--ui-radius-small)] border border-[var(--ui-primary)]/20 mb-2">
            <p className="text-xs font-bold text-[var(--ui-primary)] leading-relaxed">
              Sistem akan membagi jam secara otomatis untuk{" "}
              <span className="uppercase font-black">{selectedDaySetting}</span>{" "}
              berdasarkan pengaturan di bawah ini.
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                Jam Mulai (HH:MM)
              </label>
              <input
                type="time"
                required
                value={formData.startTime || ""}
                onChange={(e) =>
                  setFormData({ ...formData, startTime: e.target.value })
                }
                className="w-full border-none bg-slate-50 p-3.5 rounded-[var(--ui-radius-small)] text-sm font-bold focus:bg-white focus:outline-[var(--ui-primary)]"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                Durasi per JP (Menit)
              </label>
              <input
                type="number"
                min="1"
                required
                value={formData.lessonDuration || ""}
                onChange={(e) =>
                  setFormData({ ...formData, lessonDuration: e.target.value })
                }
                className="w-full border-none bg-slate-50 p-3.5 rounded-[var(--ui-radius-small)] text-sm font-bold focus:bg-white focus:outline-[var(--ui-primary)]"
              />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
              Total Jumlah Jam Pelajaran
            </label>
            <input
              type="number"
              min="1"
              required
              value={formData.totalLessons || ""}
              onChange={(e) =>
                setFormData({ ...formData, totalLessons: e.target.value })
              }
              className="w-full border-none bg-slate-50 p-3.5 rounded-[var(--ui-radius-small)] text-sm font-bold focus:bg-white focus:outline-[var(--ui-primary)]"
            />
          </div>

          <div className="border border-orange-100 bg-orange-50/30 p-4 rounded-[var(--ui-radius-small)] space-y-4">
            <h4 className="text-xs font-black text-orange-800 flex items-center gap-2">
              <Clock size={14} /> Pengaturan Istirahat 1
