        return false;
      }
      const rows = parseBulkTextRows(text, activeTab);
      if (rows.length === 0) {
        showNotification("Tidak ada baris data yang bisa diproses.", "warning");
        return false;
      }
      const requiredColumns = importConfig.requiredColumns || 0;
      let inserted = 0;
