          const map = new Map(prev.map(major => {
            const name = typeof major === 'object' && major !== null ? (major.name || major.payload || '') : String(major || '');
            return [normalizeText(name), name];
          }));
          rows.forEach(row => {
            if (row.length < requiredColumns) {
              skipped++;
              return;
            }
            const name = String(row[0] || "").trim();
            if (!name) {
              skipped++;
              return;
            }
