            </thead>
            <tbody className="divide-y divide-red-100 text-red-800">
              {generationFailures.map(failure => <tr key={failure.id} className="align-top">
                <td className="px-3 py-2 font-semibold whitespace-nowrap">
                  <div>{failure.className}</div>
