  const handleDragStart = (e, sourceDay, sourceSlotId, sourceClass) => {
    e.dataTransfer.setData("application/json", JSON.stringify({
      sourceDay,
      sourceSlotId,
      sourceClass
    }));
  };
  const handleDragOver = e => {
