  const applyThemePreset = preset => {
    const nextSettings = {
      ...appSettings,
      primaryColor: preset.primaryColor,
      accentColor: preset.accentColor,
      primaryButtonColor: preset.primaryButtonColor,
      actionButtonColor: preset.actionButtonColor,
