  const {
    activeTab,
    getTabPermissionLevel,
    activeUserRole,
    getActiveSortConfig,
    selectedRows,
    getSearchTextForTab,
    searchTerm,
    getTableSort,
    itemsPerPage,
    tablePage,
    getRowKeyForTab,
    tabSubtitles,
    setSearchTerm,
    setTablePage,
    handleSelectAll,
    handleSort,
    renderTableFilters,
    handleBulkDelete,
    setShowImportModal,
    openModal,
    deletedHistory,
    undoLastDelete,
    handleResetRuangan,
    setItemsPerPage,
    setTableSorts,
    updateSelectionForTab
  } = context;

  const [showRowsDropdown, setShowRowsDropdown] = React.useState(false);
  const [tableFilters, setTableFilters] = React.useState({});


  const renderTable = (title, columns, data, renderRow, options = {}) => {
    const permLevel = getTabPermissionLevel(options.tabKey || activeTab);
    const isViewOnly = permLevel === "view" || (permLevel === "otomatis" && activeUserRole === "kepsek");
    const tabKey = options.tabKey || activeTab;

    // Dynamic Filter lists & application
    const activeFilters = TAB_FILTER_KEYS[tabKey] || [];
    const getFilterValues = (filterKey, altKeys = []) => {
      const values = new Set();
      data.forEach(item => {
        let val = item[filterKey];
        if (val === undefined && altKeys) {
          for (const alt of altKeys) {
            if (item[alt] !== undefined) {
              val = item[alt];
              break;
            }
          }
        }
        if (val) {
          String(val).split(",").map(v => v.trim()).filter(Boolean).forEach(v => values.add(v));
        }
      });
      return ["Semua", ...Array.from(values).sort()];
    };

    let processedData = data;
    activeFilters.forEach(f => {
      const selectedValue = tableFilters[`${tabKey}_${f.key}`] || "Semua";
      if (selectedValue !== "Semua") {
        processedData = processedData.filter(item => {
          let val = item[f.key];
          if (val === undefined && f.altKeys) {
            for (const alt of f.altKeys) {
              if (item[alt] !== undefined) {
                val = item[alt];
                break;
              }
            }
          }
          if (!val) return false;
          const itemValues = String(val).split(",").map(v => v.trim().toLowerCase());
          return itemValues.includes(selectedValue.toLowerCase());
        });
      }
    });

    const sortOptions = options.sortOptions || TABLE_SORT_OPTIONS[tabKey] || [];
    const sortConfig = getActiveSortConfig(tabKey);
    const selectedKeys = selectedRows[tabKey] || [];
    const filteredData = processedData.filter(item => normalizeText(getSearchTextForTab(tabKey, item)).includes(normalizeText(searchTerm)));
    const sortedData = getTableSort(tabKey, filteredData);

    // Pagination
    const ITEMS_PER_PAGE = itemsPerPage;
    const totalPages = Math.ceil(sortedData.length / ITEMS_PER_PAGE);
    const safeTablePage = Math.max(1, Math.min(tablePage, totalPages || 1));
    const paginatedData = sortedData.slice((safeTablePage - 1) * ITEMS_PER_PAGE, safeTablePage * ITEMS_PER_PAGE);
    const visibleKeys = paginatedData.map(item => getRowKeyForTab(tabKey, item));
    const allVisibleSelected = visibleKeys.length > 0 && visibleKeys.every(key => selectedKeys.includes(key));
    const selectedCount = selectedKeys.length;
    const actualPageHeader = options.pageHeader || null;

    return (
      <div className="flex flex-col gap-4 w-full animate-in fade-in duration-300 relative z-10">
        {actualPageHeader}
        <section className="rounded-xl bg-card ring-1 ring-foreground/10 flex flex-col flex-1 overflow-hidden">
          {options.customTabs && (
            <div className="px-4 pt-4 pb-2 border-b border-border bg-muted/30">
              {options.customTabs}
            </div>
          )}

          {/* Toolbar */}
          <div className="p-3 md:p-4 border-b border-border bg-card/90 shrink-0">
            <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-3">
              <div className="text-xs font-medium text-muted-foreground shrink-0">
                <span className="font-semibold text-foreground">{filteredData.length}</span> dari {data.length} data tampil
                {selectedCount > 0 && (
                  <Badge variant="secondary" className="ml-2">{selectedCount} dipilih</Badge>
                )}
              </div>

              <div className="grid grid-cols-2 sm:flex sm:flex-wrap items-center gap-2 w-full xl:w-auto">
                {sortOptions.length > 0 && (
                  <div className="col-span-2 sm:col-span-1 flex items-center gap-1.5">
                    <UISelect
                      prefix="Sort: "
                      value={sortConfig.key}
                      onChange={e => setTableSorts(prev => ({
                        ...prev,
                        [tabKey]: { ...(prev[tabKey] || DEFAULT_TABLE_SORTS[tabKey]), key: e.target.value }
                      }))}
                    >
                      {sortOptions.map(option => (
                        <option key={option.value} value={option.value}>{option.label}</option>
                      ))}
                    </UISelect>
                    <Button
                      type="button"
                      variant="outline"
                      size="icon"
                      onClick={() => setTableSorts(prev => ({
                        ...prev,
                        [tabKey]: { ...(prev[tabKey] || DEFAULT_TABLE_SORTS[tabKey]), dir: sortConfig.dir === "asc" ? "desc" : "asc" }
                      }))}
                      title={sortConfig.dir === "asc" ? "Urutan A-Z" : "Urutan Z-A"}
                    >
                      <ArrowUpDown size={13} />
                    </Button>
                  </div>
                )}

                {/* Dynamic Filters */}
                {activeFilters.map(f => {
                  const optionsList = getFilterValues(f.key, f.altKeys);
                  if (optionsList.length <= 1) return null;
                  const currentValue = tableFilters[`${tabKey}_${f.key}`] || "Semua";
                  return (
                    <div key={f.key} className="col-span-2 sm:col-span-1 flex items-center gap-1.5">
                      <UISelect
                        prefix={`${f.label}: `}
                        value={currentValue}
                        onChange={e => {
                          setTableFilters(prev => ({
                            ...prev,
                            [`${tabKey}_${f.key}`]: e.target.value
                          }));
                          setTablePage(1);
                        }}
                      >
                        {optionsList.map(opt => (
                          <option key={opt} value={opt}>{opt}</option>
                        ))}
                      </UISelect>
                    </div>
                  );
                })}

                {options.customHeaderButtons}

                {!isViewOnly && (
                  <Button variant="outline" size="sm" onClick={() => openModal("bulk", "add")} className="text-xs hidden sm:flex gap-1.5">
                    <Upload size={13} /> Import Teks
                  </Button>
                )}

                {deletedHistory.length > 0 && (
                  <Button variant="outline" size="sm" onClick={undoLastDelete} className="text-xs gap-1.5">
                    <History size={13} /> Undo Hapus
                  </Button>
                )}

                {selectedCount > 0 && !isViewOnly && (
                  <Button variant="destructive" size="sm" onClick={() => handleBulkDelete(tabKey, selectedKeys)} className="text-xs gap-1.5">
                    <Trash2 size={13} /> Hapus ({selectedCount})
                  </Button>
                )}

                {tabKey === "ruangan" && (
                  <Button variant="destructive" size="sm" onClick={handleResetRuangan} className="text-xs gap-1.5">
                    <Trash2 size={13} /> Kosongkan Semua
                  </Button>
                )}

                {!isViewOnly && (
                  <Button size="sm" onClick={() => openModal(tabKey, "add")} className="text-xs gap-1.5">
                    <Plus size={13} strokeWidth={2.5} /> Tambah
                  </Button>
                )}
              </div>
            </div>
            {/* Search */}
            <div className="mt-3">
              <div className="relative w-full">
                <Search size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
                <input
                  type="text"
                  placeholder={`Cari ${title.toLowerCase()}...`}
                  value={searchTerm}
                  onChange={e => { setSearchTerm(e.target.value); setTablePage(1); }}
                  className={cn(
                    "h-7 w-full min-w-0 rounded-md border border-input bg-input/20 pl-8 pr-3 py-0.5 text-xs",
                    "transition-colors outline-none placeholder:text-muted-foreground font-medium",
                    "focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/30"
                  )}
                />
              </div>
            </div>
          </div>

          {/* Table */}
          <div className="overflow-x-auto flex-1">
            <Table>
              <TableHeader className="bg-muted/50 sticky top-0 z-10">
                <TableRow className="border-border">
                  <TableHead className="w-10 text-center px-3">
                    <input
                      type="checkbox"
                      checked={allVisibleSelected}
                      onChange={e => updateSelectionForTab(tabKey, current => {
                        const currentSet = new Set(current);
                        if (e.target.checked) {
                          visibleKeys.forEach(key => currentSet.add(key));
                        } else {
                          visibleKeys.forEach(key => currentSet.delete(key));
                        }
                        return [...currentSet];
                      })}
                      className="accent-primary cursor-pointer w-3.5 h-3.5"
                      aria-label={`Pilih semua ${tabKey} yang tampil`}
                    />
                  </TableHead>
                  <TableHead className="w-10 text-center text-[10px] font-semibold text-muted-foreground uppercase tracking-wider px-3">
                    No
                  </TableHead>
                  {columns.map((col, idx) => {
                    const name = String(col).toLowerCase();
                    let alignClass = "text-left";
                    if (
                      name.includes("kode") || 
                      name.includes("nis") || 
                      name.includes("wali") || 
                      name.includes("jp") || 
                      name.includes("alat") || 
                      name.includes("status") || 
                      name.includes("hari") || 
                      name.includes("jam") ||
                      name.includes("lantai")
                    ) {
                      alignClass = "text-center";
                    }
                    return (
                      <TableHead key={idx} className={cn("text-[10px] font-semibold text-muted-foreground uppercase tracking-wider px-3", alignClass)}>
                        {col}
                      </TableHead>
                    );
                  })}
                  <TableHead className="text-right text-[10px] font-semibold text-muted-foreground uppercase tracking-wider px-3">
                    Aksi
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {sortedData.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={columns.length + 3} className="px-6 py-14 text-center">
                      <Search size={22} className="mx-auto mb-2 text-muted-foreground/40" />
                      <p className="text-sm font-semibold text-foreground">Tidak ada data yang cocok.</p>
                      <p className="mt-1 text-xs text-muted-foreground">Coba ubah kata pencarian atau tambah data baru.</p>
                    </TableCell>
                  </TableRow>
                ) : (
                  paginatedData.map((item, idx) => renderRow(item, idx, selectedKeys.includes(getRowKeyForTab(tabKey, item))))
                )}
              </TableBody>
            </Table>
          </div>

          {/* Pagination — always visible */}
          <div className="p-2.5 border-t border-border bg-muted/20 flex items-center justify-between shrink-0 flex-wrap gap-2">
              <div className="flex items-center gap-2">
                <span className="text-[11px] text-muted-foreground font-medium">
                  {sortedData.length === 0 ? 0 : (safeTablePage - 1) * ITEMS_PER_PAGE + 1}–{Math.min(safeTablePage * ITEMS_PER_PAGE, sortedData.length)} dari {sortedData.length}
                </span>
                <div className="relative inline-block text-left">
                  <button
                    type="button"
                    onClick={() => setShowRowsDropdown(!showRowsDropdown)}
                    className="h-6 rounded-lg border border-border bg-card px-2 text-[11px] font-bold text-slate-700 hover:bg-slate-50 transition-all flex items-center gap-1 cursor-pointer select-none"
                  >
                    <span>{itemsPerPage} baris</span>
                    <span className="text-[8px] text-slate-400">▼</span>
                  </button>

                  {showRowsDropdown && (
                    <>
                      <div 
                        className="fixed inset-0 z-40 bg-transparent" 
                        onClick={() => setShowRowsDropdown(false)}
                      />
                      <div className="absolute left-0 bottom-7 min-w-[90px] bg-card border border-slate-200/60 shadow-lg rounded-xl p-1 z-50 flex flex-col gap-0.5 animate-in fade-in slide-in-from-bottom-1 duration-150">
                        {[20, 50, 100].map(val => (
                          <button
                            key={val}
                            type="button"
                            onClick={() => {
                              setItemsPerPage(val);
                              setTablePage(1);
                              setShowRowsDropdown(false);
                            }}
                            className={cn(
                              "w-full text-left px-2.5 py-1.5 rounded-lg text-[10px] font-bold transition-colors cursor-pointer",
                              itemsPerPage === val 
                                ? "bg-primary text-white" 
                                : "text-slate-600 hover:bg-slate-50 hover:text-slate-800"
                            )}
                          >
                            {val} baris
                          </button>
                        ))}
                      </div>
                    </>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-1.5">
                <Button
                  variant="outline"
                  size="icon-sm"
                  onClick={() => setTablePage(p => Math.max(1, p - 1))}
                  disabled={safeTablePage === 1}
                >
                  <ChevronLeft size={13} />
                </Button>
                <span className="text-[11px] font-medium text-muted-foreground px-2">
                  {safeTablePage} / {totalPages}
                </span>
                <Button
                  variant="outline"
                  size="icon-sm"
                  onClick={() => setTablePage(p => Math.min(totalPages, p + 1))}
                  disabled={safeTablePage === totalPages}
                >
                  <ChevronRight size={13} />
                </Button>
              </div>
            </div>
        </section>
      </div>
    );
  };

  return { renderTable };
}

import { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { Link } from 'react-router-dom';
import { LogIn, X, Menu, HelpCircle, Info, MessageSquare, Mail, BookOpen } from 'lucide-react';


export default function HeaderNavbar({ setIsLoginModalOpen, appSettings, schoolProfile, onPanduanClick }) {
  const location = useLocation();
  const [scrolled, setScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [activeLang, setActiveLang] = useState('ID');

  // Modal states
  const [isBantuanOpen, setIsBantuanOpen] = useState(false);
  const [isPanduanOpen, setIsPanduanOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    // Check initial scroll state immediately
    handleScroll();
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { to: '/', label: 'Beranda' },
    { to: '#bantuan', label: 'Bantuan', isBantuan: true },
    { to: '#panduan', label: 'Panduan', isPanduan: true },
  ];

  // Resolve dynamic settings
  const logoUrl = appSettings?.logoWebUrl || schoolProfile?.logo_url || appSettings?.logoUrl;
  const logoText = appSettings?.logoText || 'TS';
  const appName = appSettings?.appName || 'Sistem Akademik';

  // Fallback to reactive props directly, ensuring exact sync
  const primaryColor = appSettings?.primaryColor || '#064e3b';
  const surfaceColor = appSettings?.surfaceColor || appSettings?.bgColor || '#ffffff';
  const contactEmail = appSettings?.contactEmail || 'admin@school.sch.id';
  const contactPhone = appSettings?.contactPhone || '+62 123-456-789';

  // Helper to convert hex to rgba for maximum browser compatibility without color-mix
  const hexToRgba = (hexColor, alpha = 1) => {
    try {
      const cleanHex = String(hexColor).replace('#', '').trim();
      if (cleanHex.length === 3) {
        const r = parseInt(cleanHex[0] + cleanHex[0], 16);
        const g = parseInt(cleanHex[1] + cleanHex[1], 16);
        const b = parseInt(cleanHex[2] + cleanHex[2], 16);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
      } else if (cleanHex.length === 6) {
        const r = parseInt(cleanHex.slice(0, 2), 16);
        const g = parseInt(cleanHex.slice(2, 4), 16);
        const b = parseInt(cleanHex.slice(4, 6), 16);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
      }
    } catch (e) {
      console.warn("Gagal parse hex color", hexColor, e);
    }
    return hexColor;
  };

  // Format WhatsApp number
  const getWaLink = () => {
    const cleanPhone = String(contactPhone).replace(/\D/g, '');
    const waNumber = cleanPhone.startsWith('0') ? '62' + cleanPhone.slice(1) : cleanPhone;
    return `https://wa.me/${waNumber}?text=Halo%20Admin%2C%20saya%20butuh%20bantuan%20terkait%20aplikasi%20${encodeURIComponent(appName)}...`;
  };

  const getAbsoluteUrl = (url) => {
    if (!url) return '';
    const trimmed = String(url).trim();
    if (/^https?:\/\//i.test(trimmed)) {
      return trimmed;
    }
    return `https://${trimmed}`;
  };

  // Indo Flag Component (Red-White)
  const IndoFlag = () => (
    <div 
      onClick={() => setActiveLang('ID')}
      className={`w-7 h-[18px] rounded-[3px] overflow-hidden border flex flex-col cursor-pointer transition-all duration-200 ${
        activeLang === 'ID' 
          ? 'scale-105 border-transparent shadow-md' 
          : 'border-slate-200 opacity-60 hover:opacity-100'
      }`}
      style={{
        boxShadow: activeLang === 'ID' 
          ? `0 0 0 2px ${scrolled ? surfaceColor : primaryColor}` 
          : 'none'
      }}
      title="Bahasa Indonesia"
    >
      <div className="bg-[#EF4444] h-1/2 w-full"></div>
      <div className="bg-white h-1/2 w-full"></div>
    </div>
  );

  // UK Flag Component (Union Jack SVG)
  const UKFlag = () => (
    <svg 
      onClick={() => setActiveLang('EN')}
      viewBox="0 0 60 30" 
      className={`w-7 h-[18px] rounded-[3px] overflow-hidden border cursor-pointer transition-all duration-200 ${
        activeLang === 'EN' 
          ? 'scale-105 border-transparent shadow-md' 
          : 'border-slate-200 opacity-60 hover:opacity-100'
      }`}
      style={{
        boxShadow: activeLang === 'EN' 
          ? `0 0 0 2px ${scrolled ? surfaceColor : primaryColor}` 
          : 'none'
      }}
      title="English"
    >
      <rect width="60" height="30" fill="#012169"/>
      <path d="M0,0 L60,30 M60,0 L0,30" stroke="#fff" strokeWidth="6"/>
      <path d="M0,0 L60,30 M60,0 L0,30" stroke="#C8102E" strokeWidth="4"/>
      <path d="M30,0 L30,30 M0,15 L60,15" stroke="#fff" strokeWidth="10"/>
      <path d="M30,0 L30,30 M0,15 L60,15" stroke="#C8102E" strokeWidth="6"/>
    </svg>
  );

  const handleLinkClick = (e, link) => {
    if (link.isBantuan || link.isPanduan) {
      e.preventDefault();
      if (link.isBantuan) {
        setIsBantuanOpen(true);
      } else if (link.isPanduan) {
        setIsPanduanOpen(true);
      }
    }
    setMobileMenuOpen(false);
  };

  const [buttonHovered, setButtonHovered] = useState(false);

  return (
    <>
      <div 
        role="banner"
        className="fixed top-4 left-6 md:left-8 right-6 md:right-8 mx-auto max-w-[1336px] z-50 py-2 pl-4 md:pl-5 pr-6 md:pr-8 flex items-center justify-between transition-all duration-300 border rounded-[var(--ui-radius-card)] md:rounded-2xl"
        style={{
          backgroundColor: primaryColor,
          borderColor: hexToRgba(surfaceColor, 0.15),
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)',
          boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.15), 0 8px 10px -6px rgba(0, 0, 0, 0.1)',
        }}
      >
        <div className="w-full flex items-center justify-between">
          {/* Kiri: Logo Dinamis & Portal Teks */}
          <Link to="/" className="flex items-center gap-2.5 shrink-0 select-none group no-underline">
            {/* Logo image or fallback initials */}
            <div className="relative shrink-0 w-[30px] h-[30px] flex items-center justify-center transition-transform duration-300 group-hover:scale-105">
              {logoUrl ? (
                <img
                  src={logoUrl}
                  alt="Logo"
                  className="h-full w-full object-contain"
                />
              ) : (
                <div
                  className="h-full w-full rounded-md flex items-center justify-center font-black text-[10px] shrink-0 shadow-sm transition-colors duration-300"
                  style={{ 
                    backgroundColor: surfaceColor,
                    color: primaryColor
                  }}
                >
                  {logoText}
                </div>
              )}
            </div>
            {/* Brand text */}
            <div className="flex flex-col text-left justify-center leading-none">
              <span 
                className="text-[9.5px] font-bold uppercase tracking-[0.18em] leading-none mb-[3px] transition-colors duration-300"
                style={{ color: hexToRgba(surfaceColor, 0.8) }}
              >
                {appSettings?.logoSmallText !== undefined ? appSettings.logoSmallText : "PORTAL"}
              </span>
              <span 
                className="font-extrabold text-[15.5px] tracking-tight leading-none uppercase transition-colors duration-300"
                style={{ color: surfaceColor }}
              >
                {appName}
              </span>
            </div>
          </Link>

          {/* Kanan: Navigasi, Bendera, dan Masuk (Desktop) */}
          <div className="hidden md:flex items-center gap-8 lg:gap-10">
            <nav className="flex items-center gap-6 lg:gap-8 font-sans">
              {navLinks.map((link) => {
                const isActive = location.pathname === link.to && !link.isBantuan && !link.isPanduan;
                return (
                  <Link
                    key={link.label}
                    to={link.to}
                    onClick={(e) => handleLinkClick(e, link)}
                    className="text-[14px] font-medium transition-colors duration-300 no-underline tracking-wide"
                    style={{
                      color: surfaceColor,
                      opacity: isActive ? 1 : 0.75
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.opacity = '1';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.opacity = isActive ? '1' : '0.75';
                    }}
                  >
                    {link.label}
                  </Link>
                );
              })}
            </nav>

            {/* Bendera Negara */}
            <div className="flex items-center gap-2 border-l border-slate-200/20 pl-6 lg:pl-8 h-5">
              <IndoFlag />
              <UKFlag />
            </div>

            {/* Tombol Masuk */}
            <button
              onClick={() => setIsLoginModalOpen && setIsLoginModalOpen(true)}
              className="px-5 py-2 rounded-[10px] border font-medium text-[13.5px] transition-all duration-300 cursor-pointer flex items-center gap-1.5"
              style={{
                borderColor: surfaceColor,
                color: buttonHovered ? primaryColor : surfaceColor,
                backgroundColor: buttonHovered ? surfaceColor : 'transparent'
              }}
              onMouseEnter={() => setButtonHovered(true)}
              onMouseLeave={() => setButtonHovered(false)}
              title="Masuk ke Aplikasi"
            >
              <LogIn size={15} strokeWidth={2.5} />
              Masuk
            </button>
          </div>

          {/* Hamburger Menu Button (Mobile) */}
          <div className="flex items-center gap-3 md:hidden">
            {/* Quick Language Toggle */}
            <div className="flex items-center gap-1.5 mr-2">
              <IndoFlag />
              <UKFlag />
            </div>

            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="p-1.5 rounded-lg border transition-colors cursor-pointer bg-transparent"
              style={{
                borderColor: hexToRgba(surfaceColor, 0.3),
                color: surfaceColor
              }}
            >
              {mobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Drawer Navigation */}
      {mobileMenuOpen && (
        <div 
          className="md:hidden fixed top-[75px] left-4 right-4 backdrop-blur-md border rounded-[var(--ui-radius-card)] z-40 flex flex-col p-5 gap-4 animate-in slide-in-from-top-2 duration-200 shadow-xl"
          style={{
            backgroundColor: primaryColor,
            borderColor: hexToRgba(surfaceColor, 0.15)
          }}
        >
          <nav className="flex flex-col gap-3.5">
            {navLinks.map((link) => {
              const isActive = location.pathname === link.to && !link.isBantuan && !link.isPanduan;
              return (
                <Link
                  key={link.label}
