        "--ui-action": appSettings.actionButtonColor || appSettings.accentColor || "#a3e635",
        "--ui-bg": appSettings.bgColor || "#f8fafc",
        "--ui-surface": appSettings.surfaceColor || "#ffffff",
        "--ui-text": appSettings.textColor || "#0f172a",
