);

export default function DashboardPage({
  currentUser,
  classes,
  teachers,
  subjects,
  rooms,
  schedule,
  teachingLoads,
  subjectComposition,
  setActiveTab,
  saveDatabaseNow,
  setTeachers,
  adminUser,
  setAdminUser,
  syncAuthSnapshotNow }) {
  const today = useMemo(() => new Date().toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }), []);
  const todayShort = useMemo(() => new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }), []);

  const {
    majorCount,
    productiveTeachers,
    practiceSubjects,
    usedRooms,
    roomUsagePercent,
    roomCapacityData,
    scheduleSlots } = useMemo(() => {
    const mCount = new Set(classes.map((item) => item.major).filter(Boolean)).size;
    const pTeachers = teachers.filter((teacher) => teacher.type === "Jurusan").length;
    const nTeachers = teachers.length - pTeachers;
    const prSubjects = subjects.filter((subject) => subject.isBlock).length;
    const uRooms = new Set(schedule.map((item) => item.roomId).filter(Boolean));
    const ruPercent = rooms.length > 0 ? Math.round((uRooms.size / rooms.length) * 100) : 0;
    return {
      majorCount: mCount,
      productiveTeachers: pTeachers,
      normativeTeachers: nTeachers,
      practiceSubjects: prSubjects,
      usedRooms: uRooms,
      roomUsagePercent: ruPercent,
      roomCapacityData: [
        { name: "Terpakai", value: uRooms.size },
        { name: "Kosong", value: rooms.length - uRooms.size }
      ],
      scheduleSlots: schedule.length };
  }, [classes, teachers, subjects, schedule, rooms]);

  const activeRole = currentUser?.role === "superadmin" ? "admin" : currentUser?.role;
  const activeDivision = activeRole === "waka" ? (currentUser?.division || "kurikulum").toLowerCase() : "";
  const isTeacher = activeRole === "guru";
  const isKepsek = activeRole === "kepsek";
  const isWaka = activeRole === "waka";
  const isSuperAdmin = activeRole === "admin";
  const isTU = activeRole === "tu" || activeRole === "tata_usaha";

  const wakaProfiles = {
    kurikulum: {
      label: "Waka Kurikulum",
      subtitle: "Fokus pada jadwal, kalender akademik, modul ajar, dan beban mengajar.",
      actions: [
        { label: "Pantau Jadwal", tab: "generate", icon: Calendar, tone: "primary" },
        { label: "Beban Mengajar", tab: "beban", icon: Activity, tone: "white" },
        { label: "Modul Ajar", tab: "silabus", icon: BookOpen, tone: "white" },
      ] },
    kesiswaan: {
      label: "Waka Kesiswaan",
      subtitle: "Fokus pada rekap absensi, kegiatan sekolah, dan pesan dashboard.",
      actions: [
        { label: "Rekap Absensi", tab: "absensi", icon: CheckCircle2, tone: "primary" },
        { label: "Kalender", tab: "akademik", icon: Calendar, tone: "white" },
        { label: "Pesan", tab: "pesan", icon: Activity, tone: "white" },
      ] },
    sarpras: {
      label: "Waka Sarpras",
      subtitle: "Fokus pada ruangan, denah, fasilitas, dan pemakaian ruang.",
      actions: [
        { label: "Data Ruangan", tab: "ruangan", icon: DoorOpen, tone: "primary" },
        { label: "Denah", tab: "denah", icon: School, tone: "white" },
        { label: "Pantau Jadwal", tab: "generate", icon: Calendar, tone: "white" },
      ] },
    humas: {
      label: "Waka Humas",
      subtitle: "Fokus pada informasi publik, pesan dashboard, dan tampilan web.",
      actions: [
        { label: "Pesan", tab: "pesan", icon: Activity, tone: "primary" },
        { label: "Tampilan Web", tab: "tampilan", icon: TrendingUp, tone: "white" },
        { label: "Kalender", tab: "akademik", icon: Calendar, tone: "white" },
      ] },
    hubin: {
      label: "Waka Hubin",
      subtitle: "Fokus pada Manajemen PKL, Data Siswa Praktik, dan Mitra DUDI.",
      actions: [
        { label: "Data Siswa PKL", tab: "pkl_data_siswa", icon: Users, tone: "primary" },
        { label: "Jurnal & Logbook", tab: "pkl_jurnal", icon: BookOpen, tone: "white" },
        { label: "Approval Lokasi", tab: "pkl_lokasi", icon: CheckCircle2, tone: "white" },
      ] } };
  const wakaProfile = wakaProfiles[activeDivision] || wakaProfiles.kurikulum;

  const dashboardMode = (() => {
    if (isTeacher) return {
      label: "Dashboard Guru",
      subtitle: "Ringkasan beban mengajar, absensi kelas, modul ajar, dan jurnal KBM harian Anda.",
      badge: "Guru",
      actions: [
        { label: "Jurnal Harian", tab: "jurnal_harian", icon: BookOpen },
        { label: "Piket", tab: "kedisiplinan_piket", icon: FileText },
      ] };
    if (isTU) return {
      label: "Dashboard Tata Usaha",
      subtitle: "Ringkasan administrasi sekolah, rekap absensi, persuratan, dan data siswa.",
      badge: "Tata Usaha",
      actions: [
        { label: "Data Siswa", tab: "siswa", icon: Users },
        { label: "Rekap Absensi", tab: "absensi", icon: CheckCircle2 },
        { label: "E-Surat", tab: "esurat", icon: FileText },
      ] };
    if (isKepsek) return {
      label: "Dashboard Kepala Sekolah",
      subtitle: "Pantau kondisi sekolah, jadwal, rekap absensi, dan aktivitas terbaru.",
      badge: "Kepala Sekolah",
      actions: [
        { label: "Pantau Jadwal", tab: "generate", icon: Calendar },
        { label: "Rekap Absensi", tab: "absensi", icon: CheckCircle2 },
        { label: "Pesan Dashboard", tab: "pesan", icon: Activity },
      ] };
    if (isWaka) return {
      label: `Dashboard ${wakaProfile.label}`,
      subtitle: wakaProfile.subtitle,
      badge: "Wakil Kepala Sekolah",
      actions: wakaProfile.actions };
    if (isSuperAdmin) return {
      label: "Dashboard Admin (Terpadu)",
      subtitle: "Ringkasan sistem terpadu (Kurikulum, Kesiswaan, Sarpras, & Humas). Kelola jadwal, fasilitas, SDM, dan konfigurasi utama.",
      badge: "Administrator",
      actions: [
        { label: "Buat Jadwal", tab: "generate", icon: Calendar },
        { label: "Rekap Absensi", tab: "absensi", icon: CheckCircle2 },
        { label: "Kelola Ruangan", tab: "ruangan", icon: DoorOpen },
        { label: "Tampilan Web", tab: "tampilan", icon: TrendingUp },
      ] };
    return {
      label: "Dashboard",
      subtitle: "Ringkasan aktivitas dan data yang tersedia untuk akun Anda.",
      badge: "Akses Pengguna",
      actions: [] };
  })();

  const studentsList = useDataStore((state) => state.students || []);

  const teacherCode = currentUser?.code;
  const teacherData = useMemo(() => teachers.find((t) => t.code === teacherCode) || {}, [teachers, teacherCode]);

  const { myTeachingLoads, totalBebanJam, myClasses, myStudentsCount } = useMemo(() => {
    if (!isTeacher) return { myTeachingLoads: [], totalBebanJam: 0, myClasses: 0, myStudentsCount: 0 };
    const loads = teachingLoads.filter((load) => String(load.teacherCode || "").split(",").map((c) => c.trim()).includes(teacherCode));
    const matchesGrade = (targetGrade, className) => {
      if (!targetGrade || targetGrade === "All") return true;
      return String(targetGrade).split(",").map((g) => g.trim()).filter(Boolean).some((g) => String(className || "").startsWith(`${g} `));
    };

    // Find all matching classes
    const matchedClassesList = classes.filter((cls) => {
      return loads.some(load => {
        const loadMajor = String(load.targetMajor || "All").trim().toLowerCase();
        return matchesGrade(load.targetGrade, cls.name) &&
               (loadMajor === "all" || String(cls.major || "").trim().toLowerCase() === loadMajor);
      });
    });

    const myClassesNames = matchedClassesList.map(c => String(c.name).trim().toLowerCase());
    const studentCount = studentsList.filter(s => {
      const clsName = String(s.class_name || s.kelas || "").trim().toLowerCase();
      return myClassesNames.includes(clsName);
    }).length;

    const total = loads.reduce((sum, load) => {
      const loadMajor = String(load.targetMajor || "All").trim().toLowerCase();
      const matchingClassesCount = classes.filter((cls) =>
        matchesGrade(load.targetGrade, cls.name) &&
        (loadMajor === "all" || String(cls.major || "").trim().toLowerCase() === loadMajor)
      ).length;
      const maxClasses = Number.parseInt(load.maxClasses, 10) || 0;
      const effectiveClasses = maxClasses > 0 ? Math.min(maxClasses, matchingClassesCount) : matchingClassesCount;
      return sum + ((Number(load.duration) || 0) * effectiveClasses);
    }, 0);
    const mClasses = loads.reduce((sum, load) => {
      const loadMajor = String(load.targetMajor || "All").trim().toLowerCase();
      const matchingClassesCount = classes.filter((cls) =>
        matchesGrade(load.targetGrade, cls.name) &&
        (loadMajor === "all" || String(cls.major || "").trim().toLowerCase() === loadMajor)
      ).length;
      const maxClasses = Number.parseInt(load.maxClasses, 10) || 0;
      return sum + (maxClasses > 0 ? Math.min(maxClasses, matchingClassesCount) : matchingClassesCount);
    }, 0);
    return { myTeachingLoads: loads, totalBebanJam: total, myClasses: mClasses, myStudentsCount: studentCount };
  }, [classes, isTeacher, teachingLoads, teacherCode, studentsList]);

  const syllabuses = useAppStore((state) => state.syllabuses);
  const activityLogs = useAppStore((state) => state.activityLogs);
  const dashboardMessages = useAppStore((state) => state.dashboardMessages);
  const updateDashboardMessage = useAppStore((state) => state.updateDashboardMessage);
  const removeDashboardMessage = useAppStore((state) => state.removeDashboardMessage);
  const featureSettings = useAppStore((state) => state.featureSettings);

  const [pklStats, setPklStats] = useState(null);
  const [pklSubmissions, setPklSubmissions] = useState([]);
  const [pklMutasi, setPklMutasi] = useState([]);
  const [pklSurat, setPklSurat] = useState([]);
  const [jurnalStats, setJurnalStats] = useState({ approved: 0, pending: 0 });

  useEffect(() => {
    const token = JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken;
    const isHubinOrAdmin = isSuperAdmin || isKepsek || (isWaka && activeDivision === "hubin");
    if (isHubinOrAdmin && token) {
      fetch('/api/pkl/dashboard-stats', { headers: { Authorization: `Bearer ${token}` } })
        .then(r => r.json())
        .then(d => { if (d.ok && d.data) setPklStats(d.data); })
        .catch(err => console.warn("Failed to fetch PKL dashboard stats:", err));

      fetch('/api/pkl/submissions', { headers: { Authorization: `Bearer ${token}` } })
        .then(r => r.json())
        .then(d => { if (d.ok && Array.isArray(d.data)) setPklSubmissions(d.data); })
        .catch(() => {});

      fetch('/api/pkl/mutasi', { headers: { Authorization: `Bearer ${token}` } })
        .then(r => r.json())
        .then(d => { if (d.ok && Array.isArray(d.data)) setPklMutasi(d.data); })
        .catch(() => {});

      fetch('/api/pkl/surat-pengantar', { headers: { Authorization: `Bearer ${token}` } })
        .then(r => r.json())
        .then(d => { if (d.ok && Array.isArray(d.data)) setPklSurat(d.data); })
        .catch(() => {});

      fetch('/api/pkl/logbooks', { headers: { Authorization: `Bearer ${token}` } })
        .then(r => r.json())
        .then(d => {
          if (d.ok && Array.isArray(d.data)) {
            const approved = d.data.filter(j => j.status === 'approved').length;
            const pending = d.data.filter(j => j.status === 'pending').length;
            setJurnalStats({ approved, pending });
          }
        })
        .catch(() => {});
    }
  }, [isSuperAdmin, isKepsek, isWaka, activeDivision]);

  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [activityPage, setActivityPage] = React.useState(0);
  const [activeDataTab, setActiveDataTab] = React.useState("semua");
  const [summaryPage, setSummaryPage] = React.useState(0);
  const [dashLogs, setDashLogs] = React.useState(null);
  const [logsLoading, setLogsLoading] = React.useState(true);
  const [logPages, setLogPages] = React.useState({});
  const [showPanduan, setShowPanduan] = React.useState(false);
  const [siswaFilter, setSiswaFilter] = React.useState('hari_ini');
  const [siswaPage, setSiswaPage] = React.useState(1);
  const [guruFilter, setGuruFilter] = React.useState('hari_ini');
  const [guruPage, setGuruPage] = React.useState(1);
  const [masalahFilter, setMasalahFilter] = React.useState('hari_ini');
  const [masalahPage, setMasalahPage] = React.useState(1);
  const [sistemFilter, setSistemFilter] = React.useState('hari_ini');
  const [sistemPage, setSistemPage] = React.useState(1);
  const [rightTab, setRightTab] = React.useState('absensi_siswa');
  const [rightPage, setRightPage] = React.useState(1);
  const [newPassword, setNewPassword] = React.useState("");
  const [confirmPassword, setConfirmPassword] = React.useState("");
  const [toast, setToast] = React.useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const handleChangePassword = async (e) => {
    e.preventDefault();
    if (!newPassword.trim()) {
      showToast("Sandi baru tidak boleh kosong!", "error");
      return;
    }
    if (newPassword !== confirmPassword) {
      showToast("Konfirmasi sandi tidak cocok!", "error");
      return;
    }

    const { hashPassword } = await import("../utils/auth.js");
    const passwordHash = await hashPassword(newPassword);

    if (currentUser?.role === "admin" || currentUser?.role === "superadmin") {
      const updatedAdmin = { ...adminUser, password: passwordHash };
      await syncAuthSnapshotNow(updatedAdmin, teachers, "menyimpan profil admin");
      await saveDatabaseNow({ adminUser: updatedAdmin }, "menyimpan profil admin");
      setAdminUser(updatedAdmin);
      showToast("Sandi Admin berhasil diubah!", "success");
    } else {
      const nextTeachers = teachers.map((t) => t.code === currentUser.code ? { ...t, password: passwordHash } : t);
      await saveDatabaseNow({ teachers: nextTeachers }, "mengubah password guru");
      setTeachers(nextTeachers);
      if (syncAuthSnapshotNow) {
        try {
          await syncAuthSnapshotNow(adminUser, nextTeachers, "sinkronisasi ubah password guru");
        } catch (e) {
          console.error("Auth sync failed:", e);
        }
      }
      showToast("Sandi Anda berhasil diubah!", "success");
    }

    setNewPassword("");
    setConfirmPassword("");
  };

  React.useEffect(() => {
    const token = JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken;
    fetch('/api/dashboard/logs', { headers: { Authorization: `Bearer ${token}` } })
      .then(r => r.json())
      .then(d => { if (d.ok) setDashLogs(d.data); })
      .catch(() => {})
      .finally(() => setLogsLoading(false));
  }, []);

  const recentActivity = useMemo(() => {
    if (activityLogs.length > 0) return activityLogs.slice(0, 25);
    return [{
      id: "seed-1",
      type: "info",
      title: "Dashboard siap digunakan",
      detail: "Aktivitas baru akan muncul saat admin menyimpan data, generate jadwal, atau guru absen.",
      timestamp: new Date().toISOString() }];
  }, [activityLogs]);

  const activityPageCount = Math.max(1, Math.ceil(recentActivity.length / ACTIVITY_PAGE_SIZE));
  const currentActivityPage = Math.min(activityPage, activityPageCount - 1);
  const visibleActivity = useMemo(() => {
    const start = currentActivityPage * ACTIVITY_PAGE_SIZE;
    return recentActivity.slice(start, start + ACTIVITY_PAGE_SIZE);
  }, [currentActivityPage, recentActivity]);
  const hasOlderActivity = currentActivityPage < activityPageCount - 1;

  const formatActivityTime = (timestamp) => {
    try {
      return new Intl.DateTimeFormat("id-ID", {
        hour: "2-digit", minute: "2-digit", day: "2-digit", month: "short" }).format(new Date(timestamp));
    } catch { return "Baru saja"; }
  };

  const getActivityIcon = (type) => {
    if (type === "attendance") return CheckCircle2;
    if (type === "silabus") return BookOpen;
    if (type === "schedule") return Calendar;
    if (type === "settings") return RefreshCw;
    if (type === "data") return Trash2;
    return Activity;
  };

  const getActivityTone = (type) => {
    if (type === "attendance") return { bg: "bg-emerald-50", text: "text-emerald-500", dot: "bg-emerald-400" };
    if (type === "silabus") return { bg: "bg-[var(--ui-primary)]/10", text: "text-blue-500", dot: "bg-blue-400" };
    if (type === "schedule") return { bg: "bg-violet-50", text: "text-violet-500", dot: "bg-violet-400" };
    if (type === "settings") return { bg: "bg-amber-50", text: "text-amber-500", dot: "bg-amber-400" };
    if (type === "data") return { bg: "bg-rose-50", text: "text-rose-500", dot: "bg-rose-400" };
    return { bg: "bg-slate-50", text: "text-slate-500", dot: "bg-slate-400" };
  };

  const getStatusBadge = (type) => {
    if (type === "schedule") return { label: "Selesai", cls: "bg-emerald-50 text-emerald-600 border-emerald-100" };
    if (type === "attendance") return { label: "Selesai", cls: "bg-emerald-50 text-emerald-600 border-emerald-100" };
    if (type === "settings") return { label: "Pending", cls: "bg-amber-50 text-amber-600 border-amber-100" };
    if (type === "data") return { label: "Dihapus", cls: "bg-rose-50 text-rose-600 border-rose-100" };
    return { label: "Proses", cls: "bg-[var(--ui-primary)]/10 text-[var(--ui-primary)] border-blue-100" };
  };

  const activeDashboardMessages = useMemo(() => {
    if (featureSettings?.dashboardMessages === false) return [];
    const todayDate = new Date().toISOString().slice(0, 10);
    const role = currentUser?.role || "guru";
    return (dashboardMessages || []).filter((message) => {
      if (message.isActive === false) return false;
      if (message.target && message.target !== "all" && message.target !== role) return false;
      if (message.startDate && message.startDate > todayDate) return false;
      if (message.endDate && message.endDate < todayDate) return false;
      return true;
    }).sort((a, b) => Number(!!b.pinned) - Number(!!a.pinned) || String(b.createdAt || "").localeCompare(String(a.createdAt || ""))).slice(0, 3);
  }, [currentUser?.role, dashboardMessages, featureSettings?.dashboardMessages]);

  const historyMessages = useMemo(() => {
    const role = currentUser?.role || "guru";
    return (dashboardMessages || []).filter((message) => {
      if (message.target && message.target !== "all" && message.target !== role) return false;
      return true;
    }).sort((a, b) => Number(!!b.pinned) - Number(!!a.pinned) || String(b.createdAt || "").localeCompare(String(a.createdAt || "")));
  }, [currentUser?.role, dashboardMessages]);

  const messageTone = (priority) => {
    if (priority === "urgent") return "bg-rose-50 text-rose-800 border-rose-200";
    if (priority === "important") return "bg-amber-50 text-amber-800 border-amber-200";
    return "bg-[var(--ui-primary)]/10 text-blue-800 border-blue-200";
  };

  const mySyllabuses = useMemo(() => {
    if (!isTeacher) return 0;
    return syllabuses.filter((s) => String(s.teacherCode || "").split(",").map((c) => c.trim()).includes(teacherCode)).length;
  }, [isTeacher, syllabuses, teacherCode]);


  // ===================== ADMIN / KEPSEK / WAKA VIEW =====================
  // Summary data for table
  const summaryRows = (() => {
    const defaultRows = [
      {
        icon: School, imgSrc: "/icons/066-education.svg", iconBg: "bg-blue-50/50", iconColor: "text-blue-500",
        label: "Data Kelas", date: todayShort, count: `${classes.length} Kelas`,
        note: `${majorCount} Jurusan aktif`, progress: classes.length > 0 ? 100 : 5, type: "kelas",
        statusLabel: classes.length > 0 ? "Selesai" : "Belum Ada",
        statusCls: classes.length > 0 ? "bg-emerald-50 text-emerald-600 border-emerald-100" : "bg-slate-50 text-slate-400 border-slate-100",
        statusDot: classes.length > 0 ? "bg-emerald-500" : "bg-slate-300" },
      {
        icon: Users, imgSrc: "/icons/045-account.svg", iconBg: "bg-emerald-50/50", iconColor: "text-emerald-500",
        label: "Tenaga Pendidik", date: todayShort, count: `${teachers.length} Guru`,
        note: `${productiveTeachers} Guru Produktif`, progress: teachers.length > 0 ? 100 : 5, type: "guru",
        statusLabel: teachers.length > 0 ? "Selesai" : "Belum Ada",
        statusCls: teachers.length > 0 ? "bg-emerald-50 text-emerald-600 border-emerald-100" : "bg-slate-50 text-slate-400 border-slate-100",
        statusDot: teachers.length > 0 ? "bg-emerald-500" : "bg-slate-300" },
      {
        icon: BookOpen, imgSrc: "/icons/023-pencil.svg", iconBg: "bg-purple-50/50", iconColor: "text-purple-500",
        label: "Mata Pelajaran", date: todayShort, count: `${subjects.length} Mapel`,
        note: `${practiceSubjects} Mapel Praktik`, progress: subjects.length > 0 ? 100 : 5, type: "mapel",
        statusLabel: subjects.length > 0 ? "Selesai" : "Belum Ada",
        statusCls: subjects.length > 0 ? "bg-emerald-50 text-emerald-600 border-emerald-100" : "bg-slate-50 text-slate-400 border-slate-100",
        statusDot: subjects.length > 0 ? "bg-emerald-500" : "bg-slate-300" },
      {
        icon: Calendar, imgSrc: "/icons/011-schedule.svg", iconBg: "bg-indigo-50/50", iconColor: "text-indigo-500",
        label: "Jadwal Pelajaran", date: todayShort, count: `${scheduleSlots} Slot`,
        note: "Total slot jadwal aktif",
        progress: scheduleSlots > 0 ? Math.min(Math.round((scheduleSlots / Math.max(teachingLoads.length * classes.length, 1)) * 100), 100) : 5,
        type: "jadwal",
        statusLabel: scheduleSlots > 0 ? "In Progress" : "Belum Ada",
        statusCls: scheduleSlots > 0 ? "bg-[var(--ui-primary)]/10 text-[var(--ui-primary)] border-blue-100" : "bg-slate-50 text-slate-400 border-slate-100",
        statusDot: scheduleSlots > 0 ? "bg-blue-500" : "bg-slate-300" },
      {
        icon: DoorOpen, imgSrc: "/icons/008-warehouse.svg", iconBg: "bg-amber-50/50", iconColor: "text-amber-500",
        label: "Data Ruangan", date: todayShort, count: `${rooms.length} Ruang`,
        note: "Kapasitas & Fasilitas (Sarpras)", progress: rooms.length > 0 ? 100 : 5, type: "ruangan",
        statusLabel: rooms.length > 0 ? "Selesai" : "Belum Ada",
        statusCls: rooms.length > 0 ? "bg-emerald-50 text-emerald-600 border-emerald-100" : "bg-slate-50 text-slate-400 border-slate-100",
        statusDot: rooms.length > 0 ? "bg-emerald-500" : "bg-slate-300" },
      {
