      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 md:gap-6 flex-1">
        {/* Helper functions and variables for role-specific dashboard widgets */}
        {(() => {
          const fmtTime = (ts) => {
            try { return new Intl.DateTimeFormat('id-ID', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }).format(new Date(ts)); }
            catch { return '-'; }
          };

          const filterByTime = (logs, filterVal, dateField = 'created_at') => {
            if (!logs) return [];
            const today = new Date();
            today.setHours(0, 0, 0, 0);
            return logs.filter(item => {
              const itemDateVal = item[dateField] || item.date || item.time || item.created_at || item.last_seen;
              if (!itemDateVal) return true;
              const d = new Date(itemDateVal);
              if (isNaN(d.getTime())) return true;
              if (filterVal === 'hari_ini') {
                const check = new Date(itemDateVal);
                return check.getDate() === today.getDate() && check.getMonth() === today.getMonth() && check.getFullYear() === today.getFullYear();
              } else if (filterVal === 'minggu_ini') {
                const check = new Date(itemDateVal);
                const diffTime = Math.abs(today - check);
                const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                return diffDays <= 7;
              }
              return true;
            });
          };

          const renderBox = (title, icon, filterValue, setFilterValue, pageValue, setPageValue, filteredLogs, renderRow) => {
            const itemsPerPage = 2;
            const totalPages = Math.ceil(filteredLogs.length / itemsPerPage);
            const safePage = Math.max(1, Math.min(pageValue, totalPages || 1));
            const pageData = filteredLogs.slice((safePage - 1) * itemsPerPage, safePage * itemsPerPage);

            return (
