                  {renderBox("Siswa Dengan Pelanggaran Terbanyak", <ShieldAlert size={11} className="text-rose-500" />, masalahFilter, setMasalahFilter, masalahPage, setMasalahPage, filterByTime(dashLogs?.problematicStudentLogs || [], masalahFilter, 'last_seen'), renderMasalahRow)}
                </>
              );
            }
            if (isWaka && activeDivision === "sarpras") {
              return (
                <>
                  {renderBox("Absensi Guru & Karyawan", <UserX size={11} className="text-red-500" />, guruFilter, setGuruFilter, guruPage, setGuruPage, filterByTime(dashLogs?.teacherAbsenceLogs || [], guruFilter, 'date'), renderGuruRow)}
                  {renderBox("Absensi Siswa Terlambat", <Clock3 size={11} className="text-amber-500" />, siswaFilter, setSiswaFilter, siswaPage, setSiswaPage, filterByTime(dashLogs?.latestStudentLogs || [], siswaFilter, 'date'), renderSiswaRow)}
