                  {renderBox("Absensi Guru & Staf TU", <UserX size={11} className="text-red-500" />, guruFilter, setGuruFilter, guruPage, setGuruPage, filterByTime(dashLogs?.teacherAbsenceLogs || [], guruFilter, 'date'), renderGuruRow)}
