                      <div className="text-center py-12 bg-slate-50/30 border border-dashed border-slate-200 rounded-xl m-4 flex flex-col items-center justify-center h-[calc(100%-2rem)]">
                        <FileText size={36} className="text-slate-350 mb-2" />
                        <p className="text-xs font-bold text-slate-400">Belum ada pengajuan surat pengantar PKL.</p>
                      </div>
                    ) : (
                      <div className="flex flex-col gap-2">
                        {pklSurat.slice(0, 10).map((surat, i) => (
                          <div key={i} className="flex justify-between items-center p-2.5 rounded-xl border border-slate-150 bg-white hover:bg-slate-50/50 transition-colors">
                            <div className="min-w-0 flex-1">
                              <h4 className="text-xs font-bold text-slate-800 truncate">{surat.nama_perusahaan || surat.pt_name_temp}</h4>
                              <p className="text-[10px] text-slate-500 font-medium mt-0.5 truncate">{surat.pt_address || "Alamat tidak diisi"}</p>
                              <p className="text-[8px] text-slate-400 font-black mt-1 uppercase tracking-widest">{fmtTime(surat.created_at)}</p>
                            </div>
                            <span className={`text-[8px] font-black px-2 py-0.5 rounded-md uppercase ml-2 ${
                              surat.status === 'stempel_selesai' ? 'bg-emerald-100 text-emerald-700' :
                              surat.status === 'acc_hubin' ? 'bg-blue-100 text-blue-700' :
                              'bg-amber-100 text-amber-700'
                            }`}>
                              {surat.status === 'stempel_selesai' ? 'Selesai' :
                               surat.status === 'acc_hubin' ? 'Disetujui Waka' : 'Proses'}
                            </span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              );
            }
            if (isWaka && activeDivision === "kurikulum") {
              return (
                <div className="bg-white shadow-sm border border-slate-100 rounded-[var(--ui-radius-card)] flex flex-col overflow-hidden h-full min-h-[516px] max-h-[516px]">
                  <div className="p-4 border-b border-slate-100 flex justify-between items-center shrink-0 bg-slate-50/50">
                    <div>
                      <h2 className="text-sm font-black text-slate-800">Progres Pemenuhan Jam Pelajaran</h2>
                      <p className="text-[10px] text-slate-400 font-medium mt-0.5">Status pemenuhan beban mengajar guru minggu ini</p>
                    </div>
                    <button onClick={() => setActiveTab("beban")} className="text-[10px] font-bold text-[var(--ui-primary)] hover:underline bg-transparent border-none cursor-pointer">Lihat Detail</button>
                  </div>
                  <div className="flex-1 overflow-y-auto custom-scrollbar p-4">
                    <div className="flex flex-col gap-4">
                      {teachers.slice(0, 7).map((teacher, i) => {
                        const tLoads = teachingLoads.filter(l => String(l.teacherCode || "").split(",").map(c => c.trim()).includes(teacher.code));
                        const totalJp = tLoads.reduce((sum, l) => sum + (Number(l.duration) || 0), 0);
                        const target = Number(teacher.targetWeeklyJp) || 24;
                        const pct = Math.min(Math.round((totalJp / target) * 100), 100);
                        return (
                          <div key={i} className="space-y-1">
                            <div className="flex justify-between items-center text-xs">
                              <span className="font-bold text-slate-700">{teacher.name}</span>
                              <span className="font-black text-slate-500">{totalJp} / {target} JP</span>
                            </div>
                            <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
                              <div 
                                className="h-full rounded-full transition-all duration-500" 
                                style={{ 
                                  width: `${pct}%`,
                                  backgroundColor: pct >= 100 ? '#10b981' : pct >= 50 ? 'var(--ui-primary)' : '#f59e0b' 
                                }}
                              />
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              );
            }
            if (isWaka && activeDivision === "kesiswaan") {
              return (
                <div className="bg-white shadow-sm border border-slate-100 rounded-[var(--ui-radius-card)] flex flex-col overflow-hidden h-full min-h-[516px] max-h-[516px]">
                  <div className="p-4 border-b border-slate-100 shrink-0 bg-slate-50/50">
                    <h2 className="text-sm font-black text-slate-800">Absensi Terlambat Harian</h2>
                    <p className="text-[10px] text-slate-400 font-medium mt-0.5">Daftar siswa terlambat check-in hari ini</p>
                  </div>
                  <div className="flex-1 overflow-y-auto custom-scrollbar p-3">
                    {(dashLogs?.latestStudentLogs || []).length === 0 ? (
                      <div className="text-center py-12 bg-slate-50/30 border border-dashed border-slate-200 rounded-xl m-4 flex flex-col items-center justify-center h-[calc(100%-2rem)]">
                        <CheckCircle2 size={36} className="text-emerald-500 mb-2" />
                        <p className="text-xs font-bold text-slate-400">Tidak ada siswa terlambat hari ini. Semua tepat waktu!</p>
                      </div>
                    ) : (
                      <div className="flex flex-col gap-1.5">
                        {(dashLogs?.latestStudentLogs || []).slice(0, 10).map((log, i) => (
                          <div key={i} className="flex justify-between items-center p-2.5 rounded-xl border border-slate-100 bg-white hover:bg-slate-50 transition-colors">
                            <div className="min-w-0">
                              <p className="text-xs font-bold text-slate-800 truncate">{log.name || log.nis}</p>
                              <p className="text-[9px] text-slate-400 font-medium mt-0.5">{fmtTime(log.created_at)}</p>
                            </div>
                            <span className="text-[9px] font-black px-2 py-0.5 rounded bg-amber-100 text-amber-700 uppercase shrink-0">Terlambat</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              );
            }
            if (isWaka && activeDivision === "sarpras") {
              return (
                <div className="bg-white shadow-sm border border-slate-100 rounded-[var(--ui-radius-card)] flex flex-col overflow-hidden h-full min-h-[516px] max-h-[516px]">
                  <div className="p-4 border-b border-slate-100 shrink-0 bg-slate-50/50">
                    <h2 className="text-sm font-black text-slate-800">Rekap Status Ruangan Sekolah</h2>
                    <p className="text-[10px] text-slate-400 font-medium mt-0.5">Distribusi pemakaian ruangan teori vs praktik</p>
                  </div>
                  <div className="flex-1 overflow-y-auto custom-scrollbar p-4">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="ui-card p-4 text-center">
                        <h4 className="text-xs font-bold text-slate-500 uppercase">Ruangan Teori</h4>
                        <p className="text-2xl font-black text-slate-800 mt-1">{rooms.filter(r => r.type === "Teori").length}</p>
                      </div>
                      <div className="ui-card p-4 text-center">
                        <h4 className="text-xs font-bold text-slate-500 uppercase">Ruang Praktik/Lab</h4>
                        <p className="text-2xl font-black text-[var(--ui-primary)] mt-1">{rooms.filter(r => r.type === "Praktik").length}</p>
                      </div>
                    </div>

                    <div className="mt-6 space-y-3">
                      <h4 className="text-xs font-bold text-slate-650">Kapasitas Terpakai Hari Ini</h4>
                      <div className="flex justify-between items-center text-xs font-medium text-slate-500">
                        <span>Persentase Pemakaian Ruang</span>
                        <span>{roomUsagePercent}%</span>
                      </div>
                      <div className="w-full bg-slate-100 h-2.5 rounded-full overflow-hidden">
                        <div className="bg-[var(--ui-primary)] h-full rounded-full transition-all duration-500" style={{ width: `${roomUsagePercent}%` }} />
                      </div>
                    </div>
                  </div>
                </div>
              );
            }
            if (isTU) {
              return (
                <div className="bg-white shadow-sm border border-slate-100 rounded-[var(--ui-radius-card)] flex flex-col overflow-hidden h-full min-h-[516px] max-h-[516px]">
                  <div className="p-4 border-b border-slate-100 shrink-0 bg-slate-50/50">
                    <h2 className="text-sm font-black text-slate-800">Administrasi Surat Keluar (E-Surat)</h2>
                    <p className="text-[10px] text-slate-400 font-medium mt-0.5">Log administrasi persuratan digital terbaru</p>
                  </div>
                  <div className="flex-1 overflow-y-auto custom-scrollbar p-3">
                    <div className="text-center py-12 bg-slate-50/30 border border-dashed border-slate-200 rounded-xl m-4 flex flex-col items-center justify-center h-[calc(100%-2rem)]">
                      <FileText size={36} className="text-slate-350 mb-2 mx-auto" />
                      <p className="text-xs font-bold text-slate-400">Belum ada aktivitas persuratan harian.</p>
                    </div>
                  </div>
                </div>
              );
            }

            // Default Admin / Kepsek / humas view (Audit logs / Student Absences list)
            const roleLabel = (r) => ({ admin: 'Admin', guru: 'Guru', waka: 'Waka', kepsek: 'Kepsek', hubin: 'Hubin', siswa: 'Siswa' })[r] || r;
            const roleBadge = (r) => {
              const map = { admin: 'bg-violet-100 text-violet-700', guru: 'bg-blue-100 text-blue-700', waka: 'bg-amber-100 text-amber-700', kepsek: 'bg-red-100 text-red-700', siswa: 'bg-emerald-100 text-emerald-700' };
              return map[r] || 'bg-slate-100 text-slate-600';
            };
            const getUserName = (username, role) => {
              if (role === 'admin' || username === 'admin') return 'Administrator';
              if (teachers && teachers.length > 0) {
                const teacher = teachers.find(t => t.code === username || String(t.id) === String(username) || t.username === username);
                if (teacher && teacher.name) return teacher.name;
              }
              return username;
            };

            const currentFilter = rightTab === 'absensi_siswa' ? siswaFilter : sistemFilter;
            const filteredLogs = rightTab === 'absensi_siswa'
              ? (isSuperAdmin 
                  ? filterByTime(dashLogs?.auditLogs || [], siswaFilter, 'time') 
                  : filterByTime(dashLogs?.studentAbsenceLogs || [], siswaFilter, 'date'))
              : filterByTime(dashLogs?.loginLogs || [], sistemFilter, 'time');

            const itemsPerPage = 5;
            const totalPages = Math.ceil(filteredLogs.length / itemsPerPage);
            const safePage = Math.max(1, Math.min(rightPage, totalPages || 1));
            const pageData = filteredLogs.slice((safePage - 1) * itemsPerPage, safePage * itemsPerPage);

            return (
              <div className="bg-white rounded-[var(--ui-radius-card)] shadow-sm border border-slate-100 flex flex-col overflow-hidden h-full min-h-[516px] max-h-[516px]">
                {/* Tabs */}
                <div className="flex border-b border-slate-100 bg-slate-50/50 shrink-0">
                  <button
                    onClick={() => { setRightTab('absensi_siswa'); setRightPage(1); }}
                    className={`flex-1 py-2 px-3 text-[10px] font-black text-center border-b-2 transition-all cursor-pointer ${
                      rightTab === 'absensi_siswa' ? 'border-primary text-primary bg-white' : 'border-transparent text-slate-500 hover:text-slate-700'
                    }`}
                  >
                    {isSuperAdmin ? "Log Aktivitas (Audit)" : "Absensi Siswa (Sakit/Izin/Alpa)"}
                  </button>
                  {isSuperAdmin && (
                    <button
                      onClick={() => { setRightTab('sistem'); setRightPage(1); }}
                      className={`flex-1 py-2 px-3 text-[10px] font-black text-center border-b-2 transition-all cursor-pointer ${
                        rightTab === 'sistem' ? 'border-primary text-primary bg-white' : 'border-transparent text-slate-500 hover:text-slate-700'
                      }`}
                    >
                      Log Sistem
                    </button>
                  )}
                </div>

                {/* Sub-Filters */}
                <div className="flex items-center justify-between px-3 py-1.5 border-b border-slate-100/60 bg-white shrink-0">
                  <span className="text-[9px] font-bold text-slate-400">Filter Waktu:</span>
                  <div className="flex gap-1">
                    {[
                      { id: 'hari_ini', label: 'Hari Ini' },
                      { id: 'minggu_ini', label: 'Minggu Ini' },
                      { id: 'data_lengkap', label: 'Lengkap' }
                    ].map(filter => (
                      <button
                        key={filter.id}
                        onClick={() => {
                          if (rightTab === 'absensi_siswa') setSiswaFilter(filter.id);
                          else setSistemFilter(filter.id);
                          setRightPage(1);
                        }}
                        className={`px-2 py-0.5 rounded-[var(--ui-radius-small)] text-[8px] font-black transition-all cursor-pointer border ${
                          currentFilter === filter.id
                            ? "bg-[var(--ui-primary)] text-white border-[var(--ui-primary)] shadow-xs"
                            : "bg-white text-slate-500 border-slate-200 hover:bg-slate-50"
                        }`}
                      >
                        {filter.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* List Container */}
                <div className="p-3 overflow-y-auto flex-1 bg-white custom-scrollbar">
                  {pageData.length === 0 ? (
                    <div className="rounded-xl bg-slate-50/30 border border-dashed border-slate-200 text-center flex flex-col items-center justify-center h-full">
                      <span className="text-[10px] text-slate-400 font-bold">Tidak ada data untuk filter ini.</span>
                    </div>
                  ) : (
                    <div className="flex flex-col gap-1.5">
                      {pageData.map((item, i) => {
                        if (rightTab === 'absensi_siswa') {
                          if (isSuperAdmin) {
                            return (
                              <div key={i} className="flex justify-between items-start p-2 px-2.5 rounded-xl border border-slate-100 hover:bg-slate-50 transition-colors gap-3">
                                <div className="flex gap-2 items-start min-w-0 flex-1">
                                  <div className="w-6 h-6 rounded-full bg-violet-50 text-violet-600 flex items-center justify-center shrink-0 mt-0.5">
                                    <ShieldAlert size={11} />
                                  </div>
                                  <div className="min-w-0 flex-1">
                                    <p className="text-[11px] font-bold text-slate-800 leading-tight">{item.user_name} ({roleLabel(item.user_role)})</p>
                                    <p className="text-[10px] text-slate-500 font-semibold mt-0.5 leading-normal">{item.detail}</p>
                                    <p className="text-[8px] text-slate-400 mt-1 font-black">
                                      {item.time ? fmtTime(item.time) : '-'}
                                    </p>
                                  </div>
                                </div>
                                <span className="text-[8px] font-black px-1.5 py-0.5 rounded bg-violet-100 text-violet-700 uppercase shrink-0">
                                  {item.action}
                                </span>
                              </div>
                            );
                          }
                          return (
                            <div key={i} className="flex justify-between items-center p-1.5 px-2.5 rounded-xl border border-slate-100 hover:bg-slate-50 transition-colors">
                              <div className="flex gap-2 items-center min-w-0">
                                <div className="w-6 h-6 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
                                  <Users size={11} />
                                </div>
                                <div className="min-w-0">
                                  <p className="text-[11px] font-bold text-slate-800 leading-tight truncate">{item.name || item.nis}</p>
                                  <p className="text-[9px] text-slate-400 mt-0.5 truncate">
                                    {item.date ? new Date(item.date).toLocaleDateString('id-ID') : fmtTime(item.created_at)}
                                  </p>
                                </div>
                              </div>
                              <span className={`text-[8px] font-black px-1.5 py-0.5 rounded-md uppercase shrink-0 ${
                                String(item.status).toLowerCase() === 'alpa' || String(item.status).toLowerCase() === 'alpha' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
                              }`}>{item.status}</span>
                            </div>
                          );
                        } else {
                          return (
                            <div key={i} className="flex justify-between items-center p-1.5 px-2.5 rounded-xl border border-slate-100 hover:bg-slate-50 transition-colors">
                              <div className="flex gap-2 items-center min-w-0">
                                <div className={`w-6 h-6 rounded-full flex items-center justify-center shrink-0 text-[10px] font-black ${roleBadge(item.role)}`}>
                                  {String(item.name || getUserName(item.username, item.role))[0].toUpperCase()}
                                </div>
                                <div className="min-w-0">
                                  <p className="text-[11px] font-bold text-slate-800 leading-tight truncate">{item.name || getUserName(item.username, item.role)}</p>
                                  <p className="text-[9px] text-slate-400 mt-0.5 truncate">Role: <span className="font-bold">{roleLabel(item.role)}</span></p>
                                </div>
                              </div>
                              <span className="text-[9px] text-slate-400 font-bold shrink-0">{fmtTime(item.time)}</span>
                            </div>
                          );
                        }
                      })}
                    </div>
                  )}
                </div>

                {/* Pagination Footer */}
                {totalPages > 1 && (
                  <div className="px-4.5 py-2 border-t border-slate-100 bg-slate-50/30 flex items-center justify-between shrink-0">
                    <span className="text-[9px] text-slate-400 font-bold">
                      Hal {safePage} dari {totalPages} ({filteredLogs.length} data)
                    </span>
                    <div className="flex gap-1">
                      <button
                        disabled={safePage === 1}
                        onClick={() => setRightPage(safePage - 1)}
                        className="px-2.5 py-1 rounded-[var(--ui-radius-small)] text-[9px] font-bold border border-slate-200 bg-white text-slate-600 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
                      >
                        Sebelumnya
                      </button>
                      <button
                        disabled={safePage === totalPages}
                        onClick={() => setRightPage(safePage + 1)}
                        className="px-2.5 py-1 rounded-[var(--ui-radius-small)] text-[9px] font-bold border border-slate-200 bg-white text-slate-600 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
                      >
                        Berikutnya
                      </button>
                    </div>
                  </div>
                )}
              </div>
            );
          };

          const widgets = {
            middle: renderMiddleWidgets(),
            right: renderRightWidgets()
          };

          return (
            <>
              {/* Middle Column: Log Panels Stack */}
              <div className="lg:col-span-5 xl:col-span-5 flex flex-col gap-[18px]">
                {widgets.middle}
              </div>

              {/* Right Column: Absensi Siswa & Log Sistem (Tall Card) or Beban Mengajar Anda for Guru */}
              <div className="lg:col-span-7 xl:col-span-7 flex flex-col gap-4">
                {widgets.right}
              </div>
            </>
          );
        })()}
      </div>



      <PanduanModal isOpen={showPanduan} onClose={() => setShowPanduan(false)} role={currentUser?.role || "admin"} division={currentUser?.division || ""} />

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
}





