  book: BookOpen, chat: MessageSquare, monitor: MonitorSmartphone, wifi: Wifi,
  palette: Palette, map: MapPin, users: Users, sparkles: Sparkles,
  user: User, booktext: BookOpenText, shield: ShieldCheck
};

