        <div className="bg-white rounded-[var(--ui-radius-card)] shadow-2xl w-full max-w-4xl h-[85vh] overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
          <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50 shrink-0">
            <div>
              <h3 className="font-bold text-slate-800 text-sm flex items-center gap-2">
                <ShieldCheck className="text-red-500" size={18} />
                Peraturan &amp; Tata Tertib Sekolah
              </h3>
              <p className="text-xs text-slate-500 font-semibold mt-0.5">Dokumen resmi tata tertib dan kriteria poin sekolah</p>
            </div>
            <button onClick={() => setShowRulesModal(false)} className="text-slate-400 hover:text-slate-600 border-none bg-transparent cursor-pointer p-1"><X size={20} /></button>
          </div>

          {/* Tabs header */}
          <div className="flex border-b border-slate-200 bg-slate-50/50 shrink-0 px-6">
            <button
              type="button"
              onClick={() => setActiveRulesTab("pdf")}
              className={`px-4 py-3 text-xs font-bold border-b-2 transition-all cursor-pointer ${activeRulesTab === "pdf"
                  ? "border-[var(--ui-primary)] text-[var(--ui-primary)]"
                  : "border-transparent text-slate-500 hover:text-slate-800"
                }`}
            >
              Dokumen Resmi (PDF)
            </button>
            <button
              type="button"
              onClick={() => setActiveRulesTab("data")}
              className={`px-4 py-3 text-xs font-bold border-b-2 transition-all cursor-pointer ${activeRulesTab === "data"
                  ? "border-[var(--ui-primary)] text-[var(--ui-primary)]"
                  : "border-transparent text-slate-500 hover:text-slate-800"
                }`}
            >
              Kriteria Skor Poin &amp; Tatib (Data)
