      const timer = setInterval(() => {
        currentStep += 1;
        const progress = Math.min(Math.round((currentStep / steps) * 100), 100);
        setLoadingProgress(progress);

        if (currentStep >= steps) {
          clearInterval(timer);
          setMobileFlowStep('landing');
