          {toast.message}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import useAuthStore from '../../../store/monitoring/authStore';
import * as XLSX from 'xlsx';
import { FileText, Download, CalendarIcon, HardDrive, Search } from 'lucide-react';
import { Button } from '../../../components/monitoring/ui/index.js';
import { CustomSelect } from '../../../components/CustomSelect.jsx';


const authHeaders = (token) => ({ "Authorization": `Bearer ${token}` });

export default function HikvisionReport({ type = 'siswa' }) {
  const [logs, setLogs] = useState([]);
  const [devices, setDevices] = useState([]);
  const [loading, setLoading] = useState(false);

  const [filter, setFilter] = useState({
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0],
    deviceId: 'all',
  });

  const authToken = useAuthStore(state => state.user?.authToken);

  const handleSearch = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams(filter);
      params.append('type', type);
      const res = await fetch(`/api/hikvision/report?${params.toString()}`, { headers: authHeaders(authToken) });
      const data = await res.json();
      if (data.ok) {
        setLogs(data.logs || []);
      }
    } catch (err) {
      console.error(err);
    }
    setLoading(false);
  }, [filter, type, authToken]);

  useEffect(() => {
    // Fetch devices for filter dropdown
    const fetchDevices = async () => {
      try {
        const res = await fetch("/api/hikvision/dashboard", { headers: authHeaders(authToken) });
        const data = await res.json();
        if (data.ok) {
          // Filter mesin sesuai tipe laporan
          const filtered = (data.devices || []).filter(d => (d.device_type || 'siswa') === type);
          setDevices(filtered);
        }
      } catch (err) {
        console.error(err);
      }
    };
    fetchDevices();
    handleSearch();
  }, [type, authToken, handleSearch]);

  const handleExport = () => {
    const ws = XLSX.utils.json_to_sheet(logs.map(log => ({
      "Waktu": new Date(log.timestamp).toLocaleString('id-ID'),
      "ID": log.nis,
      "Nama": log.student_name,
      "Mesin": log.location,
      "IP Address": log.ip_address,
      "Event": "Wajah Valid"
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, `Laporan ${type === 'guru' ? 'Guru' : 'Siswa'}`);
    XLSX.writeFile(wb, `Laporan_Absensi_Hikvision_${type}_${filter.startDate}.xlsx`);
  };

  return (
    <div className="flex flex-col gap-4 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-3 bg-white p-4 rounded-[var(--ui-radius-card)] shadow-sm border-none">
        <div className="flex items-center gap-3">
          <div>
            <h2 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2">
              <FileText className="text-[var(--ui-primary)]" size={24} /> Laporan Kehadiran {type === "guru" ? "Guru" : "Siswa"}
            </h2>
            <p className="text-sm text-slate-500 mt-1 font-medium">Lihat dan unduh rekapitulasi absensi {type === "guru" ? "guru" : "siswa"}.</p>
          </div>
                  </div>
        <div>
          <Button onClick={handleExport} disabled={logs.length === 0} className="bg-[var(--ui-primary)] hover:opacity-90 text-white rounded-[var(--ui-radius-small)] px-4 py-2 font-bold flex items-center gap-2 transition-all disabled:opacity-50">
            <Download size={16} /> Export Excel
          </Button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-[var(--ui-radius-card)] shadow-sm border-none">
        <div className="flex flex-col md:flex-row gap-3 items-end">
          <div className="flex-1">
            <label className="block text-xs font-bold text-slate-600 mb-1 flex items-center gap-1"><CalendarIcon size={12}/> Dari Tanggal</label>
            <input className="px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 w-full"  
              type="date" 
              value={filter.startDate} 
              onChange={e => setFilter({...filter, startDate: e.target.value})} 
              className="w-full"
            />
          </div>
          <div className="flex-1">
            <label className="block text-xs font-bold text-slate-600 mb-1 flex items-center gap-1"><CalendarIcon size={12}/> Sampai Tanggal</label>
            <input className="px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 w-full"  
              type="date" 
              value={filter.endDate} 
              onChange={e => setFilter({...filter, endDate: e.target.value})} 
              className="w-full"
            />
          </div>
          <div className="flex-1">
            <label className="block text-xs font-bold text-slate-600 mb-1 flex items-center gap-1"><HardDrive size={12}/> Mesin</label>
            <CustomSelect
              value={filter.deviceId}
              onChange={val => setFilter({...filter, deviceId: val})}
              options={[
                { value: "all", label: "Semua Mesin" },
                ...devices.map(d => ({ value: d.id, label: `${d.location} (${d.ip_address})` }))
              ]}
            />
          </div>
          <div>
            <Button onClick={handleSearch} className="bg-slate-800 hover:bg-slate-900 text-white rounded-[var(--ui-radius-small)] px-6 py-2 font-bold flex items-center gap-2 h-[42px]">
              <Search size={16} /> Tampilkan
            </Button>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[var(--ui-radius-small)] shadow-sm border-none overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm whitespace-nowrap">
            <thead className="bg-slate-50 border-b border-slate-100 text-slate-500">
              <tr>
                <th className="px-4 py-2.5 font-bold">Waktu Scan</th>
                <th className="px-4 py-2.5 font-bold">ID / {type === "guru" ? "NIP" : "NIS"}</th>
                <th className="px-4 py-2.5 font-bold">Nama</th>
                <th className="px-4 py-2.5 font-bold">Mesin</th>
                <th className="px-4 py-2.5 font-bold">Event</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-slate-400">Memuat laporan...</td></tr>
              ) : logs.map(log => (
                <tr key={log.id} className="hover:bg-slate-50">
                  <td className="px-4 py-2.5 font-medium text-slate-700">
                    {new Date(log.timestamp).toLocaleString('id-ID', { dateStyle: 'medium', timeStyle: 'short' })}
                  </td>
                  <td className="px-4 py-2.5 text-slate-500">{log.nis}</td>
                  <td className="px-4 py-2.5 font-bold text-slate-800">{log.student_name}</td>

                  <td className="px-4 py-2.5 text-slate-600 font-medium">{log.location}</td>
                  <td className="px-4 py-2.5">
                    <span className={`px-2 py-1 rounded-[var(--ui-radius-small)] text-xs font-bold border bg-[var(--ui-primary)]/10 text-[var(--ui-primary)] border-[var(--ui-primary)]/20`}>Wajah Valid</span>
                  </td>
                </tr>
              ))}
              {!loading && logs.length === 0 && (
                <tr><td colSpan={5} className="p-8 text-center text-slate-400">Tidak ada data absensi untuk filter yang dipilih.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Save } from 'lucide-react';
import useAuthStore from '../../../store/monitoring/authStore';
import { Settings, Users, Clock } from 'lucide-react';
import { Button } from '../../../components/monitoring/ui/index.js';


export default function HikvisionSettings() {
  const authToken = useAuthStore(state => state.user?.authToken);
  const [config, setConfig] = useState({
    siswa: { masuk_start: "06:00", masuk_end: "07:30", masuk_late: "07:00", pulang_start: "15:00", pulang_end: "17:00" },
    guru: { masuk_start: "06:00", masuk_end: "07:30", masuk_late: "07:00", pulang_start: "15:00", pulang_end: "17:00" },
    karyawan: { masuk_start: "06:00", masuk_end: "07:30", masuk_late: "07:00", pulang_start: "15:00", pulang_end: "17:00" }
  });
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  useEffect(() => {
    const fetchConfig = async () => {
      setLoading(true);
      try {
        const res = await fetch("/api/hikvision/config", { headers: { "Authorization": `Bearer ${authToken}` } });
        const json = await res.json();
        if (json.ok && json.config) {
          setConfig(prev => ({ ...prev, ...json.config }));
        }
      } catch (err) {
        console.error(err);
      }
      setLoading(false);
    };
    fetchConfig();
  }, [authToken]);

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const res = await fetch("/api/hikvision/config", {
        method: "POST",
        headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" },
        body: JSON.stringify(config)
      });
      const json = await res.json();
      if (json.ok) {
        showToast("Konfigurasi berhasil disimpan!");
      } else {
        showToast(json.error || "Gagal menyimpan konfigurasi.", "error");
      }
    } catch (err) {
      console.error(err);
      showToast("Kesalahan jaringan saat menyimpan konfigurasi.", "error");
    }
    setSaving(false);
  };

  const handleChange = (type, field, value) => {
    setConfig(prev => ({
      ...prev,
      [type]: {
        ...prev[type],
        [field]: value
      }
    }));
  };

  if (loading) return <div className="p-8 text-center text-slate-500 font-bold animate-pulse">Memuat pengaturan...</div>;

  return (
    <div className="space-y-6 animate-fade-in max-w-4xl">
      <div>
        <h2 className="text-xl font-black text-slate-800 flex items-center gap-2">
          <Settings size={24} className="text-[var(--ui-primary)]" />
          Pengaturan Absensi HIKVISION
        </h2>
        <p className="text-sm text-slate-500 font-medium mt-1">
          Atur jam masuk, jam batas terlambat, dan jam pulang untuk notifikasi otomatis.
        </p>
      </div>

      <form onSubmit={handleSave} className="space-y-6">
        {["siswa", "guru", "karyawan"].map(type => (
          <div key={type} className="bg-white rounded-[var(--ui-radius-card)] shadow-sm border-none p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-800 capitalize flex items-center gap-2">
              <Users size={18} className="text-slate-400" />
              Aturan Absensi {type}
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="space-y-3">
                <h4 className="text-sm font-bold text-slate-600 border-b pb-2">Jam Masuk</h4>
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Mulai Absen Masuk</label>
                  <input type="time" value={config[type]?.masuk_start || ''} onChange={e => handleChange(type, 'masuk_start', e.target.value)} className="w-full border-none p-2 rounded-[var(--ui-radius-small)] text-sm font-bold" required />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Batas Akhir Masuk</label>
                  <input type="time" value={config[type]?.masuk_end || ''} onChange={e => handleChange(type, 'masuk_end', e.target.value)} className="w-full border-none p-2 rounded-[var(--ui-radius-small)] text-sm font-bold" required />
                </div>
              </div>

              <div className="space-y-3">
                <h4 className="text-sm font-bold text-amber-600 border-b pb-2 flex items-center gap-1"><Clock size={14}/> Keterlambatan</h4>
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Dihitung Terlambat Mulai Pukul</label>
                  <input type="time" value={config[type]?.masuk_late || ''} onChange={e => handleChange(type, 'masuk_late', e.target.value)} className="w-full border border-amber-200 bg-amber-50 focus:bg-white p-2 rounded-[var(--ui-radius-small)] text-sm font-bold text-amber-800" required />
                </div>
                <p className="text-[10px] text-slate-500 font-medium leading-relaxed">
                  Jika {type} absen lebih dari jam ini, sistem akan otomatis mengirimkan notifikasi WA (Late).
                </p>
              </div>

              <div className="space-y-3">
                <h4 className="text-sm font-bold text-indigo-600 border-b pb-2">Jam Pulang</h4>
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Mulai Absen Pulang</label>
                  <input type="time" value={config[type]?.pulang_start || ''} onChange={e => handleChange(type, 'pulang_start', e.target.value)} className="w-full border-none p-2 rounded-[var(--ui-radius-small)] text-sm font-bold" required />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Batas Akhir Pulang</label>
                  <input type="time" value={config[type]?.pulang_end || ''} onChange={e => handleChange(type, 'pulang_end', e.target.value)} className="w-full border-none p-2 rounded-[var(--ui-radius-small)] text-sm font-bold" required />
                </div>
              </div>
            </div>
          </div>
        ))}

        <div className="flex justify-end">
          <Button type="submit" disabled={saving} variant="primary" icon={Save}>
            {saving ? "Menyimpan..." : "Simpan Pengaturan"}
          </Button>
        </div>
      </form>
      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.message}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import useAuthStore from '../../../store/monitoring/authStore';
import * as XLSX from 'xlsx';
import { AlertTriangle, FileText, Filter, Search } from 'lucide-react';
import { CustomSelect } from '../../../components/CustomSelect.jsx';


export default function HikvisionStaffReport({ classes = [] }) {
  const user = useAuthStore(state => state.user);
  const authToken = user?.authToken;

  const [data, setData] = useState([]);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const [daysInMonth, setDaysInMonth] = useState(31);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");

  const [filter, setFilter] = useState({
    month: new Date().getMonth() + 1,
    year: new Date().getFullYear(),
    class_name: user?.isWalas ? user.walasClass : "all",
    type: "staff"
  });

  const [viewMode, setViewMode] = useState("monthly"); // "monthly" | "weekly"
  const [selectedWeek, setSelectedWeek] = useState(1); // 1 to 5

  const daysToRender = React.useMemo(() => {
    if (viewMode === "monthly") {
      return Array.from({ length: daysInMonth }, (_, i) => i + 1);
    }
    const startDay = (selectedWeek - 1) * 7 + 1;
    const endDay = Math.min(selectedWeek * 7, daysInMonth);
    const list = [];
    for (let d = startDay; d <= endDay; d++) {
      list.push(d);
    }
    return list;
  }, [viewMode, selectedWeek, daysInMonth]);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/hikvision/report/matrix", {
        method: 'POST',
        headers: {
          "Authorization": `Bearer ${authToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify(filter)
      });
      const json = await res.json();
      if (json.ok) {
        setData(json.data || []);
        setDaysInMonth(json.daysInMonth || 31);
      } else {
        showToast(json.error || "Gagal memuat laporan matrix", "error");
      }
    } catch (err) {
      console.error(err);
      showToast("Terjadi kesalahan jaringan.", "error");
    }
    setLoading(false);
  }, [authToken, filter]);

  useEffect(() => {
    if (user?.isWalas && !user.walasClass) {
       // Walas with no class mapped
       return;
    }
    fetchData();
  }, [fetchData, user?.isWalas, user?.walasClass]);

  const handleExport = () => {
    if (data.length === 0) return showToast("Tidak ada data untuk diekspor", "warning");

    const exportData = data.map(item => {
      const row = {
        "NIS": item.nis,
        "Nama karyawan": item.name,
        "Kelas": item.class_name || "-",
        "Total Hadir": item.total_hadir,
        "Terlambat": item.total_terlambat
      };
      for (let i = 1; i <= daysInMonth; i++) {
         const dayData = item.days[i];
         if (dayData) {
            row[`Tgl ${i}`] = `${dayData.in || '-'} / ${dayData.out || '-'}${dayData.isLate ? ' (T)' : ''}`;
         } else {
            row[`Tgl ${i}`] = "";
         }
      }
      return row;
    });

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Laporan Absensi karyawan");
    XLSX.writeFile(wb, `Laporan_Absensi_${filter.class_name}_${filter.year}_${filter.month}.xlsx`);
  };

  const filteredData = data.filter(d => {
    if (search && !d.name.toLowerCase().includes(search.toLowerCase()) && !d.nis.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 20;

  // Reset page when search or filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [search, filter.month, filter.year, filter.class_name]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = React.useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return filteredData.slice(startIndex, startIndex + itemsPerPage);
  }, [filteredData, currentPage]);

  const monthOptions = [
    { value: 1, label: "Januari" }, { value: 2, label: "Februari" }, { value: 3, label: "Maret" },
    { value: 4, label: "April" }, { value: 5, label: "Mei" }, { value: 6, label: "Juni" },
    { value: 7, label: "Juli" }, { value: 8, label: "Agustus" }, { value: 9, label: "September" },
    { value: 10, label: "Oktober" }, { value: 11, label: "November" }, { value: 12, label: "Desember" }
  ];
  const currentYear = new Date().getFullYear();
  const yearOptions = [currentYear - 1, currentYear, currentYear + 1];

  if (user?.isWalas && !user.walasClass) {
     return (
        <div className="p-8 text-center bg-red-50 rounded-[var(--ui-radius-small)] border border-red-200">
           <AlertTriangle size={48} className="mx-auto text-red-500 mb-4" />
           <h3 className="text-xl font-bold text-red-700">Data Wali Kelas Belum Lengkap</h3>
           <p className="text-red-600 mt-2">Anda terdeteksi sebagai wali kelas, tetapi kelas yang Anda ampu tidak ditemukan atau sudah dihapus.</p>
        </div>
     );
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="ui-card p-6 flex flex-col gap-6 relative z-30">
        {/* Header Row */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 pb-4 border-b border-slate-100">
          <div>
            <h2 className="text-base font-black text-slate-800 flex items-center gap-2">
              <FileText size={18} className="text-[var(--ui-primary)]" />
              Laporan Absensi Karyawan {user?.isWalas && `(Kelas ${user.walasClass})`}
            </h2>
            <p className="text-xs text-slate-500 font-medium mt-1">
              Rekap kehadiran karyawan per bulan dalam bentuk matriks.
            </p>
          </div>
          <div className="flex gap-2">
             <button 
               onClick={handleExport}
               disabled={loading || data.length === 0}
               className="px-4 py-2 bg-[var(--ui-primary)] text-white border-none hover:bg-[var(--ui-primary)]/90 rounded-[var(--ui-radius-small)] font-bold text-xs transition-colors disabled:opacity-50 shadow-sm cursor-pointer"
             >
               Export
             </button>
          </div>
        </div>

        {/* Filters Row */}
        <div className="flex flex-wrap gap-4 items-end">
           <div className="flex-1 min-w-[150px]">
             <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Pilih Bulan</label>
             <CustomSelect 
               value={filter.month} 
               onChange={val => setFilter({ ...filter, month: parseInt(val) })}
               options={monthOptions}
             />
           </div>
           <div className="flex-1 min-w-[100px]">
             <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Tahun</label>
             <CustomSelect 
               value={filter.year} 
               onChange={val => setFilter({ ...filter, year: parseInt(val) })}
               options={yearOptions.map(y => ({ value: y, label: y.toString() }))}
             />
           </div>
           <div className="flex-1 min-w-[130px]">
             <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Tipe Laporan</label>
             <CustomSelect
               value={viewMode}
               onChange={val => setViewMode(val)}
               options={[
                 { value: "monthly", label: "Bulanan" },
                 { value: "weekly", label: "Mingguan" }
               ]}
             />
           </div>
           {viewMode === "weekly" && (
             <div className="flex-1 min-w-[130px] animate-in slide-in-from-left-2 duration-150">
               <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Pilih Minggu</label>
               <CustomSelect
                 value={selectedWeek}
                 onChange={val => setSelectedWeek(parseInt(val))}
                 options={[
                   { value: 1, label: "Minggu 1 (Tgl 1 - 7)" },
                   { value: 2, label: "Minggu 2 (Tgl 8 - 14)" },
                   { value: 3, label: "Minggu 3 (Tgl 15 - 21)" },
                   { value: 4, label: "Minggu 4 (Tgl 22 - 28)" },
                   { value: 5, label: `Minggu 5 (Tgl 29 - ${daysInMonth})` }
                 ]}
               />
             </div>
           )}
           {!user?.isWalas && (
           <div className="flex-1 min-w-[150px]">
             <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Filter Kelas</label>
             <CustomSelect 
               value={filter.class_name} 
               onChange={val => setFilter({ ...filter, class_name: val })}
               options={[
                 { value: "all", label: "-- Semua Kelas --" },
                 ...classes.map(c => ({ value: c.name, label: c.name }))
               ]}
             />
           </div>
           )}
           <div className="w-full md:w-auto flex gap-2">
              <button 
                onClick={fetchData} 
                disabled={loading}
                className="flex-1 flex items-center justify-center gap-2 px-6 py-2.5 bg-slate-800 text-white rounded-[var(--ui-radius-small)] hover:bg-slate-700 font-bold text-sm transition-colors disabled:opacity-50"
              >
                <Filter size={16} />
                Terapkan
              </button>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[var(--ui-radius-small)] shadow-sm border-none overflow-hidden relative z-10">
        <div className="p-4 border-b border-slate-200 bg-slate-50/50 flex flex-col md:flex-row justify-between items-center gap-4">
           <div className="relative w-full md:w-80">
              <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input 
                type="text" 
                placeholder="Cari karyawan..." 
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-white border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-[var(--ui-primary)]"
              />
           </div>
           <div className="flex gap-4 text-xs font-bold text-slate-500">
              <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-[var(--ui-radius-small)] bg-green-500 inline-block"></span> Tepat Waktu</span>
              <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-[var(--ui-radius-small)] bg-red-500 inline-block"></span> Terlambat</span>
              <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-[var(--ui-radius-small)] bg-slate-200 inline-block"></span> Kosong</span>
           </div>
        </div>

        <div className="overflow-x-auto relative">
          <table className="w-full text-left border-collapse min-w-max">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 text-[10px] uppercase tracking-wider">
                <th className="px-4 py-3 font-black sticky left-0 bg-slate-50 z-10 border-r border-slate-200">Karyawan</th>
                <th className="px-3 py-3 font-black text-center border-r border-slate-200">Hadir</th>
                <th className="px-3 py-3 font-black text-center border-r border-slate-200">Telat</th>
                {daysToRender.map((dayNum) => (
                   <th key={dayNum} className="px-2 py-3 font-black text-center min-w-[70px] border-r border-slate-200">
                     {dayNum}
                   </th>
                ))}
              </tr>
            </thead>
            <tbody className="text-sm font-medium text-slate-700">
              {loading ? (
                <tr>
                  <td colSpan={3 + daysToRender.length} className="px-6 py-12 text-center text-slate-500 font-bold">Memuat data absen...</td>
                </tr>
              ) : paginatedData.length === 0 ? (
                <tr>
                  <td colSpan={3 + daysToRender.length} className="px-6 py-12 text-center text-slate-500 font-bold">Tidak ada data untuk filter ini.</td>
                </tr>
              ) : (
                paginatedData.map(d => (
                  <tr key={d.nis} className="border-b border-slate-100 hover:bg-slate-50/50">
                     <td className="px-4 py-3 sticky left-0 bg-white border-r border-slate-100 -[2px_0_5px_-2px_rgba(0,0,0,0.05)] z-10">
                        <div className="font-bold text-slate-800 text-xs truncate max-w-[150px]" title={d.name}>{d.name}</div>
                        <div className="text-[9px] text-slate-400 font-bold truncate max-w-[150px]">{d.class_name || 'Tanpa Kelas'}</div>
                     </td>
                     <td className="px-3 py-3 text-center font-black text-slate-700 border-r border-slate-100">{d.total_hadir}</td>
                     <td className="px-3 py-3 text-center font-black text-amber-600 border-r border-slate-100">{d.total_terlambat}</td>
                     {daysToRender.map((dayNum) => {
                        const dayData = d.days[dayNum];
                        if (!dayData) {
                           return <td key={dayNum} className="px-1 py-3 text-center border-r border-slate-100 text-[10px] text-slate-300">-</td>;
                        }
                        return (
                           <td key={dayNum} className="px-1 py-2 text-center border-r border-slate-100">
                              <div className={`text-[9px] font-black leading-tight p-1 rounded-[var(--ui-radius-small)] ${dayData.isLate ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'}`} style={{ color: dayData.isLate ? '#b91c1c' : '#166534' }}>
                                 <div>{dayData.in?.substring(0,5) || '--:--'}</div>
                                 <div className="border-t border-black/10 my-0.5"></div>
                                 <div>{dayData.out?.substring(0,5) || '--:--'}</div>
                              </div>
                           </td>
                        );
                     })}
                  </tr>
                ))
              )}
            </tbody>
          </table>

         {/* Pagination Controls */}
         {totalPages > 1 && (
           <div className="flex flex-col sm:flex-row items-center justify-between gap-4 px-6 py-4 bg-slate-50 border-t border-slate-200 text-xs font-bold text-slate-500">
             <div>
               Menampilkan {Math.min((currentPage - 1) * itemsPerPage + 1, filteredData.length)} - {Math.min(currentPage * itemsPerPage, filteredData.length)} dari {filteredData.length} data
             </div>
             <div className="flex items-center gap-1.5 flex-wrap">
               <button
                 type="button"
                 disabled={currentPage === 1}
                 onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                 className="px-3 py-1.5 bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 rounded disabled:opacity-50 transition-colors cursor-pointer"
               >
                 Sebelumnya
               </button>
               {Array.from({ length: totalPages }).map((_, idx) => {
                 const pageNum = idx + 1;
                 return (
                   <button
                     key={pageNum}
                     type="button"
                     onClick={() => setCurrentPage(pageNum)}
                     className={`px-3 py-1.5 rounded transition-all cursor-pointer ${
                       currentPage === pageNum
                         ? "bg-slate-800 text-white border-none"
                         : "bg-white border border-slate-200 text-slate-700 hover:bg-slate-50"
                     }`}
                   >
                     {pageNum}
                   </button>
                 );
               })}
               <button
                 type="button"
                 disabled={currentPage === totalPages}
                 onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                 className="px-3 py-1.5 bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 rounded disabled:opacity-50 transition-colors cursor-pointer"
               >
                 Selanjutnya
               </button>
             </div>
           </div>
         )}
        </div>
      </div>
      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.message}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import useAuthStore from '../../../store/monitoring/authStore';
import { FileText, UserX } from 'lucide-react';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import { useAppStore } from '../../../store/useAppStore';
import { AlertTriangle, ShieldAlert, UserCheck, Filter, Search, X, CheckCircle2 } from 'lucide-react';
import AbsensiSiswa from '../../kedisiplinan/AbsensiSiswa.jsx';
import { PageHeader } from '../../../components/monitoring/ui/index.js';
import { CustomSelect } from '../../../components/CustomSelect.jsx';


export default function HikvisionStudentReport({ classes = [], students = [] }) {
  const user = useAuthStore(state => state.user);
  const authToken = user?.authToken;
  const [activeTab, setActiveTab] = useState("matriks"); // "matriks" | "surat"


  const [data, setData] = useState([]);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };
  const [daysInMonth, setDaysInMonth] = useState(31);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");

  const [filter, setFilter] = useState({
    month: new Date().getMonth() + 1,
    year: new Date().getFullYear(),
    class_name: user?.isWalas ? user.walasClass : "all"
  });

  const [viewMode, setViewMode] = useState("monthly"); // "monthly" | "weekly"
  const [selectedWeek, setSelectedWeek] = useState(1); // 1 to 5

  const daysToRender = React.useMemo(() => {
    if (viewMode === "monthly") {
      return Array.from({ length: daysInMonth }, (_, i) => i + 1);
    }
    const startDay = (selectedWeek - 1) * 7 + 1;
    const endDay = Math.min(selectedWeek * 7, daysInMonth);
    const list = [];
    for (let d = startDay; d <= endDay; d++) {
      list.push(d);
    }
    return list;
  }, [viewMode, selectedWeek, daysInMonth]);

  const [selectedCell, setSelectedCell] = useState(null); // { nis, name, day }
  const [permissionForm, setPermissionForm] = useState({ status: "Sakit", keterangan: "", fileData: null, fileName: null, fileSizeKB: null });
  const [isSubmittingCell, setIsSubmittingCell] = useState(false);

  const handleCellClick = (d, dayNum) => {
    if (user?.role === "siswa") return; // Siswa cannot edit their own or others' data
    setSelectedCell({
      nis: d.nis,
      name: d.name,
      day: dayNum
    });
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        let width = img.width;
        let height = img.height;
        const MAX_WIDTH = 1000;
        const MAX_HEIGHT = 1000;

        if (width > height) {
          if (width > MAX_WIDTH) {
            height *= MAX_WIDTH / width;
            width = MAX_WIDTH;
          }
        } else {
          if (height > MAX_HEIGHT) {
            width *= MAX_HEIGHT / height;
            height = MAX_HEIGHT;
          }
        }

        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);

        const dataUrl = canvas.toDataURL("image/jpeg", 0.7);
        const stringLength = dataUrl.length - 'data:image/jpeg;base64,'.length;
        const sizeInBytes = 4 * Math.ceil(stringLength / 3) * 0.5624896334383812;
        const sizeInKB = Math.round(sizeInBytes / 1024);

        setPermissionForm(prev => ({
          ...prev,
          fileData: dataUrl,
          fileName: file.name,
          fileSizeKB: sizeInKB
        }));
      };
      img.src = event.target.result;
    };
    reader.readAsDataURL(file);
  };

  const handleCellSubmit = async (e) => {
    e.preventDefault();
    if (!selectedCell) return;
    setIsSubmittingCell(true);
    try {
      const dateStr = `${filter.year}-${String(filter.month).padStart(2, '0')}-${String(selectedCell.day).padStart(2, '0')}`;
      const res = await fetch("/api/kedisiplinan/absensi", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${authToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          siswa_nis: selectedCell.nis,
          tanggal: dateStr,
          status: permissionForm.status,
          keterangan: permissionForm.keterangan,
          fileData: permissionForm.fileData,
          fileName: permissionForm.fileName
        })
      });
      const json = await res.json();
      if (json.ok) {
        showToast("Pengajuan ketidakhadiran berhasil disimpan.");
        setSelectedCell(null);
        setPermissionForm({ status: "Sakit", keterangan: "", fileData: null, fileName: null, fileSizeKB: null });
        fetchData();
      } else {
        showToast(json.error || "Gagal menyimpan pengajuan.", "error");
      }
    } catch (err) {
      console.error(err);
      showToast("Terjadi kesalahan jaringan.", "error");
    }
    setIsSubmittingCell(false);
  };

  const getCellStyle = (dayData) => {
    const status = dayData.status || (dayData.isLate ? "Terlambat" : (dayData.in || dayData.out ? "Hadir" : ""));

    if (status === "Alpa") {
      return {
        className: "bg-slate-950 text-white font-bold",
        style: { color: "#ffffff" }
      };
    }
    if (status === "Sakit") {
      return {
        className: "bg-amber-100 text-amber-800 font-bold",
        style: { color: "#92400e" }
      };
    }
    if (status === "Izin") {
      return {
        className: "bg-blue-100 text-blue-800 font-bold",
        style: { color: "#1e40af" }
      };
    }
    if (status === "Terlambat" || dayData.isLate) {
      return {
        className: "bg-red-100 text-red-800 font-bold",
        style: { color: "#b91c1c" }
      };
    }
    return {
      className: "bg-green-100 text-green-800 font-bold",
      style: { color: "#166534" }
    };
  };

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/hikvision/report/matrix", {
        method: 'POST',
        headers: {
          "Authorization": `Bearer ${authToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify(filter)
      });
      const json = await res.json();
      if (json.ok) {
        setData(json.data || []);
        setDaysInMonth(json.daysInMonth || 31);
      } else {
        showToast(json.error || "Gagal memuat laporan matrix", "error");
      }
    } catch (err) {
      console.error(err);
      showToast("Terjadi kesalahan jaringan.", "error");
    }
    setLoading(false);
  }, [authToken, filter]);

  useEffect(() => {
    if (user?.isWalas && !user.walasClass) {
       // Walas with no class mapped
       return;
    }
    fetchData();
  }, [fetchData, user?.isWalas, user?.walasClass]);

  const handleExport = () => {
    if (data.length === 0) return showToast("Tidak ada data untuk diekspor", "warning");

    const exportData = data.map(item => {
      const row = {
        "NIS": item.nis,
        "Nama Siswa": item.name,
        "Kelas": item.class_name || "-",
        "Total Hadir": item.total_hadir,
        "Terlambat": item.total_terlambat
      };
      for (let i = 1; i <= daysInMonth; i++) {
         const dayData = item.days[i];
         if (dayData) {
            row[`Tgl ${i}`] = `${dayData.in || '-'} / ${dayData.out || '-'}${dayData.isLate ? ' (T)' : ''}`;
         } else {
            row[`Tgl ${i}`] = "";
         }
      }
      return row;
    });

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Laporan Absensi Siswa");
    XLSX.writeFile(wb, `Laporan_Absensi_${filter.class_name}_${filter.year}_${filter.month}.xlsx`);
  };

  const handleExportPDF = () => {
    if (data.length === 0) return showToast("Tidak ada data untuk diekspor", "warning");

    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: 'a4'
    });

    doc.setFont("Helvetica", "bold");
    doc.setFontSize(14);
    doc.text(`LAPORAN KINERJA & KEHADIRAN SISWA`, 14, 15);

    doc.setFontSize(10);
    doc.setFont("Helvetica", "normal");
    doc.text(`Kelas: ${filter.class_name === 'all' ? 'Semua Kelas' : filter.class_name} | Periode: ${monthOptions.find(m => m.value === filter.month)?.label} ${filter.year}`, 14, 21);

    const startY = 28;
    doc.setFillColor(241, 245, 249);
    doc.rect(14, startY, 269, 8, 'F');

    doc.setFont("Helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(51, 65, 85);
    doc.text("NIS", 16, startY + 5.5);
    doc.text("Nama Siswa", 40, startY + 5.5);
    doc.text("Kelas", 110, startY + 5.5);
    doc.text("Hadir", 150, startY + 5.5);
    doc.text("Terlambat", 175, startY + 5.5);
    doc.text("Sakit", 200, startY + 5.5);
    doc.text("Izin", 225, startY + 5.5);
    doc.text("Alpa", 250, startY + 5.5);

    doc.setDrawColor(203, 213, 225);
    doc.line(14, startY + 8, 283, startY + 8);

    let currentY = startY + 8;

    data.forEach((item) => {
      if (currentY > 180) {
        doc.addPage();
        currentY = 15;

        doc.setFillColor(241, 245, 249);
        doc.rect(14, currentY, 269, 8, 'F');
        doc.setFont("Helvetica", "bold");
        doc.text("NIS", 16, currentY + 5.5);
        doc.text("Nama Siswa", 40, currentY + 5.5);
        doc.text("Kelas", 110, currentY + 5.5);
        doc.text("Hadir", 150, currentY + 5.5);
        doc.text("Terlambat", 175, currentY + 5.5);
        doc.text("Sakit", 200, currentY + 5.5);
        doc.text("Izin", 225, currentY + 5.5);
        doc.text("Alpa", 250, currentY + 5.5);

        doc.line(14, currentY + 8, 283, currentY + 8);
        currentY += 8;
      }

      doc.setFont("Helvetica", "normal");
      doc.setFontSize(8.5);
      doc.setTextColor(71, 85, 105);

      let sakit = 0, izin = 0, alpa = 0;
      Object.values(item.days || {}).forEach(d => {
        if (d.status === 'Sakit') sakit++;
        else if (d.status === 'Izin') izin++;
        else if (d.status === 'Alpa' || d.status === 'Alpa (Tanpa Keterangan)' || d.status === 'Belum Scan') alpa++;
      });

      doc.text(String(item.nis), 16, currentY + 5.5);
      doc.text(String(item.name).substring(0, 30), 40, currentY + 5.5);
      doc.text(String(item.class_name || '-'), 110, currentY + 5.5);
      doc.text(String(item.total_hadir || 0), 150, currentY + 5.5);
      doc.text(String(item.total_terlambat || 0), 175, currentY + 5.5);
      doc.text(String(sakit), 200, currentY + 5.5);
      doc.text(String(izin), 225, currentY + 5.5);
      doc.text(String(alpa), 250, currentY + 5.5);

      doc.setDrawColor(241, 245, 249);
      doc.line(14, currentY + 8, 283, currentY + 8);

      currentY += 8;
    });

    doc.save(`Laporan_Absensi_Siswa_${filter.class_name}_${filter.year}_${filter.month}.pdf`);
  };

  const filteredData = data.filter(d => {
    if (search && !d.name.toLowerCase().includes(search.toLowerCase()) && !d.nis.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 20;

  // Reset page when search or filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [search, filter.month, filter.year, filter.class_name]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = React.useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return filteredData.slice(startIndex, startIndex + itemsPerPage);
  }, [filteredData, currentPage]);

  const monthOptions = [
    { value: 1, label: "Januari" }, { value: 2, label: "Februari" }, { value: 3, label: "Maret" },
    { value: 4, label: "April" }, { value: 5, label: "Mei" }, { value: 6, label: "Juni" },
    { value: 7, label: "Juli" }, { value: 8, label: "Agustus" }, { value: 9, label: "September" },
    { value: 10, label: "Oktober" }, { value: 11, label: "November" }, { value: 12, label: "Desember" }
  ];
  const currentYear = new Date().getFullYear();
  const yearOptions = [currentYear - 1, currentYear, currentYear + 1];

  // Calculate lists for today if selected month/year is current month/year
  const today = React.useMemo(() => new Date(), []);
  const todayNum = today.getDate();
  const isCurrentMonthYear = filter.month === (today.getMonth() + 1) && filter.year === today.getFullYear();

  const academicCalendarRaw = useAppStore(state => state.academicCalendar);
  const calendarCategoriesRaw = useAppStore(state => state.calendarCategories);
  const academicCalendar = academicCalendarRaw || [];
  const calendarCategories = calendarCategoriesRaw || [];

  const isWeekendToday = (() => {
    const day = today.getDay();
    return day === 0 || day === 6;
  })();

  const isHolidayToday = React.useMemo(() => {
    const yyyy = today.getFullYear();
    const mm = String(today.getMonth() + 1).padStart(2, "0");
    const dd = String(today.getDate()).padStart(2, "0");
    const todayStr = `${yyyy}-${mm}-${dd}`;

    return academicCalendar.some(evt => {
      const start = evt.dateStart;
      const end = evt.dateEnd || evt.dateStart;
      if (todayStr >= start && todayStr <= end) {
        const cat = calendarCategories.find(c => c.id === evt.categoryId);
        const catName = cat ? String(cat.name).toLowerCase() : "";
        const title = String(evt.title).toLowerCase();
        return catName.includes("libur") || title.includes("libur");
      }
      return false;
    });
  }, [academicCalendar, calendarCategories, today]);

  const isHolidayOrWeekendToday = isWeekendToday || isHolidayToday;

  const lateStudentsToday = React.useMemo(() => {
    if (!isCurrentMonthYear || isHolidayOrWeekendToday) return [];
    return data.filter(student => {
      const dayData = student.days[todayNum];
      return dayData && (dayData.isLate || dayData.status === "Terlambat");
    });
  }, [data, isCurrentMonthYear, todayNum, isHolidayOrWeekendToday]);

  const absentStudentsToday = React.useMemo(() => {
    if (!isCurrentMonthYear || isHolidayOrWeekendToday) return [];
    return data.filter(student => {
      const dayData = student.days[todayNum];
      if (!dayData) return true; // No scan yet
      return ["Sakit", "Izin", "Alpa"].includes(dayData.status) || dayData.in === "Alpa" || dayData.in === "Sakit" || dayData.in === "Izin";
    });
  }, [data, isCurrentMonthYear, todayNum, isHolidayOrWeekendToday]);

  if (user?.isWalas && !user.walasClass) {
     return (
        <div className="p-8 text-center bg-red-50 rounded-[var(--ui-radius-small)] border border-red-200">
           <AlertTriangle size={48} className="mx-auto text-red-500 mb-4" />
           <h3 className="text-xl font-bold text-red-700">Data Wali Kelas Belum Lengkap</h3>
           <p className="text-red-600 mt-2">Anda terdeteksi sebagai wali kelas, tetapi kelas yang Anda ampu tidak ditemukan atau sudah dihapus.</p>
        </div>
     );
  }

  return (
    <div className="space-y-6 animate-fade-in w-full">
      <PageHeader 
        title={activeTab === 'matriks' ? "Laporan Matriks Bulanan" : "Manajemen Surat Izin/Sakit"}
        icon={activeTab === 'matriks' ? FileText : UserX}
        description={activeTab === 'matriks' 
          ? "Rekap kehadiran siswa per bulan dalam bentuk matriks." 
          : "Rekap data ketidakhadiran harian siswa dan manajemen file surat izin/sakit."}
        tabs={[
          { id: 'matriks', label: 'Laporan Matriks Bulanan' },
          { id: 'surat', label: 'Manajemen Surat Izin/Sakit' }
        ]}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      />

      {activeTab === 'surat' ? (
        <AbsensiSiswa students={students} classes={classes} />
      ) : (
        <>
          {/* Wali Kelas Daily Monitoring Widgets */}
      {isCurrentMonthYear && !isHolidayOrWeekendToday && data.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Late Students Today */}
          <div className="bg-white rounded-[var(--ui-radius-card)] border border-slate-100 shadow-sm overflow-hidden flex flex-col">
            <div className="p-4 bg-amber-50 border-b border-amber-100 flex items-center justify-between">
              <h3 className="text-xs font-black text-amber-800 flex items-center gap-1.5 uppercase tracking-wider">
                <ShieldAlert size={16} />
                Siswa Terlambat Hari Ini
              </h3>
              <span className="text-[10px] font-black px-2 py-0.5 bg-amber-100 text-amber-800 rounded-full">
                {lateStudentsToday.length} Siswa
              </span>
            </div>
            <div className="flex-1 min-h-[120px] max-h-52 overflow-y-auto custom-scrollbar">
              {lateStudentsToday.length === 0 ? (
                <div className="p-8 text-center text-xs text-slate-400 font-bold flex flex-col items-center justify-center gap-2">
                  <UserCheck size={20} className="text-slate-300" />
                  <span>Tidak ada siswa terlambat hari ini.</span>
                </div>
              ) : (
                <div className="divide-y divide-slate-100">
                  {lateStudentsToday.map(s => {
                    const dayData = s.days[todayNum];
                    return (
                      <div key={s.nis} className="p-3 flex items-center justify-between gap-3 text-xs">
                        <div className="min-w-0 flex-1">
                          <div className="font-bold text-slate-800 truncate" title={s.name}>{s.name}</div>
                          <div className="text-[10px] text-slate-400 font-semibold">{s.nis}</div>
                        </div>
                        <div className="flex items-center gap-2 shrink-0">
                          <span className="px-2 py-0.5 bg-amber-100 text-amber-800 font-bold rounded text-[10px] border border-amber-200">
                            {dayData.in?.substring(0, 5) || "Terlambat"}
                          </span>
                          <button
                            onClick={() => handleCellClick(s, todayNum)}
                            className="px-2.5 py-1 bg-slate-50 border border-slate-200 hover:bg-slate-100 text-slate-600 font-bold rounded-lg transition-all text-[10px] cursor-pointer"
                          >
                            Ubah
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>

          {/* Absent Students Today */}
          <div className="bg-white rounded-[var(--ui-radius-card)] border border-slate-100 shadow-sm overflow-hidden flex flex-col">
            <div className="p-4 bg-rose-50 border-b border-rose-100 flex items-center justify-between">
              <h3 className="text-xs font-black text-rose-800 flex items-center gap-1.5 uppercase tracking-wider">
                <UserX size={16} />
                Siswa Tidak Masuk Hari Ini
              </h3>
              <span className="text-[10px] font-black px-2 py-0.5 bg-rose-100 text-rose-800 rounded-full">
                {absentStudentsToday.length} Siswa
              </span>
            </div>
            <div className="flex-1 min-h-[120px] max-h-52 overflow-y-auto custom-scrollbar">
              {absentStudentsToday.length === 0 ? (
                <div className="p-8 text-center text-xs text-slate-400 font-bold flex flex-col items-center justify-center gap-2">
                  <UserCheck size={20} className="text-slate-300" />
                  <span>Semua siswa telah fingerprint hari ini.</span>
                </div>
              ) : (
                <div className="divide-y divide-slate-100">
                  {absentStudentsToday.map(s => {
                    const dayData = s.days[todayNum];
                    const status = dayData?.status || dayData?.in || "Alpa";

                    let badgeClass = "bg-red-50 text-red-700 border-red-100";
                    if (status === "Sakit") badgeClass = "bg-amber-50 text-amber-700 border-amber-100";
                    if (status === "Izin") badgeClass = "bg-blue-50 text-blue-700 border-blue-100";

                    return (
                      <div key={s.nis} className="p-3 flex items-center justify-between gap-3 text-xs">
                        <div className="min-w-0 flex-1">
                          <div className="font-bold text-slate-800 truncate" title={s.name}>{s.name}</div>
                          <div className="text-[10px] text-slate-400 font-semibold flex items-center gap-1.5">
                            <span>{s.nis}</span>
                            {dayData?.note && <span className="truncate text-slate-500 max-w-[120px]">({dayData.note})</span>}
                          </div>
                        </div>
                        <div className="flex items-center gap-2 shrink-0">
                          <span className={`px-2 py-0.5 font-bold border rounded text-[10px] ${badgeClass}`}>
                            {status === "Alpa" ? "Belum Scan" : status}
                          </span>
                          <button
                            onClick={() => handleCellClick(s, todayNum)}
                            className="px-2.5 py-1 bg-[var(--ui-primary)] text-white font-bold rounded-lg hover:opacity-90 transition-opacity text-[10px] border-none cursor-pointer"
                          >
                            Input Surat
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      <div className="ui-card p-6 flex flex-col gap-6 relative z-30">
        {/* Header Row */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 pb-4 border-b border-slate-100">
          <div>
            <h2 className="text-base font-black text-slate-800 flex items-center gap-2">
              <FileText size={18} className="text-[var(--ui-primary)]" />
              Laporan Absensi Siswa {user?.isWalas && `(Kelas ${user.walasClass})`}
            </h2>
            <p className="text-xs text-slate-500 font-medium mt-1">
              Rekap kehadiran siswa per bulan dalam bentuk matriks.
            </p>
          </div>
          <div className="flex gap-2">
             <button 
               onClick={handleExport}
               disabled={loading || data.length === 0}
               className="px-4 py-2 bg-emerald-600 text-white border-none hover:bg-emerald-700 rounded-[var(--ui-radius-small)] font-bold text-xs transition-colors disabled:opacity-50 shadow-sm cursor-pointer"
             >
               Excel Export
             </button>
             <button 
               onClick={handleExportPDF}
               disabled={loading || data.length === 0}
               className="px-4 py-2 bg-rose-600 text-white border-none hover:bg-rose-700 rounded-[var(--ui-radius-small)] font-bold text-xs transition-colors disabled:opacity-50 shadow-sm cursor-pointer"
             >
               PDF Export
             </button>
          </div>
        </div>

        {/* Filters Row */}
        <div className="flex flex-wrap gap-4 items-end">
           <div className="flex-1 min-w-[150px]">
             <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Pilih Bulan</label>
             <CustomSelect 
               value={filter.month} 
               onChange={val => setFilter({ ...filter, month: parseInt(val) })}
               options={monthOptions}
             />
           </div>
           <div className="flex-1 min-w-[100px]">
             <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Tahun</label>
             <CustomSelect 
               value={filter.year} 
               onChange={val => setFilter({ ...filter, year: parseInt(val) })}
               options={yearOptions.map(y => ({ value: y, label: y.toString() }))}
             />
           </div>
           <div className="flex-1 min-w-[130px]">
             <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Tipe Laporan</label>
             <CustomSelect
               value={viewMode}
               onChange={val => setViewMode(val)}
               options={[
                 { value: "monthly", label: "Bulanan" },
                 { value: "weekly", label: "Mingguan" }
               ]}
             />
           </div>
           {viewMode === "weekly" && (
             <div className="flex-1 min-w-[130px] animate-in slide-in-from-left-2 duration-150">
               <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Pilih Minggu</label>
               <CustomSelect
                 value={selectedWeek}
                 onChange={val => setSelectedWeek(parseInt(val))}
                 options={[
                   { value: 1, label: "Minggu 1 (Tgl 1 - 7)" },
                   { value: 2, label: "Minggu 2 (Tgl 8 - 14)" },
                   { value: 3, label: "Minggu 3 (Tgl 15 - 21)" },
                   { value: 4, label: "Minggu 4 (Tgl 22 - 28)" },
                   { value: 5, label: `Minggu 5 (Tgl 29 - ${daysInMonth})` }
                 ]}
               />
             </div>
           )}
           {!user?.isWalas && (
           <div className="flex-1 min-w-[150px]">
             <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Filter Kelas</label>
             <CustomSelect 
               value={filter.class_name} 
               onChange={val => setFilter({ ...filter, class_name: val })}
               options={[
                 { value: "all", label: "-- Semua Kelas --" },
                 ...classes.map(c => ({ value: c.name, label: c.name }))
               ]}
             />
           </div>
           )}
           <div className="w-full md:w-auto flex gap-2">
              <button 
                onClick={fetchData} 
                disabled={loading}
                className="flex-1 flex items-center justify-center gap-2 px-6 py-2.5 bg-slate-800 text-white rounded-[var(--ui-radius-small)] hover:bg-slate-700 font-bold text-sm transition-colors disabled:opacity-50"
              >
                <Filter size={16} />
                Terapkan
              </button>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[var(--ui-radius-small)] shadow-sm border-none overflow-hidden relative z-10">
        <div className="p-4 border-b border-slate-200 bg-slate-50/50 flex flex-col md:flex-row justify-between items-center gap-4">
           <div className="relative w-full md:w-80">
              <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input 
                type="text" 
                placeholder="Cari siswa..." 
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-white border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]"
              />
           </div>
            <div className="flex flex-wrap gap-4 text-[10px] font-black uppercase tracking-wider text-slate-500">
               <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-[var(--ui-radius-small)] bg-green-500 inline-block"></span> Tepat Waktu</span>
               <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-[var(--ui-radius-small)] bg-red-500 inline-block"></span> Terlambat</span>
               <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-[var(--ui-radius-small)] bg-blue-500 inline-block"></span> Izin</span>
               <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-[var(--ui-radius-small)] bg-amber-400 inline-block"></span> Sakit</span>
               <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-[var(--ui-radius-small)] bg-slate-900 inline-block"></span> Alpa</span>
               <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-[var(--ui-radius-small)] bg-slate-200 inline-block"></span> Kosong</span>
            </div>
         </div>

         <div className="overflow-x-auto relative">
           <table className="w-full text-left border-collapse min-w-max">
             <thead>
               <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 text-[10px] uppercase tracking-wider">
                 <th className="px-4 py-3 font-black sticky left-0 bg-slate-50 z-10 border-r border-slate-200">Siswa</th>
                 <th className="px-3 py-3 font-black text-center border-r border-slate-200">Σ Hdr</th>
                 <th className="px-3 py-3 font-black text-center border-r border-slate-200">Σ Tlt</th>
                 {daysToRender.map((dayNum) => (
                    <th key={dayNum} className="px-2 py-3 font-black text-center min-w-[70px] border-r border-slate-200">
                      {dayNum}
                    </th>
                 ))}
               </tr>
             </thead>
             <tbody className="text-sm font-medium text-slate-700">
               {loading ? (
                 <tr>
                   <td colSpan={3 + daysToRender.length} className="px-6 py-12 text-center text-slate-500 font-bold">Memuat data absen...</td>
                 </tr>
               ) : paginatedData.length === 0 ? (
                 <tr>
                   <td colSpan={3 + daysToRender.length} className="px-6 py-12 text-center text-slate-500 font-bold">Tidak ada data untuk filter ini.</td>
                 </tr>
               ) : (
                 paginatedData.map(d => (
                   <tr key={d.nis} className="border-b border-slate-100 hover:bg-slate-50/50">
                      <td className="px-4 py-3 sticky left-0 bg-white border-r border-slate-100 -[2px_0_5px_-2px_rgba(0,0,0,0.05)] z-10">
                         <div className="font-bold text-slate-800 text-xs truncate max-w-[150px]" title={d.name}>{d.name}</div>
                         <div className="text-[9px] text-slate-400 font-bold truncate max-w-[150px]">{d.class_name || 'Tanpa Kelas'}</div>
                      </td>
                      <td className="px-3 py-3 text-center font-black text-slate-700 border-r border-slate-100">{d.total_hadir}</td>
                      <td className="px-3 py-3 text-center font-black text-amber-600 border-r border-slate-100">{d.total_terlambat}</td>
                      {daysToRender.map((dayNum) => {
                         const dayData = d.days[dayNum];
                         if (!dayData) {
                            return (
                               <td 
                                 key={dayNum} 
                                 onClick={() => handleCellClick(d, dayNum)}
                                 className="px-1 py-3 text-center border-r border-slate-100 text-[10px] text-slate-300 cursor-pointer hover:bg-slate-50"
                               >
                                 -
                               </td>
                            );
                         }
                         const cellColors = getCellStyle(dayData);
                         return (
                            <td 
                              key={dayNum} 
                              onClick={() => handleCellClick(d, dayNum)}
                              className="px-1 py-2 text-center border-r border-slate-100 cursor-pointer hover:bg-slate-50 transition-colors"
                            >
                               <div className={`text-[9px] font-black leading-tight p-1 rounded-[var(--ui-radius-small)] ${cellColors.className}`} style={cellColors.style}>
                                  {["Sakit", "Izin", "Alpa"].includes(dayData.status) ? (
                                    <div className="py-1.5 flex flex-col items-center gap-1">
                                      <span>{dayData.status}</span>
                                      {dayData.note && <span className="text-[7.5px] font-semibold opacity-70">({dayData.note})</span>}
                                      {dayData.gdrive_url && (
                                        <a 
                                          href={dayData.gdrive_url} 
                                          target="_blank" 
                                          rel="noreferrer" 
                                          onClick={(e) => e.stopPropagation()} 
                                          className="text-[7.5px] text-blue-600 hover:underline font-bold bg-white/60 px-1 rounded border border-blue-200 mt-0.5"
                                        >
                                          Lihat Surat
                                        </a>
                                      )}
                                    </div>
                                  ) : (
                                    <>
                                      <div>{dayData.in?.substring(0,5) || '--:--'}</div>
                                      <div className="border-t border-black/10 my-0.5"></div>
                                      <div>{dayData.out?.substring(0,5) || '--:--'}</div>
                                    </>
                                  )}
                               </div>
                            </td>
                         );
                      })}
                   </tr>
                 ))
               )}
             </tbody>
           </table>
         </div>

         {/* Pagination Controls */}
         {totalPages > 1 && (
           <div className="flex flex-col sm:flex-row items-center justify-between gap-4 px-6 py-4 bg-slate-50 border-t border-slate-200 text-xs font-bold text-slate-500">
             <div>
               Menampilkan {Math.min((currentPage - 1) * itemsPerPage + 1, filteredData.length)} - {Math.min(currentPage * itemsPerPage, filteredData.length)} dari {filteredData.length} data
             </div>
             <div className="flex items-center gap-1.5 flex-wrap">
               <button
                 type="button"
                 disabled={currentPage === 1}
                 onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                 className="px-3 py-1.5 bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 rounded disabled:opacity-50 transition-colors cursor-pointer"
               >
                 Sebelumnya
               </button>
               {Array.from({ length: totalPages }).map((_, idx) => {
                 const pageNum = idx + 1;
                 return (
                   <button
                     key={pageNum}
                     type="button"
                     onClick={() => setCurrentPage(pageNum)}
                     className={`px-3 py-1.5 rounded transition-all cursor-pointer ${
                       currentPage === pageNum
                         ? "bg-slate-800 text-white border-none"
                         : "bg-white border border-slate-200 text-slate-700 hover:bg-slate-50"
                     }`}
                   >
                     {pageNum}
                   </button>
                 );
               })}
               <button
                 type="button"
                 disabled={currentPage === totalPages}
                 onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                 className="px-3 py-1.5 bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 rounded disabled:opacity-50 transition-colors cursor-pointer"
               >
                 Selanjutnya
               </button>
             </div>
           </div>
         )}
       </div>

       {/* Input Ketidakhadiran Modal */}
       {selectedCell && (
         <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-xs animate-in fade-in duration-200">
           <div className="bg-white rounded-[var(--ui-radius-card)] shadow-lg max-w-sm w-full overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="flex items-center justify-between p-4 border-b border-slate-100">
               <h3 className="text-xs font-black text-slate-800 uppercase tracking-wider">Input Ketidakhadiran</h3>
               <button 
                 type="button" 
                 onClick={() => setSelectedCell(null)}
                 className="p-1.5 text-slate-400 hover:text-slate-700 hover:bg-slate-50 rounded-md transition-colors"
               >
                 <X size={16} />
               </button>
             </div>

             <form onSubmit={handleCellSubmit} className="p-4 space-y-4">
               <div>
                 <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest block mb-1">Nama Siswa</label>
                 <div className="text-xs font-black text-slate-800">{selectedCell.name} ({selectedCell.nis})</div>
               </div>

               <div>
                 <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest block mb-1">Tanggal</label>
                 <div className="text-xs font-black text-slate-800">
                   {String(selectedCell.day).padStart(2, '0')} / {String(filter.month).padStart(2, '0')} / {filter.year}
                 </div>
               </div>

               <div>
                 <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest block mb-1">Status Kehadiran</label>
                 <select
                   value={permissionForm.status}
                   onChange={(e) => setPermissionForm({ ...permissionForm, status: e.target.value })}
                   className="w-full bg-slate-50 border border-slate-200 p-2.5 rounded-[var(--ui-radius-small)] text-xs font-black focus:outline-[var(--ui-primary)]"
                 >
                   <option value="Sakit">Sakit</option>
                   <option value="Izin">Izin</option>
                   <option value="Alpa">Alpa (Tanpa Keterangan)</option>
                 </select>
               </div>

               {["Sakit", "Izin"].includes(permissionForm.status) && (
                 <div>
                   <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest block mb-1">
                     Upload Surat / Bukti (Gambar)
                   </label>
                   <input
                     type="file"
                     accept="image/*"
                     onChange={handleFileChange}
                     className="w-full bg-slate-50 border border-slate-200 p-2 rounded-[var(--ui-radius-small)] text-xs font-semibold"
                   />
                    {permissionForm.fileData && (
                      <div className="inline-flex items-center gap-1 text-[9px] text-emerald-600 font-bold mt-1">
                        <CheckCircle2 size={11} className="shrink-0 text-emerald-600" />
                        <span>Gambar dikompres ({permissionForm.fileSizeKB} KB)</span>
                      </div>
                    )}
                 </div>
               )}

               <div>
                 <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest block mb-1">Keterangan / Alasan</label>
                 <textarea
                   required
                   rows={3}
                   value={permissionForm.keterangan}
                   onChange={(e) => setPermissionForm({ ...permissionForm, keterangan: e.target.value })}
                   placeholder="Tulis alasan ketidakhadiran siswa di sini..."
                   className="w-full bg-slate-50 border border-slate-200 p-2.5 rounded-[var(--ui-radius-small)] text-xs font-semibold focus:outline-[var(--ui-primary)]"
                 />
               </div>

               <div className="text-[9px] font-bold text-amber-600 bg-amber-50 p-2.5 rounded-[var(--ui-radius-small)] border border-amber-100 leading-normal">
                 ⚠️ Catatan: Pengajuan ketidakhadiran dari halaman ini memerlukan persetujuan dari Tata Usaha atau Kesiswaan sebelum aktif di laporan rekapitulasi.
               </div>

               <div className="flex justify-end gap-2 pt-2 border-t border-slate-100">
                 <button 
                   type="button" 
                   onClick={() => setSelectedCell(null)}
                   disabled={isSubmittingCell}
                   className="px-3 py-1.5 text-xs font-bold rounded-md bg-slate-100 text-slate-700 hover:bg-slate-200 transition-colors disabled:opacity-50"
                 >
                   Batal
                 </button>
                 <button 
                   type="submit" 
                   disabled={isSubmittingCell}
                   className="px-3 py-1.5 text-xs font-black rounded-md bg-[var(--ui-primary)] text-white hover:opacity-90 transition-opacity disabled:opacity-50"
                 >
                   {isSubmittingCell ? "Menyimpan..." : "Simpan Pengajuan"}
                 </button>
               </div>
             </form>
           </div>
         </div>
       )}
        </>
      )}
      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.message}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import useAuthStore from '../../../store/monitoring/authStore';
import { AlertTriangle, CheckCircle2, Info, UserCheck, Briefcase, GraduationCap, Fingerprint } from 'lucide-react';
import * as XLSX from 'xlsx';
import { Link } from 'react-router-dom';
import { X, Users, Link2Off, RefreshCw, Wifi, Sparkles, Upload, CheckSquare, Search, AlertCircle } from 'lucide-react';
import { CustomSelect } from '../../../components/CustomSelect.jsx';
import { Modal } from '../../../components/ui.jsx';
import { PageHeader } from '../../../components/monitoring/ui/index.js';


// Toast
const Toast = ({ message, type, onClose }) => {
  if (!message) return null;
  const bg = { success: "bg-emerald-50 border-emerald-200 text-emerald-800", error: "bg-red-50 border-red-200 text-red-800", info: "bg-blue-50 border-blue-200 text-blue-800" };
  const Icon = type === 'success' ? CheckCircle2 : type === 'error' ? AlertTriangle : Info;
  const ic = { success: "text-emerald-500", error: "text-red-500", info: "text-blue-500" };
  return (
    <div className="fixed bottom-4 right-4 z-50 animate-in slide-in-from-bottom-5 fade-in duration-300">
      <div className={`flex items-center gap-3 px-4 py-3 rounded-[var(--ui-radius-small)] border shadow-sm ${bg[type] || bg.info} max-w-sm`}>
        <Icon size={20} className={ic[type] || ic.info} />
        <p className="text-sm font-bold flex-1">{message}</p>
        <button onClick={onClose} className="p-1 hover:bg-black/5 rounded-[var(--ui-radius-small)] transition-colors"><X size={16} /></button>
      </div>
    </div>
  );
};

// ── TAB SISWA ──────────────────────────────────────────────────────────────────
function TabSiswa({ classes, authToken, showToast }) {
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [search, setSearch] = useState("");
  const [groupFilter, setGroupFilter] = useState("all");
  const [saving, setSaving] = useState({});
  const [selectedNis, setSelectedNis] = useState(new Set());
  const [bulkClass, setBulkClass] = useState("");
  const [isBulkSaving, setIsBulkSaving] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const [importReview, setImportReview] = useState(null);
  const fileInputRef = useRef(null);
  const parentRef = useRef(null);

  const handleSync = async () => {
    setSyncing(true);
    try {
      const res = await fetch('/api/hikvision/sync-students', {
        method: 'POST',
        headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" }
      });
      const data = await res.json();
      if (data.ok) {
        showToast(data.message || 'Sinkronisasi siswa berhasil!', 'success');
        await fetchStudents();
      } else {
        showToast(data.error || 'Sinkronisasi gagal', 'error');
      }
    } catch (err) {
      showToast('Kesalahan jaringan saat sinkronisasi.', 'error');
    }
    setSyncing(false);
  };

  const fetchStudents = async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/hikvision/students?type=siswa", {
        headers: { "Authorization": `Bearer ${authToken}` }
      });
      const data = await res.json();
      if (data.ok) setStudents(data.data || []);
      else showToast(data.error || "Gagal memuat data siswa", "error");
    } catch (err) { showToast("Terjadi kesalahan jaringan.", "error"); }
    setLoading(false);
  };

  useEffect(() => { fetchStudents(); }, []);

  const handleClassChange = async (nis, newClassName) => {
    setSaving(prev => ({ ...prev, [nis]: true }));
    try {
      const res = await fetch(`/api/hikvision/students/${nis}`, {
        method: 'PUT',
        headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({ class_name: newClassName })
      });
      const data = await res.json();
      if (data.ok) {
        setStudents(prev => prev.map(s => s.nis === nis ? { ...s, class_name: newClassName } : s));
        showToast("Kelas berhasil diperbarui", "success");
      } else showToast(data.error || "Gagal menyimpan", "error");
    } catch (err) { showToast("Kesalahan jaringan.", "error"); }
    setSaving(prev => ({ ...prev, [nis]: false }));
  };

  const handleBulkApply = async () => {
    if (selectedNis.size === 0) return showToast("Pilih minimal 1 siswa.", "error");
    if (!bulkClass) return showToast("Pilih kelas yang ingin diterapkan.", "error");
    setIsBulkSaving(true);
    const updates = Array.from(selectedNis).map(nis => ({ nis, class_name: bulkClass }));
    try {
      const res = await fetch('/api/hikvision/students/bulk', {
        method: 'PUT',
        headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({ updates })
      });
      const data = await res.json();
      if (data.ok) {
        setStudents(prev => prev.map(s => selectedNis.has(s.nis) ? { ...s, class_name: bulkClass } : s));
        setSelectedNis(new Set());
        showToast("Berhasil memetakan kelas secara massal!", "success");
      } else showToast(data.error || "Gagal memetakan kelas", "error");
    } catch (err) { showToast("Kesalahan jaringan.", "error"); }
    setIsBulkSaving(false);
  };

  const handleAutoDetect = () => {
    const validClassesMap = new Map((classes || []).map(c => [c?.name ? String(c.name).trim().toLowerCase() : "", c?.name || ""]));
    const updates = [];
    (students || []).forEach(s => {
      if (s && s.group_name) {
        const gName = String(s.group_name).trim().toLowerCase();
        if (gName && validClassesMap.has(gName)) {
          const correctClassName = validClassesMap.get(gName);
          if (s.class_name !== correctClassName) updates.push({ nis: s.nis, class_name: correctClassName });
        }
      }
    });
    if (updates.length === 0) { showToast("Tidak ada kecocokan baru ditemukan.", "info"); return; }
    setImportReview({ updates, isAutoDetect: true });
  };

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const wb = XLSX.read(evt.target.result, { type: 'binary' });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1 });
        if (data.length === 0) { showToast("File kosong.", "error"); return; }
        const header = data[0].map(h => String(h).toLowerCase().trim());
        const nisIdx = header.findIndex(h => h.includes('nis') || h.includes('id'));
        const classIdx = header.findIndex(h => h.includes('kelas'));
        if (nisIdx === -1 || classIdx === -1) { showToast("Format Excel tidak valid. Pastikan ada kolom 'NIS' dan 'Kelas'.", "error"); return; }
        const updates = [];
        for (let i = 1; i < data.length; i++) {
          const row = data[i];
          if (row[nisIdx] && row[classIdx]) updates.push({ nis: String(row[nisIdx]).trim(), class_name: String(row[classIdx]).trim() });
        }
        if (updates.length === 0) { showToast("Tidak ada data valid.", "error"); return; }
        setImportReview({ updates });
      } catch (err) { showToast("Gagal membaca file Excel.", "error"); }
      finally { if (fileInputRef.current) fileInputRef.current.value = ""; }
    };
    reader.readAsBinaryString(file);
  };

  const executeBulkImport = async () => {
    if (!importReview) return;
    setIsBulkSaving(true);
    try {
      const res = await fetch('/api/hikvision/students/bulk', {
        method: 'PUT',
        headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({ updates: importReview.updates })
      });
      const json = await res.json();
      if (json.ok) {
        showToast(`Berhasil mengimport ${importReview.updates.length} pemetaan kelas!`, "success");
        setShowImportModal(false); setImportReview(null); fetchStudents();
      } else showToast(json.error || "Gagal import bulk", "error");
    } catch (err) { showToast("Kesalahan jaringan.", "error"); }
    setIsBulkSaving(false);
  };

  const filteredStudents = students.filter(s => {
    if (groupFilter !== "all" && s.group_name !== groupFilter) return false;
    if (search && !s.name?.toLowerCase().includes(search.toLowerCase()) && !s.nis?.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });
  const uniqueGroups = [...new Set(students.map(s => s.group_name).filter(Boolean))];
  const allSelected = filteredStudents.length > 0 && selectedNis.size === filteredStudents.length;

  const rowVirtualizer = useVirtualizer({
    count: filteredStudents.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 65,
    overscan: 10 });

  const connectedCount = students.filter(s => s.is_connected).length;
  const notConnectedCount = students.filter(s => !s.is_connected).length;

  return (
    <div className="space-y-4">
      {/* Info bar */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
        <div className="ui-card p-3 flex items-center gap-3">
          <div className="w-9 h-9 rounded-[var(--ui-radius-small)] bg-[var(--ui-primary)]/10 flex items-center justify-center">
            <Users size={18} className="text-[var(--ui-primary)]" />
          </div>
          <div>
            <p className="text-xs font-bold text-slate-400">Total Siswa</p>
            <p className="text-lg font-black text-slate-800">{students.length}</p>
          </div>
        </div>
        <div className="ui-card p-3 flex items-center gap-3">
          <div className="w-9 h-9 rounded-[var(--ui-radius-small)] bg-emerald-50 flex items-center justify-center">
            <Link size={18} className="text-emerald-600" />
          </div>
          <div>
            <p className="text-xs font-bold text-slate-400">Terhubung</p>
            <p className="text-lg font-black text-emerald-700">{connectedCount}</p>
          </div>
        </div>
        <div className="ui-card p-3 flex items-center gap-3">
          <div className="w-9 h-9 rounded-[var(--ui-radius-small)] bg-amber-50 flex items-center justify-center">
            <Link2Off size={18} className="text-amber-500" />
          </div>
          <div>
            <p className="text-xs font-bold text-slate-400">Belum Terhubung</p>
            <p className="text-lg font-black text-amber-600">{notConnectedCount}</p>
          </div>
        </div>
      </div>

      {/* toolbar */}
      <div className="flex gap-2 flex-wrap items-center">
        <button
          onClick={handleSync}
          disabled={syncing}
          className="flex items-center gap-2 px-4 py-2 bg-[var(--ui-primary)] text-white rounded-[var(--ui-radius-small)] hover:opacity-90 font-bold text-sm shadow-sm disabled:opacity-60"
        >
          {syncing
            ? <><RefreshCw size={16} className="animate-spin" /> Menyinkronkan...</>
            : <><Wifi size={16} /> Sinkron dari Mesin</>
          }
        </button>
        <button onClick={handleAutoDetect} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-[var(--ui-radius-small)] hover:bg-indigo-700 font-bold text-sm shadow-sm">
          <Sparkles size={16} /> Deteksi Otomatis
        </button>
        <button onClick={() => setShowImportModal(true)} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-[var(--ui-radius-small)] hover:bg-emerald-700 font-bold text-sm shadow-sm">
          <Upload size={16} /> Import Excel
        </button>
        <button onClick={fetchStudents} className="flex items-center gap-2 px-4 py-2 bg-slate-100 text-slate-700 rounded-[var(--ui-radius-small)] hover:bg-slate-200 font-bold text-sm">
          <RefreshCw size={16} className={loading ? "animate-spin" : ""} /> Refresh
        </button>
        <p className="text-xs text-slate-400 font-semibold ml-auto">Klik &quot;Sinkron dari Mesin&quot; untuk menarik data terbaru dari perangkat fingerprint bertipe Siswa.</p>
      </div>

      <div className="ui-card overflow-hidden">
        {/* Bulk bar */}
        {selectedNis.size > 0 && (
          <div className="bg-[var(--ui-primary)]/10 border-b border-[var(--ui-primary)]/20 p-3 px-4 flex flex-col md:flex-row items-center justify-between gap-4">
            <span className="text-sm font-bold text-[var(--ui-primary)] flex items-center gap-2">
              <CheckSquare size={16} /> {selectedNis.size} Siswa Terpilih
            </span>
            <div className="flex items-center gap-2 w-full md:w-auto">
              <div className="w-full md:w-56">
                <CustomSelect value={bulkClass} onChange={setBulkClass} options={[{ value: "", label: "-- Pilih Kelas --" }, ...(classes || []).map(c => ({ value: c.name, label: c.name }))]} />
              </div>
              <button onClick={handleBulkApply} disabled={isBulkSaving} className="px-6 py-2 bg-[var(--ui-primary)] text-white text-sm font-bold rounded-[var(--ui-radius-small)] hover:bg-[var(--ui-primary)]/90 disabled:opacity-50 flex items-center gap-2 whitespace-nowrap">
                {isBulkSaving && <RefreshCw size={14} className="animate-spin" />} Terapkan
              </button>
            </div>
          </div>
        )}
        {/* filter */}
        <div className="p-4 border-b border-slate-200 bg-slate-50/50 flex flex-col sm:flex-row gap-4">
          <div className="relative flex-1">
            <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input type="text" placeholder="Cari nama atau NIS..." value={search} onChange={e => setSearch(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-white border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-[var(--ui-primary)] shadow-sm" />
          </div>
          <div className="w-full sm:w-48">
            <CustomSelect value={groupFilter} onChange={setGroupFilter} options={[{ value: "all", label: "Semua Grup Mesin" }, ...(uniqueGroups || []).map(g => ({ value: g, label: g }))]} />
          </div>
        </div>
        {/* table */}
        <div ref={parentRef} className="overflow-x-auto overflow-y-auto max-h-[600px]">
          <table className="w-full text-left border-collapse">
            <thead className="sticky top-0 z-10 bg-slate-50 shadow-sm">
              <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 text-xs uppercase tracking-wider">
                <th className="px-4 py-3 w-12 text-center"><input type="checkbox" checked={allSelected} onChange={e => e.target.checked ? setSelectedNis(new Set(filteredStudents.map(s => s.nis))) : setSelectedNis(new Set())} className="w-4 h-4 rounded-[var(--ui-radius-small)]" /></th>
                <th className="px-2 py-3 font-black">No</th>
                <th className="px-4 py-3 font-black w-full">Nama / NIS</th>
                <th className="px-4 py-3 font-black">Grup Alat</th>
                <th className="px-4 py-3 font-black">Pemetaan Kelas</th>
              </tr>
            </thead>
            <tbody className="text-sm font-medium text-slate-700">
              {loading ? (
                <tr><td colSpan={5} className="px-4 py-8 text-center text-slate-500 font-bold">Memuat data siswa...</td></tr>
              ) : filteredStudents.length === 0 ? (
                <tr><td colSpan={5} className="px-4 py-8 text-center text-slate-500 font-bold">Tidak ada data siswa ditemukan.</td></tr>
              ) : (
                <>
                  {rowVirtualizer.getVirtualItems().length > 0 && (
                    <tr style={{ height: `${rowVirtualizer.getVirtualItems()[0].start}px` }}></tr>
                  )}
                  {rowVirtualizer.getVirtualItems().map((virtualRow) => {
                    const s = filteredStudents[virtualRow.index];
                    const idx = virtualRow.index;
                    return (
                      <tr key={virtualRow.key} data-index={virtualRow.index} ref={rowVirtualizer.measureElement} className={`border-b border-slate-100 hover:bg-slate-50/50 ${selectedNis.has(s.nis) ? 'bg-[var(--ui-primary)]/5' : ''}`}>
                        <td className="px-4 py-3 text-center"><input type="checkbox" checked={selectedNis.has(s.nis)} onChange={() => { const ns = new Set(selectedNis); ns.has(s.nis) ? ns.delete(s.nis) : ns.add(s.nis); setSelectedNis(ns); }} className="w-4 h-4 rounded-[var(--ui-radius-small)]" /></td>
                        <td className="px-2 py-3 font-bold text-slate-400">{idx + 1}</td>
                        <td className="px-4 py-3">
                          <div className="flex items-center gap-2">
                            <div className="font-bold text-slate-800 line-clamp-1">{s.name}</div>
                            {s.is_connected ? (
                              <span className="text-emerald-500 shrink-0 cursor-help" title="Data siswa terhubung dengan ID Mesin absensi."><CheckCircle2 size={14} strokeWidth={3} /></span>
                            ) : (
                              <span className="text-amber-500 shrink-0 cursor-help" title="Siswa belum terhubung dengan mesin absensi. Gunakan 'Deteksi Otomatis' atau 'Import Excel' untuk memetakan kelas agar terhubung."><AlertCircle size={14} strokeWidth={3} /></span>
                            )}
                          </div>
                          <div className="text-[11px] text-slate-500 font-semibold">{s.nis}</div>
