              <p className="text-sm font-bold opacity-80">Data pemetaan</p>
            </div>
            <div className="flex gap-3">
              <button disabled={isBulkSaving} onClick={() => setImportReview(null)} className="flex-1 py-2.5 bg-slate-100 text-slate-600 font-bold rounded-[var(--ui-radius-small)]">Batal</button>
              <button disabled={isBulkSaving} onClick={executeBulkImport} className="flex-1 py-2.5 bg-[var(--ui-primary)] text-white font-bold rounded-[var(--ui-radius-small)] flex items-center justify-center gap-2">
                {isBulkSaving && <RefreshCw size={16} className="animate-spin" />} Lanjutkan
              </button>
