  const tabs = [
    { id: "guru", label: "Data Guru", icon: Users, onClick: () => setActiveTab("guru"), isActive: activeTab === "guru" },
    { id: "karyawan", label: "Data Karyawan", icon: Briefcase, onClick: () => setActiveTab("karyawan"), isActive: activeTab === "karyawan" },
  ];

  return (
    <div className="flex flex-col gap-4 w-full h-full animate-in fade-in duration-300 relative z-10 ">

      <PageHeader 
        title="Data Guru & Karyawan"
        icon={Users}
        tabs={tabs}
        description="Kelola data induk guru dan karyawan di sekolah."
      />

      {/* Content Area */}
      <div className="flex-1 min-h-0 overflow-y-auto">
        {activeTab === "guru" && (
          <MasterDataGuru
            {...props}
            teachers={props.teachers}
            classes={props.classes}
            teacherTargetJpMap={props.teacherTargetJpMap}
            teacherScheduleCountMap={props.teacherScheduleCountMap}
            quickEditGuruCode={props.quickEditGuruCode}
            quickGuruForm={props.quickGuruForm}
            setQuickGuruForm={props.setQuickGuruForm}
            setQuickEditGuruCode={props.setQuickEditGuruCode}
            updateSelectionForTab={props.updateSelectionForTab}
            openModal={props.openModal}
            checkDependencies={props.checkDependencies}
            handleDelete={props.handleDelete}
            saveQuickEditGuru={props.saveQuickEditGuru}
            startQuickEditGuru={props.startQuickEditGuru}
            renderTable={props.renderTable}
          />
        )}
        {activeTab === "karyawan" && (
          <MasterDataKaryawan
            {...props}
            staffs={props.staffs}
            renderTable={props.renderTable}
          />
        )}
      </div>

    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { Building2 } from 'lucide-react';
import * as XLSX from 'xlsx';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { getMajorFullName } from '../../../utils/constants.js';
import { CheckCircle2, Clock, Upload, Download, Plus, Search, Loader2, MapPin, Badge, Edit3, Trash2, Users } from 'lucide-react';
import { PageHeader } from "../../../components/monitoring/ui/index.js";
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import ImportModal from "../../../components/monitoring/ui/ImportModal.jsx";
import { CustomSelect } from '../../../components/CustomSelect.jsx';


/**
 * admin/DataPerusahaan.jsx
 * Halaman daftar perusahaan mitra PKL dengan peta interaktif.
 */











delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png',
});



const JURUSAN_COLORS = { TJKT: '#15803d', Akuntansi: '#7c3aed', DKV: '#db2777' };

const createIcon = (color) => L.divIcon({
  className: '',
  html: `<div style="width:28px;height:28px;border-radius:50% 50% 50% 0;background:${color};transform:rotate(-45deg);border:2px solid white;boxShadow:0 2px 6px rgba(0,0,0,0.25)"></div>`,
  iconSize: [28, 28], iconAnchor: [14, 28], popupAnchor: [0, -30],
});

const DataPerusahaan = ({ students = [], readOnly, majors = [] }) => {
  const [locations, setLocations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filterJurusan, setFilterJurusan] = useState('Semua');
  const [filterVerified, setFilterVerified] = useState('Semua'); // 'Semua' | 'verified' | 'pending'
  const [view, setView] = useState('list'); // 'list' | 'map'
  const [showAddModal, setShowAddModal] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const [formData, setFormData] = useState({ id: null, nama_perusahaan: '', alamat: '', kota: '', bidang: '', telepon: '', jurusan: '', kuota: 0, lat: -6.2618, lng: 107.0005, kompetensi: [] });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const jurusanOptions = useMemo(() => {
    const fromSchool = majors || [];
    const fromLocations = locations.map(p => p.jurusan).filter(Boolean);
    return ['Semua', ...new Set([...fromSchool, ...fromLocations])];
  }, [majors, locations]);

  const fetchLocations = () => {
    setLoading(true);
    fetch('/api/pkl/locations', {
      headers: { 'Authorization': `Bearer ${JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken}` }
    })
    .then(res => res.json())
    .then(data => {
      if (data.ok) setLocations(data.data);
      setLoading(false);
    })
    .catch(() => setLoading(false));
  };

  useEffect(() => {
    fetchLocations();
  }, []);

  const handleAddSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      const isEdit = !!formData.id;
      const url = isEdit ? `/api/pkl/locations/${formData.id}` : '/api/pkl/locations';
      const method = isEdit ? 'PUT' : 'POST';
      const res = await fetch(url, {
        method: method,
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken}` 
        },
        body: JSON.stringify(formData)
      });
      if (res.ok) {
        setShowAddModal(false);
        fetchLocations();
        setFormData({ id: null, nama_perusahaan: '', alamat: '', kota: '', bidang: '', telepon: '', jurusan: '', kuota: 0, lat: -6.2618, lng: 107.0005, kompetensi: [] });
      }
    } catch (error) {
      console.error(error);
    }
    setIsSubmitting(false);
  };

  const handleEdit = (p) => {
    setFormData({
      id: p.id,
      nama_perusahaan: p.nama_perusahaan || '',
      alamat: p.alamat || '',
      kota: p.kota || '',
      bidang: p.bidang || '',
      telepon: p.telepon || '',
      jurusan: p.jurusan || '',
      kuota: p.kuota || 0,
      lat: p.lat || -6.2618,
      lng: p.lng || 107.0005,
      kompetensi: typeof p.kompetensi === 'string' ? JSON.parse(p.kompetensi || '[]') : (p.kompetensi || [])
    });
    setShowAddModal(true);
  };

  const handleDelete = async (id, nama) => {
    if (!(await window.confirmAsync(`Yakin ingin menghapus perusahaan ${nama}?`))) return;
    try {
      const res = await fetch(`/api/pkl/locations/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken}` }
      });
      if (res.ok) fetchLocations();
    } catch (err) {
      console.error(err);
    }
  };

  const filtered = locations.filter(p => {
    const matchSearch = p.nama_perusahaan.toLowerCase().includes(search.toLowerCase()) ||
      (p.alamat || '').toLowerCase().includes(search.toLowerCase());
    const matchJurusan = filterJurusan === 'Semua' || p.jurusan === filterJurusan;
    const matchVerified = filterVerified === 'Semua' || 
      (filterVerified === 'verified' && p.verified) || 
      (filterVerified === 'pending' && !p.verified);
    return matchSearch && matchJurusan && matchVerified;
  });

  const handleVerify = async (id, nama) => {
    if (!(await window.confirmAsync(`Verifikasi perusahaan "${nama}" sebagai mitra resmi? Status akan berubah menjadi Terverifikasi.`))) return;
    try {
      const res = await fetch(`/api/pkl/locations/${id}/verify`, {
        method: 'PUT',
        headers: { 'Authorization': `Bearer ${JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken}` }
      });
      if (res.ok) fetchLocations();
    } catch (err) { console.error(err); }
  };

  const handleExport = () => {
    const exportData = filtered.map(p => ({
      ID: p.id,
      "Nama Perusahaan": p.nama_perusahaan,
      Alamat: p.alamat,
      Kota: p.kota,
      Telepon: p.telepon,
      "Bidang Usaha": p.bidang,
      Jurusan: p.jurusan,
      Kuota: p.kuota
    }));
    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Perusahaan PKL");
    XLSX.writeFile(wb, "Data_Perusahaan_PKL.xlsx");
  };

  const handleDownloadTemplate = () => {
    const templateData = [
      {
        'Nama Perusahaan': 'PT Inovasi Teknologi',
        'Alamat': 'Jl. Sudirman No 123',
        'Kota': 'Jakarta',
        'Telepon': '021-123456',
        'Bidang Usaha': 'IT / Software',
        'Jurusan': 'RPL',
        'Kuota': 5
      }
    ];
    const ws = XLSX.utils.json_to_sheet(templateData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Template Perusahaan");
    XLSX.writeFile(wb, "Template_Master_Perusahaan.xlsx");
  };

  const handleProcessImport = async (jsonData) => {
    let successCount = 0;

    // We process sequentially so we don't overwhelm the backend if there are many rows.
    for (const row of jsonData) {
      const payload = {
        nama_perusahaan: row['Nama Perusahaan'] || row['nama_perusahaan'] || '',
        alamat: row['Alamat'] || row['alamat'] || '',
        kota: row['Kota'] || row['kota'] || '',
        telepon: row['Telepon'] || row['telepon'] || '',
        bidang: row['Bidang Usaha'] || row['Bidang'] || row['bidang'] || '',
        jurusan: row['Jurusan'] || row['jurusan'] || 'Semua',
        kuota: parseInt(row['Kuota'] || row['kuota']) || 0,
        lat: -6.2618,
        lng: 107.0005,
        kompetensi: []
      };

      if (!payload.nama_perusahaan) continue;

      try {
        const res = await fetch('/api/pkl/locations', {
          method: 'POST',
          headers: { 
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken}` 
          },
          body: JSON.stringify(payload)
        });
        if (res.ok) successCount++;
      } catch (err) {
        console.error("Gagal menyimpan row", payload.nama_perusahaan, err);
      }
    }

    showToast(`Berhasil menyimpan ${successCount} data perusahaan baru.`);
    fetchLocations();
  };

  return (
    <div className="space-y-4">
      <PageHeader
        icon={Building2}
        title="Data Perusahaan PKL"
        description={
          <div className="flex flex-wrap items-center gap-3">
            <span>{loading ? "Memuat..." : `${locations.length} mitra terdaftar`}</span>
            {!loading && (
              <>
                <span className="text-[10px] bg-white/20 text-white font-bold px-2 py-0.5 rounded-[var(--ui-radius-small)] flex items-center gap-1 backdrop-blur-sm border border-white/20">
                  <CheckCircle2 size={10} /> {locations.filter(l => l.verified).length} Terverifikasi
                </span>
                {locations.filter(l => !l.verified).length > 0 && (
                  <span className="text-[10px] bg-white/20 text-white font-bold px-2 py-0.5 rounded-[var(--ui-radius-small)] flex items-center gap-1 backdrop-blur-sm border border-white/20">
                    <Clock size={10} /> {locations.filter(l => !l.verified).length} Menunggu
                  </span>
                )}
              </>
            )}
          </div>
        }
      >
        <div className="flex flex-wrap items-center gap-2">
          {!readOnly && (
            <button onClick={() => setShowImportModal(true)} className="px-4 py-2 bg-white/10 hover:bg-white/20 text-white border border-white/20 text-sm font-semibold rounded-[var(--ui-radius-small)] transition-all flex items-center gap-1.5 backdrop-blur-sm cursor-pointer">
              <Upload size={16} /> Impor
            </button>
          )}
          <button onClick={handleExport} className="px-4 py-2 bg-white hover:bg-slate-50 text-[var(--ui-primary)] text-sm font-semibold rounded-[var(--ui-radius-small)] transition-all flex items-center gap-1.5 cursor-pointer shadow-sm border-none">
            <Download size={16} /> Ekspor
          </button>
          {!readOnly && (
            <button onClick={() => { setFormData({ id: null, nama_perusahaan: '', alamat: '', kota: '', bidang: '', telepon: '', jurusan: '', kuota: 0, lat: -6.2618, lng: 107.0005, kompetensi: [] }); setShowAddModal(true); }} className="px-4 py-2 bg-white/10 hover:bg-white/20 text-white border border-white/20 text-sm font-semibold rounded-[var(--ui-radius-small)] transition-all flex items-center gap-1.5 backdrop-blur-sm cursor-pointer">
              <Plus size={16} /> Tambah
            </button>
          )}
          <div className="flex border border-white/20 rounded-[var(--ui-radius-small)] overflow-hidden shadow-sm backdrop-blur-sm ml-2">
            <button onClick={() => setView('list')}
              className={`px-4 py-2 text-sm font-semibold transition-all cursor-pointer border-none ${view === 'list' ? 'bg-white text-[var(--ui-primary)]' : 'bg-white/10 text-white hover:bg-white/20'}`}>
              Daftar
            </button>
            <button onClick={() => setView('map')}
              className={`px-4 py-2 text-sm font-semibold transition-all cursor-pointer border-none ${view === 'map' ? 'bg-white text-[var(--ui-primary)]' : 'bg-white/10 text-white hover:bg-white/20'}`}>
              Peta
            </button>
          </div>
        </div>
      </PageHeader>

      {/* Filters */}
      <div className="ui-card p-4 flex flex-col lg:flex-row gap-4 items-center justify-between">
        <div className="relative flex-1 w-full">
          <Search size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            value={search} 
            onChange={e => setSearch(e.target.value)}
            placeholder="Cari perusahaan atau alamat..."
            className="w-full pl-10 pr-4 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:bg-white focus:ring-1 focus:ring-[var(--ui-primary)]" 
          />
        </div>
        <div className="flex flex-wrap items-center gap-3 shrink-0 w-full lg:w-auto justify-start lg:justify-end">
          <div className="flex flex-wrap gap-1.5">
            {['Semua', 'verified', 'pending'].map(f => (
              <button key={f} onClick={() => setFilterVerified(f)}
                className={`px-3 py-2 text-xs font-semibold rounded-[var(--ui-radius-small)] transition-all whitespace-nowrap flex items-center gap-1 ${
                  filterVerified === f ? 'bg-slate-700 text-white shadow-sm' : 'bg-slate-50 border-none text-gray-600 hover:bg-slate-100'
                }`}>
                {f === 'verified' && <CheckCircle2 size={11} />}
                {f === 'pending' && <Clock size={11} />}
                {f === 'Semua' ? 'Semua Status' : f === 'verified' ? 'Terverifikasi' : 'Menunggu Verifikasi'}
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-1.5 border-l border-slate-200 pl-3">
            {jurusanOptions.map(j => (
              <button key={j} onClick={() => setFilterJurusan(j)}
                className={`px-3.5 py-2 text-xs font-semibold rounded-[var(--ui-radius-small)] transition-all whitespace-nowrap ${
                  filterJurusan === j ? 'bg-[var(--ui-primary)] text-white shadow-sm' : 'bg-slate-50 border-none text-gray-600 hover:bg-slate-100'
                }`}>{j}</button>
            ))}
          </div>
        </div>
      </div>

      {loading ? (
        <div className="ui-card flex items-center justify-center py-12">
          <Loader2 className="animate-spin text-[var(--ui-primary)]" size={32} />
        </div>
      ) : view === 'list' ? (
        <div className="ui-card overflow-hidden">
          <div className="divide-y divide-slate-100">
            {filtered.length === 0 && (
              <div className="py-12 px-4 flex flex-col items-center justify-center text-slate-500">
                <Building2 size={32} className="text-slate-300 mb-2" />
                <p className="text-sm font-medium">Tidak ada data ditemukan.</p>
              </div>
            )}
            {filtered.map(p => {
              let kompetensi = [];
              try { kompetensi = typeof p.kompetensi === 'string' ? JSON.parse(p.kompetensi) : p.kompetensi; } catch(e){ /* ignore */ }
              const jurusanColor = JURUSAN_COLORS[p.jurusan] || '#64748b';
              const terisi = students.filter(s => s.perusahaanId === p.id).length;
              const kuota = p.kuota || 0;
              const percent = kuota > 0 ? Math.min(100, Math.round((terisi / kuota) * 100)) : 0;
              const isFull = kuota > 0 && terisi >= kuota;

              return (
                <div key={p.id} className={`flex items-center gap-4 px-5 py-4 hover:bg-slate-50/50 transition-colors border-b border-slate-50 last:border-0 ${!p.verified ? 'bg-amber-50/30' : ''}`}>
                  <div className="w-10 h-10 rounded-[var(--ui-radius-small)] flex items-center justify-center flex-shrink-0"
                    style={{ backgroundColor: jurusanColor + '20' }}>
                    <Building2 size={18} style={{ color: jurusanColor }} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <p className="font-semibold text-slate-800">{p.nama_perusahaan}</p>
                      {p.verified 
                        ? <span className="text-[9px] bg-emerald-100 text-emerald-700 font-bold px-1.5 py-0.5 rounded-[var(--ui-radius-small)] flex items-center gap-0.5"><CheckCircle2 size={9}/> Terverifikasi</span>
                        : <span className="text-[9px] bg-amber-100 text-amber-700 font-bold px-1.5 py-0.5 rounded-[var(--ui-radius-small)] flex items-center gap-0.5"><Clock size={9}/> Diajukan Siswa – Belum Diverifikasi</span>
                      }
                    </div>
                    <div className="flex items-center gap-1.5 mt-0.5">
                      <MapPin size={11} className="text-slate-400 flex-shrink-0" />
                      <p className="text-xs text-slate-400 truncate">{p.alamat || 'Alamat belum diatur'}</p>
                    </div>
                    {kompetensi && kompetensi.length > 0 && (
                      <div className="flex flex-wrap gap-1 mt-1.5">
                        {kompetensi.map(k => (
                          <span key={k} className="text-[10px] bg-gray-100 text-gray-600 px-2 py-0.5 rounded-[var(--ui-radius-small)] font-medium">{k}</span>
                        ))}
                      </div>
                    )}
                  </div>
                  <div className="w-40 flex-shrink-0 flex flex-col items-end space-y-2">
                    {p.jurusan && <Badge variant={p.jurusan} label={p.jurusan} withDot={false} />}
                    <div className="w-full mt-1 flex flex-col items-end gap-1">
                      <div className="flex items-center justify-between w-full text-[10px] font-bold">
                        <span className="text-slate-500">Kapasitas</span>
                        <span className={isFull ? 'text-red-600' : 'text-emerald-600'}>{terisi} / {kuota}</span>
                      </div>
                      <div className="w-full h-1.5 bg-slate-100 rounded-[var(--ui-radius-small)] overflow-hidden">
                        <div className={`h-full rounded-[var(--ui-radius-small)] transition-all ${isFull ? 'bg-red-500' : 'bg-emerald-500'}`} style={{ width: `${percent}%` }}></div>
                      </div>
                    </div>
                    {!readOnly && (
                      <div className="flex gap-2 mt-2 flex-wrap justify-end">
                        {!p.verified && (
                          <button onClick={() => handleVerify(p.id, p.nama_perusahaan)} className="p-1.5 text-emerald-600 hover:bg-emerald-50 rounded-[var(--ui-radius-small)] transition-colors" title="Verifikasi sebagai mitra resmi">
                            <CheckCircle2 size={14} />
                          </button>
                        )}
                        <button onClick={() => handleEdit(p)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-[var(--ui-radius-small)] transition-colors" title="Edit">
                          <Edit3 size={14} />
                        </button>
                        <button onClick={() => handleDelete(p.id, p.nama_perusahaan)} className="p-1.5 text-red-600 hover:bg-red-50 rounded-[var(--ui-radius-small)] transition-colors" title="Hapus">
                          <Trash2 size={14} />
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ) : (
        <div className="ui-card overflow-hidden h-[500px]">
          <MapContainer center={[-6.2618, 107.0005]} zoom={12}
            style={{ height: '100%', width: '100%' }} scrollWheelZoom={false}>
            <TileLayer
              attribution='&copy; OpenStreetMap'
              url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
            {filtered.map(p => (
              <Marker key={p.id} position={[p.lat || -6.2618, p.lng || 107.0005]}
                icon={createIcon(JURUSAN_COLORS[p.jurusan] || '#15803d')}>
                <Popup>
                  <div className="min-w-[200px]" style={{ fontFamily: 'Lexend, sans-serif' }}>
                    <p className="font-bold text-sm text-gray-900 mb-1">{p.nama_perusahaan}</p>
                    <p className="text-xs text-gray-500 mb-2">{p.alamat || 'Alamat tidak tersedia'}</p>
                    <div className="flex items-center gap-1.5 text-xs text-green-700 font-semibold">
                      <Users size={11} /> {p.kuota || 0} kuota
                    </div>
                  </div>
                </Popup>
              </Marker>
            ))}
          </MapContainer>
        </div>
      )}

      {/* Add Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
          <div className="bg-white rounded-[var(--ui-radius-small)] shadow-sm w-full max-w-md overflow-hidden">
            <div className="px-5 py-4 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-800">{formData.id ? 'Edit Perusahaan' : 'Tambah Perusahaan'}</h3>
              <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-slate-600">&times;</button>
            </div>
            <form onSubmit={handleAddSubmit} className="p-5 space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1.5">Nama Perusahaan</label>
                <input required type="text" value={formData.nama_perusahaan} onChange={e => setFormData({...formData, nama_perusahaan: e.target.value})} className="w-full px-3 py-2 text-sm border-none rounded-[var(--ui-radius-small)] focus:border-[var(--ui-primary)] focus:ring-1 focus:ring-[var(--ui-primary)] outline-none" placeholder="PT Contoh Maju" />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1.5">Alamat Lengkap</label>
                <textarea required value={formData.alamat} onChange={e => setFormData({...formData, alamat: e.target.value})} className="w-full px-3 py-2 text-sm border-none rounded-[var(--ui-radius-small)] focus:border-[var(--ui-primary)] focus:ring-1 focus:ring-[var(--ui-primary)] outline-none" rows="2" placeholder="Jl. Raya No. 123"></textarea>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1.5">Jurusan Prioritas</label>
                  <CustomSelect 
                    value={formData.jurusan} 
                    onChange={val => setFormData({...formData, jurusan: val})}
                    options={[
                      { value: "", label: "-- Pilih --" },
                      ...jurusanOptions.filter(j => j !== 'Semua').map(j => ({ value: j, label: `${j} - ${getMajorFullName(j)}` }))
                    ]}
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1.5">Kuota Siswa</label>
                  <input type="text" inputMode="numeric" value={formData.kuota} onChange={e => setFormData({...formData, kuota: e.target.value.replace(/[^0-9]/g, '')})} className="w-full px-3 py-2 text-sm border-none rounded-[var(--ui-radius-small)] focus:border-[var(--ui-primary)] focus:ring-1 focus:ring-[var(--ui-primary)] outline-none" />
                </div>
              </div>
              <div className="pt-2 flex justify-end gap-2">
                <button type="button" onClick={() => setShowAddModal(false)} className="px-4 py-2 text-sm font-semibold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-[var(--ui-radius-small)] transition-colors">Batal</button>
                <button type="submit" disabled={isSubmitting} className="px-4 py-2 text-sm font-semibold text-white bg-[var(--ui-primary)] hover:opacity-90 rounded-[var(--ui-radius-small)] transition-colors disabled:opacity-50">
                  {isSubmitting ? 'Menyimpan...' : 'Simpan'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showImportModal && (
        <ImportModal
          isOpen={showImportModal}
          onClose={() => setShowImportModal(false)}
          title="Import Data Perusahaan PKL"
          expectedColumns={['Nama Perusahaan', 'Alamat', 'Kota', 'Telepon', 'Bidang Usaha', 'Jurusan', 'Kuota']}
          guideText="Data perusahaan akan ditambahkan (menjadi data baru). Sistem tidak menimpa data perusahaan secara otomatis berdasarkan nama karena ada kemungkinan nama perusahaan sama untuk cabang berbeda."
          onDownloadTemplate={handleDownloadTemplate}
          onImport={handleProcessImport}
          onExportCurrent={handleExport}
        />
      )}
      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          <CheckCircle2 size={18} /> {toast.message}
        </div>
      )}
    </div>
  );
};

export default DataPerusahaan;

import { useState, useMemo, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { Users, CheckCircle2, XCircle } from 'lucide-react';
import * as XLSX from 'xlsx';
import useAuthStore from '../../../store/monitoring/authStore';
import { getDatabaseSnapshot, setDatabaseSnapshot } from '../../../utils/dataSource';
import { ChevronDown, Settings, Save, Upload, Download, Search, Badge, ChevronRight, X, AlertCircle } from 'lucide-react';
import { PageHeader, StatCard, Avatar } from '../../../components/monitoring/ui/index.js';


/**
 * admin/DataSiswa.jsx
 * Halaman manajemen data siswa PKL dengan search, filter jurusan, dan detail.
 */














const ClickPicker = ({ value, onChange, options, placeholder = "Pilih..." }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const ref = useRef(null);

  useEffect(() => {
    const handleOutsideClick = (e) => {
      if (ref.current && !ref.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, []);

  const filteredOptions = options.filter(opt => 
    opt.label.toLowerCase().includes(search.toLowerCase())
  );

  const selectedOpt = options.find(o => String(o.value) === String(value));

  return (
    <div className="relative" ref={ref}>
      <button
        type="button"
        onClick={() => { setIsOpen(!isOpen); setSearch(''); }}
        className="w-full text-left px-3 py-2 border-none bg-slate-50 hover:bg-white rounded-[var(--ui-radius-small)] text-xs font-bold flex justify-between items-center transition-colors focus:outline-[var(--ui-primary)] cursor-pointer"
      >
        <span className={selectedOpt ? "text-slate-800 font-bold" : "text-slate-400"}>
          {selectedOpt ? selectedOpt.label : placeholder}
        </span>
        <ChevronDown size={14} className="text-slate-400" />
      </button>

      {isOpen && (
        <div className="absolute z-[60] mt-1 w-full bg-white border-none rounded-[var(--ui-radius-small)] shadow-sm max-h-60 overflow-hidden flex flex-col">
          <div className="p-2 border-b border-slate-100 bg-slate-50 shrink-0">
            <input
              type="text"
              autoFocus
              placeholder="Cari..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full px-2.5 py-1.5 text-xs border-none rounded-[var(--ui-radius-small)] focus:outline-none focus:ring-1 focus:ring-[var(--ui-primary)] focus:border-[var(--ui-primary)]"
            />
          </div>
          <div className="overflow-y-auto flex-1 py-1 custom-scrollbar">
            {filteredOptions.length === 0 ? (
              <div className="px-3 py-2 text-xs text-slate-400 text-center">Tidak ditemukan</div>
            ) : (
              filteredOptions.map(opt => (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => {
                    onChange(opt.value);
                    setIsOpen(false);
                  }}
                  className={`w-full text-left px-3 py-2 text-xs font-semibold hover:bg-slate-50 transition-colors flex items-center justify-between border-none cursor-pointer ${
                    String(opt.value) === String(value) ? 'bg-[var(--ui-primary)]/5 text-[var(--ui-primary)] font-bold' : 'text-slate-700 bg-transparent'
                  }`}
                >
                  <span>{opt.label}</span>
                  {String(opt.value) === String(value) && (
                    <span className="w-1.5 h-1.5 rounded-[var(--ui-radius-small)] bg-[var(--ui-primary)]"></span>
                  )}
                </button>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const DataSiswa = ({ students = [], teachers = [], appSettings, setAppSettings, onSave, setActiveTab }) => {
  const navigate = useNavigate();
  const [search, setSearch]         = useState('');
  const [filterJurusan, setFilterJurusan] = useState('Semua');
  const [filterKelas, setFilterKelas] = useState('Semua');
  const [selectedSiswa, setSelectedSiswa] = useState(null);

  const [eligibleClass, setEligibleClass] = useState("XII");

  const statusOptions  = ['Semua', 'hadir', 'absen', 'terlambat', 'izin', 'belum_absen'];

  const authToken = useAuthStore(state => state.user?.authToken);
  
  const [perusahaanPKL, setPerusahaanPKL] = useState([]);
  const [pklStudentsMapping, setPklStudentsMapping] = useState([]);
  const [isSavingSettings, setIsSavingSettings] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  useEffect(() => {
    fetch("/api/monitoring/lokasi-pkl/public")
      .then(res => res.json())
      .then(data => { if (data.ok) setPerusahaanPKL(data.data); })
      .catch(console.error);
      
    // Load eligibleClass from local appSettings
    const localSnapshot = getDatabaseSnapshot() || {};
    const localSettings = localSnapshot.appSettings || {};
    setEligibleClass(localSettings.eligibleClass || "XII");
        
    if (authToken) {
      fetch("/api/monitoring/pkl-students", { headers: { "Authorization": `Bearer ${authToken}` } })
        .then(res => res.json())
        .then(data => { if (data.ok) setPklStudentsMapping(data.data); })
        .catch(console.error);
    }
  }, [authToken]);

  const saveSettings = async () => {
    setIsSavingSettings(true);
    try {
      const localSnapshot = getDatabaseSnapshot() || {};
      const newSettings = { ...(localSnapshot.appSettings || {}), eligibleClass };
      const updatedSnapshot = { ...localSnapshot, appSettings: newSettings };
      
      // Update local storage / global state
      setDatabaseSnapshot(updatedSnapshot);
      if (setAppSettings) setAppSettings(newSettings);
      if (onSave) await onSave(updatedSnapshot);
      showToast("Pengaturan kelas PKL berhasil disimpan!");
    } catch (e) {
      showToast("Gagal menyimpan pengaturan", "error");
    }
    setIsSavingSettings(false);
  };

  const pklStudents = useMemo(() => {
     return students.filter(s => s.class_name && s.class_name.toUpperCase().startsWith(eligibleClass.toUpperCase()))
        .map(s => {
           const mapping = pklStudentsMapping.find(m => m.nis === s.nis) || {};
            return {
               id: s.nis,
               nis: s.nis,
               nama: s.name,
               kelas: s.class_name,
               jurusan: s.class_name.split(' ')[1] || 'Umum',
               perusahaanId: mapping.location_id,
               guruPembimbingCode: mapping.teacher_code,
               statusPKL: mapping.location_id ? 'Sudah PKL' : 'Belum PKL',
               lamaPKL: mapping.location_id ? '6 Bulan' : '-'
            };
        });
  }, [students, eligibleClass, pklStudentsMapping]);

  const jurusanOptions = useMemo(() => ['Semua', ...Array.from(new Set(pklStudents.map(s => s.jurusan))).filter(Boolean)], [pklStudents]);
  const kelasOptions = useMemo(() => ['Semua', ...Array.from(new Set(pklStudents.map(s => s.kelas))).filter(Boolean)], [pklStudents]);

  const filtered = useMemo(() => {
    return pklStudents.filter((s) => {
      const matchSearch =
        s.nama.toLowerCase().includes(search.toLowerCase()) ||
        s.nis.includes(search);
      const matchJurusan = filterJurusan === 'Semua' || s.jurusan === filterJurusan;
      const matchKelas = filterKelas === 'Semua' || s.kelas === filterKelas;
      return matchSearch && matchJurusan && matchKelas;
    });
  }, [pklStudents, search, filterJurusan, filterKelas]);

  const stats = [
    { label: 'Total Siswa PKL', value: pklStudents.length, icon: Users, iconBg: 'bg-blue-100', iconColor: 'text-blue-600' },
    { label: 'Sudah PKL', value: pklStudents.filter(s => s.statusPKL === 'Sudah PKL').length, icon: CheckCircle2, iconBg: 'bg-emerald-100', iconColor: 'text-emerald-600' },
    { label: 'Belum PKL', value: pklStudents.filter(s => s.statusPKL === 'Belum PKL').length, icon: XCircle, iconBg: 'bg-red-100', iconColor: 'text-red-600' },
  ];

  const handleExport = () => {
    const exportData = filtered.map(s => {
      const guru = teachers.find(g => g.code === s.guruPembimbingCode);
      const perusahaan = perusahaanPKL.find(p => p.id === s.perusahaanId);
      return {
        NIS: s.nis,
        Nama: s.nama,
        Kelas: s.kelas,
        Jurusan: s.jurusan,
        "Perusahaan PKL": perusahaan?.nama_perusahaan || "Belum Ditempatkan",
        "Guru Pembimbing": guru?.name || "Belum Ditugaskan",
        "Status PKL": s.statusPKL,
        "Lama PKL": s.lamaPKL
      };
    });
    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Siswa PKL");
    XLSX.writeFile(wb, `Data_Siswa_PKL_${eligibleClass}.xlsx`);
  };

  return (
    <div className="space-y-4">
      <PageHeader
        icon={Users}
        title="Data Siswa PKL"
        description={`${pklStudents.length} siswa kelas ${eligibleClass} sinkron otomatis dari Master Data`}
      >
        <div className="flex flex-col sm:flex-row items-center gap-3">
           <div className="bg-white/10 backdrop-blur-sm border border-white/20 px-3 py-1.5 rounded-[var(--ui-radius-small)] flex items-center gap-2.5 shadow-sm">
             <Settings size={15} className="text-white"/>
             <span className="text-[11px] font-bold text-white uppercase tracking-wider">Kelas PKL:</span>
             <div className="flex bg-white/10 p-0.5 rounded-[var(--ui-radius-small)] border-none">
                {["X", "XI", "XII"].map(lvl => (
                  <button
                    key={lvl}
                    type="button"
                    onClick={() => setEligibleClass(lvl)}
                    className={`px-3 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold transition-all border-none cursor-pointer ${
                      eligibleClass === lvl
                        ? 'bg-white text-[var(--ui-primary)] shadow-sm'
                        : 'text-white/80 hover:text-white bg-transparent'
                    }`}
                  >
                    {lvl}
                  </button>
                ))}
              </div>
             <button onClick={saveSettings} disabled={isSavingSettings} className="bg-white/20 text-white rounded-[var(--ui-radius-small)] p-1 hover:bg-white/30 disabled:opacity-50 transition-colors ml-1 cursor-pointer border-none" title="Simpan Pengaturan Kelas">
                <Save size={13} />
             </button>
           </div>
           
           <div className="flex items-center gap-2">
              <button onClick={() => {
                if (setActiveTab) {
                  setActiveTab('pkl_import');
                } else {
                  navigate('/monitoring/import');
                }
              }} className="px-4 py-2 bg-white/10 hover:bg-white/20 text-white border border-white/20 text-sm font-semibold rounded-[var(--ui-radius-small)] transition-all flex items-center gap-1.5 cursor-pointer backdrop-blur-sm">
               <Upload size={16} /> Impor
             </button>
             <button onClick={handleExport} className="px-4 py-2 bg-white hover:bg-slate-50 text-[var(--ui-primary)] text-sm font-semibold rounded-[var(--ui-radius-small)] transition-all flex items-center gap-1.5 cursor-pointer shadow-sm border-none">
               <Download size={16} /> Ekspor
             </button>
           </div>
        </div>
      </PageHeader>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        {stats.map(s => <StatCard key={s.label} {...s} />)}
      </div>

      {/* Filter Bar - Click Based pills */}
      <div className="ui-card p-4 space-y-3">
        <div className="relative">
          <Search size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Cari nama atau NIS..."
            className="w-full pl-10 pr-4 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:bg-white focus:ring-1 focus:ring-[var(--ui-primary)]"
          />
        </div>
        <div className="flex flex-col gap-3 pt-1 border-t border-slate-100">
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest min-w-[70px]">Kelas:</span>
            <div className="flex flex-wrap gap-1.5">
              {kelasOptions.map(k => (
                <button
                  key={k}
                  type="button"
                  onClick={() => setFilterKelas(k)}
                  className={`px-3 py-1 rounded-[var(--ui-radius-small)] text-xs font-bold transition-all border cursor-pointer ${
                    filterKelas === k
                      ? 'bg-[var(--ui-primary)] border-[var(--ui-primary)] text-white shadow-sm'
                      : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                  }`}
                >
                  {k === 'Semua' ? 'Semua Kelas' : k}
                </button>
              ))}
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest min-w-[70px]">Jurusan:</span>
            <div className="flex flex-wrap gap-1.5">
              {jurusanOptions.map(j => (
                <button
                  key={j}
                  type="button"
                  onClick={() => setFilterJurusan(j)}
                  className={`px-3 py-1 rounded-[var(--ui-radius-small)] text-xs font-bold transition-all border cursor-pointer ${
                    filterJurusan === j
                      ? 'bg-[var(--ui-primary)] border-[var(--ui-primary)] text-white shadow-sm'
                      : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                  }`}
                >
                  {j === 'Semua' ? 'Semua Jurusan' : j}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="ui-card overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 text-[11px] font-bold uppercase tracking-wider">
                <th className="px-3 py-2 text-left">Siswa</th>
                <th className="px-4 py-3 text-left">Jurusan</th>
                <th className="px-4 py-3 text-left hidden md:table-cell">Perusahaan</th>
                <th className="px-4 py-3 text-left hidden lg:table-cell">Guru Pembimbing</th>
                <th className="px-4 py-3 text-center">Status PKL</th>
                <th className="px-4 py-3 text-center">Lama PKL</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {filtered.map(s => {
                const guru = teachers.find(g => g.code === s.guruPembimbingCode);
                const perusahaan = perusahaanPKL.find(p => p.id === s.perusahaanId);
                return (
                  <tr key={s.id} className="hover:bg-slate-50/50 transition-colors border-b border-slate-50 last:border-0">
                    <td className="px-3 py-2">
                      <div className="flex items-center gap-3">
                        <Avatar name={s.nama} size="xs" />
                        <div>
                          <p className="font-bold text-slate-800 text-[13px]">{s.nama}</p>
                          <p className="text-[11px] font-medium text-slate-500 mt-0.5">{s.nis} - {s.kelas}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-3 py-2">
                      <Badge variant={s.jurusan} label={s.jurusan} withDot={false} />
                    </td>
                    <td className="px-3 py-2 hidden md:table-cell">
                      <p className="text-xs font-medium text-slate-700 max-w-[180px] truncate">
                        {perusahaan?.nama_perusahaan || '-'}
                      </p>
                    </td>
                    <td className="px-3 py-2 hidden lg:table-cell">
                      <p className="text-xs font-medium text-slate-700 truncate max-w-[150px]">
                        {guru?.name || <span className="text-amber-600 text-xs font-medium">Belum ditugaskan</span>}
                      </p>
                    </td>
                    <td className="px-3 py-2 text-center">
                      <span className={`px-2 py-0.5 text-[10px] font-bold rounded-[var(--ui-radius-small)] border ${s.statusPKL === 'Sudah PKL' ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-red-50 text-red-600 border-red-200'}`}>
                        {s.statusPKL}
                      </span>
                    </td>
                    <td className="px-3 py-2 text-center">
                      <span className="text-[10px] font-bold text-slate-700 bg-slate-100 px-2 py-0.5 rounded-[var(--ui-radius-small)] border-none">
                        {s.lamaPKL}
                      </span>
                    </td>
                    <td className="px-3 py-2 text-right">
                      <button onClick={() => setSelectedSiswa(s)}
                        className="flex items-center justify-center gap-1.5 px-3 py-1.5 text-[11px] font-bold text-[var(--ui-primary)] bg-[var(--ui-primary)]/10 hover:bg-[var(--ui-primary)]/20 rounded-[var(--ui-radius-small)] transition-all ml-auto">
                        Detail <ChevronRight size={13} />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        {filtered.length === 0 && (
          <div className="py-16 text-center text-slate-400">
            <Users size={32} className="mx-auto mb-3 text-gray-300" />
            <p className="font-semibold">Tidak ada siswa ditemukan</p>
          </div>
        )}
      </div>

      {/* Detail Panel (slide-over) */}
      {selectedSiswa && (
        <div className="fixed inset-0 z-50 flex justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity"
            onClick={() => setSelectedSiswa(null)} />
          <div className="relative bg-[#f8fafc] w-full max-w-sm h-full overflow-y-auto shadow-2xl z-10 p-4 sm:p-5 flex flex-col space-y-4 animate-in slide-in-from-right-full duration-300">
            <div className="flex items-center justify-between pb-3 border-b border-slate-200/60 shrink-0">
              <h2 className="font-bold text-slate-800 text-base">Detail Siswa</h2>
              <button onClick={() => setSelectedSiswa(null)}
                className="p-1.5 rounded-[var(--ui-radius-small)] hover:bg-slate-200/50 text-slate-400 hover:text-slate-800 transition-colors">
                <X size={18} />
              </button>
            </div>

            <div className="ui-card p-4 flex flex-col items-center text-center">
              <Avatar name={selectedSiswa.nama} size="lg" className="mb-3 shadow-sm" />
              <p className="font-extrabold text-lg text-slate-800 tracking-tight">{selectedSiswa.nama}</p>
              <p className="text-sm font-semibold text-slate-400 mt-0.5">{selectedSiswa.kelas}</p>
              <Badge variant={selectedSiswa.jurusan} label={selectedSiswa.jurusan} withDot={false} className="mt-3 px-3 py-1 text-[11px]" />
            </div>

            <div className="ui-card p-4 space-y-3">
              {[
                { label: 'NIS', value: selectedSiswa.nis },
                { label: 'Status PKL', value: selectedSiswa.statusPKL },
                { label: 'Lama PKL', value: selectedSiswa.lamaPKL },
                { label: 'Perusahaan', value: perusahaanPKL.find(p => p.id == selectedSiswa.perusahaanId)?.nama_perusahaan || '-' },
                { label: 'Guru Pembimbing', value: teachers.find(g => g.code === selectedSiswa.guruPembimbingCode)?.name || 'Belum ditugaskan' },
              ].map(info => (
                <div key={info.label} className="flex justify-between items-start gap-4 py-1 border-b border-slate-50 last:border-0 last:pb-0">
                  <span className="text-xs font-semibold text-slate-400">{info.label}</span>
                  <span className="text-sm font-bold text-slate-800 text-right">{info.value}</span>
                </div>
              ))}
            </div>

            <div className="ui-card p-4">
               <h3 className="text-sm font-bold text-slate-800 mb-3 flex items-center gap-2"><Settings size={16} className="text-slate-400"/> Edit Penugasan</h3>
               <div className="space-y-4">
                  <div>
                    <label className="text-xs text-slate-500 font-semibold mb-1.5 block">Perusahaan PKL</label>
                    <ClickPicker 
                      value={selectedSiswa.perusahaanId || ""}
                      onChange={(val) => setSelectedSiswa({...selectedSiswa, perusahaanId: val})}
                      placeholder="Pilih Perusahaan PKL"
                      options={[
                        { value: "", label: "-- Tanpa Perusahaan --" },
                        ...perusahaanPKL.map(p => ({ value: p.id, label: p.nama_perusahaan }))
                      ]}
                    />
                  </div>
                  <div>
                    <label className="text-xs text-slate-500 font-semibold mb-1.5 block">Guru Pembimbing</label>
                    <ClickPicker 
                      value={selectedSiswa.guruPembimbingCode || ""}
                      onChange={(val) => setSelectedSiswa({...selectedSiswa, guruPembimbingCode: val})}
                      placeholder="Pilih Guru Pembimbing"
                      options={[
                        { value: "", label: "-- Tanpa Pembimbing --" },
                        ...teachers.map(g => ({ value: g.code, label: g.name }))
                      ]}
                    />
                  </div>
                  <button
                    onClick={async () => {
                       setIsSavingSettings(true);
                       try {
                         await fetch("/api/monitoring/pkl-students/bulk", {
                           method: "POST",
                           headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" },
                           body: JSON.stringify({ updates: [{ nis: selectedSiswa.nis, location_id: selectedSiswa.perusahaanId || null, teacher_code: selectedSiswa.guruPembimbingCode || null }] })
                         });
                         // Update local state
                         setPklStudentsMapping(prev => {
                            const newMap = [...prev];
                            const idx = newMap.findIndex(m => m.nis === selectedSiswa.nis);
                            if (idx >= 0) {
                               newMap[idx].location_id = selectedSiswa.perusahaanId;
                               newMap[idx].teacher_code = selectedSiswa.guruPembimbingCode;
                            } else {
                               newMap.push({ nis: selectedSiswa.nis, location_id: selectedSiswa.perusahaanId, teacher_code: selectedSiswa.guruPembimbingCode });
                            }
                            return newMap;
                         });
                          showToast("Tersimpan!");
                        } catch (e) {
                          showToast("Gagal", "error");
                        }
                        setIsSavingSettings(false);
                    }}
                    disabled={isSavingSettings}
                    className="w-full bg-[var(--ui-primary)] hover:opacity-90 text-white font-bold py-2 rounded-[var(--ui-radius-small)] text-sm transition-colors mt-2"
                  >
                    {isSavingSettings ? 'Menyimpan...' : 'Simpan Penugasan'}
                  </button>
               </div>
            </div>
          </div>
        </div>
      )}
      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
};

