import { GRADES } from '../../../utils/constants';
import useAuthStore from '../../../store/monitoring/authStore';
import { HardDrive, Link2, CheckCircle2, XCircle, Edit2, Lock, Trash2 } from 'lucide-react';
import { Button, PageHeader } from '../../../components/monitoring/ui/index.js';
import { UISelect, Modal } from '../../../components/ui.jsx';


const MasterDataGuru = memo(function MasterDataGuru({
  teachers,
  classes,
  teacherTargetJpMap,
  teacherScheduleCountMap,
  quickEditGuruCode,
  quickGuruForm,
  setQuickGuruForm,
  setQuickEditGuruCode,
  updateSelectionForTab,
  openModal,
  checkDependencies,
  handleDelete,
  saveQuickEditGuru,
  startQuickEditGuru,
  renderTable,
  setTeachers,
  saveDatabaseNow,
  isViewOnly = false
}) {
  const [hikTeachers, setHikTeachers] = useState([]);
  const [isFetchingHik, setIsFetchingHik] = useState(false);
  const authToken = useAuthStore(state => state.user?.authToken);

  const fetchHikTeachers = async () => {
    if (!authToken) return;
    setIsFetchingHik(true);
    try {
      const [resGuru, resKaryawan] = await Promise.all([
        fetch("/api/hikvision/students?type=guru", { headers: { "Authorization": `Bearer ${authToken}` } }),
        fetch("/api/hikvision/students?type=karyawan", { headers: { "Authorization": `Bearer ${authToken}` } }),
      ]);
      const [dataGuru, dataKaryawan] = await Promise.all([
        resGuru.json().catch(() => ({ ok: false, data: [] })),
        resKaryawan.json().catch(() => ({ ok: false, data: [] })),
      ]);
      const combined = [
        ...(dataGuru.ok ? (dataGuru.data || []) : []),
        ...(dataKaryawan.ok ? (dataKaryawan.data || []) : []),
      ];
      setHikTeachers(combined);
    } catch (err) {
      console.error("Gagal memuat guru Hikvision:", err);
    } finally {
      setIsFetchingHik(false);
    }
  };

  useEffect(() => {
    fetchHikTeachers();
  }, [authToken]);

  // Set of NIS values from hikvision (employee ID di mesin = kode guru)
  const hikNisSet = useMemo(
    () => new Set(hikTeachers.map(t => String(t.nis || "").trim().toLowerCase())),
    [hikTeachers]
  );

  const [showSyncModal, setShowSyncModal] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [importConfirmOpen, setImportConfirmOpen] = useState(false);
  const [feedbackModal, setFeedbackModal] = useState({ open: false, title: "", message: "", type: "info" });

  const showFeedback = (title, message, type = "info") => {
    setFeedbackModal({ open: true, title, message, type });
  };

  const handleImportFromHikvision = () => {
    if (hikTeachers.length === 0) {
      showFeedback("Data Kosong", "Data guru Hikvision kosong. Pastikan Anda telah menarik data dari Dashboard Hikvision terlebih dahulu.", "error");
      return;
    }
    setImportConfirmOpen(true);
  };

  const executeImportFromHikvision = () => {
    setImportConfirmOpen(false);
    let addedCount = 0;
    const existingCodeSet = new Set(teachers.map(t => String(t.code || "").trim().toLowerCase()));
    const nextTeachers = [...teachers];

    hikTeachers.forEach(hik => {
      const code = String(hik.nis || "").trim().toLowerCase();
      if (code && !existingCodeSet.has(code)) {
        nextTeachers.push({
          code: hik.nis,
          name: hik.name,
          type: "Umum",
          phone: hik.phone || "",
          preferredGrade: "Semua",
          preferredMajor: "Semua",
          targetWeeklyJp: 24,
          password: ""
        });
        existingCodeSet.add(code);
        addedCount++;
      }
    });

    if (addedCount > 0) {
      if (setTeachers) setTeachers(nextTeachers);
      if (saveDatabaseNow) saveDatabaseNow({ teachers: nextTeachers });
      showFeedback("Berhasil", `Berhasil menarik ${addedCount} guru baru dari mesin ke dalam sistem.`, "success");
    } else {
      showFeedback("Info", "Tidak ada guru baru yang ditambahkan. Semua ID Karyawan di mesin sudah ada di sistem.", "info");
    }
  };

  const syncTeachersToHikvision = async () => {
    setIsSyncing(true);
    try {
      let matchedCount = 0;
      const updates = [];

      teachers.forEach(t => {
        const schoolCode = String(t.code || "").trim().toLowerCase();
        const schoolName = String(t.name || "").trim().toLowerCase();

        const matchedHik = hikTeachers.find(h => 
          String(h.nis || "").trim().toLowerCase() === schoolCode || 
          String(h.name || "").trim().toLowerCase() === schoolName
        );

        if (matchedHik) {
          updates.push({
            nis: matchedHik.nis,
            class_name: "guru"
          });
          matchedCount++;
        }
      });

      if (updates.length === 0) {
        showFeedback("Tidak Ada Kecocokan", "Tidak ada kecocokan data guru yang dapat disinkronkan ke mesin.", "info");
        setIsSyncing(false);
        return;
      }

      const res = await fetch('/api/hikvision/students/bulk', {
        method: 'PUT',
        headers: {
          "Authorization": `Bearer ${authToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ updates })
      });
      const data = await res.json();
      if (data.ok) {
        showFeedback("Berhasil", `Berhasil menyinkronkan ${matchedCount} data guru ke mesin absensi!`, "success");
        await fetchHikTeachers();
      } else {
        showFeedback("Gagal", data.error || "Gagal melakukan sinkronisasi", "error");
      }
    } catch (err) {
      console.error(err);
      showFeedback("Kesalahan Jaringan", "Gagal melakukan sinkronisasi karena kesalahan jaringan.", "error");
    }
    setIsSyncing(false);
  };

  const customButtons = !isViewOnly ? (
    <>
      <Button 
        type="button" 
        variant="secondary" 
        onClick={handleImportFromHikvision} 
        className="text-xs flex items-center gap-1.5 bg-blue-50 text-blue-700 border border-blue-200 hover:bg-blue-100"
      >
        <HardDrive size={14} /> Tarik dari Mesin
      </Button>
      <Button 
        type="button" 
        variant="secondary" 
        onClick={syncTeachersToHikvision} 
        disabled={isSyncing}
        className="text-xs flex items-center gap-1.5 bg-emerald-50 text-emerald-700 border border-emerald-200 hover:bg-emerald-100"
      >
        <Link2 size={14} /> Sinkron Hikvision
      </Button>
    </>
  ) : null;

  return (
    <>
      {renderTable(
        "Kelola Data Guru",
        ["Kode", "Nama Lengkap", "Kategori", "No. WhatsApp", "Wali Kelas", "Target/Terjadwal JP", "Prioritas Jurusan", "Prioritas Tingkat", "Status Alat"],
        teachers,
        (item, idx, isSelected) => {
          const assignedHomeroom = classes.find((c) => c.homeroom === item.code)?.name || "-";
          const targetJP = teacherTargetJpMap.get(item.code) || 0;
          const scheduledJP = teacherScheduleCountMap.get(item.code) || 0;

          // Cek apakah kode guru ini ada di mesin Hikvision
          const codeKey = String(item.code || "").trim().toLowerCase();
          const nipKey = String(item.nip || "").trim().toLowerCase();
          const isConnected = hikNisSet.has(codeKey) || (nipKey && hikNisSet.has(nipKey));

          return (
            <tr key={item.code} className={`hover:bg-slate-50/50 transition-colors ${isSelected ? "bg-[var(--ui-accent)]/20/40" : ""}`}>
              <td className="px-3 py-2.5 text-center">
                <input
                  type="checkbox"
                  checked={isSelected}
                  onChange={() => updateSelectionForTab("guru", (current) => current.includes(item.code) ? current.filter((x) => x !== item.code) : [...current, item.code])}
                  className="accent-[var(--ui-primary)] cursor-pointer"
                  aria-label={`Pilih guru ${item.code}`}
                />
              </td>
              <td className="px-3 py-2.5 text-center font-bold text-slate-400 text-xs">{idx + 1}</td>
              <td className="px-3 py-2.5 text-center font-black text-[var(--ui-primary)] text-xs">{item.code}</td>
              <td className="px-3 py-2.5 font-bold text-slate-800 text-xs">
                {quickEditGuruCode === item.code ? (
                  <input type="text" value={quickGuruForm.name || ""} onChange={(e) => setQuickGuruForm({ ...quickGuruForm, name: e.target.value })} className="w-full border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold" />
                ) : item.name}
              </td>
              <td className="px-3 py-2.5 text-center">
                {quickEditGuruCode === item.code ? (
                  <UISelect value={quickGuruForm.type || "Umum"} onChange={(e) => setQuickGuruForm({ ...quickGuruForm, type: e.target.value })} className="border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold">
                    <option value="Umum">Umum</option>
                    <option value="Jurusan">Jurusan</option>
                    <option value="Campuran">Campuran</option>
                  </UISelect>
                ) : (
                  <span className={`text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-[var(--ui-radius-small)] whitespace-nowrap ${item.type === "Umum" ? "bg-slate-100 text-slate-600" : "bg-[var(--ui-accent)]/20 text-[var(--ui-primary)]"}`}>{item.type}</span>
                )}
              </td>
              <td className="px-3 py-2.5 font-semibold text-slate-700 text-xs text-center">
                {quickEditGuruCode === item.code ? (
                  <input type="text" value={quickGuruForm.phone || ""} onChange={(e) => setQuickGuruForm({ ...quickGuruForm, phone: e.target.value.replace(/[^0-9]/g, '') })} className="w-full border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold" placeholder="6281xxx" />
                ) : (item.phone || "-")}
              </td>
              <td className="px-3 py-2.5 text-center">
                {assignedHomeroom !== "-" ? (
                  <span className="text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-[var(--ui-radius-small)] bg-[var(--ui-primary)]/10 text-[var(--ui-primary)] border border-blue-100/50 whitespace-nowrap">
                    {assignedHomeroom}
                  </span>
                ) : (
                  <span className="text-slate-400 font-semibold text-xs">-</span>
                )}
              </td>
              <td className="px-3 py-2.5">
                <div className="flex flex-col items-center">
                  {quickEditGuruCode === item.code ? (
                    <input type="text" inputMode="numeric" value={quickGuruForm.targetWeeklyJp || ""} onChange={(e) => setQuickGuruForm({ ...quickGuruForm, targetWeeklyJp: e.target.value.replace(/[^0-9]/g, '') })} className="w-20 border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold text-center" placeholder={`${targetJP}`} />
                  ) : (
                    <span className="font-bold text-slate-800 text-xs whitespace-nowrap">{targetJP} JP</span>
                  )}
                  <span className={`text-[10px] font-bold mt-0.5 whitespace-nowrap ${scheduledJP === targetJP && targetJP > 0 ? "text-[var(--ui-primary)]" : scheduledJP > 0 ? "text-amber-600" : "text-slate-400"}`}>
                    Terjadwal: {scheduledJP} JP
                  </span>
                </div>
              </td>
              <td className="px-3 py-2.5 font-semibold text-slate-600 text-xs text-center">
                {quickEditGuruCode === item.code ? (
                  <div className="flex items-center gap-2">
                    <input type="text" value={quickGuruForm.preferredMajor || "Semua"} onChange={(e) => setQuickGuruForm({ ...quickGuruForm, preferredMajor: e.target.value })} className="border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold w-24" placeholder="Semua atau TKJ,TKR" />
                    <input type="password" value={quickGuruForm.password || ""} onChange={(e) => setQuickGuruForm({ ...quickGuruForm, password: e.target.value })} className="w-20 border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold" placeholder="Kosongkan jika sama" />
                  </div>
                ) : (item.preferredMajor && item.preferredMajor !== 'Semua' ? item.preferredMajor : 'Semua Jurusan')}
              </td>
              <td className="px-3 py-2.5 font-semibold text-slate-600 text-xs text-center">
                {quickEditGuruCode === item.code ? (
                  <UISelect value={quickGuruForm.preferredGrade || "Semua"} onChange={(e) => setQuickGuruForm({ ...quickGuruForm, preferredGrade: e.target.value })} className="w-24 border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold">
                    <option value="Semua">Semua</option>
                    {GRADES.filter(g => g !== 'Semua').map((m) => (<option key={m} value={m}>Tingkat {m}</option>))}
                  </UISelect>
                ) : (item.preferredGrade && item.preferredGrade !== 'Semua' ? `Tingkat ${item.preferredGrade}` : 'Semua Tingkat')}
              </td>
              {/* Status Alat Hikvision */}
              <td className="px-3 py-2.5 text-center">
                {isFetchingHik ? (
                  <div className="flex justify-center text-slate-400" title="Memuat..."><div className="w-4 h-4 border-2 border-slate-300 border-t-[var(--ui-primary)] rounded-full animate-spin"></div></div>
                ) : isConnected ? (
                  <div className="flex justify-center text-emerald-500" title="Terhubung"><CheckCircle2 size={16} strokeWidth={3} /></div>
                ) : (
                  <div className="flex justify-center text-slate-300" title="Belum Terhubung"><XCircle size={16} strokeWidth={3} /></div>
                )}
              </td>
              <td className="px-3 py-2.5 text-right">
                <div className="flex justify-end gap-1.5">
                  {quickEditGuruCode === item.code ? (
                    <>
                      <Button variant="primary" onClick={() => saveQuickEditGuru(item.code)}>Save</Button>
                      <Button variant="ghost" onClick={() => { setQuickEditGuruCode(""); setQuickGuruForm({}); }}>Cancel</Button>
                    </>
                  ) : (
                    <Button variant="accent" onClick={() => startQuickEditGuru(item)}>Quick Edit</Button>
                  )}
                  <Button variant="secondary" onClick={() => openModal("ketersediaan_mapel", "edit", item)}>Mapel</Button>
                  <Button variant="ghost" className="px-2" onClick={() => openModal('guru', 'edit', item)}><Edit2 size={14} /></Button>
                  {(() => {
                    const deps = checkDependencies('guru', item.code);
                    if (deps.length > 0) {
                      return (
                        <Button variant="ghost" className="px-2 opacity-50" disabled title={`Tidak bisa dihapus. Masih digunakan oleh: ${deps.join(', ')}. Hapus koneksi terlebih dahulu.`}>
                          <Lock size={14} className="text-amber-500" />
                        </Button>
                      );
                    }
                    return (
                      <Button variant="danger" className="px-2" onClick={() => handleDelete('guru', item.code)} title="Hapus"><Trash2 size={14} /></Button>
                    );
                  })()}
                </div>
              </td>
            </tr>
          );
        },
        { customHeaderButtons: customButtons, pageHeader: <PageHeader title="Data Guru" description="Kelola data induk guru, beban mengajar, dan target jam mengajar." icon={Users} /> }
      )}

      {/* Import Confirm Modal */}
      {importConfirmOpen && (
        <Modal isOpen={true} onClose={() => setImportConfirmOpen(false)}>
          <div className="p-6 w-full max-w-[400px] text-center">
            <HardDrive size={40} className="mx-auto text-blue-600 mb-4" />
            <h3 className="text-lg font-bold text-slate-800 mb-2">Tarik Data Guru</h3>
            <p className="text-sm text-slate-600 mb-6">
              Apakah Anda yakin ingin menarik data guru dari mesin ke dalam sistem? Guru baru yang tidak ada di sistem akan ditambahkan secara otomatis.
            </p>
            <div className="flex justify-center gap-3">
              <Button onClick={() => setImportConfirmOpen(false)} variant="ghost">Batal</Button>
              <Button onClick={executeImportFromHikvision} variant="primary" className="bg-blue-600 hover:bg-blue-700 text-white font-bold">Ya, Tarik Data</Button>
            </div>
          </div>
        </Modal>
      )}

      {/* Feedback Modal */}
      {feedbackModal.open && (
        <Modal isOpen={true} onClose={() => setFeedbackModal({ ...feedbackModal, open: false })}>
          <div className="p-6 w-full max-w-[400px] text-center">
            <h3 className="text-lg font-bold text-slate-800 mb-2">{feedbackModal.title}</h3>
            <p className="text-sm text-slate-600 mb-6">{feedbackModal.message}</p>
            <Button onClick={() => setFeedbackModal({ ...feedbackModal, open: false })} variant="primary">Selesai</Button>
          </div>
        </Modal>
      )}
    </>
  );
});

export default MasterDataGuru;

import { memo } from 'react';
import { SlidersHorizontal } from 'lucide-react';
import { getMajorFullName } from '../../../utils/constants.js';
import { Edit2, Lock, Trash2 } from 'lucide-react';
import { PageHeader } from '../../../components/monitoring/ui/index.js';


const MasterDataJurusan = memo(function MasterDataJurusan({
  majors,
  updateSelectionForTab,
  openModal,
  checkDependencies,
  handleDelete,
  renderTable
}) {
  const pageHeader = (
    <PageHeader 
      title="Data Jurusan"
      icon={SlidersHorizontal}
      description="Kelola daftar kompetensi keahlian atau program studi yang ada."
    />
  );

  // Normalize majors array to handle both strings and objects robustly
  const normalizedMajors = (majors || []).map((m) => {
    if (typeof m === 'object' && m !== null) {
      return { name: m.name || m.payload || '' };
    }
    return { name: String(m || '') };
  });

  return renderTable(
    "Kelola Data Jurusan",
    ["Nama Jurusan"],
    normalizedMajors,
    (item, idx, isSelected) => (
      <tr key={item.name} className={`hover:bg-slate-50/50 transition-colors ${isSelected ? "bg-[var(--ui-accent)]/20/40" : ""}`}>
        <td className="px-4 py-4 text-center">
          <input
            type="checkbox"
            checked={isSelected}
            onChange={() => updateSelectionForTab("jurusan", (current) => current.includes(item.name) ? current.filter((x) => x !== item.name) : [...current, item.name])}
            className="accent-[var(--ui-primary)] cursor-pointer"
            aria-label={`Pilih jurusan ${item.name}`}
          />
        </td>
        <td className="px-6 py-4 text-center font-bold text-slate-400">{idx + 1}</td>
        <td className="px-6 py-4 font-bold text-slate-800">
          {item.name} <span className="text-slate-400 font-medium text-xs ml-2">({getMajorFullName(item.name)})</span>
        </td>
        <td className="px-6 py-4 text-right">
          <div className="flex justify-end gap-2">
            <button onClick={() => openModal('jurusan', 'edit', { name: item.name })} className="p-2 text-slate-400 hover:text-[var(--ui-primary)] bg-white hover:bg-[var(--ui-accent)]/20 border-none rounded-[var(--ui-radius-small)] transition-colors cursor-pointer"><Edit2 size={14} /></button>
            {(() => {
              const deps = checkDependencies('jurusan', item.name);
              if (deps.length > 0) {
                return (
                  <button title={`Tidak bisa dihapus. Masih digunakan oleh: ${deps.join(', ')}. Hapus koneksi terlebih dahulu.`} disabled className="p-2 text-slate-300 bg-slate-50 border-none rounded-[var(--ui-radius-small)] cursor-not-allowed">
                    <Lock size={14} className="text-amber-500" />
                  </button>
                );
              }
              return (
                <button onClick={() => handleDelete('jurusan', item.name)} className="p-2 text-slate-400 hover:text-red-600 bg-white hover:bg-red-50 border-none rounded-[var(--ui-radius-small)] transition-colors cursor-pointer" title="Hapus"><Trash2 size={14} /></button>
              );
            })()}
          </div>
        </td>
      </tr>
    ),
    { pageHeader }
  );
});

export default MasterDataJurusan;

import { memo, useState, useEffect, useMemo } from 'react';
import { Users } from 'lucide-react';
import useAuthStore from '../../../store/monitoring/authStore';
import { HardDrive, Link2, CheckCircle2, XCircle, Edit2, Lock, Trash2 } from 'lucide-react';
import { Button, PageHeader } from '../../../components/monitoring/ui/index.js';
import { Modal } from '../../../components/ui.jsx';


const MasterDataKaryawan = memo(function MasterDataKaryawan({
  staffs,
  classes = [],
  staffTargetJpMap = new Map(),
  staffscheduleCountMap = new Map(),
  updateSelectionForTab = () => {},
  openModal = () => {},
  checkDependencies = () => [],
  handleDelete = () => {},
  renderTable,
  setStaffs,
  saveDatabaseNow,
  isViewOnly = false
}) {
  const [quickEditKaryawanCode, setQuickEditKaryawanCode] = useState("");
  const [quickKaryawanForm, setQuickKaryawanForm] = useState({});
  const [hikstaffs, setHikstaffs] = useState([]);
  const authToken = useAuthStore(state => state.user?.authToken);

  const startQuickEditKaryawan = (item) => {
    setQuickEditKaryawanCode(item.code);
    setQuickKaryawanForm({
      name: item.name || "",
      division: item.division || "",
      phone: item.phone || ""
    });
  };

  const saveQuickEditKaryawan = async (code) => {
    const nextName = String(quickKaryawanForm.name || "").trim();
    if (!nextName) {
      showFeedback("Peringatan", "Nama karyawan wajib diisi.", "error");
      return;
    }
    const nextStaffs = staffs.map(s => s.code === code ? {
      ...s,
      ...quickKaryawanForm,
      name: nextName
    } : s);

    if (setStaffs) setStaffs(nextStaffs);
    if (saveDatabaseNow) {
      await saveDatabaseNow({ staffs: nextStaffs }, "menyimpan quick edit karyawan");
    }
    setQuickEditKaryawanCode("");
    setQuickKaryawanForm({});
  };

  const fetchHikstaffs = async () => {
    if (!authToken) return;
    try {
      const [resKaryawan1, resKaryawan2] = await Promise.all([
        fetch("/api/hikvision/students?type=Karyawan", { headers: { "Authorization": `Bearer ${authToken}` } }),
        fetch("/api/hikvision/students?type=karyawan", { headers: { "Authorization": `Bearer ${authToken}` } }),
      ]);
      const [dataKaryawan1, dataKaryawan2] = await Promise.all([
        resKaryawan1.json().catch(() => ({ ok: false, data: [] })),
        resKaryawan2.json().catch(() => ({ ok: false, data: [] })),
      ]);
      const combined = [
        ...(dataKaryawan1.ok ? (dataKaryawan1.data || []) : []),
        ...(dataKaryawan2.ok ? (dataKaryawan2.data || []) : []),
      ];
      setHikstaffs(combined);
    } catch (err) {
      console.error("Gagal memuat Karyawan Hikvision:", err);
    }
  };

  useEffect(() => {
    fetchHikstaffs();
  }, [authToken]);

  // Set of NIS values from hikvision (employee ID di mesin = kode Karyawan)
  const hikNisSet = useMemo(
    () => new Set(hikstaffs.map(t => String(t.nis || "").trim().toLowerCase())),
    [hikstaffs]
  );

  const [isSyncing, setIsSyncing] = useState(false);
  const [importConfirmOpen, setImportConfirmOpen] = useState(false);
  const [feedbackModal, setFeedbackModal] = useState({ open: false, title: "", message: "", type: "info" });

  const showFeedback = (title, message, type = "info") => {
    setFeedbackModal({ open: true, title, message, type });
  };

  const handleImportFromHikvision = () => {
    if (hikstaffs.length === 0) {
      showFeedback("Data Kosong", "Data karyawan Hikvision kosong. Pastikan Anda telah menarik data dari Dashboard Hikvision terlebih dahulu.", "error");
      return;
    }
    setImportConfirmOpen(true);
  };

  const executeImportFromHikvision = () => {
    setImportConfirmOpen(false);
    let addedCount = 0;
    const existingCodeSet = new Set(staffs.map(t => String(t.code || "").trim().toLowerCase()));
    const nextStaffs = [...staffs];

    hikstaffs.forEach(hik => {
      const code = String(hik.nis || "").trim().toLowerCase();
      if (code && !existingCodeSet.has(code)) {
        nextStaffs.push({
          code: hik.nis,
          staff_code: hik.nis,
          name: hik.name,
          type: "Umum",
          phone: hik.phone || "",
          preferredGrade: "Semua",
          preferredMajor: "Semua",
          targetWeeklyJp: 24,
          password: ""
        });
        existingCodeSet.add(code);
        addedCount++;
      }
    });

    if (addedCount > 0) {
      if (setStaffs) setStaffs(nextStaffs);
      if (saveDatabaseNow) saveDatabaseNow({ staffs: nextStaffs });
      showFeedback("Berhasil", `Berhasil menarik ${addedCount} karyawan baru dari mesin ke dalam sistem.`, "success");
    } else {
      showFeedback("Info", "Tidak ada karyawan baru yang ditambahkan. Semua ID Karyawan di mesin sudah ada di sistem.", "info");
    }
  };

  const syncStaffToHikvision = async () => {
    setIsSyncing(true);
    try {
      let matchedCount = 0;
      const updates = [];

      staffs.forEach(t => {
        const schoolCode = String(t.code || "").trim().toLowerCase();
        const schoolName = String(t.name || "").trim().toLowerCase();

        const matchedHik = hikstaffs.find(h => 
          String(h.nis || "").trim().toLowerCase() === schoolCode || 
          String(h.name || "").trim().toLowerCase() === schoolName
        );

        if (matchedHik) {
          updates.push({
            nis: matchedHik.nis,
            class_name: "karyawan"
          });
          matchedCount++;
        }
      });

      if (updates.length === 0) {
        showFeedback("Tidak Ada Kecocokan", "Tidak ada kecocokan data karyawan yang dapat disinkronkan ke mesin.", "info");
        setIsSyncing(false);
        return;
      }

      const res = await fetch('/api/hikvision/students/bulk', {
        method: 'PUT',
        headers: {
          "Authorization": `Bearer ${authToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ updates })
      });
      const data = await res.json();
      if (data.ok) {
        showFeedback("Berhasil", `Berhasil menyinkronkan ${matchedCount} data karyawan ke mesin absensi!`, "success");
        await fetchHikstaffs();
      } else {
        showFeedback("Gagal", data.error || "Gagal melakukan sinkronisasi", "error");
      }
    } catch (err) {
      console.error(err);
      showFeedback("Kesalahan Jaringan", "Gagal melakukan sinkronisasi karena kesalahan jaringan.", "error");
    }
    setIsSyncing(false);
  };

  const customButtons = !isViewOnly ? (
    <>
      <Button 
        type="button" 
        variant="secondary" 
        onClick={handleImportFromHikvision} 
        className="text-xs flex items-center gap-1.5 bg-blue-50 text-blue-700 border border-blue-200 hover:bg-blue-100"
      >
        <HardDrive size={14} /> Tarik dari Mesin
      </Button>
      <Button 
        type="button" 
        variant="secondary" 
        onClick={syncStaffToHikvision} 
        disabled={isSyncing}
        className="text-xs flex items-center gap-1.5 bg-emerald-50 text-emerald-700 border border-emerald-200 hover:bg-emerald-100"
      >
        <Link2 size={14} /> Sinkron Hikvision
      </Button>
    </>
  ) : null;

  return (
    <>
      {renderTable(
        "Kelola Data Karyawan",
        ["Kode", "Nama Lengkap", "Bagian / Divisi", "No. WhatsApp", "Status Alat"],
        staffs,
        (item, idx, isSelected) => {
          // Cek apakah kode Karyawan ini ada di mesin Hikvision
          const codeKey = String(item.code || "").trim().toLowerCase();
          const nipKey = String(item.nip || "").trim().toLowerCase();
          const isConnected = hikNisSet.has(codeKey) || (nipKey && hikNisSet.has(nipKey));

          return (
            <tr key={item.code} className={`hover:bg-slate-50/50 transition-colors ${isSelected ? "bg-[var(--ui-accent)]/20/40" : ""}`}>
              <td className="px-4 py-4 text-center">
                <input
                  type="checkbox"
                  checked={isSelected}
                  onChange={() => updateSelectionForTab("Karyawan", (current) => current.includes(item.code) ? current.filter((x) => x !== item.code) : [...current, item.code])}
                  className="accent-[var(--ui-primary)] cursor-pointer"
                  aria-label={`Pilih Karyawan ${item.code}`}
                />
              </td>
              <td className="px-6 py-4 text-center font-bold text-slate-400">{idx + 1}</td>
              <td className="px-6 py-4 text-center font-black text-[var(--ui-primary)]">{item.code}</td>
              <td className="px-6 py-4 font-bold text-slate-800">
                {quickEditKaryawanCode === item.code ? (
                  <input type="text" value={quickKaryawanForm.name || ""} onChange={(e) => setQuickKaryawanForm({ ...quickKaryawanForm, name: e.target.value })} className="w-full border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold" />
                ) : item.name}
              </td>
              <td className="px-6 py-4 font-bold text-slate-700 text-sm">
                {quickEditKaryawanCode === item.code ? (
                  <input type="text" value={quickKaryawanForm.division || ""} onChange={(e) => setQuickKaryawanForm({ ...quickKaryawanForm, division: e.target.value })} className="w-full border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold" placeholder="Contoh: Kebersihan" />
                ) : (item.division || "-")}
              </td>
              <td className="px-6 py-4 font-semibold text-slate-700 text-sm">
                {quickEditKaryawanCode === item.code ? (
                  <input type="text" value={quickKaryawanForm.phone || ""} onChange={(e) => setQuickKaryawanForm({ ...quickKaryawanForm, phone: e.target.value.replace(/[^0-9]/g, '') })} className="w-full border-none bg-white px-2 py-1 rounded-[var(--ui-radius-small)] text-[11px] font-bold" placeholder="6281xxx" />
                ) : (item.phone || "-")}
              </td>
              {/* Status Alat Hikvision */}
              <td className="px-6 py-4">
                {isConnected ? (
                  <div className="flex justify-center text-emerald-500" title="Terhubung"><CheckCircle2 size={18} strokeWidth={3} /></div>
                ) : (
                  <div className="flex justify-center text-slate-300" title="Belum Terhubung"><XCircle size={18} strokeWidth={3} /></div>
                )}
              </td>
              <td className="px-6 py-4 text-right">
                <div className="flex justify-end gap-2">
                  {quickEditKaryawanCode === item.code ? (
                    <>
                      <Button variant="outline" className="px-3 py-1 text-[11px]" onClick={() => saveQuickEditKaryawan(item.code)}>Save</Button>
                      <Button variant="ghost" className="px-3 py-1 text-[11px]" onClick={() => { setQuickEditKaryawanCode(""); setQuickKaryawanForm({}); }}>Cancel</Button>
                    </>
                  ) : (
                    <Button variant="outline" className="px-3 py-1 text-[11px]" onClick={() => startQuickEditKaryawan(item)}>Quick Edit</Button>
                  )}
                  <Button variant="ghost" className="px-2" onClick={() => openModal('Karyawan', 'edit', item)} title="Edit"><Edit2 size={14} /></Button>
                  {(() => {
                    const deps = checkDependencies('Karyawan', item.code);
                    if (deps.length > 0) {
                      return (
                        <Button variant="ghost" className="px-2 opacity-50" disabled title={`Tidak bisa dihapus. Masih digunakan oleh: ${deps.join(', ')}. Hapus koneksi terlebih dahulu.`}>
                          <Lock size={14} className="text-amber-500" />
                        </Button>
                      );
                    }
                    return (
                      <Button variant="danger" className="px-2" onClick={() => handleDelete('Karyawan', item.code)} title="Hapus"><Trash2 size={14} /></Button>
                    );
                  })()}
                </div>
              </td>
            </tr>
          );
        },
        { customHeaderButtons: customButtons, pageHeader: <PageHeader title="Data Karyawan" description="Kelola data induk staf dan karyawan sekolah serta status mesin absensi." icon={Users} /> }
      )}

      {/* Import Confirm Modal */}
      {importConfirmOpen && (
        <Modal isOpen={true} onClose={() => setImportConfirmOpen(false)}>
          <div className="p-6 w-full max-w-[400px] text-center">
            <HardDrive size={40} className="mx-auto text-blue-600 mb-4" />
            <h3 className="text-lg font-bold text-slate-800 mb-2">Tarik Data Karyawan</h3>
            <p className="text-sm text-slate-600 mb-6">
              Apakah Anda yakin ingin menarik data karyawan dari mesin ke dalam sistem? Karyawan baru yang tidak ada di sistem akan ditambahkan secara otomatis.
            </p>
            <div className="flex justify-center gap-3">
              <Button onClick={() => setImportConfirmOpen(false)} variant="ghost">Batal</Button>
              <Button onClick={executeImportFromHikvision} variant="primary" className="bg-blue-600 hover:bg-blue-700 text-white font-bold">Ya, Tarik Data</Button>
            </div>
          </div>
        </Modal>
      )}

      {/* Feedback Modal */}
      {feedbackModal.open && (
        <Modal isOpen={true} onClose={() => setFeedbackModal({ ...feedbackModal, open: false })}>
