            <p className="text-sm text-slate-600 mb-6">{feedbackModal.message}</p>
            <Button onClick={() => setFeedbackModal({ ...feedbackModal, open: false })} variant="primary">Selesai</Button>
          </div>
        </Modal>
      )}
    </>
  );
});

