        <Search size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
      </div>

      {isOpen && (
        <>
          <div className="absolute z-50 mt-2 w-full bg-white border-none rounded-[var(--ui-radius-small)] shadow-sm max-h-64 overflow-y-auto overflow-x-hidden">
            {filtered.length > 0 ? (
              filtered.map(t => (
                <div 
                  key={t.id || t.code}
                  className="px-4 py-3 hover:bg-slate-50 cursor-pointer border-b border-slate-100 last:border-0 transition-colors"
                  onClick={() => {
                    onSelect(t.id || t.code);
                    setSearch('');
                    setIsOpen(false);
                  }}
                >
                  <div className="text-sm font-bold text-slate-800 truncate">{t.name}</div>
                  {t.code && <div className="text-[10px] font-bold tracking-widest text-slate-400 mt-1 uppercase">KODE: {t.code}</div>}
                </div>
              ))
            ) : (
               <div className="px-4 py-4 text-sm font-bold text-slate-400 text-center bg-slate-50">Guru tidak ditemukan</div>
            )}
          </div>
          <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)} />
        </>
      )}
    </div>
  );
};

export default function AdminStrukturOrganisasi({ appSettings, setAppSettings, onSave, showNotification, teachers = [] }) {
  const [struktur, setStruktur] = useState(appSettings?.strukturOrganisasi || []);
  const [draggedIndex, setDraggedIndex] = useState(null);

  const handleAdd = () => {
    setStruktur([
      ...struktur,
      {
        id: `struktur_${Date.now()}`,
        name: '',
        position: '',
        description: '',
        photoUrl: '',
        parentId: '',
        order: struktur.length,
      }
    ]);
  };

  const handleAddFromTeacher = (teacherId) => {
    const teacher = teachers.find(t => t.id === teacherId || t.code === teacherId);
    if (!teacher) return;

    setStruktur([
      ...struktur,
      {
        id: `struktur_${Date.now()}_${teacher.code || teacher.id}`,
        name: teacher.name || '',
        position: 'Guru',
        description: teacher.code ? `Kode: ${teacher.code}` : '',
        photoUrl: '', 
        parentId: '',
        order: struktur.length,
      }
    ]);
  };

  const handleUpdate = (index, field, value) => {
    const newStruktur = [...struktur];
    newStruktur[index][field] = value;
    setStruktur(newStruktur);
  };

  const handleRemove = async (index) => {
    if (await window.confirmAsync('Apakah Anda yakin ingin menghapus data ini?')) {
      const newStruktur = struktur.filter((_, i) => i !== index);
      setStruktur(newStruktur);
    }
  };

  const handleImageUpload = (index, file) => {
    if (!file) return;

    if (file.size > 2 * 1024 * 1024) {
      showNotification('Ukuran gambar maksimal 2MB', 'warning');
      return;
    }

    compressImage(file, { maxWidth: 300, maxHeight: 300, quality: 0.8 }).then(compressedBase64 => {
      handleUpdate(index, 'photoUrl', compressedBase64);
    });
  };

  const handleSave = async () => {
    const validStruktur = struktur.filter(s => s.name.trim() !== '' && s.position.trim() !== '');

    if (struktur.length !== validStruktur.length) {
      showNotification('Beberapa data kosong telah diabaikan.', 'info');
    }

    setAppSettings({
      ...appSettings,
      strukturOrganisasi: validStruktur
    });

    try {
      await onSave({ appSettings: { ...appSettings, strukturOrganisasi: validStruktur } }, "menyimpan struktur organisasi");
      showNotification('Struktur organisasi berhasil disimpan!');
    } catch (e) {
      showNotification('Gagal menyimpan struktur organisasi.', 'error');
    }
  };

  const handleDragStart = (e, index) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", index);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e, dropIndex) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === dropIndex) return;

    const newStruktur = [...struktur];
    const draggedItem = newStruktur[draggedIndex];
    newStruktur.splice(draggedIndex, 1);
    newStruktur.splice(dropIndex, 0, draggedItem);

    setStruktur(newStruktur);
    setDraggedIndex(null);
  };

  return (
    <div className="w-full mx-auto animate-in fade-in duration-300 flex flex-col gap-4">
      <PageHeader 
        title="Struktur Organisasi"
        description="Kelola urutan kepengurusan dengan cara Drag & Drop."
        icon={Users}
      />
      <div className="ui-card p-6 flex flex-col w-full">
        {/* Actions & Filters Bar */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 pb-4 border-b border-slate-100">
          <div className="flex flex-wrap items-center gap-3 w-full sm:w-auto">
            <TeacherCombobox teachers={teachers} onSelect={handleAddFromTeacher} />
            <Button type="button" variant="outline" onClick={handleAdd} className="py-2.5 px-4 rounded-[var(--ui-radius-small)] font-bold shadow-sm flex items-center gap-2 border-slate-200 bg-white">
              <Plus size={16} /> Manual
            </Button>
          </div>
          <Button type="button" onClick={handleSave} style={{ backgroundColor: 'var(--ui-primary)' }} className="py-2.5 px-5 rounded-[var(--ui-radius-small)] text-white font-black shadow-sm flex items-center gap-2 hover:opacity-90 self-start sm:self-center">
            <Save size={16} /> Simpan
          </Button>
        </div>

        {struktur.length === 0 ? (
          <div className="text-center py-16 bg-slate-50 border border-dashed border-slate-300 rounded-[var(--ui-radius-small)]">
            <Users size={48} className="mx-auto text-slate-300 mb-3" />
            <h4 className="text-lg font-bold text-slate-600 mb-1">Belum Ada Data</h4>
            <p className="text-sm text-slate-500 mb-4">Tambahkan struktur kepengurusan pertama Anda.</p>
            <Button type="button" onClick={handleAdd} className="rounded-[var(--ui-radius-small)] shadow-sm">
              <Plus size={16} className="mr-1" /> Tambah Sekarang
            </Button>
          </div>
        ) : (
          <div className="flex flex-col gap-3">
            {struktur.map((item, index) => (
              <div 
                key={item.id} 
                draggable
                onDragStart={(e) => handleDragStart(e, index)}
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, index)}
                onDragEnd={() => setDraggedIndex(null)}
                className={`bg-white border transition-all duration-200 rounded-[var(--ui-radius-card)] p-3 relative group flex flex-col md:flex-row gap-4 items-center shadow-sm ${draggedIndex === index ? 'opacity-40 scale-[0.98] border-indigo-300 bg-indigo-50/50' : 'border-slate-200 hover:border-slate-300 hover:-md'}`}
              >

                {/* Drag Handle */}
                <div className="cursor-grab active:cursor-grabbing text-slate-400 hover:text-indigo-500 p-2 shrink-0 hidden md:block">
                  <GripVertical size={20} />
                </div>

                {/* Photo Upload */}
                <div className="w-16 h-16 shrink-0 bg-slate-50 border-none rounded-full flex items-center justify-center overflow-hidden relative shadow-sm">
                  {item.photoUrl ? (
                    <img src={item.photoUrl} alt="Foto" className="w-full h-full object-cover" />
                  ) : (
                    <ImageIcon size={20} className="text-slate-300" />
                  )}
                  <label className="absolute inset-0 bg-black/50 text-white opacity-0 hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-[9px] font-bold text-center leading-tight p-1">
                    Ubah
                    <input type="file" accept="image/*" className="hidden" onChange={(e) => handleImageUpload(index, e.target.files[0])} />
                  </label>
                </div>

                {/* Form Fields */}
                <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-4 gap-3">
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-1 block">Nama Lengkap</label>
                    <input 
                      type="text" 
                      placeholder="Nama" 
                      value={item.name} 
                      onChange={(e) => handleUpdate(index, 'name', e.target.value)} 
                      className="w-full border-none bg-slate-50 hover:bg-white p-2 rounded-[var(--ui-radius-small)] text-sm font-bold focus:outline-[var(--ui-primary)] transition-colors"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-1 block">Jabatan</label>
                    <input 
                      type="text" 
                      placeholder="Jabatan" 
                      value={item.position} 
                      onChange={(e) => handleUpdate(index, 'position', e.target.value)} 
                      className="w-full border-none bg-slate-50 hover:bg-white p-2 rounded-[var(--ui-radius-small)] text-sm font-bold focus:outline-[var(--ui-primary)] transition-colors"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-1 block">Atasan (Parent)</label>
                    <select 
                      value={item.parentId || ""}
                      onChange={(e) => handleUpdate(index, 'parentId', e.target.value)}
                      className="w-full border-none bg-slate-50 hover:bg-white p-2 rounded-[var(--ui-radius-small)] text-sm font-bold focus:outline-[var(--ui-primary)] transition-colors"
                    >
                      <option value="">- Paling Atas (Pucuk) -</option>
                      {struktur.map(s => {
                        if (s.id === item.id) return null;
                        return <option key={s.id} value={s.id}>{s.name} ({s.position})</option>;
                      })}
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-1 block">Keterangan (Opsional)</label>
                    <input 
                      type="text" 
                      placeholder="NIP / Info" 
                      value={item.description} 
                      onChange={(e) => handleUpdate(index, 'description', e.target.value)} 
                      className="w-full border-none bg-slate-50 hover:bg-white p-2 rounded-[var(--ui-radius-small)] text-sm focus:outline-[var(--ui-primary)] transition-colors"
                    />
                  </div>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-2 shrink-0 self-end md:self-auto w-full md:w-auto justify-end">
                  <div className="md:hidden text-xs font-bold text-slate-400 mr-auto uppercase tracking-wider">
                     Urutan #{index + 1}
                  </div>
                  {item.photoUrl && (
                    <button onClick={() => handleUpdate(index, 'photoUrl', '')} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-[var(--ui-radius-small)] transition-colors" title="Hapus Foto">
                      <ImageIcon size={16} className="opacity-50" />
                    </button>
                  )}
                  <button onClick={() => handleRemove(index)} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-[var(--ui-radius-small)] transition-colors" title="Hapus Data">
                    <Trash2 size={16} />
                  </button>
                </div>

              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { Activity, Trash2, User, Database, CheckCircle2, Edit2, LogOut, Send, ShieldCheck, Key, History } from 'lucide-react';
import useAuthStore from '../../../store/monitoring/authStore.js';
import { Search, RefreshCw, AlertCircle } from 'lucide-react';
import { PageHeader } from '../../../components/monitoring/ui/index.js';
import { UISelect } from '../../../components/ui.jsx';


const ACTION_COLORS = {
  UPDATE: { bg: 'bg-blue-50', text: 'text-blue-700', border: 'border-blue-200' },
  UPSERT: { bg: 'bg-emerald-50', text: 'text-emerald-700', border: 'border-emerald-200' },
  DELETE: { bg: 'bg-red-50', text: 'text-red-700', border: 'border-red-200' },
  SEND_WA: { bg: 'bg-green-50', text: 'text-green-700', border: 'border-green-200' },
  LOGIN: { bg: 'bg-violet-50', text: 'text-violet-700', border: 'border-violet-200' },
  LOGOUT: { bg: 'bg-slate-50', text: 'text-slate-600', border: 'border-slate-200' },
  KENAIKAN_KELAS: { bg: 'bg-amber-50', text: 'text-amber-700', border: 'border-amber-200' },
  DEFAULT: { bg: 'bg-slate-50', text: 'text-slate-600', border: 'border-slate-200' },
};

const ACTION_ICONS = {
  UPDATE: Edit2, UPSERT: CheckCircle2, DELETE: Trash2, SEND_WA: Send,
  LOGIN: User, LOGOUT: LogOut, KENAIKAN_KELAS: Activity, DEFAULT: Database,
};

export default function AuditLog({ activeTab, setActiveTab }) {
  const [logs, setLogs] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [filterAction, setFilterAction] = useState('all');
  const [filterRole, setFilterRole] = useState('all');
  const [toast, setToast] = useState(null);
  const authToken = useAuthStore(state => state.user?.authToken);
  const LIMIT = 50;

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const fetchLogs = async (p = 1) => {
    if (!authToken) return;
    setIsLoading(true);
    try {
      const res = await fetch(`/api/audit-logs?page=${p}&limit=${LIMIT}`, { headers: { Authorization: `Bearer ${authToken}` } });
      const data = await res.json();
      if (data.ok) { setLogs(data.data || []); setTotal(data.total || 0); }
    } catch (e) { console.error(e); }
    setIsLoading(false);
  };

  useEffect(() => { fetchLogs(page); }, [authToken, page]);

  const handleClearLogs = async () => {
    if (!await window.confirmAsync('Hapus SEMUA log aktivitas? Tindakan ini tidak bisa dibatalkan.')) return;
    try {
      await fetch('/api/audit-logs', {
        method: 'POST', headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'clear' }),
      });
      showToast('Semua log berhasil dibersihkan.');
      setLogs([]); setTotal(0); setPage(1);
    } catch (e) { showToast('Gagal.', 'error'); }
  };

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const matchSearch = !search || log.user_name?.toLowerCase().includes(search.toLowerCase()) || log.action?.toLowerCase().includes(search.toLowerCase()) || log.detail?.toLowerCase().includes(search.toLowerCase()) || log.target_type?.toLowerCase().includes(search.toLowerCase());
      const matchAction = filterAction === 'all' || log.action === filterAction;
      const matchRole = filterRole === 'all' || log.user_role === filterRole;
      return matchSearch && matchAction && matchRole;
    });
  }, [logs, search, filterAction, filterRole]);

  const uniqueActions = useMemo(() => ['all', ...new Set(logs.map(l => l.action).filter(Boolean))], [logs]);
  const uniqueRoles = useMemo(() => ['all', ...new Set(logs.map(l => l.user_role).filter(Boolean))], [logs]);
  const totalPages = Math.ceil(total / LIMIT);

  return (
    <div className="space-y-6 relative animate-in fade-in duration-300 z-10">
      <PageHeader 
        title="Log Aktivitas (Audit Trail)"
        description="Rekam jejak semua perubahan data penting yang dilakukan oleh pengguna sistem."
        icon={Activity}
        tabs={[
          { id: "hak_akses", label: "Hak Akses & Role", icon: ShieldCheck },
          { id: "pengaturanuser", label: "Akun Pengguna", icon: Key },
          { id: "audit_log", label: "Audit Log & Aktivitas", icon: History }
        ]}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      />

      {/* Filters & Actions Bar */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-4 rounded-[var(--ui-radius-small)] border-none shadow-sm">
        <div className="flex flex-wrap items-center gap-3 flex-1">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Cari pengguna, aksi, detail..."
              className="w-full pl-9 pr-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:border-[var(--ui-primary)]" />
          </div>
          <div className="w-48">
            <UISelect value={filterAction} onChange={e => setFilterAction(e.target.value)} className="!py-2 !text-sm bg-slate-50">
              {uniqueActions.map(a => <option key={a} value={a}>{a === 'all' ? 'Semua Aksi' : a}</option>)}
            </UISelect>
          </div>
          <div className="w-40">
            <UISelect value={filterRole} onChange={e => setFilterRole(e.target.value)} className="!py-2 !text-sm bg-slate-50">
              {uniqueRoles.map(r => <option key={r} value={r}>{r === 'all' ? 'Semua Role' : r}</option>)}
            </UISelect>
          </div>
        </div>

        <div className="flex items-center gap-2 self-start lg:self-center">
          <span className="text-xs text-slate-500 bg-slate-100 border border-slate-200 px-3 py-1.5 rounded-[var(--ui-radius-small)] font-bold">{total.toLocaleString()} total log</span>
          <button onClick={() => fetchLogs(page)} className="flex items-center gap-2 text-xs font-bold text-slate-600 bg-slate-50 hover:bg-slate-100 border border-slate-200 px-3 py-1.5 rounded-[var(--ui-radius-small)] transition-all">
            <RefreshCw size={14} /> Refresh
          </button>
          <button onClick={handleClearLogs} className="flex items-center gap-2 text-xs font-bold text-white bg-red-600 hover:bg-red-700 px-3 py-1.5 rounded-[var(--ui-radius-small)] transition-all">
            <Trash2 size={14} /> Bersihkan
          </button>
        </div>
      </div>

      {/* Log Table */}
      <div className="bg-white rounded-[var(--ui-radius-small)] border-none shadow-sm overflow-hidden">
        <table className="w-full text-sm">
          <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-4 py-3 font-bold text-left w-40">Waktu</th>
              <th className="px-4 py-3 font-bold text-left">Pengguna</th>
              <th className="px-4 py-3 font-bold text-center w-32">Aksi</th>
              <th className="px-4 py-3 font-bold text-left">Objek</th>
              <th className="px-4 py-3 font-bold text-left">Keterangan</th>
            </tr>
          </thead>
          <tbody>
            {isLoading ? (
              <tr><td colSpan={5} className="px-4 py-10 text-center text-slate-400">Memuat log...</td></tr>
            ) : filteredLogs.length === 0 ? (
              <tr><td colSpan={5} className="px-4 py-10 text-center text-slate-400">
                {logs.length === 0 ? 'Belum ada aktivitas yang tercatat.' : 'Tidak ada log yang cocok dengan filter.'}
              </td></tr>
            ) : filteredLogs.map(log => {
              const colors = ACTION_COLORS[log.action] || ACTION_COLORS.DEFAULT;
              const ActionIcon = ACTION_ICONS[log.action] || ACTION_ICONS.DEFAULT;
              return (
                <tr key={log.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                  <td className="px-4 py-3 text-xs text-slate-400 font-mono whitespace-nowrap">
                    {new Date(log.created_at).toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: '2-digit' })}<br />
                    {new Date(log.created_at).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      <div className="w-7 h-7 rounded-full bg-[var(--ui-primary)]/10 flex items-center justify-center shrink-0">
                        <User size={12} className="text-[var(--ui-primary)]" />
                      </div>
                      <div>
                        <p className="font-bold text-slate-700 text-xs">{log.user_name || 'Sistem'}</p>
                        <p className="text-[10px] text-slate-400">{log.user_role || '-'} {log.ip_address ? `• ${log.ip_address}` : ''}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-[var(--ui-radius-small)] text-[10px] font-bold border ${colors.bg} ${colors.text} ${colors.border}`}>
                      <ActionIcon size={9} />
                      {log.action}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    <span className="text-xs bg-slate-100 text-slate-600 px-2 py-0.5 rounded-[var(--ui-radius-small)] font-mono">{log.target_type}</span>
                    {log.target_id && <span className="text-xs text-slate-400 ml-1">#{log.target_id}</span>}
                  </td>
                  <td className="px-4 py-3 text-xs text-slate-600 max-w-xs">
                    <p className="line-clamp-2">{log.detail || '-'}</p>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="px-4 py-3 border-t border-slate-100 flex items-center justify-between bg-slate-50">
            <p className="text-xs text-slate-500">Halaman {page} dari {totalPages} ({total} total)</p>
            <div className="flex gap-2">
              <button disabled={page <= 1} onClick={() => setPage(p => p - 1)}
                className="px-3 py-1.5 text-xs font-bold rounded-[var(--ui-radius-small)] border-none bg-white text-slate-600 hover:border-[var(--ui-primary)] disabled:opacity-40 disabled:cursor-not-allowed">← Prev</button>
              <button disabled={page >= totalPages} onClick={() => setPage(p => p + 1)}
                className="px-3 py-1.5 text-xs font-bold rounded-[var(--ui-radius-small)] border-none bg-white text-slate-600 hover:border-[var(--ui-primary)] disabled:opacity-40 disabled:cursor-not-allowed">Next →</button>
            </div>
          </div>
        )}
      </div>

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-sm font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { CloudUpload, Settings, LayoutDashboard, KeyRound, DatabaseBackup, MessageSquare } from 'lucide-react';
import useAuthStore from '../../../store/monitoring/authStore.js';
import { HardDrive, Send, Cloud, UploadCloud, Trash2, FileSpreadsheet, Download, CheckCircle2, AlertCircle, RefreshCw, Info, Shield, Calendar } from 'lucide-react';
