export default function BackupGDrive({ activeTab: activeSystemTab, setActiveTab: setSystemTab }) {
  const [activeTab, setActiveTab] = useState('local'); // 'local', 'telegram', 'r2', 'gdrive', 'restore', 'archive'

  const [isTelegramConfigured, setIsTelegramConfigured] = useState(false);
  const [isR2Configured, setIsR2Configured] = useState(false);
  const [isGDriveConfigured, setIsGDriveConfigured] = useState(false);
  const [isCheckingConfig, setIsCheckingConfig] = useState(true);

  const [isBackingUp, setIsBackingUp] = useState(false);
  const [isRestoring, setIsRestoring] = useState(false);
  const [isArchiving, setIsArchiving] = useState(false);
  const [archiveDate, setArchiveDate] = useState('');

  const [backupLogs, setBackupLogs] = useState([]);
  const [toast, setToast] = useState(null);
  const fileInputRef = useRef(null);

  const authToken = useAuthStore(state => state.user?.authToken);

  const showToast = (msg, type = 'success') => { setToast({ message: msg, type }); setTimeout(() => setToast(null), 3500); };

  useEffect(() => {
    const checkConfig = async () => {
      if (!authToken) return;
      try {
        const res = await fetch('/api/api-keys', { headers: { Authorization: `Bearer ${authToken}` } });
        const data = await res.json();
        if (data.ok) {
          const telegramKey = (data.data || []).find(k => k.service_name === 'telegram_backup' && k.is_active);
          const r2Key = (data.data || []).find(k => k.service_name === 'cloudflare_r2' && k.is_active);
          const gdriveKey = (data.data || []).find(k => k.service_name === 'google_drive' && k.is_active);
          setIsTelegramConfigured(!!telegramKey);
          setIsR2Configured(!!r2Key);
          setIsGDriveConfigured(!!gdriveKey);
        }
      } catch (e) { console.error(e); }
      setIsCheckingConfig(false);
    };
    checkConfig();

    // Default 6 months ago for archive
    const d = new Date();
    d.setMonth(d.getMonth() - 6);
    setArchiveDate(d.toISOString().split('T')[0]);
  }, [authToken]);

  const handleManualBackup = async (type) => {
    setIsBackingUp(true);
    let apiEndpoint = '';
    let label = '';
    if (type === 'telegram') { apiEndpoint = '/api/backup-telegram'; label = 'Telegram'; }
    if (type === 'gdrive') { apiEndpoint = '/api/backup-gdrive'; label = 'Google Drive'; }
    if (type === 'r2') { apiEndpoint = '/api/backup-r2'; label = 'Cloudflare R2'; }

    showToast(`Memulai backup ke ${label}...`, 'success');

    try {
      const res = await fetch(apiEndpoint, {
        method: 'POST',
        headers: { Authorization: `Bearer ${authToken}` }
      });
      const data = await res.json();

      if (data.ok) {
        const newLog = { 
          id: Date.now(), type: label, status: 'success', filename: data.data.filename, size: data.data.size, created_at: new Date().toISOString() 
        };
        setBackupLogs(prev => [newLog, ...prev]);
        showToast(`Backup berhasil dikirim ke ${label}! 🎉`);
      } else {
        showToast(data.error || 'Terjadi kesalahan saat mem-backup.', 'error');
      }
    } catch (e) {
      showToast('Gagal memanggil API backup.', 'error');
    } finally {
      setIsBackingUp(false);
    }
  };

  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (!file.name.endsWith('.json')) {
      showToast('File backup harus berformat .json', 'error');
      return;
    }

    if (!await window.confirmAsync('PERINGATAN: Memulihkan database akan menimpa SEMUA data yang ada saat ini. Apakah Anda yakin?')) {
      e.target.value = '';
      return;
    }

    setIsRestoring(true);
    showToast('Memulihkan database, mohon tunggu...', 'success');

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const jsonContent = event.target.result;
        JSON.parse(jsonContent);

        const res = await fetch('/api/restore-backup', {
          method: 'POST',
          headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
          body: jsonContent
        });
        const data = await res.json();

        if (data.ok) {
          showToast('Database berhasil dipulihkan! 🎉');
          setTimeout(() => window.location.reload(), 2000);
        } else {
          showToast(data.error || 'Terjadi kesalahan saat memulihkan.', 'error');
        }
      } catch (e) {
        showToast('File tidak valid atau gagal terhubung ke server.', 'error');
      } finally {
        setIsRestoring(false);
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleArchive = async () => {
    if (!archiveDate) return;
    if (!await window.confirmAsync(`PERINGATAN KRITIKAL! Anda akan MENGHAPUS PERMANEN seluruh data log/absensi yang dibuat sebelum tanggal ${archiveDate}. Data ini akan diunggah ke Cloud sebagai arsip. Lanjutkan?`)) {
      return;
    }

    setIsArchiving(true);
    showToast('Memulai proses pengarsipan dan pembersihan...', 'success');

    try {
      const res = await fetch('/api/archive-data', {
        method: 'POST',
        headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ dateBefore: archiveDate + 'T00:00:00Z' })
      });
      const data = await res.json();

      if (data.ok) {
        showToast(data.message);
      } else {
        showToast(data.error || 'Gagal melakukan pembersihan.', 'error');
      }
    } catch (e) {
      showToast('Gagal memanggil API.', 'error');
    } finally {
      setIsArchiving(false);
    }
  };

  return (
    <div className="space-y-6 relative animate-in fade-in duration-300 z-10">
      <PageHeader 
        title="Manajemen Backup & Arsip"
        description="Kelola pencadangan database sekolah ke berbagai platform (R2, Telegram, GDrive) dan bersihkan data lampau."
        icon={CloudUpload}
        tabs={[
          { id: "fitur", label: "Fitur", icon: Settings },
          { id: "tampilan", label: "Tampilan Web", icon: LayoutDashboard },
          { id: "whatsapp", label: "WhatsApp", icon: MessageSquare },
          { id: "api_keys", label: "API Key", icon: KeyRound },
          { id: "gdrive_backup", label: "Backup", icon: DatabaseBackup }
        ]}
        activeTab={activeSystemTab}
        onTabChange={setSystemTab}
      />

      {/* TABS */}
      <div className="flex border-b border-slate-200 gap-4 overflow-x-auto">
        <button onClick={() => setActiveTab('local')} className={`pb-3 font-bold text-sm transition-colors border-b-2 whitespace-nowrap px-2 ${activeTab === 'local' ? 'border-[var(--ui-primary)] text-[var(--ui-primary)]' : 'border-transparent text-slate-500 hover:text-slate-700'}`}>
          <div className="flex items-center gap-2"><HardDrive size={16} /> Backup Lokal</div>
        </button>
        <button onClick={() => setActiveTab('telegram')} className={`pb-3 font-bold text-sm transition-colors border-b-2 whitespace-nowrap px-2 ${activeTab === 'telegram' ? 'border-[var(--ui-primary)] text-[var(--ui-primary)]' : 'border-transparent text-slate-500 hover:text-slate-700'}`}>
          <div className="flex items-center gap-2"><Send size={16} /> Telegram</div>
        </button>
        <button onClick={() => setActiveTab('r2')} className={`pb-3 font-bold text-sm transition-colors border-b-2 whitespace-nowrap px-2 ${activeTab === 'r2' ? 'border-[var(--ui-primary)] text-[var(--ui-primary)]' : 'border-transparent text-slate-500 hover:text-slate-700'}`}>
          <div className="flex items-center gap-2"><Cloud size={16} /> Cloudflare R2</div>
        </button>
        <button onClick={() => setActiveTab('gdrive')} className={`pb-3 font-bold text-sm transition-colors border-b-2 whitespace-nowrap px-2 ${activeTab === 'gdrive' ? 'border-[var(--ui-primary)] text-[var(--ui-primary)]' : 'border-transparent text-slate-500 hover:text-slate-700'}`}>
          <div className="flex items-center gap-2"><HardDrive size={16} /> Google Drive</div>
        </button>
        <button onClick={() => setActiveTab('restore')} className={`pb-3 font-bold text-sm transition-colors border-b-2 whitespace-nowrap px-2 ${activeTab === 'restore' ? 'border-[var(--ui-primary)] text-[var(--ui-primary)]' : 'border-transparent text-slate-500 hover:text-slate-700'}`}>
          <div className="flex items-center gap-2"><UploadCloud size={16} /> Pulihkan Data</div>
        </button>
        <button onClick={() => setActiveTab('archive')} className={`pb-3 font-bold text-sm transition-colors border-b-2 whitespace-nowrap px-2 ${activeTab === 'archive' ? 'border-red-500 text-red-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}>
          <div className="flex items-center gap-2"><Trash2 size={16} /> Arsip & Bersihkan</div>
        </button>
      </div>

      {/* TAB CONTENT: LOCAL BACKUP */}
      {activeTab === 'local' && (
        <div className="space-y-6 animate-in fade-in">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

            {/* Card 1: Excel Master Data Backup */}
            <div className="ui-card p-6 flex flex-col justify-between relative group hover:border-[var(--ui-primary)] transition-all">
              <div className="flex items-start gap-4 mb-4">
                <div className="w-12 h-12 bg-emerald-100 text-emerald-600 rounded-[var(--ui-radius-small)] flex items-center justify-center shrink-0">
                  <FileSpreadsheet size={24} />
                </div>
                <div>
                  <h4 className="font-bold text-slate-800 text-sm">Backup Master Data (Format Excel)</h4>
                  <p className="text-xs text-slate-500 mt-1 font-medium leading-relaxed">
                    Ekspor seluruh data akademik primer (Jurusan, Kelas, Guru, Mapel, Ruangan, Beban, Modul Ajar, Sesi Belajar, Ketersediaan) ke dalam format dokumen Excel (.xlsx) multi-sheet.
                  </p>
                </div>
              </div>
              <button 
                onClick={() => {
                  window.open(`/api/backup/excel?token=${authToken || ''}`, '_blank');
                }}
                className="w-full mt-4 flex items-center justify-center gap-2 py-2.5 px-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-[var(--ui-radius-small)] font-bold text-xs shadow-sm transition-colors border-none cursor-pointer"
              >
                <Download size={14} /> Unduh Master Data Excel (.xlsx)
              </button>
            </div>

            {/* Card 2: PostgreSQL Dump Backup */}
            <div className="ui-card p-6 flex flex-col justify-between relative group hover:border-[var(--ui-primary)] transition-all">
              <div className="flex items-start gap-4 mb-4">
                <div className="w-12 h-12 bg-indigo-100 text-indigo-600 rounded-[var(--ui-radius-small)] flex items-center justify-center shrink-0">
                  <DatabaseBackup size={24} />
                </div>
                <div>
                  <h4 className="font-bold text-slate-800 text-sm">Backup Relasional Database (PostgreSQL Dump)</h4>
                  <p className="text-xs text-slate-500 mt-1 font-medium leading-relaxed">
                    Unduh skrip skema relasional lengkap beserta seluruh record/baris data (DML SQL) dari PostgreSQL untuk pemulihan database penuh secara cepat.
                  </p>
                </div>
              </div>
              <button 
                onClick={() => {
                  window.open(`/api/backup/postgresql?token=${authToken || ''}`, '_blank');
                }}
                className="w-full mt-4 flex items-center justify-center gap-2 py-2.5 px-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-[var(--ui-radius-small)] font-bold text-xs shadow-sm transition-colors border-none cursor-pointer"
              >
                <Download size={14} /> Unduh Database Dump SQL (.sql)
              </button>
            </div>

          </div>
        </div>
      )}

      {/* TAB CONTENT: TELEGRAM */}
      {activeTab === 'telegram' && (
        <div className="space-y-6 animate-in fade-in">
          {!isCheckingConfig && (
            <div className={`p-5 rounded-[var(--ui-radius-small)] border-2 flex items-start justify-between gap-4 ${isTelegramConfigured ? 'bg-emerald-50 border-emerald-300' : 'bg-amber-50 border-amber-300'}`}>
              <div className="flex items-start gap-4">
                <div className={`w-10 h-10 rounded-[var(--ui-radius-small)] flex items-center justify-center shrink-0 ${isTelegramConfigured ? 'bg-emerald-100' : 'bg-amber-100'}`}>
                  {isTelegramConfigured ? <CheckCircle2 size={20} className="text-emerald-600" /> : <AlertCircle size={20} className="text-amber-600" />}
                </div>
                <div>
                  <p className={`font-bold flex items-center gap-1.5 ${isTelegramConfigured ? 'text-emerald-700' : 'text-amber-700'}`}>
                    {isTelegramConfigured ? (
                      <>
                        <span>Telegram Terhubung</span>
                        <CheckCircle2 size={13} className="text-emerald-600" />
                      </>
                    ) : (
                      <span>Telegram Belum Dikonfigurasi</span>
                    )}
                  </p>
                  <p className={`text-sm mt-0.5 ${isTelegramConfigured ? 'text-emerald-600' : 'text-amber-600'}`}>
                    {isTelegramConfigured
                      ? 'Backup otomatis aktif setiap hari pukul 02:00 WIB. Data terkirim ke obrolan Telegram Anda secara gratis dan bebas limit.'
                      : 'Tambahkan API Key Telegram di menu Manajemen API Key → pilih "Telegram Auto-Backup".'}
                  </p>
                </div>
              </div>
              <Button onClick={() => handleManualBackup('telegram')} disabled={isBackingUp || !isTelegramConfigured} className="flex items-center gap-2 shrink-0">
                {isBackingUp ? <RefreshCw size={14} className="animate-spin" /> : <CloudUpload size={14} />} Backup Telegram
              </Button>
            </div>
          )}
        </div>
      )}

      {/* TAB CONTENT: R2 */}
      {activeTab === 'r2' && (
        <div className="space-y-6 animate-in fade-in">
          {!isCheckingConfig && (
            <div className={`p-5 rounded-[var(--ui-radius-small)] border-2 flex items-start justify-between gap-4 ${isR2Configured ? 'bg-emerald-50 border-emerald-300' : 'bg-amber-50 border-amber-300'}`}>
              <div className="flex items-start gap-4">
                <div className={`w-10 h-10 rounded-[var(--ui-radius-small)] flex items-center justify-center shrink-0 ${isR2Configured ? 'bg-emerald-100' : 'bg-amber-100'}`}>
                  {isR2Configured ? <CheckCircle2 size={20} className="text-emerald-600" /> : <AlertCircle size={20} className="text-amber-600" />}
                </div>
                <div>
                  <p className={`font-bold flex items-center gap-1.5 ${isR2Configured ? 'text-emerald-700' : 'text-amber-700'}`}>
                    {isR2Configured ? (
                      <>
                        <span>Cloudflare R2 Terhubung</span>
                        <CheckCircle2 size={13} className="text-emerald-600" />
                      </>
                    ) : (
                      <span>Cloudflare R2 Belum Dikonfigurasi</span>
                    )}
                  </p>
                  <p className={`text-sm mt-0.5 ${isR2Configured ? 'text-emerald-600' : 'text-amber-600'}`}>
                    {isR2Configured
                      ? 'Backup otomatis aktif setiap hari pukul 02:00 WIB. File tersimpan aman di Cloudflare (AWS S3) tanpa biaya egress.'
                      : 'Tambahkan API Key di menu Manajemen API Key → pilih "Cloudflare R2 Backup".'}
                  </p>
                </div>
              </div>
              <Button onClick={() => handleManualBackup('r2')} disabled={isBackingUp || !isR2Configured} className="flex items-center gap-2 shrink-0">
                {isBackingUp ? <RefreshCw size={14} className="animate-spin" /> : <CloudUpload size={14} />} Backup R2
              </Button>
            </div>
          )}

          <div className="bg-white rounded-xl border-none shadow-sm p-6">
            <h2 className="font-bold text-slate-700 mb-4 flex items-center gap-2"><Info size={16} className="text-[var(--ui-primary)]" /> Cara Setup Cloudflare R2</h2>
            <ol className="space-y-3">
              {[
                { step: '1', title: 'Buat Akun Cloudflare', desc: 'Daftar di cloudflare.com, masuk to menu R2 Object Storage.' },
                { step: '2', title: 'Buat Bucket Baru', desc: 'Buat Bucket baru (misal: kurmon-backup). Catat nama bucket ini.' },
                { step: '3', title: 'Dapatkan Kredensial', desc: 'Pilih "Manage R2 API Tokens", buat token dengan akses Admin Read & Write. Anda akan mendapatkan Access Key dan Secret Key.' },
                { step: '4', title: 'Dapatkan Endpoint URL', desc: 'Di halaman dashboard R2, Anda akan melihat URL Endpoint (contoh: https://<account_id>.r2.cloudflarestorage.com).' },
                { step: '5', title: 'Simpan di Sistem', desc: 'Salin semua data tersebut dan simpan di Manajemen API Key.' },
              ].map(item => (
                <li key={item.step} className="flex items-start gap-4">
                  <span className="w-8 h-8 rounded-full bg-[var(--ui-primary)] text-white font-black text-sm flex items-center justify-center shrink-0">{item.step}</span>
                  <div>
                    <p className="font-bold text-slate-700 text-sm">{item.title}</p>
                    <p className="text-xs text-slate-500 mt-0.5">{item.desc}</p>
                  </div>
                </li>
              ))}
            </ol>
          </div>
        </div>
      )}

      {/* TAB CONTENT: G DRIVE */}
      {activeTab === 'gdrive' && (
        <div className="space-y-6 animate-in fade-in">
          {!isCheckingConfig && (
            <div className={`p-5 rounded-[var(--ui-radius-small)] border-2 flex items-start justify-between gap-4 ${isGDriveConfigured ? 'bg-emerald-50 border-emerald-300' : 'bg-amber-50 border-amber-300'}`}>
              <div className="flex items-start gap-4">
                <div className={`w-10 h-10 rounded-[var(--ui-radius-small)] flex items-center justify-center shrink-0 ${isGDriveConfigured ? 'bg-emerald-100' : 'bg-amber-100'}`}>
                  {isGDriveConfigured ? <CheckCircle2 size={20} className="text-emerald-600" /> : <AlertCircle size={20} className="text-amber-600" />}
                </div>
                <div>
                  <p className={`font-bold flex items-center gap-1.5 ${isGDriveConfigured ? 'text-emerald-700' : 'text-amber-700'}`}>
                    {isGDriveConfigured ? (
                      <>
                        <span>Google Drive Terhubung</span>
                        <CheckCircle2 size={13} className="text-emerald-600" />
                      </>
                    ) : (
                      <span>GDrive Belum Dikonfigurasi</span>
                    )}
                  </p>
                  <p className={`text-sm mt-0.5 ${isGDriveConfigured ? 'text-emerald-600' : 'text-amber-600'}`}>
                    {isGDriveConfigured
                      ? 'Backup otomatis aktif setiap hari pukul 02:00 WIB. File tersimpan di folder Google Drive Anda.'
                      : 'PENTING: Hanya untuk akun Google Workspace (belajar.id). Akun @gmail.com tidak bisa.'}
                  </p>
                </div>
              </div>
              <Button onClick={() => handleManualBackup('gdrive')} disabled={isBackingUp || !isGDriveConfigured} className="flex items-center gap-2 shrink-0">
                {isBackingUp ? <RefreshCw size={14} className="animate-spin" /> : <CloudUpload size={14} />} Backup GDrive
              </Button>
            </div>
          )}
        </div>
      )}

      {/* TAB CONTENT: RESTORE */}
      {activeTab === 'restore' && (
        <div className="space-y-6 animate-in fade-in">
          <div className="bg-white rounded-xl border-none shadow-sm p-8 text-center">
            <div className="w-20 h-20 bg-[var(--ui-primary)]/10 text-[var(--ui-primary)] rounded-full flex items-center justify-center mx-auto mb-6">
              <UploadCloud size={36} />
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Pulihkan Database (Restore)</h2>
            <p className="text-slate-500 mb-8 max-w-lg mx-auto">
              Sistem akan membaca file JSON dari backup dan memasukkan seluruh datanya kembali ke database.
            </p>

            <div className="inline-block p-4 bg-red-50 border border-red-200 rounded-[var(--ui-radius-small)] text-left mb-8 max-w-lg">
              <p className="text-sm font-bold text-red-700 flex items-center gap-2 mb-1"><AlertCircle size={16} /> PERINGATAN KRITIKAL!</p>
              <p className="text-xs text-red-600 leading-relaxed">
                Melakukan restore akan <b>MENGHAPUS SELURUH DATA</b> saat ini dan menggantinya dengan data dari file JSON yang diunggah.
              </p>
            </div>

            <div>
              <input type="file" accept=".json" className="hidden" ref={fileInputRef} onChange={handleFileChange} />
              <Button onClick={() => fileInputRef.current?.click()} disabled={isRestoring} size="lg" className="flex items-center justify-center gap-2 mx-auto min-w-[200px]">
                {isRestoring ? <RefreshCw size={18} className="animate-spin" /> : <Shield size={18} />}
                {isRestoring ? 'Memulihkan Data...' : 'Pilih File JSON & Restore'}
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* TAB CONTENT: ARCHIVE */}
      {activeTab === 'archive' && (
        <div className="space-y-6 animate-in fade-in">
          <div className="bg-white rounded-xl border-none shadow-sm p-8 text-center">
            <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6">
              <Trash2 size={36} />
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Arsip & Pembersihan (Purging)</h2>
            <p className="text-slate-500 mb-8 max-w-lg mx-auto">
              Fitur ini akan menarik miliaran data log/absensi lampau, membungkusnya menjadi JSON Arsip ke Cloud, lalu menghapusnya secara permanen dari server agar sistem kembali super cepat.
            </p>

            <div className="inline-block p-4 bg-amber-50 border border-amber-200 rounded-[var(--ui-radius-small)] text-left mb-6 max-w-lg">
              <p className="text-sm font-bold text-amber-700 flex items-center gap-2 mb-1"><AlertCircle size={16} /> Syarat Pembersihan</p>
              <p className="text-xs text-amber-600 leading-relaxed">
                Pembersihan hanya dapat dijalankan jika Anda telah menghubungkan salah satu layanan penyimpanan Cloud <b>(Cloudflare R2 atau Telegram)</b>.
                Data tidak akan dihapus jika proses unggah ke awan gagal demi keamanan data Anda.
              </p>
            </div>

            <div className="max-w-xs mx-auto mb-8 text-left">
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Hapus Semua Log Sebelum Tanggal:</label>
              <input type="date" value={archiveDate} onChange={e => setArchiveDate(e.target.value)}
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-bold text-slate-700 focus:outline-none focus:border-[var(--ui-primary)]" />
            </div>

            <div>
              <Button onClick={handleArchive} disabled={isArchiving || !archiveDate || (!isTelegramConfigured && !isR2Configured)} size="lg" className="flex items-center justify-center gap-2 mx-auto min-w-[200px] bg-red-600 hover:bg-red-700 border-red-600">
                {isArchiving ? <RefreshCw size={18} className="animate-spin text-white" /> : <Trash2 size={18} className="text-white" />}
                <span className="text-white">{isArchiving ? 'Sedang Memproses...' : 'Mulai Bersihkan Data'}</span>
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* LOGS TABLE (Shared) */}
      <div className="bg-white rounded-[var(--ui-radius-small)] border-none shadow-sm overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between">
          <h2 className="font-bold text-slate-700 flex items-center gap-2"><Calendar size={16} /> Riwayat Eksekusi (Sesi Ini)</h2>
        </div>
        <table className="w-full text-sm">
          <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-4 py-3 font-bold text-left">Platform</th>
              <th className="px-4 py-3 font-bold text-left">File Backup</th>
              <th className="px-4 py-3 font-bold text-center">Ukuran</th>
              <th className="px-4 py-3 font-bold text-center">Status</th>
            </tr>
          </thead>
          <tbody>
            {backupLogs.length === 0 ? (
              <tr>
                <td colSpan="4" className="px-4 py-8 text-center text-slate-500">Belum ada riwayat aktivitas di sesi ini.</td>
              </tr>
            ) : backupLogs.map(log => (
              <tr key={log.id} className="border-b border-slate-100 hover:bg-slate-50">
                <td className="px-4 py-3 font-bold text-xs text-slate-700">{log.type}</td>
                <td className="px-4 py-3 font-mono text-xs text-slate-600">{log.filename}</td>
                <td className="px-4 py-3 text-center text-slate-500 text-xs">{log.size || '-'}</td>
                <td className="px-4 py-3 text-center">
                  <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-[var(--ui-radius-small)] text-[10px] font-bold ${log.status === 'success' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                    {log.status === 'success' ? <CheckCircle2 size={9} /> : <AlertCircle size={9} />} Sukses
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-sm font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white max-w-sm ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { FileText, Printer, FileSignature } from 'lucide-react';
import useAuthStore from '../../../store/monitoring/authStore.js';
import { useAppStore } from '../../../store/useAppStore';
import { Plus, Edit2, Trash2, X, AlertCircle, CheckCircle2 } from 'lucide-react';
import { PageHeader, Button } from '../../../components/monitoring/ui/index.js';


const JENIS_SURAT = [
  { key: 'sp1', label: 'Surat Panggilan 1 (SP1)', desc: 'Peringatan pertama untuk siswa bermasalah' },
  { key: 'sp2', label: 'Surat Panggilan 2 (SP2)', desc: 'Peringatan kedua, orang tua wajib hadir' },
  { key: 'sp3', label: 'Surat Panggilan 3 (SP3)', desc: 'Peringatan ketiga, ancaman skorsing' },
  { key: 'ket_aktif', label: 'Surat Keterangan Aktif', desc: 'Menerangkan bahwa siswa masih aktif bersekolah' },
  { key: 'ket_lulus', label: 'Surat Keterangan Lulus', desc: 'Surat keterangan kelulusan sementara' },
  { key: 'mutasi', label: 'Surat Keterangan Mutasi', desc: 'Perpindahan siswa ke sekolah lain' },
  { key: 'dispensasi', label: 'Surat Dispensasi', desc: 'Izin tidak masuk untuk kegiatan resmi' },
  { key: 'custom', label: 'Template Custom', desc: 'Buat template surat sesuai kebutuhan' },
];

const PLACEHOLDER_VARIABLES = [
  { var: '{NAMA_SISWA}', desc: 'Nama lengkap siswa' },
  { var: '{NIS}', desc: 'Nomor Induk Siswa' },
  { var: '{NISN}', desc: 'Nomor Induk Siswa Nasional' },
  { var: '{KELAS}', desc: 'Kelas siswa' },
  { var: '{JURUSAN}', desc: 'Jurusan/Kompetensi' },
  { var: '{NAMA_SEKOLAH}', desc: 'Nama sekolah' },
  { var: '{NAMA_KEPSEK}', desc: 'Nama Kepala Sekolah' },
  { var: '{NIP_KEPSEK}', desc: 'NIP Kepala Sekolah' },
  { var: '{TANGGAL}', desc: 'Tanggal hari ini' },
  { var: '{KETERANGAN}', desc: 'Keterangan / alasan khusus' },
  { var: '{TOTAL_POIN}', desc: 'Total poin pelanggaran' },
];

function PrintPreview({ template, student, school, appSettings = {} }) {
  const today = new Date().toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  const rendered = (template?.isi_template || '').replace(/{NAMA_SISWA}/g, student?.name || '[NAMA_SISWA]').replace(/{NIS}/g, student?.nis || '[NIS]').replace(/{NISN}/g, student?.nisn || '[NISN]').replace(/{KELAS}/g, student?.class_name || '[KELAS]').replace(/{JURUSAN}/g, student?.major || '[JURUSAN]').replace(/{NAMA_SEKOLAH}/g, school?.nama_sekolah || '[NAMA_SEKOLAH]').replace(/{NAMA_KEPSEK}/g, school?.kepala_sekolah || '[NAMA_KEPSEK]').replace(/{NIP_KEPSEK}/g, school?.nip_kepsek || '[NIP_KEPSEK]').replace(/{TANGGAL}/g, today).replace(/{KETERANGAN}/g, '[KETERANGAN]').replace(/{TOTAL_POIN}/g, '[TOTAL_POIN]');

  return (
    <div className="bg-white p-8 rounded-[var(--ui-radius-small)] border-2 border-slate-200 text-sm leading-loose font-serif text-slate-800" style={{ minHeight: '400px' }}>
      {/* Kop Surat */}
      {appSettings.useKopSuratGambar && appSettings.kopSuratGambar ? (
        <img src={appSettings.kopSuratGambar} alt="Kop Surat" className="w-full h-auto object-contain mb-6" />
      ) : (
        <div className="flex items-center gap-4 pb-4 border-b-4 border-double border-slate-800 mb-6">
          {school?.logo_url && <img src={school.logo_url} alt="Logo" className="w-16 h-16 object-contain" />}
          <div className="text-center flex-1">
            <p className="text-xs">PEMERINTAH DAERAH</p>
            <h2 className="font-black text-xl uppercase">{school?.nama_sekolah || 'NAMA SEKOLAH'}</h2>
            <p className="text-xs">{school?.alamat || 'Alamat Sekolah'}</p>
            <p className="text-xs">Telp: {school?.telepon || '-'} | Website: {school?.website || '-'}</p>
            <p className="text-xs">Email: {school?.email || '-'}</p>
          </div>
        </div>
      )}
      <div className="whitespace-pre-wrap text-justify">{rendered || <span className="text-slate-300 italic">Isi template akan muncul di sini...</span>}</div>
    </div>
  );
}

export default function ESurat() {
  const [templates, setTemplates] = useState([]);
  const [students, setStudents] = useState([]);
  const [school, setSchool] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState(null);
  const [form, setForm] = useState({ jenis: 'sp1', nama: '', isi_template: '' });
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [studentSearch, setStudentSearch] = useState('');
  const [activeTab, setActiveTab] = useState('cetak');
  const [toast, setToast] = useState(null);
  const authToken = useAuthStore(state => state.user?.authToken);

  const showToast = (msg, type = 'success') => { setToast({ message: msg, type }); setTimeout(() => setToast(null), 3500); };

  const fetchData = async () => {
    if (!authToken) return;
    setIsLoading(true);
    try {
      const [tRes, sRes, scRes] = await Promise.all([
        fetch('/api/esurat', { headers: { Authorization: `Bearer ${authToken}` } }),
        fetch('/api/data/load', { headers: { Authorization: `Bearer ${authToken}` } }),
        fetch('/api/school-profile', { headers: { Authorization: `Bearer ${authToken}` } }),
      ]);
      const tData = await tRes.json(); if (tData.ok) setTemplates(tData.data || []);
      const sData = await sRes.json(); if (sData.payload && sData.payload.students) setStudents(sData.payload.students);
      const scData = await scRes.json(); if (scData.ok) setSchool(scData.data || {});
    } catch (e) { console.error(e); }
    setIsLoading(false);
  };

  useEffect(() => { fetchData(); }, [authToken]);

  const handleSave = async () => {
    if (!form.jenis || !form.nama || !form.isi_template) return showToast('Semua field wajib diisi!', 'error');
    try {
      const body = editingTemplate ? { ...form, id: editingTemplate.id } : form;
      const res = await fetch('/api/esurat', {
        method: 'POST', headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const data = await res.json();
      if (data.ok) { showToast(editingTemplate ? 'Template diperbarui!' : 'Template ditambahkan!'); setShowModal(false); fetchData(); }
      else showToast(data.error || 'Gagal.', 'error');
    } catch (e) { showToast('Gagal.', 'error'); }
  };

  const handleDelete = async (id) => {
    if (!await window.confirmAsync('Hapus template surat ini?')) return;
    try {
      await fetch('/api/esurat', {
        method: 'POST', headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delete', id }),
      });
      showToast('Dihapus!'); fetchData();
    } catch (e) { showToast('Gagal.', 'error'); }
  };

  const handlePrint = () => {
    if (!selectedTemplate || !selectedStudent) return showToast('Pilih template dan siswa terlebih dahulu!', 'error');
    window.print();
  };

  const filteredStudents = useMemo(() => students.filter(s => !studentSearch || (s.namaSiswa || s.name)?.toLowerCase().includes(studentSearch.toLowerCase()) || s.nis?.includes(studentSearch)), [students, studentSearch]);

  const tabs = [
    { id: 'cetak', label: 'Cetak Surat', icon: Printer },
    { id: 'template', label: 'Kelola Template', icon: FileText }
  ];

  return (
    <div className="space-y-4 relative animate-in fade-in duration-300">
      <PageHeader
        title="E-Surat & Template Surat"
        icon={FileSignature}
        description="Buat, kelola, dan cetak berbagai template surat sekolah dengan variabel otomatis."
        tabs={tabs}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      >
        <button 
          onClick={() => { setEditingTemplate(null); setForm({ jenis: 'sp1', nama: '', isi_template: '' }); setShowModal(true); }} 
          className="flex items-center gap-1.5 px-3 md:px-4 py-1.5 md:py-2 text-[11px] md:text-xs font-black rounded-[var(--ui-radius-small)] transition-all active:scale-95 cursor-pointer bg-white text-[var(--ui-primary)] shadow-sm hover:bg-slate-50 shrink-0 border border-transparent"
        >
          <Plus size={14} /> Buat Template
        </button>
      </PageHeader>

      {activeTab === 'cetak' && (
        <div className="grid grid-cols-1 lg:grid-cols-[300px,1fr] gap-6">
          {/* Panel Kiri */}
          <div className="space-y-4">
            <div className="ui-card p-4 space-y-3">
              <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">1. Pilih Template</p>
              {templates.length === 0 ? <p className="text-xs text-slate-400">Belum ada template. Buat di tab "Kelola Template".</p> :
                templates.map(t => (
                  <button key={t.id} onClick={() => setSelectedTemplate(t)}
                    className={`w-full text-left p-3 rounded-[var(--ui-radius-small)] border transition-all ${selectedTemplate?.id === t.id ? 'bg-[var(--ui-primary)]/10 border-[var(--ui-primary)] text-[var(--ui-primary)]' : 'bg-slate-50 border-slate-200 text-slate-700 hover:border-[var(--ui-primary)]'}`}>
                    <p className="font-bold text-sm">{t.nama}</p>
                    <p className="text-xs opacity-60">{JENIS_SURAT.find(j => j.key === t.jenis)?.label || t.jenis}</p>
                  </button>
                ))
              }
            </div>
            <div className="ui-card p-4 space-y-3">
              <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">2. Pilih Siswa</p>
              <input value={studentSearch} onChange={e => setStudentSearch(e.target.value)} placeholder="Cari siswa..."
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:border-[var(--ui-primary)]" />
              <div className="max-h-48 overflow-y-auto space-y-1">
                {filteredStudents.slice(0, 20).map(s => (
                  <button key={s.nis} onClick={() => setSelectedStudent(s)}
                    className={`w-full text-left p-2 rounded-[var(--ui-radius-small)] text-xs transition-all ${selectedStudent?.nis === s.nis ? 'bg-[var(--ui-primary)]/10 text-[var(--ui-primary)] font-bold' : 'text-slate-600 hover:bg-slate-50'}`}>
                    {s.namaSiswa || s.name} <span className="opacity-60">({s.class_name})</span>
                  </button>
                ))}
              </div>
            </div>
            <Button onClick={handlePrint} disabled={!selectedTemplate || !selectedStudent} className="w-full flex items-center justify-center gap-2">
              <Printer size={14} /> Cetak Surat
            </Button>
          </div>
          {/* Preview */}
          <div className="print-area">
            <PrintPreview template={selectedTemplate} student={selectedStudent} school={school} appSettings={useAppStore.getState().appSettings} />
          </div>
        </div>
      )}

      {activeTab === 'template' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {isLoading ? <p className="text-slate-400 py-8">Memuat...</p> : templates.length === 0 ? (
            <div className="col-span-3 text-center py-16 text-slate-400">
              <FileText size={48} className="mx-auto mb-4 opacity-30" />
              <p className="font-bold">Belum ada template surat.</p>
              <p className="text-sm mt-1">Klik "Buat Template" untuk memulai.</p>
            </div>
          ) : templates.map(t => {
            const jenis = JENIS_SURAT.find(j => j.key === t.jenis);
            return (
              <div key={t.id} className="ui-card p-5 hover:-translate-y-1 transition-all">
                <div className="flex items-start justify-between gap-3 mb-3">
                  <div>
                    <span className="text-[10px] font-bold bg-[var(--ui-primary)]/10 text-[var(--ui-primary)] px-2 py-0.5 rounded-[var(--ui-radius-small)] uppercase tracking-wider">{jenis?.label || t.jenis}</span>
                    <h3 className="font-bold text-slate-800 mt-2">{t.nama}</h3>
                  </div>
                  <div className="flex gap-1 shrink-0">
                    <button onClick={() => { setEditingTemplate(t); setForm({ jenis: t.jenis, nama: t.nama, isi_template: t.isi_template }); setShowModal(true); }}
                      className="p-1.5 text-slate-400 hover:text-[var(--ui-primary)] bg-slate-50 rounded-[var(--ui-radius-small)]"><Edit2 size={13} /></button>
                    <button onClick={() => handleDelete(t.id)} className="p-1.5 text-slate-400 hover:text-red-600 bg-slate-50 rounded-[var(--ui-radius-small)]"><Trash2 size={13} /></button>
                  </div>
                </div>
                <p className="text-xs text-slate-500 line-clamp-3 leading-relaxed">{t.isi_template}</p>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-[var(--ui-radius-small)] shadow-sm w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between sticky top-0 bg-white">
              <h3 className="font-bold text-slate-800">{editingTemplate ? 'Edit Template' : 'Buat Template Baru'}</h3>
              <button onClick={() => setShowModal(false)}><X size={20} className="text-slate-400" /></button>
            </div>
            <div className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Jenis Surat</label>
                  <select value={form.jenis} onChange={e => setForm(p => ({ ...p, jenis: e.target.value }))}
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]">
                    {JENIS_SURAT.map(j => <option key={j.key} value={j.key}>{j.label}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Nama Template</label>
                  <input type="text" value={form.nama} onChange={e => setForm(p => ({ ...p, nama: e.target.value }))} placeholder="Nama template..."
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]" />
                </div>
              </div>
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider">Isi Template</label>
                  <div className="flex flex-wrap gap-1">
                    {PLACEHOLDER_VARIABLES.map(v => (
                      <button key={v.var} onClick={() => setForm(p => ({ ...p, isi_template: p.isi_template + v.var }))}
                        title={v.desc} className="text-[10px] font-mono bg-slate-100 text-slate-600 hover:bg-[var(--ui-primary)] hover:text-white px-2 py-0.5 rounded-[var(--ui-radius-small)] transition-colors">
                        {v.var}
                      </button>
                    ))}
                  </div>
                </div>
                <textarea rows={12} value={form.isi_template} onChange={e => setForm(p => ({ ...p, isi_template: e.target.value }))}
                  placeholder="Tulis isi template surat. Gunakan tombol variabel di atas untuk menyisipkan data otomatis..."
                  className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-mono focus:outline-none focus:border-[var(--ui-primary)] resize-y" />
              </div>
              <div className="pt-4 flex justify-end gap-3">
                <Button type="button" variant="outline" onClick={() => setShowModal(false)}>Batal</Button>
                <Button onClick={handleSave}>Simpan Template</Button>
              </div>
            </div>
          </div>
        </div>
      )}

      <style>{`@media print { body * { visibility: hidden !important; } .print-area, .print-area * { visibility: visible !important; } .print-area { position: fixed; top: 0; left: 0; width: 100%; } }`}</style>

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-sm font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { CheckCircle2, BookOpen, MapPin, FileBarChart2, BadgeCheck, UserCog, Users, GraduationCap, Settings, LayoutDashboard, MessageSquare, KeyRound, DatabaseBackup } from 'lucide-react';
import useFiturStore, { FITUR_CONFIG } from '../../../store/monitoring/fiturStore';
import { Info, AlertTriangle, RotateCcw } from 'lucide-react';
import { PageHeader } from '../../../components/monitoring/ui/index.js';


/**
 * admin/FiturManagement.jsx
 * Halaman Admin: kontrol fitur mana yang aktif/nonaktif di seluruh sistem.
 * Perubahan langsung berdampak ke Panel Siswa dan Guru.
 */





const ICON_MAP = {
  CheckCircle2, BookOpen, MapPin, FileBarChart2, BadgeCheck, UserCog,
};

const ROLE_BADGE = {
  siswa:  { label: 'Siswa', bg: 'bg-sky-100', text: 'text-sky-700', icon: Users },
  guru:   { label: 'Guru', bg: 'bg-purple-100', text: 'text-purple-700', icon: GraduationCap },
  admin:  { label: 'Admin', bg: 'bg-[var(--ui-primary)]/10', text: 'text-[var(--ui-primary)]', icon: null },
};

const FiturManagement = ({ hideHeader = false, activeTab, setActiveTab }) => {
  const { fitur, toggleFitur, resetFitur } = useFiturStore();
  const [confirmReset, setConfirmReset] = useState(false);
  const [savedMsg, setSavedMsg] = useState(false);
  const [confirmKey, setConfirmKey] = useState(null); // fitur key yang perlu konfirmasi disable

  const activeCount = Object.values(fitur).filter(Boolean).length;

  const handleToggle = (key, critical) => {
    if (critical && fitur[key]) {
      setConfirmKey(key);
      return;
    }
    toggleFitur(key);
    setSavedMsg(true);
    setTimeout(() => setSavedMsg(false), 2500);
  };

  const handleConfirmDisable = () => {
    toggleFitur(confirmKey);
    setConfirmKey(null);
    setSavedMsg(true);
    setTimeout(() => setSavedMsg(false), 2500);
  };

  const handleReset = () => {
    resetFitur();
    setConfirmReset(false);
    setSavedMsg(true);
    setTimeout(() => setSavedMsg(false), 2500);
  };

  return (
    <div className="space-y-4">
      {!hideHeader ? (
        <PageHeader
          icon={Settings}
          title="Manajemen Fitur"
          description="Aktifkan atau nonaktifkan fitur untuk Panel Siswa dan Guru secara real-time."
          tabs={[
            { id: "fitur", label: "Fitur", icon: Settings },
            { id: "tampilan", label: "Tampilan Web", icon: LayoutDashboard },
            { id: "whatsapp", label: "WhatsApp", icon: MessageSquare },
            { id: "api_keys", label: "API Key", icon: KeyRound },
            { id: "gdrive_backup", label: "Backup", icon: DatabaseBackup }
          ]}
          activeTab={activeTab}
          onTabChange={setActiveTab}
        />
      ) : (
        <div className="flex items-center justify-between mb-4">
          <div>
            <h2 className="text-lg font-bold text-slate-800">Bidang Hubin (PKL)</h2>
            <p className="text-xs text-slate-400">Fitur untuk Guru, Siswa, dan Instruktur PKL</p>
          </div>
          <div className="flex items-center gap-3 flex-shrink-0">
            {savedMsg && (
              <span className="text-xs text-[var(--ui-primary)] font-semibold animate-fade-in-up flex items-center gap-1">
                <CheckCircle2 size={13} />
                Tersimpan
              </span>
            )}
            <span className={`text-[10px] font-bold px-2 py-1 rounded-[var(--ui-radius-small)] ${
              activeCount === FITUR_CONFIG.length
                ? 'bg-[var(--ui-primary)]/10 text-[var(--ui-primary)]'
                : 'bg-amber-100 text-amber-700'
            }`}>
              {activeCount}/{FITUR_CONFIG.length} aktif
            </span>
          </div>
        </div>
      )}

      {/* Info banner */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-sky-50 border border-sky-200 rounded-[var(--ui-radius-small)] p-4">
        <div className="flex items-start gap-3">
          <Info size={16} className="text-sky-600 mt-0.5 flex-shrink-0" />
          <p className="text-xs text-sky-800 leading-relaxed">
            Perubahan di halaman ini berlaku <strong>langsung</strong> tanpa perlu reload.
            Fitur yang dinonaktifkan tidak akan tampil di navigasi Panel Siswa maupun Panel Guru.
          </p>
        </div>
        <div className="flex items-center gap-3 flex-shrink-0 sm:self-center">
          {savedMsg && (
            <span className="text-xs text-emerald-600 font-extrabold animate-fade-in-up flex items-center gap-1">
              <CheckCircle2 size={14} />
              Tersimpan
            </span>
          )}
          <span className={`text-xs font-black px-3 py-1.5 rounded-[var(--ui-radius-small)] border shadow-xs ${
            activeCount === FITUR_CONFIG.length
              ? 'bg-emerald-500 text-white border-emerald-500'
              : 'bg-amber-500 text-white border-amber-500'
          }`}>
            {activeCount}/{FITUR_CONFIG.length} fitur aktif
          </span>
        </div>
      </div>

      {/* Feature Cards */}
      <div className="space-y-3">
        {FITUR_CONFIG.map((cfg) => {
          const Icon = ICON_MAP[cfg.icon] || CheckCircle2;
          const isActive = fitur[cfg.key] ?? true;

          return (
            <div
              key={cfg.key}
              className={`bg-white border rounded-[var(--ui-radius-small)] transition-all duration-200 ${
                isActive ? 'border-slate-200' : 'border-gray-200 opacity-75'
              }`}
            >
              <div className="flex items-start gap-4 p-5">
                {/* Icon */}
                <div className={`w-11 h-11 rounded-[var(--ui-radius-small)] flex items-center justify-center flex-shrink-0 transition-colors ${
                  isActive ? 'bg-[var(--ui-primary)]/10' : 'bg-gray-100'
                }`}>
                  <Icon size={20} className={isActive ? 'text-[var(--ui-primary)]' : 'text-gray-400'} />
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap mb-1">
                    <p className={`font-bold text-sm ${isActive ? 'text-slate-800' : 'text-gray-500'}`}>
                      {cfg.label}
                    </p>
                    {cfg.critical && (
                      <span className="text-[10px] bg-amber-100 text-amber-700 font-bold px-2 py-0.5 rounded-[var(--ui-radius-small)]">
                        KRITIS
                      </span>
                    )}
                  </div>
                  <p className="text-xs text-slate-400 mb-2.5">{cfg.description}</p>

                  {/* Affected roles */}
                  <div className="flex items-center gap-1.5 flex-wrap">
                    <span className="text-[10px] text-slate-400 font-medium">Berdampak ke:</span>
                    {cfg.affectedRoles.map((role) => {
                      const rb = ROLE_BADGE[role];
                      const RoleIcon = rb.icon;
                      return (
                        <span key={role}
                          className={`inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-[var(--ui-radius-small)] ${rb.bg} ${rb.text}`}>
                          {RoleIcon && <RoleIcon size={9} />}
                          {rb.label}
                        </span>
                      );
                    })}
                  </div>
                </div>

                {/* Toggle */}
                <button
                  type="button"
                  role="switch"
                  aria-checked={isActive}
                  onClick={() => handleToggle(cfg.key, cfg.critical)}
                  className={`relative flex-shrink-0 w-12 h-6 rounded-full transition-colors duration-300 mt-1
                    focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)] focus:ring-offset-2
                    ${isActive ? 'bg-[var(--ui-primary)]' : 'bg-gray-200'}`}
                >
                  <div className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow-sm
                    transition-transform duration-300 ${isActive ? 'translate-x-7' : 'translate-x-1'}`}
                  />
                </button>
              </div>

              {/* Warning saat dimatikan */}
              {!isActive && (
                <div className="mx-5 mb-4 flex items-center gap-2 text-xs text-amber-700
                  bg-amber-50 border border-amber-200 rounded-[var(--ui-radius-small)] px-3 py-2">
                  <AlertTriangle size={13} className="flex-shrink-0" />
                  Fitur ini tidak tampil di panel {cfg.affectedRoles.join(' dan ')}.
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Reset */}
      <div className="flex items-center justify-between pt-4 border-t border-slate-200">
        <p className="text-xs text-slate-400">Atur ulang semua fitur ke kondisi awal (semua aktif)</p>
        {confirmReset ? (
          <div className="flex items-center gap-2">
            <span className="text-xs text-amber-700 font-medium">Yakin reset semua?</span>
            <button onClick={handleReset}
              className="text-xs font-bold text-white bg-danger px-3 py-1.5 rounded-[var(--ui-radius-small)] hover:bg-red-600 transition-colors">
              Ya, Reset
            </button>
            <button onClick={() => setConfirmReset(false)}
              className="text-xs font-semibold text-gray-600 px-3 py-1.5 rounded-[var(--ui-radius-small)] border-none hover:bg-bg transition-colors">
              Batal
            </button>
          </div>
        ) : (
          <button onClick={() => setConfirmReset(true)}
            className="flex items-center gap-2 text-sm font-medium text-gray-500
              hover:text-danger transition-colors">
            <RotateCcw size={14} />
            Reset ke Default
          </button>
        )}
      </div>

      {/* Confirm disable critical feature modal */}
      {confirmKey && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setConfirmKey(null)} />
          <div className="relative bg-white rounded-[var(--ui-radius-card)] p-6 max-w-sm w-full shadow-xl z-10">
            <div className="w-12 h-12 bg-amber-100 rounded-[var(--ui-radius-small)] flex items-center justify-center mb-4">
              <AlertTriangle size={24} className="text-amber-600" />
            </div>
            <h3 className="font-bold text-slate-800 mb-2">Nonaktifkan Fitur Kritis?</h3>
            <p className="text-sm text-slate-400 mb-5">
              Mematikan fitur <strong>{FITUR_CONFIG.find(f => f.key === confirmKey)?.label}</strong> akan
              berdampak signifikan. Siswa tidak akan bisa menggunakannya hingga diaktifkan kembali.
            </p>
            <div className="flex gap-3">
              <button onClick={() => setConfirmKey(null)}
                className="flex-1 py-2.5 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold text-gray-600 hover:bg-bg transition-colors">
                Batal
              </button>
              <button onClick={handleConfirmDisable}
                className="flex-1 py-2.5 bg-danger text-white rounded-[var(--ui-radius-small)] text-sm font-bold hover:bg-red-600 transition-colors">
                Nonaktifkan
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FiturManagement;

import { useState, useEffect, useMemo } from 'react';
import { MessageSquare, CheckCircle2, AlertCircle, Clock, Settings, LayoutDashboard, KeyRound, DatabaseBackup } from 'lucide-react';
import useAuthStore from '../../../store/monitoring/authStore.js';
import { INITIAL_CLASSES } from '../../../data.js';
import { Send, Calendar, History, UserCog, Phone, Users, FileText, RefreshCw } from 'lucide-react';
import { PageHeader, Button } from '../../../components/monitoring/ui/index.js';


const TRIGGER_TEMPLATES = [
  { key: 'terlambat', label: '⏰ Notifikasi Keterlambatan', template: 'Yth. Orang Tua/Wali {NAMA_SISWA}, kami ingin memberitahukan bahwa putra/putri Anda ({NAMA_SISWA}) hadir terlambat ke sekolah pada {TANGGAL} pukul {WAKTU}. Mohon perhatian dan dukungannya. Terima kasih. - {NAMA_SEKOLAH}' },
  { key: 'pelanggaran', label: '⚠️ Notifikasi Pelanggaran', template: 'Yth. Orang Tua/Wali {NAMA_SISWA}, putra/putri Anda ({NAMA_SISWA}) telah mendapatkan {POIN} poin pelanggaran karena {KETERANGAN} pada {TANGGAL}. Total poin saat ini: {TOTAL_POIN}. Mohon dukungan dan bimbingannya. - {NAMA_SEKOLAH}' },
  { key: 'sp1', label: '📋 Surat Panggilan 1 (SP1)', template: 'Yth. Orang Tua/Wali {NAMA_SISWA}, dengan ini kami sampaikan bahwa putra/putri Anda ({NAMA_SISWA}) telah mendapatkan peringatan pertama (SP1) dari sekolah karena akumulasi pelanggaran. Kami memohon kehadiran Anda di sekolah pada hari _{HARI}_ untuk melakukan konsultasi. - {NAMA_SEKOLAH}' },
  { key: 'absen', label: '📅 Rekap Absensi', template: 'Yth. Orang Tua/Wali {NAMA_SISWA}, rekap kehadiran putra/putri Anda bulan {BULAN}: Hadir {HADIR} hari, Sakit {SAKIT} hari, Izin {IZIN} hari, Alpa {ALPA} hari. - {NAMA_SEKOLAH}' },
  { key: 'pengumuman', label: '📢 Pengumuman Sekolah', template: 'Pengumuman dari {NAMA_SEKOLAH}: {ISI_PENGUMUMAN}' },
];

export default function IntegrasiWhatsApp({ activeTab: activeSystemTab, setActiveTab: setSystemTab }) {
  const [logs, setLogs] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSending, setIsSending] = useState(false);
  const [toast, setToast] = useState(null);
  const [activeTab, setActiveTab] = useState('kirim');
  const [filterStatus, setFilterStatus] = useState('all');
  const [students, setStudents] = useState([]);

  // Broadcast form
  const [broadcastForm, setBroadcastForm] = useState({ phone: '', recipient_name: '', message: '' });
  const [selectedTemplate, setSelectedTemplate] = useState('');
  const [broadcastMode, setBroadcastMode] = useState('single'); // single | bulk
  const [selectedStudents, setSelectedStudents] = useState([]);
  const [bulkMessage, setBulkMessage] = useState('');

  // Walikelas Data
  const [walikelasData, setWalikelasData] = useState({});
  const [isSavingWalikelas, setIsSavingWalikelas] = useState(false);
  const [classesList, setClassesList] = useState([]);
  const [teachersList, setTeachersList] = useState([]);

  // Rekap
  const [isSendingRekap, setIsSendingRekap] = useState(false);

  const authToken = useAuthStore(state => state.user?.authToken);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const fetchLogs = async () => {
    if (!authToken) return;
    setIsLoading(true);
    try {
      const [logsRes, studRes] = await Promise.all([
        fetch('/api/whatsapp/logs', { headers: { Authorization: `Bearer ${authToken}` } }),
        fetch('/api/data/load', { headers: { Authorization: `Bearer ${authToken}` } }),
      ]);
      const logsData = await logsRes.json();
      if (logsData.ok) setLogs(logsData.data || []);
      const appDataRes = studRes.ok ? await studRes.json() : { payload: {} };
      if (appDataRes.payload) {
        if (appDataRes.payload.students) {
          const mappedStudents = appDataRes.payload.students.map(s => ({
            ...s,
            name: s.namaSiswa || s.name,
            wa_ortu: s.phone || s.wa_ortu
          }));
          setStudents(mappedStudents);
        }
        if (appDataRes.payload.classes) {
          setClassesList(appDataRes.payload.classes);
        }
        if (appDataRes.payload.teachers) {
          setTeachersList(appDataRes.payload.teachers);
        }
      }
    } catch (e) { console.error(e); }
    setIsLoading(false);
  };

  useEffect(() => { fetchLogs(); }, [authToken]);

  const applyTemplate = (key) => {
    const tmpl = TRIGGER_TEMPLATES.find(t => t.key === key);
    if (tmpl) {
      setSelectedTemplate(key);
      setBroadcastForm(prev => ({ ...prev, message: tmpl.template }));
      setBulkMessage(tmpl.template);
    }
  };

  const handleSend = async () => {
    if (!broadcastForm.phone || !broadcastForm.message) return showToast('Nomor HP dan pesan wajib diisi!', 'error');
    setIsSending(true);
    try {
      const res = await fetch('/api/whatsapp/send', {
        method: 'POST',
        headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...broadcastForm, trigger_type: 'manual' }),
      });
      const data = await res.json();
      if (data.ok) { showToast('Pesan berhasil dikirim!'); setBroadcastForm({ phone: '', recipient_name: '', message: '' }); fetchLogs(); }
      else showToast(data.error || 'Gagal mengirim. Cek konfigurasi API Key WhatsApp.', 'error');
    } catch (e) { showToast('Gagal.', 'error'); }
    setIsSending(false);
  };

  const handleBulkSend = async () => {
    if (selectedStudents.length === 0 || !bulkMessage) return showToast('Pilih penerima dan tulis pesan!', 'error');
    setIsSending(true);
    let sent = 0, failed = 0;
    for (const nis of selectedStudents) {
      const student = students.find(s => s.nis === nis);
      if (!student?.wa_ortu) { failed++; continue; }
      try {
        const msg = bulkMessage.replace(/{NAMA_SISWA}/g, student.name || 'Siswa').replace(/{TANGGAL}/g, new Date().toLocaleDateString('id-ID'));
        const res = await fetch('/api/whatsapp/send', {
          method: 'POST',
          headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({ phone: student.wa_ortu, recipient_name: student.name, message: msg, trigger_type: 'bulk' }),
        });
        const data = await res.json();
        if (data.ok) sent++; else failed++;
      } catch { failed++; }
    }
    showToast(`Broadcast selesai: ${sent} terkirim, ${failed} gagal.`, sent > 0 ? 'success' : 'error');
    setIsSending(false);
    fetchLogs();
  };

  const handleSendRekap = async (type) => {
    setIsSendingRekap(true);
    try {
      const res = await fetch("/api/whatsapp/send-rekap", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${authToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          target: "siswa",
          type: type,
          date: new Date().toISOString().split("T")[0]
        })
      });
      const data = await res.json();
      if (res.ok && data.ok) {
        showToast(type === "daily" ? "Rekap Harian berhasil dikirim ke seluruh Walikelas!" : "Rekap Bulanan & Poin Pelanggaran berhasil dikirim ke Orang Tua!");
        fetchLogs();
      } else {
        showToast(data.error || "Gagal mengirim rekap ke WhatsApp.", "error");
      }
    } catch (err) {
      console.error(err);
      showToast("Kesalahan jaringan saat mengirim rekap.", "error");
    }
    setIsSendingRekap(false);
  };

  const filteredLogs = useMemo(() => filterStatus === 'all' ? logs : logs.filter(l => l.status === filterStatus), [logs, filterStatus]);

  const stats = useMemo(() => ({
    total: logs.length,
    sent: logs.filter(l => l.status === 'sent').length,
    pending: logs.filter(l => l.status === 'pending').length,
    failed: logs.filter(l => l.status === 'failed').length,
  }), [logs]);

  return (
    <div className="space-y-6 relative animate-in fade-in duration-300 z-10">
      <PageHeader 
        title="Integrasi WhatsApp Notification"
        description="Kirim notifikasi otomatis/manual ke orang tua siswa via WhatsApp menggunakan API Fonnte."
        icon={MessageSquare}
        tabs={[
          { id: "fitur", label: "Fitur", icon: Settings },
          { id: "tampilan", label: "Tampilan Web", icon: LayoutDashboard },
          { id: "whatsapp", label: "WhatsApp", icon: MessageSquare },
          { id: "api_keys", label: "API Key", icon: KeyRound },
          { id: "gdrive_backup", label: "Backup", icon: DatabaseBackup }
        ]}
        activeTab={activeSystemTab}
        onTabChange={setSystemTab}
      />

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total Pesan', value: stats.total, icon: MessageSquare, color: 'blue' },
          { label: 'Sukses', value: stats.sent, icon: CheckCircle2, color: 'emerald' },
          { label: 'Pending', value: stats.pending, icon: Clock, color: 'amber' },
          { label: 'Gagal', value: stats.failed, icon: AlertCircle, color: 'red' },
        ].map(stat => (
          <div key={stat.label} className="bg-white p-5 rounded-xl border-none shadow-sm flex items-center gap-4">
            <div className={`w-12 h-12 rounded-[var(--ui-radius-small)] flex items-center justify-center bg-${stat.color}-50`}>
              <stat.icon size={22} className={`text-${stat.color}-500`} />
            </div>
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">{stat.label}</p>
              <p className="text-3xl font-black text-slate-800">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div className="flex gap-1 bg-slate-100 p-1 rounded-[var(--ui-radius-small)] w-fit">
        {[
          { key: 'kirim', label: 'Kirim Pesan', icon: <Send size={16} /> },
          { key: 'rekap', label: 'Rekap Otomatis', icon: <Calendar size={16} /> },
          { key: 'log', label: 'Riwayat & Log', icon: <History size={16} /> },
          { key: 'walikelas', label: 'Data Walikelas', icon: <UserCog size={16} /> }
        ].map(tab => (
          <button key={tab.key} onClick={() => setActiveTab(tab.key)}
            className={`px-5 py-2 rounded-[var(--ui-radius-small)] text-sm font-bold transition-all flex items-center gap-2 ${activeTab === tab.key ? 'bg-white  text-[var(--ui-primary)]' : 'text-slate-500 hover:text-slate-700'}`}>
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {/* Send Tab */}
      {activeTab === 'kirim' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Single Send */}
          <div className="bg-white rounded-xl border-none shadow-sm p-6 space-y-4">
            <h2 className="font-bold text-slate-700 flex items-center gap-2"><Phone size={16} /> Kirim Pesan Tunggal</h2>

            {/* Template Picker */}
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Template Pesan</label>
              <div className="flex flex-wrap gap-2">
                {TRIGGER_TEMPLATES.map(t => (
                  <button key={t.key} onClick={() => applyTemplate(t.key)}
                    className={`px-3 py-1.5 rounded-[var(--ui-radius-small)] text-xs font-bold border transition-all ${selectedTemplate === t.key ? 'bg-[var(--ui-primary)] text-white border-[var(--ui-primary)]' : 'bg-slate-50 text-slate-600 border-slate-200 hover:border-[var(--ui-primary)]'}`}>
                    {t.label}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Nomor HP Penerima</label>
              <input type="text" value={broadcastForm.phone} onChange={e => setBroadcastForm(p => ({ ...p, phone: e.target.value }))}
                placeholder="08xxxxxxxxxx atau 62xxxxxxxxxx"
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]" />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Nama Penerima (Opsional)</label>
              <input type="text" value={broadcastForm.recipient_name} onChange={e => setBroadcastForm(p => ({ ...p, recipient_name: e.target.value }))}
                placeholder="Nama untuk log..."
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]" />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Isi Pesan</label>
              <textarea rows={5} value={broadcastForm.message} onChange={e => setBroadcastForm(p => ({ ...p, message: e.target.value }))}
                placeholder="Ketik pesan atau pilih template di atas..."
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:border-[var(--ui-primary)] resize-none" />
              <p className="text-xs text-slate-400 mt-1">{broadcastForm.message.length} karakter</p>
            </div>
            <Button onClick={handleSend} disabled={isSending} className="w-full flex items-center justify-center gap-2">
              <Send size={14} /> {isSending ? 'Mengirim...' : 'Kirim Sekarang'}
            </Button>
          </div>

          {/* Broadcast */}
          <div className="bg-white rounded-xl border-none shadow-sm p-6 space-y-4">
            <h2 className="font-bold text-slate-700 flex items-center gap-2"><Users size={16} /> Broadcast ke Banyak Siswa</h2>
            <div className="p-4 bg-amber-50 border border-amber-200 rounded-[var(--ui-radius-small)]">
              <p className="text-xs font-bold text-amber-700 mb-1">⚠️ Perhatian</p>
              <p className="text-xs text-amber-600">Broadcast mengirim pesan ke semua orang tua yang memiliki nomor WA terdaftar di Data Siswa. Pastikan nomor WA sudah diisi di profil siswa.</p>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Template Pesan Broadcast</label>
              <select value={selectedTemplate} onChange={e => applyTemplate(e.target.value)}
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]">
                <option value="">-- Pilih Template --</option>
                {TRIGGER_TEMPLATES.map(t => <option key={t.key} value={t.key}>{t.label}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Isi Pesan (Variabel: {'{NAMA_SISWA}'}, {'{TANGGAL}'})</label>
              <textarea rows={4} value={bulkMessage} onChange={e => setBulkMessage(e.target.value)}
                placeholder="Gunakan {NAMA_SISWA} untuk nama otomatis..."
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:border-[var(--ui-primary)] resize-none" />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Pilih Penerima ({selectedStudents.length} terpilih)</label>
              <div className="max-h-48 overflow-y-auto border-none rounded-[var(--ui-radius-small)] bg-slate-50 p-2 space-y-1">
                {students.length === 0 ? (
                  <p className="text-xs text-slate-400 p-2 text-center">Data siswa tidak ditemukan. Import terlebih dahulu.</p>
                ) : students.slice(0, 50).map(s => (
                  <label key={s.nis} className="flex items-center gap-2 p-1.5 rounded-[var(--ui-radius-small)] cursor-pointer hover:bg-white">
                    <input type="checkbox" checked={selectedStudents.includes(s.nis)} onChange={e => {
                      if (e.target.checked) setSelectedStudents(prev => [...prev, s.nis]);
                      else setSelectedStudents(prev => prev.filter(id => id !== s.nis));
                    }} className="accent-[var(--ui-primary)]" />
                    <span className="text-xs font-semibold text-slate-700 flex items-center gap-1.5">
                      <span>{s.name}</span>
                      <span className="text-slate-400">({s.nis})</span>
                      <span className="inline-flex items-center gap-0.5">
                        {s.wa_ortu ? (
                          <span className="inline-flex items-center gap-0.5 text-emerald-600 font-bold bg-emerald-50 px-1 py-0.2 rounded">
                            <CheckCircle2 size={10} className="shrink-0" />
                            <span>WA</span>
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-0.5 text-amber-600 font-bold bg-amber-50 px-1 py-0.2 rounded">
                            <AlertCircle size={10} className="shrink-0" />
                            <span>no WA</span>
                          </span>
                        )}
                      </span>
                    </span>
                  </label>
                ))}
              </div>
              <div className="flex gap-2 mt-2">
                <button onClick={() => setSelectedStudents(students.filter(s => s.wa_ortu).map(s => s.nis))} className="text-xs font-bold text-[var(--ui-primary)] hover:underline">Pilih Semua (punya WA)</button>
                <span className="text-slate-300">|</span>
                <button onClick={() => setSelectedStudents([])} className="text-xs font-bold text-slate-400 hover:underline">Batalkan</button>
              </div>
            </div>
            <Button onClick={handleBulkSend} disabled={isSending || selectedStudents.length === 0} className="w-full flex items-center justify-center gap-2">
