        title="Administrasi Modul Ajar"
        description="Ruang unggah Modul Ajar bagi Guru dan monitoring pengumpulan berkas bagi Kurikulum."
        icon={BookOpen}
        tabs={tabs}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      />

      {/* 0. TAB SILABUS / MODUL AJAR (Curriculum List & Templates) */}
      {activeTab === 'silabus' && isCurriculum && (
        <Suspense fallback={<div className="p-12 text-center text-slate-500 font-bold animate-pulse">Memuat Modul Ajar...</div>}>
          <TabSilabus {...props} hideHeader={true} />
        </Suspense>
      )}

      {/* 0. TAB SILABUS GURU / MODUL AJAR GURU (Teacher Personal View) */}
      {activeTab === 'silabusguru' && userRole === 'guru' && (
        <Suspense fallback={<div className="p-12 text-center text-slate-500 font-bold animate-pulse">Memuat Modul Ajar Saya...</div>}>
          <TabSilabusGuru 
            {...props} 
            availableSubjects={availableSubjects}
            availableClasses={availableClasses}
            myDocuments={myDocuments}
            fetchData={fetchData}
            activeYear={activeYear}
            authToken={authToken}
            handleDelete={handleDelete}
          />
        </Suspense>
      )}

      {/* 1. MONITORING TAB (Curriculum Admin View) */}
      {activeTab === 'rekap' && isCurriculum && (
        <div className="space-y-6 animate-in fade-in duration-200">
