            <div className="ui-card p-5 flex items-center gap-4 bg-white">
              <div className="w-12 h-12 rounded-[var(--ui-radius-small)] bg-blue-50 flex items-center justify-center text-blue-500 shrink-0">
                <Users size={22} />
              </div>
              <div>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Guru</p>
                <p className="text-3xl font-black text-slate-800">{stats.total}</p>
              </div>
            </div>
            <div className="ui-card p-5 flex items-center gap-4 bg-white">
              <div className="w-12 h-12 rounded-[var(--ui-radius-small)] bg-emerald-50 flex items-center justify-center text-emerald-500 shrink-0">
                <CheckCircle2 size={22} />
              </div>
              <div>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Sudah Kumpul</p>
                <p className="text-3xl font-black text-emerald-700">{stats.submitted}</p>
              </div>
            </div>
            <div className="ui-card p-5 flex items-center gap-4 bg-white">
              <div className="w-12 h-12 rounded-[var(--ui-radius-small)] bg-rose-50 flex items-center justify-center text-rose-500 shrink-0">
                <AlertCircle size={22} />
              </div>
              <div>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Belum Kumpul</p>
                <p className="text-3xl font-black text-rose-700">{stats.pending}</p>
              </div>
            </div>
            <div className="ui-card p-5 flex items-center gap-4 bg-white">
              <div className="w-12 h-12 rounded-[var(--ui-radius-small)] bg-indigo-50 flex items-center justify-center text-indigo-500 shrink-0">
                <RefreshCw size={22} />
              </div>
              <div>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Persentase</p>
                <p className="text-3xl font-black text-indigo-700">{stats.percentage}%</p>
              </div>
            </div>
          </div>

          {/* Monitoring Table */}
          <div className="ui-card p-6 space-y-4">
