            </div>
          </div>

          <div className="overflow-x-auto border border-slate-150 rounded-[var(--ui-radius-small)]">
            <table className="w-full text-sm">
              <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 font-bold text-left">Mata Pelajaran</th>
                  <th className="px-6 py-4 font-bold text-left">Kelas & Sem.</th>
                  <th className="px-6 py-4 font-bold text-left">Guru Pengunggah</th>
                  <th className="px-6 py-4 font-bold text-left w-48">Tahun Ajaran</th>
                  <th className="px-6 py-4 font-bold text-left">Berkas</th>
                  <th className="px-6 py-4 font-bold text-right w-36">Aksi</th>
                </tr>
              </thead>
              <tbody>
                {filteredDocuments.length === 0 ? (
                  <tr><td colSpan={6} className="px-6 py-8 text-center text-slate-400">Tidak ada Modul Ajar yang diunggah.</td></tr>
                ) : (
                  filteredDocuments.map(doc => {
                    const isMyOwn = doc.teacher_code === teacherCode;
                    const canDelete = isCurriculum || isMyOwn;
                    return (
                      <tr key={doc.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 font-bold text-slate-800">
                          {doc.mapel || "Umum"}
                        </td>
                        <td className="px-6 py-4 text-slate-600 font-semibold">
                          {doc.kelas || "-"} ({doc.semester || "-"})
                        </td>
                        <td className="px-6 py-4 text-slate-600 font-semibold">{doc.teacher_name}</td>
                        <td className="px-6 py-4 text-slate-600 font-semibold">{doc.tahun_ajaran}</td>
                        <td className="px-6 py-4 text-slate-500 text-xs">
                          <div className="flex items-center gap-2">
                            <FileText size={16} className="text-red-500 shrink-0" />
                            <span className="truncate max-w-[150px]" title={doc.nama_dokumen}>{doc.nama_dokumen}</span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-right flex items-center justify-end gap-2">
                          <button
                            onClick={() => handlePreviewPdf(doc)}
                            className="p-1.5 text-slate-700 hover:bg-slate-100 border border-slate-200 rounded-[var(--ui-radius-small)] transition-colors flex items-center gap-1 text-xs font-bold font-sans cursor-pointer bg-white"
                            title="Pratinjau berkas"
                          >
                            <Eye size={14} /> Pratinjau
                          </button>
                          <a href={doc.file_url} download={doc.nama_dokumen}
                            className="p-1.5 text-blue-600 hover:bg-blue-50 border border-blue-200 rounded-[var(--ui-radius-small)] transition-colors flex items-center gap-1 text-xs font-bold font-sans no-underline"
                            title="Unduh berkas">
                            <Download size={14} /> Unduh
                          </a>
                          {canDelete && (
                            <button onClick={() => handleDelete(doc.id, doc.teacher_code)}
                              className="p-1.5 text-slate-400 hover:text-red-600 rounded hover:bg-red-50 transition-colors border-none bg-transparent cursor-pointer"
                              title="Hapus Modul">
                              <Trash2 size={14} />
                            </button>
                          )}
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 3. UNGGAH TAB (Teacher Form & Private View) */}
      {activeTab === 'unggah' && userRole === 'guru' && (
        <div className="grid grid-cols-1 lg:grid-cols-[380px,1fr] gap-6 animate-in fade-in duration-200">
          {/* Left Column: Form */}
          <div className="ui-card p-5 space-y-4 h-fit">
            <h3 className="font-bold text-slate-800 text-sm border-b border-slate-100 pb-3 flex items-center gap-2">
              <Upload size={16} className="text-[var(--ui-primary)]" /> Unggah Modul Ajar Baru
            </h3>
            <form onSubmit={handleUploadSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 mb-2">Mata Pelajaran (Mapel)</label>
                <select value={form.mapel} required onChange={e => setForm({ ...form, mapel: e.target.value })}
                  className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold bg-white focus:outline-none focus:border-[var(--ui-primary)]">
                  <option value="">-- Pilih Mata Pelajaran --</option>
                  {availableSubjects.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-500 mb-2">Kelas</label>
                <select value={form.kelas} required onChange={e => setForm({ ...form, kelas: e.target.value })}
                  className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold bg-white focus:outline-none focus:border-[var(--ui-primary)]">
                  <option value="">-- Pilih Kelas --</option>
                  {availableClasses.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-500 mb-2">Semester</label>
                <select value={form.semester} required onChange={e => setForm({ ...form, semester: e.target.value })}
                  className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold bg-white focus:outline-none focus:border-[var(--ui-primary)]">
                  <option value="Ganjil">Semester Ganjil</option>
                  <option value="Genap">Semester Genap</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-500 mb-2">Pilih File Berkas (PDF)</label>
                <input id="file-input" type="file" required accept=".pdf" onChange={handleFileChange}
