                    URL.revokeObjectURL(previewDoc.url);
                  }
                  setPreviewDoc(null);
                }}
                className="w-8 h-8 rounded-full hover:bg-slate-200 flex items-center justify-center text-slate-500 hover:text-slate-800 transition-colors border-none bg-transparent cursor-pointer"
              >
                <X size={18} />
              </button>
            </div>
            <div className="flex-1 bg-slate-800 p-2 relative flex items-center justify-center">
              <iframe
                src={previewDoc.url}
                title="Pratinjau Modul Ajar"
                className="w-full h-full border-none rounded-lg bg-white"
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { School, BookOpen, MessageSquare, MonitorSmartphone, Wifi, Palette, MapPin, Users, Sparkles } from 'lucide-react';
import { compressImage } from '../../../utils/imageUtils.js';
import { Star, Upload, Globe, Save, Plus, Edit2, Trash2, Printer, ImageIcon, X, AlertCircle, CheckCircle2 } from 'lucide-react';
import { PageHeader, Button } from '../../../components/monitoring/ui/index.js';


const SCHOOL_FIELDS = [
  { key: 'nama_sekolah', label: 'Nama Sekolah', placeholder: 'SMK Negeri 1 ...' },
  { key: 'npsn', label: 'NPSN', placeholder: '20XXXXXXXX' },
  { key: 'nss', label: 'NSS', placeholder: 'Nomor Statistik Sekolah' },
  { key: 'alamat', label: 'Alamat Lengkap', placeholder: 'Jl. ...', multiline: true },
  { key: 'kota', label: 'Kota / Kabupaten', placeholder: 'Kota ...' },
  { key: 'provinsi', label: 'Provinsi', placeholder: 'Jawa Barat' },
  { key: 'kode_pos', label: 'Kode Pos', placeholder: '12345' },
  { key: 'telepon', label: 'Telepon / Fax', placeholder: '(021) XXXXXXXX' },
  { key: 'email', label: 'Email Sekolah', placeholder: 'info@smkn1.sch.id' },
  { key: 'website', label: 'Website', placeholder: 'https://smkn1.sch.id' },
  { key: 'kepala_sekolah', label: 'Nama Kepala Sekolah', placeholder: 'Drs. ..., M.Pd.' },
  { key: 'nip_kepsek', label: 'NIP Kepala Sekolah', placeholder: '19XXXXXXXXXXXXXXXX' },
  { key: 'akreditasi', label: 'Akreditasi', placeholder: 'A' },
  { key: 'tahun_berdiri', label: 'Tahun Berdiri', placeholder: '1985' },
  { key: 'max_poin_pelanggaran', label: 'Batas Maksimal Poin Pelanggaran (DO)', placeholder: '100' },
];

const MAJOR_ICON_OPTIONS = [
  { value: "book", label: "Buku / Mapel", icon: BookOpen },
  { value: "chat", label: "Komunikasi", icon: MessageSquare },
  { value: "monitor", label: "Komputer", icon: MonitorSmartphone },
  { value: "wifi", label: "Jaringan", icon: Wifi },
  { value: "palette", label: "Desain", icon: Palette },
  { value: "map", label: "Denah", icon: MapPin },
  { value: "users", label: "Siswa", icon: Users },
  { value: "sparkles", label: "Unggulan", icon: Sparkles },
];

export default function ProfilSekolah({ appSettings = {}, setAppSettings = () => {}, onSave = () => {} }) {
  const [profile, setProfile] = useState(appSettings?.schoolProfile || {});
  const [academicYears, setAcademicYears] = useState(appSettings?.academicYears || []);
  const [isSaving, setIsSaving] = useState(false);
  const [toast, setToast] = useState(null);
  const [activeTab, setActiveTab] = useState('profil');
  const [logoPreview, setLogoPreview] = useState(appSettings?.schoolProfile?.logo_url || appSettings?.logoUrl || '');
  const [logoMobilePreview, setLogoMobilePreview] = useState(appSettings?.logoMobileUrl || '');
  const [logoWebPreview, setLogoWebPreview] = useState(appSettings?.logoWebUrl || '');
  const [showYearModal, setShowYearModal] = useState(false);
  const [editingYear, setEditingYear] = useState(null);
  const [yearForm, setYearForm] = useState({ nama: '', semester: 'Ganjil', tanggal_mulai: '', tanggal_selesai: '' });

  const logoInputRef = useRef();
  const logoMobileInputRef = useRef();
  const logoWebInputRef = useRef();

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  useEffect(() => {
    setProfile(appSettings?.schoolProfile || {});
    setLogoPreview(appSettings?.schoolProfile?.logo_url || appSettings?.logoUrl || '');
    setLogoMobilePreview(appSettings?.logoMobileUrl || '');
    setLogoWebPreview(appSettings?.logoWebUrl || '');
    setAcademicYears(appSettings?.academicYears || []);
  }, [appSettings?.schoolProfile, appSettings?.academicYears, appSettings?.logoUrl, appSettings?.logoMobileUrl, appSettings?.logoWebUrl]);

  const handleSaveProfile = async () => {
    setIsSaving(true);
    try {
      const updatedSettings = { 
        ...appSettings, 
        schoolProfile: profile, 
        logoUrl: logoPreview,
        logoMobileUrl: logoMobilePreview,
        logoWebUrl: logoWebPreview
      };
      setAppSettings(updatedSettings);
      await onSave({ appSettings: updatedSettings });
      showToast('Profil sekolah berhasil disimpan!');
    } catch { showToast('Gagal menyimpan profil.', 'error'); }
    setIsSaving(false);
  };

  const handleLogoChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    compressImage(file, { maxWidth: 500, maxHeight: 500, quality: 0.8 }).then(dataUrl => {
      setLogoPreview(dataUrl);
      setProfile(prev => ({ ...prev, logo_url: dataUrl }));
      const updatedSettings = { ...appSettings, logoUrl: dataUrl };
      setAppSettings(updatedSettings);
      onSave({ appSettings: updatedSettings });
    });
  };

  const handleLogoMobileChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    compressImage(file, { maxWidth: 500, maxHeight: 500, quality: 0.8 }).then(dataUrl => {
      setLogoMobilePreview(dataUrl);
      const updatedSettings = { ...appSettings, logoMobileUrl: dataUrl };
      setAppSettings(updatedSettings);
      onSave({ appSettings: updatedSettings });
    });
  };

  const handleLogoWebChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    compressImage(file, { maxWidth: 500, maxHeight: 500, quality: 0.8 }).then(dataUrl => {
      setLogoWebPreview(dataUrl);
      const updatedSettings = { ...appSettings, logoWebUrl: dataUrl };
      setAppSettings(updatedSettings);
      onSave({ appSettings: updatedSettings });
    });
  };

  const handleSaveYear = async () => {
    if (!yearForm.nama.trim()) return showToast('Nama tahun ajaran wajib diisi.', 'error');
    try {
      let currentYears = [...(appSettings.academicYears || [])];

      if (editingYear) {
        currentYears = currentYears.map(y => y.id === editingYear.id ? { ...y, ...yearForm } : y);
      } else {
        const newYear = { ...yearForm, id: Date.now(), is_active: currentYears.length === 0 };
        currentYears.push(newYear);
      }

      const updatedSettings = { ...appSettings, academicYears: currentYears };
      setAppSettings(updatedSettings);
      await onSave({ appSettings: updatedSettings });

      showToast(editingYear ? 'Tahun Ajaran diperbarui!' : 'Tahun Ajaran ditambahkan!');
      setShowYearModal(false);
    } catch { showToast('Gagal menyimpan tahun ajaran.', 'error'); }
  };

  const handleSetActive = async (id) => {
    try {
      let currentYears = [...(appSettings.academicYears || [])];
      currentYears = currentYears.map(y => ({ ...y, is_active: y.id === id }));

      const updatedSettings = { ...appSettings, academicYears: currentYears };
      setAppSettings(updatedSettings);
      await onSave({ appSettings: updatedSettings });

      showToast('Tahun Ajaran aktif diperbarui!');
    } catch { showToast('Gagal mengatur status aktif.', 'error'); }
  };

  const handleDeleteYear = async (id) => {
    if (!await window.confirmAsync('Hapus tahun ajaran ini?')) return;
    try {
      let currentYears = [...(appSettings.academicYears || [])];
      currentYears = currentYears.filter(y => y.id !== id);

      const updatedSettings = { ...appSettings, academicYears: currentYears };
      setAppSettings(updatedSettings);
      await onSave({ appSettings: updatedSettings });

      showToast('Tahun Ajaran dihapus!');
    } catch { showToast('Gagal menghapus.', 'error'); }
  };

  const openAddYear = () => {
    setEditingYear(null);
    setYearForm({ nama: '', semester: 'Ganjil', tanggal_mulai: '', tanggal_selesai: '' });
    setShowYearModal(true);
  };

  const openEditYear = (year) => {
    setEditingYear(year);
    setYearForm({
      nama: year.nama,
      semester: year.semester,
      tanggal_mulai: year.tanggal_mulai ? year.tanggal_mulai.split('T')[0] : '',
      tanggal_selesai: year.tanggal_selesai ? year.tanggal_selesai.split('T')[0] : '',
    });
    setShowYearModal(true);
  };

  const activeYear = academicYears.find(y => y.is_active);

  const tabs = [
    { id: 'profil', label: 'Profil Sekolah' }, 
    { id: 'tahun', label: 'Tahun Ajaran' },
    { id: 'kop', label: 'Kop Surat' }
  ];

  return (
    <div className="space-y-4 relative animate-in fade-in duration-300">
      {/* Header */}
      <PageHeader
        title="Profil Sekolah & Tahun Ajaran"
        icon={School}
        description="Kelola identitas sekolah, logo, dan manajemen tahun ajaran."
        tabs={tabs}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      />
      {activeYear && (
        <div className="flex justify-end mb-4">
          <div className="flex items-center gap-2 bg-emerald-50 border border-emerald-200 text-emerald-700 px-4 py-2 rounded-[var(--ui-radius-small)] text-sm font-semibold shadow-sm w-fit">
            <Star size={14} className="fill-emerald-500 text-emerald-500" />
            TA Aktif: {activeYear.nama} {activeYear.semester}
          </div>
        </div>
      )}

      {/* PROFIL TAB */}
      {activeTab === 'profil' && (
        <div className="ui-card p-6 space-y-6">
          {/* Logo Section */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pb-6 border-b border-slate-100">
            {/* 1. Logo Umum */}
            <div className="flex flex-col items-center text-center p-4 bg-slate-50/50 rounded-[var(--ui-radius-small)] border border-slate-150">
              <div className="w-20 h-20 rounded-[var(--ui-radius-small)] border border-slate-200 flex items-center justify-center overflow-hidden bg-white shrink-0 mb-3">
                {logoPreview ? <img src={logoPreview} alt="Logo Umum" className="w-full h-full object-contain" /> :
                  <School className="text-slate-300" size={32} />}
              </div>
              <p className="font-bold text-slate-700 text-xs mb-0.5">Logo Umum (Kartu/Laporan)</p>
              <p className="text-[10px] text-slate-400 mb-3 max-w-[180px]">Digunakan pada Kartu Pelajar, Kop Surat, dan dokumen cetak.</p>
              <input type="file" accept="image/*" ref={logoInputRef} onChange={handleLogoChange} className="hidden" />
              <button onClick={() => logoInputRef.current?.click()} className="flex items-center gap-1.5 text-xs font-semibold text-[var(--ui-primary)] bg-[var(--ui-accent)]/20 hover:bg-[var(--ui-accent)]/40 px-3 py-1.5 rounded-[var(--ui-radius-small)] transition-colors border-none cursor-pointer">
                <Upload size={12} /> Upload Logo
              </button>
            </div>

            {/* 2. Logo Mobile */}
            <div className="flex flex-col items-center text-center p-4 bg-slate-50/50 rounded-[var(--ui-radius-small)] border border-slate-150">
              <div className="w-20 h-20 rounded-[var(--ui-radius-small)] border border-slate-200 flex items-center justify-center overflow-hidden bg-white shrink-0 mb-3">
                {logoMobilePreview ? <img src={logoMobilePreview} alt="Logo Mobile" className="w-full h-full object-contain" /> :
                  <MonitorSmartphone className="text-slate-350" size={32} />}
              </div>
              <p className="font-bold text-slate-700 text-xs mb-0.5">Logo Mobile (Landing Page)</p>
              <p className="text-[10px] text-slate-400 mb-3 max-w-[180px]">Digunakan pada header Landing Page Mobile sekolah.</p>
              <input type="file" accept="image/*" ref={logoMobileInputRef} onChange={handleLogoMobileChange} className="hidden" />
              <button onClick={() => logoMobileInputRef.current?.click()} className="flex items-center gap-1.5 text-xs font-semibold text-[var(--ui-primary)] bg-[var(--ui-accent)]/20 hover:bg-[var(--ui-accent)]/40 px-3 py-1.5 rounded-[var(--ui-radius-small)] transition-colors border-none cursor-pointer">
                <Upload size={12} /> Upload Logo
              </button>
            </div>

            {/* 3. Logo Website */}
            <div className="flex flex-col items-center text-center p-4 bg-slate-50/50 rounded-[var(--ui-radius-small)] border border-slate-150">
              <div className="w-20 h-20 rounded-[var(--ui-radius-small)] border border-slate-200 flex items-center justify-center overflow-hidden bg-white shrink-0 mb-3">
                {logoWebPreview ? <img src={logoWebPreview} alt="Logo Website" className="w-full h-full object-contain" /> :
                  <Globe className="text-slate-355" size={32} />}
              </div>
              <p className="font-bold text-slate-700 text-xs mb-0.5">Logo Website (Desktop)</p>
              <p className="text-[10px] text-slate-400 mb-3 max-w-[180px]">Digunakan pada header panel Dashboard & Sidebar Web Admin.</p>
              <input type="file" accept="image/*" ref={logoWebInputRef} onChange={handleLogoWebChange} className="hidden" />
              <button onClick={() => logoWebInputRef.current?.click()} className="flex items-center gap-1.5 text-xs font-semibold text-[var(--ui-primary)] bg-[var(--ui-accent)]/20 hover:bg-[var(--ui-accent)]/40 px-3 py-1.5 rounded-[var(--ui-radius-small)] transition-colors border-none cursor-pointer">
                <Upload size={12} /> Upload Logo
              </button>
            </div>
          </div>

          {/* Fields */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            {SCHOOL_FIELDS.map(field => (
              <div key={field.key} className={field.multiline ? 'col-span-full' : ''}>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">{field.label}</label>
                {field.multiline ? (
                  <textarea rows={3} value={profile[field.key] || ''} onChange={e => setProfile(prev => ({ ...prev, [field.key]: e.target.value }))}
                    placeholder={field.placeholder}
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:border-[var(--ui-primary)] resize-none" />
                ) : (
                  <input type="text" value={profile[field.key] || ''} onChange={e => setProfile(prev => ({ ...prev, [field.key]: e.target.value }))}
                    placeholder={field.placeholder}
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:border-[var(--ui-primary)]" />
                )}
              </div>
            ))}
          </div>

          <div className="flex justify-end pt-4 border-t border-slate-100">
            <Button onClick={handleSaveProfile} disabled={isSaving} className="flex items-center gap-2">
              <Save size={14} /> {isSaving ? 'Menyimpan...' : 'Simpan Profil'}
            </Button>
          </div>
        </div>
      )}

      {/* TAHUN AJARAN TAB */}
      {activeTab === 'tahun' && (
        <div className="ui-card p-6 space-y-6">
          <div className="flex flex-col sm:flex-row justify-between sm:items-center gap-4 border-b border-slate-100 pb-4">
            <div>
              <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest">Manajemen Tahun Ajaran</h2>
              <p className="text-xs text-slate-500 mt-1">Kelola data tahun akademik aktif, semester ganjil/genap, dan rentang periode sekolah.</p>
            </div>
            <Button onClick={openAddYear} className="flex items-center gap-2 text-xs px-4 py-2 font-bold rounded-[var(--ui-radius-small)] self-start sm:self-center">
              <Plus size={14} /> Tambah Tahun Ajaran
            </Button>
          </div>
          <div className="overflow-x-auto border border-slate-150 rounded-[var(--ui-radius-small)]">
            <table className="w-full text-sm">
              <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 font-bold text-left">Tahun Ajaran</th>
                  <th className="px-6 py-4 font-bold text-left">Semester</th>
                  <th className="px-6 py-4 font-bold text-left">Periode</th>
                  <th className="px-6 py-4 font-bold text-center">Status</th>
                  <th className="px-6 py-4 font-bold text-right">Aksi</th>
                </tr>
              </thead>
              <tbody>
                {academicYears.length === 0 ? (
                  <tr><td colSpan={5} className="px-6 py-8 text-center text-slate-400">Belum ada tahun ajaran. Tambahkan yang pertama!</td></tr>
                ) : academicYears.map(year => (
                  <tr key={year.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 font-bold text-slate-800">{year.nama}</td>
                    <td className="px-6 py-4 text-slate-600">{year.semester}</td>
                    <td className="px-6 py-4 text-slate-500 text-xs">
                      {year.tanggal_mulai ? new Date(year.tanggal_mulai).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) : '-'}
                      {' → '}
                      {year.tanggal_selesai ? new Date(year.tanggal_selesai).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) : '-'}
                    </td>
                    <td className="px-6 py-4 text-center">
                      {year.is_active ? (
                        <span className="inline-flex items-center gap-1 px-3 py-1 rounded-[var(--ui-radius-small)] text-xs font-bold bg-emerald-100 text-emerald-700">
                          <Star size={10} className="fill-emerald-600 text-emerald-600" /> Aktif
                        </span>
                      ) : (
                        <button onClick={() => handleSetActive(year.id)}
                          className="px-3 py-1 rounded-[var(--ui-radius-small)] text-xs font-bold bg-slate-100 text-slate-500 hover:bg-[var(--ui-accent)]/30 hover:text-[var(--ui-primary)] transition-colors">
                          Set Aktif
                        </button>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex justify-end gap-2">
                        <button onClick={() => openEditYear(year)} className="p-2 text-slate-400 hover:text-[var(--ui-primary)] bg-white hover:bg-[var(--ui-accent)]/20 border-none rounded-[var(--ui-radius-small)] transition-colors"><Edit2 size={14} /></button>
                        <button onClick={() => handleDeleteYear(year.id)} className="p-2 text-slate-400 hover:text-red-600 bg-white hover:bg-red-50 border-none rounded-[var(--ui-radius-small)] transition-colors"><Trash2 size={14} /></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* KOP SURAT TAB */}
      {activeTab === 'kop' && (
        <div className="ui-card p-6 space-y-6 animate-in fade-in duration-300">
          <div className="flex justify-between items-center border-b border-slate-100 pb-3 mb-4">
            <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
              <Printer size={18} className="text-slate-400" /> Kop Surat Resmi (Untuk Cetak)
            </h2>
            <div className="flex items-center gap-2">
              <label className="flex items-center gap-2.5 cursor-pointer bg-slate-50 border-none px-3.5 py-1.5 rounded-[var(--ui-radius-small)] hover:bg-slate-100/50 transition-colors">
                <input
                  type="checkbox"
                  checked={!!appSettings.useKopSuratGambar}
                  onChange={(e) => setAppSettings({ ...appSettings, useKopSuratGambar: e.target.checked })}
                  className="rounded-[var(--ui-radius-small)] text-[var(--ui-primary)] focus:ring-[var(--ui-primary)] cursor-pointer"
                />
                <span className="text-xs font-black text-slate-700 cursor-pointer">Gunakan File Gambar Kop Surat Utuh</span>
              </label>
            </div>
          </div>

          {appSettings.useKopSuratGambar ? (
            <div className="bg-slate-50/50 border-none rounded-[var(--ui-radius-small)] p-6 flex flex-col md:flex-row gap-6 items-center">
              <div className="w-full md:w-[480px] h-32 rounded-[var(--ui-radius-small)] border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden bg-white shrink-0 shadow-sm">
                {appSettings.kopSuratGambar ? (
                  <img src={appSettings.kopSuratGambar} alt="Gambar Kop Surat" className="w-full h-full object-contain p-1" />
                ) : (
                  <ImageIcon className="text-slate-300" size={32} />
                )}
              </div>
              <div className="flex-1 flex flex-col gap-3">
                <h4 className="text-sm font-black text-slate-800">Unggah Gambar Kop Surat Utuh</h4>
                <p className="text-xs text-slate-500 font-medium leading-relaxed">
                  Format gambar yang disarankan adalah PNG/JPG dengan rasio mendatar/lebar (landscape) yang proporsional untuk menggantikan seluruh teks Kop Surat di bagian atas cetak.
                </p>
                <div className="flex flex-wrap items-center gap-3 mt-2">
                  <input 
                    type="file" 
                    accept="image/*" 
                    onChange={(e) => {
                      const file = e.target.files[0];
                      if (file) {
                        compressImage(file, { maxWidth: 1000, maxHeight: 500, quality: 0.8 }).then(compressedBase64 => {
                          setAppSettings({ ...appSettings, kopSuratGambar: compressedBase64 });
                        });
                      }
                    }}
                    className="text-xs file:mr-3 file:py-1.5 file:px-4 file:rounded-[var(--ui-radius-small)] file:border-0 file:font-semibold file:bg-[var(--ui-primary)] file:text-white hover:file:opacity-90 cursor-pointer"
                  />
                  {appSettings.kopSuratGambar && (
                    <button 
                      type="button" 
                      className="text-xs font-bold text-red-500 hover:underline" 
                      onClick={() => setAppSettings({ ...appSettings, kopSuratGambar: "" })} 
                    >
                      Hapus Gambar Kop
                    </button>
                  )}
                </div>
                <div className="pt-4 mt-2 border-t border-slate-200">
                  <Button onClick={() => onSave({ appSettings })} className="w-full md:w-auto flex items-center gap-2">
                    <Save size={14} /> Simpan Gambar Kop Surat
                  </Button>
                </div>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in duration-300">
              <div className="space-y-5">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Logo Kop Surat</label>
                  <div className="flex gap-4 items-center">
                    <div className="w-20 h-20 rounded-[var(--ui-radius-small)] border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden bg-slate-50 shrink-0">
                      {appSettings.kopSuratLogo ? (
                        <img src={appSettings.kopSuratLogo} alt="Logo Kop" className="w-full h-full object-contain p-1" />
                      ) : (
                        <ImageIcon className="text-slate-300" size={24} />
                      )}
                    </div>
                    <div className="flex flex-col gap-2">
                      <input 
                        type="file" 
                        accept="image/*" 
                        onChange={(e) => {
                          const file = e.target.files[0];
                          if (file) {
                            compressImage(file, { maxWidth: 500, maxHeight: 500, quality: 0.8 }).then(compressedBase64 => {
                              setAppSettings({ ...appSettings, kopSuratLogo: compressedBase64 });
                            });
                          }
                        }}
                        className="text-xs file:mr-3 file:py-1.5 file:px-4 file:rounded-[var(--ui-radius-small)] file:border-0 file:font-semibold file:bg-[var(--ui-primary)] file:text-white hover:file:opacity-90 cursor-pointer"
                      />
                      {appSettings.kopSuratLogo && (
                        <button 
                          type="button" 
                          className="self-start text-xs font-bold text-red-500 hover:underline" 
                          onClick={() => setAppSettings({ ...appSettings, kopSuratLogo: "" })} 
                        >
                          Hapus Logo Khusus
                        </button>
                      )}
                      <p className="text-[10px] text-slate-400 max-w-[200px] leading-tight">Gunakan logo ini khusus untuk kop surat. Jika kosong, akan menggunakan logo sekolah utama.</p>
                    </div>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Baris 1 (Pemerintah)</label>
                  <input type="text" value={appSettings.kopSuratBaris1 || ""} onChange={(e) => setAppSettings({ ...appSettings, kopSuratBaris1: e.target.value })} placeholder="Pemerintah Provinsi Jawa Barat" className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:border-[var(--ui-primary)]" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Baris 2 (Instansi/Dinas)</label>
                  <input type="text" value={appSettings.kopSuratBaris2 || ""} onChange={(e) => setAppSettings({ ...appSettings, kopSuratBaris2: e.target.value })} placeholder="Dinas Pendidikan" className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:border-[var(--ui-primary)]" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Baris 3 (Nama Sekolah)</label>
                  <input type="text" value={appSettings.kopSuratBaris3 || ""} onChange={(e) => setAppSettings({ ...appSettings, kopSuratBaris3: e.target.value })} placeholder="SMK NEGERI 1 INKSCOD" className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-bold focus:outline-none focus:border-[var(--ui-primary)] text-[var(--ui-primary)]" />
                </div>
              </div>

              <div className="space-y-5">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Alamat Lengkap</label>
                  <textarea rows={3} value={appSettings.kopSuratAlamat || ""} onChange={(e) => setAppSettings({ ...appSettings, kopSuratAlamat: e.target.value })} placeholder="Jl. Pendidikan No. 123..." className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:border-[var(--ui-primary)] resize-none" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Kontak (Telp/Email/Web)</label>
                  <textarea rows={2} value={appSettings.kopSuratKontak || ""} onChange={(e) => setAppSettings({ ...appSettings, kopSuratKontak: e.target.value })} placeholder="Telp: (022) 1234567 | Email: info@..." className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:border-[var(--ui-primary)] resize-none" />
                </div>

                <div className="mt-6 pt-4 border-t border-slate-100">
                  <p className="text-xs text-slate-500 mb-4 bg-blue-50 text-blue-700 p-3 rounded-[var(--ui-radius-small)] border border-blue-100">Pratinjau kop surat akan terlihat pada dokumen cetak jadwal, absen, dan laporan.</p>
                  <Button onClick={() => onSave({ appSettings })} className="w-full flex items-center justify-center gap-2 py-3">
                    <Save size={16} /> Simpan Format Kop Surat
                  </Button>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Year Modal */}
      {showYearModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-[var(--ui-radius-small)] shadow-sm w-full max-w-md overflow-hidden">
            <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <h3 className="font-bold text-slate-800">{editingYear ? 'Edit Tahun Ajaran' : 'Tambah Tahun Ajaran'}</h3>
              <button onClick={() => setShowYearModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>
            <div className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Nama Tahun Ajaran</label>
                <input type="text" value={yearForm.nama} onChange={e => setYearForm(p => ({ ...p, nama: e.target.value }))}
                  placeholder="2025/2026"
                  className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]" />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Semester</label>
                <select value={yearForm.semester} onChange={e => setYearForm(p => ({ ...p, semester: e.target.value }))}
                  className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]">
                  <option value="Ganjil">Ganjil</option>
                  <option value="Genap">Genap</option>
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Tanggal Mulai</label>
                  <input type="date" value={yearForm.tanggal_mulai} onChange={e => setYearForm(p => ({ ...p, tanggal_mulai: e.target.value }))}
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Tanggal Selesai</label>
                  <input type="date" value={yearForm.tanggal_selesai} onChange={e => setYearForm(p => ({ ...p, tanggal_selesai: e.target.value }))}
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]" />
                </div>
              </div>
              <div className="pt-4 flex justify-end gap-3">
                <Button type="button" variant="outline" onClick={() => setShowYearModal(false)}>Batal</Button>
                <Button onClick={handleSaveYear}>Simpan</Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-sm font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { UserMinus } from 'lucide-react';
import useAuthStore from '../../../store/monitoring/authStore.js';
import { Search, RotateCcw, AlertCircle, CheckCircle2 } from 'lucide-react';
import { PageHeader, Button } from '../../../components/monitoring/ui/index.js';


export default function SiswaKeluar() {
  const [exitedStudents, setExitedStudents] = useState([]);
  const [activeStudents, setActiveStudents] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [historySearchTerm, setHistorySearchTerm] = useState('');
  const [selectedStudent, setSelectedStudent] = useState(null);

  // Exit Form State
  const [exitForm, setExitForm] = useState({
    tanggal_keluar: new Date().toISOString().split('T')[0],
    alasan: 'Pindah Sekolah',
    keterangan: ''
  });

  const [toast, setToast] = useState(null);
  const authToken = useAuthStore(state => state.user?.authToken);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const fetchData = async () => {
    if (!authToken) return;
    setIsLoading(true);
    try {
      const [exitedRes, activeRes] = await Promise.all([
        fetch('/api/siswa-keluar', { headers: { Authorization: `Bearer ${authToken}` } }),
        fetch('/api/data/load', { headers: { Authorization: `Bearer ${authToken}` } })
      ]);

      const exitedData = await exitedRes.json();
      if (exitedData.ok) setExitedStudents(exitedData.data || []);

      const activeData = await activeRes.json();
      if (activeData.payload && activeData.payload.students) {
        setActiveStudents(activeData.payload.students || []);
      }
    } catch (e) {
      console.error(e);
      showToast('Gagal memuat data', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [authToken]);

  // Search autocomplete for active students
  const filteredActive = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return activeStudents.filter(s => 
      s.name?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      s.namaSiswa?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      s.nis?.includes(searchTerm)
    ).slice(0, 5); // limit to 5 suggestions
  }, [activeStudents, searchTerm]);

  // Exited students log list search
  const filteredHistory = useMemo(() => {
    return exitedStudents.filter(s => 
      s.nama?.toLowerCase().includes(historySearchTerm.toLowerCase()) || 
      s.nis?.includes(historySearchTerm) ||
      s.kelas_terakhir?.toLowerCase().includes(historySearchTerm.toLowerCase())
    );
  }, [exitedStudents, historySearchTerm]);

  // Chart summary reasons count
  const reasonStats = useMemo(() => {
    const stats = { 'Pindah Sekolah': 0, 'Mengundurkan Diri': 0, 'Dikeluarkan': 0, 'Lainnya': 0 };
    exitedStudents.forEach(s => {
      if (stats[s.alasan] !== undefined) {
        stats[s.alasan]++;
      } else {
        stats['Lainnya']++;
      }
    });
    return stats;
  }, [exitedStudents]);

  const handleProcessExit = async (e) => {
    e.preventDefault();
    if (!selectedStudent) return showToast('Pilih siswa aktif terlebih dahulu', 'error');
    if (!exitForm.tanggal_keluar) return showToast('Pilih tanggal keluar', 'error');

    if (!await window.confirmAsync(`Apakah Anda yakin ingin memproses pengeluaran siswa ${selectedStudent.namaSiswa || selectedStudent.name}?\nSiswa ini akan dihapus dari daftar kelas aktif.`)) return;

    try {
      const res = await fetch('/api/siswa-keluar', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${authToken}` },
        body: JSON.stringify({
          action: 'keluar',
          nis: selectedStudent.nis,
          nama: selectedStudent.namaSiswa || selectedStudent.name,
          kelas_terakhir: selectedStudent.class_name || 'Umum',
          tanggal_keluar: exitForm.tanggal_keluar,
          alasan: exitForm.alasan,
          keterangan: exitForm.keterangan
        })
      });
      const data = await res.json();
      if (data.ok) {
        showToast('Siswa berhasil dicatat keluar!');
        setSelectedStudent(null);
        setSearchTerm('');
        setExitForm({
          tanggal_keluar: new Date().toISOString().split('T')[0],
          alasan: 'Pindah Sekolah',
          keterangan: ''
        });
        fetchData();
      } else {
        showToast(data.error || 'Gagal memproses pengeluaran', 'error');
      }
    } catch (e) {
      console.error(e);
      showToast('Gagal memproses pengeluaran', 'error');
    }
  };

  const handleCancelExit = async (nis, name) => {
    if (!await window.confirmAsync(`Batalkan status keluar untuk siswa ${name}?\nSiswa ini akan dikembalikan ke daftar siswa aktif.`)) return;

    try {
      const res = await fetch('/api/siswa-keluar', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${authToken}` },
        body: JSON.stringify({ action: 'batal', nis })
      });
      const data = await res.json();
      if (data.ok) {
        showToast('Status keluar berhasil dibatalkan. Siswa telah aktif kembali!');
        fetchData();
      } else {
        showToast(data.error || 'Gagal membatalkan status keluar', 'error');
      }
    } catch (e) {
      console.error(e);
      showToast('Gagal membatalkan status keluar', 'error');
    }
  };

  return (
    <div className="space-y-6 relative animate-in fade-in duration-300 z-10">
      <PageHeader 
        title="Pendataan Siswa Keluar"
        description="Mencatat dan mendata siswa yang mutasi pindah sekolah, mengundurkan diri, atau dikeluarkan."
        icon={UserMinus}
      />

      {/* Grid Utama */}
      <div className="grid grid-cols-1 lg:grid-cols-[380px,1fr] gap-6">

        {/* Kolom Kiri: Form Keluar */}
        <div className="ui-card p-5 space-y-5 h-fit">
          <h3 className="font-bold text-slate-800 text-sm border-b border-slate-100 pb-3">Formulir Keluar</h3>

          <form onSubmit={handleProcessExit} className="space-y-4">
            {/* Input Siswa Autocomplete */}
            <div className="relative">
              <label className="block text-xs font-bold text-slate-500 mb-1">Cari &amp; Pilih Siswa</label>
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <input 
                  value={searchTerm} 
                  onChange={e => {
                    setSearchTerm(e.target.value);
                    if (selectedStudent && e.target.value !== (selectedStudent.namaSiswa || selectedStudent.name)) {
                      setSelectedStudent(null);
                    }
                  }} 
                  placeholder="Nama atau NIS..."
                  className="w-full pl-9 pr-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:border-[var(--ui-primary)]" 
                />
              </div>

              {/* Autocomplete Suggestions */}
              {filteredActive.length > 0 && !selectedStudent && (
                <div className="absolute left-0 right-0 mt-1 bg-white border border-slate-200 rounded-[var(--ui-radius-small)] shadow-lg z-20 max-h-48 overflow-y-auto">
                  {filteredActive.map(s => (
                    <button
                      key={s.nis}
                      type="button"
                      onClick={() => {
                        setSelectedStudent(s);
                        setSearchTerm(s.namaSiswa || s.name);
                      }}
                      className="w-full px-4 py-2 text-left hover:bg-slate-50 text-xs font-semibold text-slate-700 flex items-center justify-between"
                    >
                      <span>{s.namaSiswa || s.name} ({s.nis})</span>
                      <span className="text-slate-400 font-bold">{s.class_name || 'Tanpa Kelas'}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>

            {selectedStudent && (
              <div className="p-3 bg-blue-50 border border-blue-100 rounded-lg space-y-1 text-xs text-blue-900">
                <p className="font-extrabold">Siswa Terpilih:</p>
                <p className="font-semibold">{selectedStudent.namaSiswa || selectedStudent.name} ({selectedStudent.nis})</p>
                <p className="text-blue-700">Kelas Terakhir: {selectedStudent.class_name || 'Umum'}</p>
              </div>
            )}

            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1">Tanggal Keluar</label>
              <input 
                type="date"
                required
                value={exitForm.tanggal_keluar} 
                onChange={e => setExitForm({ ...exitForm, tanggal_keluar: e.target.value })}
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm" 
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1">Alasan Keluar</label>
              <select 
                value={exitForm.alasan} 
                onChange={e => setExitForm({ ...exitForm, alasan: e.target.value })}
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold bg-white"
              >
                <option value="Pindah Sekolah">Pindah Sekolah (Mutasi Keluar)</option>
                <option value="Mengundurkan Diri">Mengundurkan Diri</option>
                <option value="Dikeluarkan">Dikeluarkan</option>
                <option value="Lainnya">Lainnya</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1">Keterangan / Tujuan</label>
              <textarea 
                rows="3"
                value={exitForm.keterangan} 
                onChange={e => setExitForm({ ...exitForm, keterangan: e.target.value })}
                placeholder="Contoh: Pindah ke SMKN 1 Jakarta Timur"
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:border-[var(--ui-primary)]" 
              />
            </div>

            <Button type="submit" disabled={!selectedStudent} className="w-full flex items-center justify-center gap-2 bg-red-600 hover:bg-red-700 text-white font-bold py-2.5">
              <UserMinus size={16} /> Proses Siswa Keluar
            </Button>
          </form>

          {/* Mini Chart Stats */}
          <div className="pt-4 border-t border-slate-100 space-y-3">
            <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Statistik Pengeluaran</h4>
            <div className="grid grid-cols-2 gap-2 text-xs">
              {[
                { label: 'Pindah', value: reasonStats['Pindah Sekolah'], color: 'bg-blue-500' },
                { label: 'Mundur', value: reasonStats['Mengundurkan Diri'], color: 'bg-amber-500' },
                { label: 'Dikeluarkan', value: reasonStats['Dikeluarkan'], color: 'bg-red-500' },
                { label: 'Lainnya', value: reasonStats['Lainnya'], color: 'bg-slate-400' },
              ].map(stat => (
                <div key={stat.label} className="p-2 bg-slate-50 rounded-lg flex flex-col justify-between">
                  <span className="text-[10px] text-slate-400 font-bold uppercase">{stat.label}</span>
                  <div className="flex items-center justify-between mt-1">
                    <span className="text-sm font-black text-slate-700">{stat.value}</span>
                    <span className={`w-2 h-2 rounded-full ${stat.color}`} />
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Kolom Kanan: Daftar Riwayat Keluar */}
        <div className="ui-card p-6 space-y-4">
          <div className="flex flex-col md:flex-row justify-between items-stretch md:items-center gap-3 border-b border-slate-100 pb-4">
            <div>
              <h3 className="font-bold text-slate-800 text-sm">Arsip Siswa Keluar</h3>
              <p className="text-xs text-slate-500 mt-1">Total {exitedStudents.length} siswa keluar terdaftar di riwayat.</p>
            </div>
            <div className="relative w-full md:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input 
                value={historySearchTerm} 
                onChange={e => setHistorySearchTerm(e.target.value)} 
                placeholder="Cari arsip..."
                className="w-full pl-9 pr-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:border-[var(--ui-primary)]" 
              />
            </div>
          </div>

          <div className="overflow-x-auto border border-slate-150 rounded-[var(--ui-radius-small)]">
            <table className="w-full text-sm">
              <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-6 py-4 font-bold text-left">Nama Siswa</th>
                  <th className="px-6 py-4 font-bold text-left">NIS</th>
                  <th className="px-6 py-4 font-bold text-left">Kelas Terakhir</th>
                  <th className="px-6 py-4 font-bold text-left">Alasan</th>
                  <th className="px-6 py-4 font-bold text-left">Keterangan / Tujuan</th>
                  <th className="px-6 py-4 font-bold text-left">Tanggal Keluar</th>
                  <th className="px-6 py-4 font-bold text-right w-24">Aksi</th>
                </tr>
              </thead>
              <tbody>
                {isLoading ? (
                  <tr><td colSpan={7} className="px-6 py-8 text-center text-slate-400">Memuat arsip siswa...</td></tr>
                ) : filteredHistory.length === 0 ? (
                  <tr><td colSpan={7} className="px-6 py-8 text-center text-slate-400">Tidak ada riwayat siswa keluar.</td></tr>
                ) : (
                  filteredHistory.map(student => (
                    <tr key={student.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4 font-bold text-slate-800">{student.nama}</td>
                      <td className="px-6 py-4 font-mono text-xs text-slate-500">{student.nis}</td>
                      <td className="px-6 py-4 text-slate-600">{student.kelas_terakhir}</td>
                      <td className="px-6 py-4">
                        <span className={`inline-flex px-2 py-0.5 rounded-[var(--ui-radius-small)] text-xs font-bold ${
                          student.alasan === 'Dikeluarkan' ? 'bg-red-100 text-red-800' :
                          student.alasan === 'Mengundurkan Diri' ? 'bg-amber-100 text-amber-800' :
                          student.alasan === 'Pindah Sekolah' ? 'bg-blue-100 text-blue-800' :
                          'bg-slate-100 text-slate-800'
                        }`}>
                          {student.alasan}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-slate-500 text-xs">{student.keterangan || '-'}</td>
                      <td className="px-6 py-4 text-slate-600">
                        {new Date(student.tanggal_keluar).toLocaleDateString('id-ID', {
                          day: '2-digit',
                          month: 'short',
                          year: 'numeric'
                        })}
                      </td>
                      <td className="px-6 py-4 text-right">
                        <button
                          onClick={() => handleCancelExit(student.nis, student.nama)}
                          className="flex items-center gap-1 px-2.5 py-1 text-xs font-bold text-blue-600 hover:text-blue-800 hover:bg-blue-50 border border-blue-200 rounded-[var(--ui-radius-small)] transition-colors self-end"
                          title="Batalkan & aktifkan kembali"
                        >
                          <RotateCcw size={12} /> Batal
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-sm font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'} z-50`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { BookOpen } from 'lucide-react';
import useAuthStore from '../../../store/monitoring/authStore.js';
import { useAppStore } from '../../../store/useAppStore.js';
import { ShieldAlert, Award, HelpCircle, Search, Plus, Edit2, Trash2, X, Save, AlertCircle, CheckCircle2 } from 'lucide-react';
import { PageHeader, Button } from '../../../components/monitoring/ui/index.js';


export default function TatibSkorKredit() {
  const [items, setItems] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState('all'); // 'all', 'pelanggaran', 'prestasi'
  const [showModal, setShowModal] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [toast, setToast] = useState(null);
  const [form, setForm] = useState({ nama_tindakan: '', jenis: 'pelanggaran', nilai_poin: 10 });
  const authToken = useAuthStore(state => state.user?.authToken);
  const userRole = useAuthStore(state => state.user?.role || 'guru');
  const isAdmin = ['admin', 'superadmin', 'waka_kesiswaan', 'guru'].includes(userRole);

  const { kedisiplinanSettings, updateKedisiplinanSettings } = useAppStore();
  const [batasPoin, setBatasPoin] = useState(100);

  useEffect(() => {
    if (kedisiplinanSettings?.batasPoinSiswaBermasalah) {
      setBatasPoin(kedisiplinanSettings.batasPoinSiswaBermasalah);
    }
  }, [kedisiplinanSettings]);

  const handleUpdateBatasPoin = (val) => {
    setBatasPoin(val);
    updateKedisiplinanSettings({ batasPoinSiswaBermasalah: val });
  };

  const [hasPdf, setHasPdf] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  const checkPdfExists = async () => {
    try {
      const res = await fetch('/api/kedisiplinan/rules.pdf', { method: 'HEAD' });
      setHasPdf(res.ok);
    } catch {
      setHasPdf(false);
    }
  };

  useEffect(() => {
    checkPdfExists();
  }, []);

  const handlePdfUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.type !== 'application/pdf') {
      showToast('File harus format PDF!', 'error');
      return;
    }

    setIsUploading(true);
    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const fileData = evt.target.result;
        const res = await fetch('/api/kedisiplinan/upload-rules', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${authToken}`
          },
          body: JSON.stringify({
            fileData,
            fileName: file.name
          })
        });
        const data = await res.json();
        if (data.ok) {
          showToast('Dokumen PDF Peraturan berhasil diunggah!');
          setHasPdf(true);
          updateKedisiplinanSettings({ hasRulesPdf: true });
        } else {
          showToast('Gagal mengunggah PDF: ' + (data.error || 'error'), 'error');
        }
      } catch (err) {
        console.error(err);
        showToast('Gagal mengunggah PDF', 'error');
      } finally {
        setIsUploading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handlePdfDelete = async () => {
    if (!await window.confirmAsync('Hapus dokumen PDF peraturan ini?')) return;
    try {
      const res = await fetch('/api/kedisiplinan/delete-rules', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${authToken}` }
      });
      if (res.ok) {
        showToast('Dokumen PDF Peraturan dihapus.');
        setHasPdf(false);
        updateKedisiplinanSettings({ hasRulesPdf: false });
      }
    } catch (e) {
      console.error(e);
      showToast('Gagal menghapus PDF', 'error');
    }
  };

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const fetchData = async () => {
    if (!authToken) return;
    setIsLoading(true);
    try {
      const res = await fetch('/api/kedisiplinan/master', { headers: { Authorization: `Bearer ${authToken}` } });
      const data = await res.json();
      if (data.ok) {
        setItems(data.data || []);
      }
    } catch (e) {
      console.error(e);
      showToast('Gagal memuat tata tertib', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [authToken]);

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const matchSearch = !searchTerm || item.nama_tindakan?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchType = filterType === 'all' || String(item.jenis || '').toLowerCase() === filterType.toLowerCase();
      return matchSearch && matchType;
    });
  }, [items, searchTerm, filterType]);

  const handleSave = async (e) => {
    e.preventDefault();
    if (!form.nama_tindakan.trim()) return showToast('Nama tindakan wajib diisi', 'error');
    if (form.nilai_poin <= 0) return showToast('Skor poin harus lebih besar dari 0', 'error');

    try {
      const res = await fetch('/api/kedisiplinan/master', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${authToken}` },
        body: JSON.stringify(editingItem ? { ...form, id: editingItem.id } : form)
      });
      const data = await res.json();
      if (data.ok) {
        showToast(editingItem ? 'Tata tertib diperbarui!' : 'Tata tertib ditambahkan!');
        setShowModal(false);
        fetchData();
      } else {
        showToast('Gagal menyimpan: ' + (data.error || ''), 'error');
      }
    } catch (e) {
      console.error(e);
      showToast('Terjadi kesalahan', 'error');
    }
  };

  const handleDelete = async (id) => {
    if (!await window.confirmAsync('Hapus aturan tata tertib ini?')) return;
    try {
      const res = await fetch('/api/kedisiplinan/master', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${authToken}` },
        body: JSON.stringify({ action: 'delete', id })
      });
      const data = await res.json();
      if (data.ok) {
        showToast('Aturan berhasil dihapus!');
        fetchData();
      } else {
        showToast('Gagal menghapus', 'error');
      }
    } catch (e) {
      console.error(e);
      showToast('Terjadi kesalahan', 'error');
    }
  };

  const openAdd = () => {
    setEditingItem(null);
    setForm({ nama_tindakan: '', jenis: 'pelanggaran', nilai_poin: 10 });
    setShowModal(true);
  };

  const openEdit = (item) => {
    setEditingItem(item);
    setForm({ nama_tindakan: item.nama_tindakan, jenis: String(item.jenis || 'pelanggaran').toLowerCase(), nilai_poin: item.nilai_poin });
    setShowModal(true);
  };

  return (
    <div className="space-y-6 relative animate-in fade-in duration-300 z-10">
      <PageHeader 
        title="Aturan & Tatib Skor Kredit"
        description="Daftar tata tertib sekolah beserta skor kredit poin pelanggaran dan penghargaan prestasi siswa."
        icon={BookOpen}
      />

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Info Poin */}
        <div className="ui-card p-5 flex items-center gap-4 bg-red-50/60 border-red-150">
          <div className="w-12 h-12 rounded-[var(--ui-radius-small)] bg-red-100 flex items-center justify-center text-red-600 shrink-0">
            <ShieldAlert size={22} />
          </div>
          <div>
            <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Tingkat Pelanggaran</h4>
            <p className="text-sm font-black text-red-800 mt-1">Maksimal {batasPoin} Poin (Drop Out)</p>
          </div>
        </div>

        <div className="ui-card p-5 flex items-center gap-4 bg-emerald-50/60 border-emerald-150">
          <div className="w-12 h-12 rounded-[var(--ui-radius-small)] bg-emerald-100 flex items-center justify-center text-emerald-600 shrink-0">
            <Award size={22} />
          </div>
          <div>
            <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Poin Penghargaan</h4>
            <p className="text-sm font-black text-emerald-800 mt-1">Mengurangi akumulasi poin pelanggaran</p>
          </div>
        </div>

        <div className="ui-card p-5 flex items-center gap-4 bg-blue-50/60 border-blue-150">
          <div className="w-12 h-12 rounded-[var(--ui-radius-small)] bg-blue-100 flex items-center justify-center text-blue-600 shrink-0">
            <HelpCircle size={22} />
          </div>
          <div className="flex-1 min-w-0">
            <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Batas Poin Bermasalah</h4>
            {isAdmin ? (
              <div className="flex items-center gap-2 mt-1">
                <input
                  type="text"
                  inputMode="numeric"
                  value={batasPoin}
                  onChange={(e) => handleUpdateBatasPoin(parseInt(e.target.value.replace(/[^0-9]/g, '')) || 0)}
                  className="w-16 px-1.5 py-0.5 text-xs font-bold border border-slate-200 rounded-[var(--ui-radius-small)] bg-white focus:outline-none focus:ring-1 focus:ring-[var(--ui-primary)] text-slate-700"
                />
                <span className="text-[11px] font-bold text-blue-700 truncate">Poin (DO)</span>
              </div>
            ) : (
              <p className="text-sm font-black text-blue-800 mt-1">{batasPoin} Poin (DO)</p>
            )}
          </div>
        </div>

        <div className="ui-card p-5 flex items-center gap-4 bg-purple-50/60 border-purple-150">
          <div className="w-12 h-12 rounded-[var(--ui-radius-small)] bg-purple-100 flex items-center justify-center text-purple-600 shrink-0">
            <BookOpen size={22} />
          </div>
          <div className="flex-1 min-w-0">
            <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">PDF Peraturan Sekolah</h4>
            <div className="mt-1 flex items-center gap-2">
              {hasPdf ? (
                <>
                  <a
                    href="/api/kedisiplinan/rules.pdf"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-xs font-bold text-purple-700 hover:underline flex items-center gap-1"
                  >
                    Lihat PDF
                  </a>
                  {isAdmin && (
                    <button
                      onClick={handlePdfDelete}
                      className="text-[10px] font-bold text-red-500 hover:underline border-none bg-transparent cursor-pointer"
                    >
                      Hapus
                    </button>
                  )}
                </>
              ) : (
                <span className="text-xs font-bold text-slate-400">Belum diunggah</span>
              )}
            </div>
            {isAdmin && (
              <div className="mt-1.5">
                <label className="text-[10px] font-extrabold px-2 py-1 bg-purple-600 hover:bg-purple-700 text-white rounded-[var(--ui-radius-small)] cursor-pointer inline-block">
                  {isUploading ? 'Mengunggah...' : hasPdf ? 'Ganti PDF' : 'Unggah PDF'}
                  <input
                    type="file"
                    accept="application/pdf"
                    onChange={handlePdfUpload}
                    disabled={isUploading}
                    className="hidden"
                  />
                </label>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="ui-card p-6 space-y-4">
        {/* Toolbar */}
        <div className="flex flex-col md:flex-row gap-4 justify-between items-stretch md:items-center">
          <div className="flex flex-wrap gap-2 flex-1 items-center">
            <div className="relative flex-1 min-w-[200px]">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Cari tata tertib..."
                className="w-full pl-9 pr-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:border-[var(--ui-primary)]" />
            </div>
            <select value={filterType} onChange={e => setFilterType(e.target.value)}
              className="px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:border-[var(--ui-primary)]">
              <option value="all">Semua Tipe</option>
              <option value="pelanggaran">Pelanggaran (Skor Minus)</option>
              <option value="prestasi">Penghargaan (Skor Plus)</option>
            </select>
          </div>

          {isAdmin && (
            <Button onClick={openAdd} className="flex items-center gap-2 self-start md:self-auto">
              <Plus size={14} /> Tambah Aturan Baru
            </Button>
          )}
        </div>

        {/* List Table */}
        <div className="overflow-x-auto border border-slate-150 rounded-[var(--ui-radius-small)]">
          <table className="w-full text-sm">
            <thead className="text-xs text-slate-500 bg-slate-50 border-b border-slate-200 uppercase">
              <tr>
                <th className="px-6 py-4 font-bold text-left">Deskripsi Tindakan / Kriteria</th>
                <th className="px-6 py-4 font-bold text-center w-36">Tipe Poin</th>
                <th className="px-6 py-4 font-bold text-center w-36">Skor Kredit</th>
                {isAdmin && <th className="px-6 py-4 font-bold text-right w-28">Aksi</th>}
              </tr>
            </thead>
            <tbody>
              {isLoading ? (
                <tr><td colSpan={isAdmin ? 4 : 3} className="px-6 py-8 text-center text-slate-400">Memuat data tatib...</td></tr>
              ) : filteredItems.length === 0 ? (
                <tr><td colSpan={isAdmin ? 4 : 3} className="px-6 py-8 text-center text-slate-400">Tidak ada aturan ditemukan.</td></tr>
              ) : (
                filteredItems.map(item => (
                  <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 font-bold text-slate-700">{item.nama_tindakan}</td>
                    <td className="px-6 py-4 text-center">
                      <span className={`inline-flex px-2.5 py-0.5 rounded-[var(--ui-radius-small)] text-xs font-bold ${
                        String(item.jenis || '').toLowerCase() === 'pelanggaran' ? 'bg-red-100 text-red-800' : 'bg-emerald-100 text-emerald-800'
                      }`}>
                        {String(item.jenis || '').toLowerCase() === 'pelanggaran' ? 'Pelanggaran' : 'Prestasi'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-center font-black">
                      <span className={String(item.jenis || '').toLowerCase() === 'pelanggaran' ? 'text-red-600' : 'text-emerald-600'}>
                        {String(item.jenis || '').toLowerCase() === 'pelanggaran' ? '-' : '+'}{item.nilai_poin}
                      </span>
                    </td>
                    {isAdmin && (
                      <td className="px-6 py-4 text-right flex items-center justify-end gap-1.5">
                        <button onClick={() => openEdit(item)} className="p-1.5 text-slate-400 hover:text-blue-600 rounded hover:bg-slate-100" title="Edit">
                          <Edit2 size={14} />
                        </button>
                        <button onClick={() => handleDelete(item.id)} className="p-1.5 text-slate-400 hover:text-red-600 rounded hover:bg-red-50" title="Hapus">
                          <Trash2 size={14} />
                        </button>
                      </td>
                    )}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Edit / Add Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
          <div className="bg-white rounded-[var(--ui-radius-small)] shadow-sm w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-4 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-800">{editingItem ? 'Edit Aturan Tatib' : 'Tambah Aturan Tatib'}</h3>
              <button type="button" onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-600"><X size={18} /></button>
            </div>
            <form onSubmit={handleSave} className="p-4 space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 mb-1">Deskripsi Tindakan / Aturan</label>
                <input required value={form.nama_tindakan} onChange={e => setForm({ ...form, nama_tindakan: e.target.value })}
                  placeholder="Contoh: Terlambat masuk sekolah..."
                  className="w-full px-3 py-2 border-none focus:outline-[var(--ui-primary)] rounded-[var(--ui-radius-small)] text-sm bg-slate-50" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 mb-1">Tipe</label>
                  <select value={form.jenis} onChange={e => setForm({ ...form, jenis: e.target.value })}
                    className="w-full px-3 py-2 border-none focus:outline-[var(--ui-primary)] rounded-[var(--ui-radius-small)] text-sm bg-slate-50">
                    <option value="pelanggaran">Pelanggaran (Minus)</option>
                    <option value="prestasi">Prestasi (Plus)</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 mb-1">Nilai Poin</label>
                  <input type="text" inputMode="numeric" required value={form.nilai_poin} onChange={e => setForm({ ...form, nilai_poin: parseInt(e.target.value.replace(/[^0-9]/g, '')) || 0 })}
                    className="w-full px-3 py-2 border-none focus:outline-[var(--ui-primary)] rounded-[var(--ui-radius-small)] text-sm bg-slate-50" />
                </div>
              </div>
              <div className="pt-2 flex justify-end gap-2">
                <Button type="button" onClick={() => setShowModal(false)} className="bg-slate-100 text-slate-600 hover:bg-slate-200 border-0">Batal</Button>
                <Button type="submit" className="bg-[var(--ui-primary)] text-white flex items-center gap-1">
                  <Save size={14} /> Simpan Aturan
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-sm font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'} z-50`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useMemo } from "react";
import { Users, Clock, Building, FileBarChart2 } from "lucide-react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";
import { AlertTriangle, RefreshCw, MapIcon } from 'lucide-react';
import { PageHeader } from '../../../components/monitoring/ui/index.js';


/**
 * admin/DashboardPKL.jsx
 * Dashboard PKL — menggunakan data aktual dari database PKL.
 * Ditampilkan dalam tata letak penuh (full-width) dengan peta yang interaktif.
 */

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png",
  iconUrl: "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png",
  shadowUrl: "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png",
});

const getToken = () => {
  try { return JSON.parse(sessionStorage.getItem("school_schedule_session_v1"))?.authToken; }
  catch { return null; }
};

const DashboardPKL = () => {
  const [stats, setStats] = useState({ totalSiswa: 0, totalPerusahaan: 0, totalGuru: 0, jurnalPending: [] });
  const [journals, setJournals] = useState([]);
  const [locations, setLocations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);

  const fetchData = () => {
    const token = getToken();
    setLoading(true);
    setError(null);

    Promise.all([
      fetch("/api/pkl/dashboard-stats", { headers: { Authorization: `Bearer ${token}` } }).then(r => r.json()).catch(() => ({ ok: false })),
      fetch("/api/pkl/logbooks", { headers: { Authorization: `Bearer ${token}` } }).then(r => r.json()).catch(() => ({ ok: false, data: [] })),
      fetch("/api/pkl/locations", { headers: { Authorization: `Bearer ${token}` } }).then(r => r.json()).catch(() => ({ ok: false, data: [] })),
    ]).then(([statsData, journalsData, locData]) => {
      if (statsData?.ok) setStats(statsData.data || {});
      else setError("Gagal memuat statistik PKL dari server.");

      if (journalsData?.ok) setJournals(Array.isArray(journalsData.data) ? journalsData.data : []);
      if (locData?.ok) setLocations(Array.isArray(locData.data) ? locData.data : []);

      setLastUpdated(new Date());
      setLoading(false);
    }).catch(err => {
      console.error("[DashboardPKL]", err);
      setError("Koneksi ke server gagal.");
      setLoading(false);
    });
  };

  useEffect(() => { fetchData(); }, []);

  const pendingJurnals = useMemo(() => {
    if (stats?.jurnalPending?.length) return stats.jurnalPending;
    return journals.filter(j => j.status === "pending").slice(0, 10);
  }, [stats, journals]);

  // FIX: Menggunakan loc.lat dan loc.lng karena database mengembalikan kolom tersebut (bukan latitude/longitude)
  const locationsWithCoords = useMemo(() =>
    locations.filter(loc => loc.lat && loc.lng), [locations]);

  const mapCenter = useMemo(() => {
    if (locationsWithCoords.length === 0) return [-6.2, 106.816666]; // Default ke Jakarta jika kosong
    const avgLat = locationsWithCoords.reduce((s, l) => s + parseFloat(l.lat), 0) / locationsWithCoords.length;
    const avgLng = locationsWithCoords.reduce((s, l) => s + parseFloat(l.lng), 0) / locationsWithCoords.length;
    return [avgLat, avgLng];
  }, [locationsWithCoords]);

  if (loading) return (
    <div className="flex flex-col items-center justify-center h-64 gap-3">
      <div className="animate-spin h-8 w-8 border-4 border-[var(--ui-primary)] border-t-transparent rounded-full" />
      <p className="text-sm font-semibold text-slate-500">Memuat data Dashboard PKL...</p>
    </div>
  );

  if (error) return (
    <div className="flex flex-col items-center justify-center h-64 gap-3 text-center">
      <div className="w-12 h-12 rounded-full bg-red-50 flex items-center justify-center">
        <AlertTriangle size={22} className="text-red-500" />
      </div>
      <p className="text-sm font-semibold text-slate-700">{error}</p>
      <button onClick={fetchData} className="flex items-center gap-2 px-4 py-2 bg-[var(--ui-primary)] text-white text-xs font-bold rounded-lg cursor-pointer">
        <RefreshCw size={14} /> Coba Lagi
      </button>
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in w-full pb-8">
      <PageHeader
        icon={FileBarChart2}
        title="Dashboard PKL"
        description="Ringkasan pemantauan Praktek Kerja Lapangan secara langsung."
        rightContent={
          <div className="flex items-center gap-4">
            {lastUpdated && (
              <p className="text-xs font-semibold text-slate-400">
