const KelolaAdministrasiPKL = ({ currentUser: propsUser, readOnly, appSettings, setAppSettings, onSave }) => {
  const { user: storeUser } = useAuthStore();
  const currentUser = propsUser || storeUser;
  const [activeTab, setActiveTab] = useState("surat");
  const [suratList, setSuratList] = useState([]);
  const [mutasiList, setMutasiList] = useState([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  // Auto numbering settings
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [accModal, setAccModal] = useState({ isOpen: false, suratId: null, formattedNumber: "" });

  const formatTemplate = appSettings?.suratFormat || "{INDEX}/PKL-SMK/{MONTH}/{YEAR}";
  const nextIndex = Number(appSettings?.suratNextIndex || 1);
  const padding = Number(appSettings?.suratPadding || 3);
  const monthStyle = appSettings?.suratMonthStyle || "romawi";

  const generateFormattedNumber = (format, index, padVal, mStyle) => {
    const now = new Date();
    const paddedIndex = String(index).padStart(Number(padVal || 3), '0');
    const romanMonths = ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII"];
    const numericMonth = String(now.getMonth() + 1).padStart(2, '0');
    const monthVal = mStyle === 'romawi' ? romanMonths[now.getMonth()] : numericMonth;
    const yearVal = String(now.getFullYear());

    return format
      .replace(/{INDEX}/g, paddedIndex)
      .replace(/{MONTH}/g, monthVal)
      .replace(/{YEAR}/g, yearVal);
  };

  const updateNumberingSetting = async (key, val) => {
    try {
      const localSnapshot = getDatabaseSnapshot() || {};
      const newSettings = { ...(localSnapshot.appSettings || {}), [key]: val };
      const updatedSnapshot = { ...localSnapshot, appSettings: newSettings };

      setDatabaseSnapshot(updatedSnapshot);
      if (setAppSettings) setAppSettings(newSettings);
      if (onSave) await onSave(updatedSnapshot);
    } catch (e) {
      console.error(e);
    }
  };

  const role = currentUser?.role;
  const isHubinOrAdmin = ["admin", "hubin", "waka"].includes(role);
  const canViewSurat = isHubinOrAdmin || role === "kepsek";

  const fetchSurat = async () => {
    try {
      const res = await fetch("/api/pkl/surat-pengantar", {
        headers: { Authorization: `Bearer ${currentUser?.authToken}` }
      });
      const data = await res.json();
      if (data.ok) setSuratList(data.data);
    } catch (e) { console.error(e); }
  };

  const fetchMutasi = async () => {
    try {
      const res = await fetch("/api/pkl/mutasi", {
        headers: { Authorization: `Bearer ${currentUser?.authToken}` }
      });
      const data = await res.json();
      if (data.ok) setMutasiList(data.data);
    } catch (e) { console.error(e); }
  };

  useEffect(() => {
    if (currentUser?.authToken) {
      if (activeTab === "surat" && canViewSurat) fetchSurat();
      if (activeTab === "mutasi") fetchMutasi();
    }
  }, [currentUser, activeTab, canViewSurat]);

  const accSurat = (id) => {
    const num = generateFormattedNumber(formatTemplate, nextIndex, padding, monthStyle);
    setAccModal({ isOpen: true, suratId: id, formattedNumber: num });
  };

  const handleAccConfirm = async (e) => {
    if (e) e.preventDefault();
    if (!accModal.formattedNumber) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/pkl/surat-pengantar/${accModal.suratId}/acc`, {
        method: "PUT",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${currentUser?.authToken}` },
        body: JSON.stringify({ nomor_surat: accModal.formattedNumber })
      });
      if (res.ok) {
        await updateNumberingSetting('suratNextIndex', nextIndex + 1);
        setAccModal({ isOpen: false, suratId: null, formattedNumber: "" });
        showToast('Surat berhasil di-ACC!');
        fetchSurat();
      } else {
        showToast('Gagal mem-ACC surat.', 'error');
      }
    } catch (err) { showToast('Terjadi kesalahan.', 'error'); }
    setLoading(false);
  };

  const validasiStempel = async (id) => {
    if (!(await window.confirmAsync("Apakah surat ini sudah dicap/stempel basah? Status akan berubah menjadi Selesai (Sah)."))) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/pkl/surat-pengantar/${id}/stempel`, {
        method: "PUT",
        headers: { Authorization: `Bearer ${currentUser?.authToken}` }
      });
      if (res.ok) { showToast('Status surat diperbarui ke Selesai (Sah).'); fetchSurat(); }
      else showToast('Gagal memperbarui status.', 'error');
    } catch (err) { showToast('Terjadi kesalahan.', 'error'); }
    setLoading(false);
  };

  const accMutasi = async (id, status) => {
    if (!(await window.confirmAsync(`Apakah Anda yakin ingin melakukan ${status === 'acc' ? 'ACC' : 'PENOLAKAN'} mutasi ini?`))) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/pkl/mutasi/${id}/acc`, {
        method: "PUT",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${currentUser?.authToken}` },
        body: JSON.stringify({ status })
      });
      if (res.ok) { showToast(`Mutasi berhasil ${status === 'acc' ? 'disetujui' : 'ditolak'}.`); fetchMutasi(); }
      else showToast('Gagal memproses mutasi.', 'error');
    } catch (err) { showToast('Terjadi kesalahan.', 'error'); }
    setLoading(false);
  };

  const deleteSurat = async (id) => {
    if (!(await window.confirmAsync("Apakah Anda yakin ingin menghapus surat ini secara permanen?"))) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/pkl/surat-pengantar/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${currentUser?.authToken}` }
      });
      if (res.ok) { showToast('Surat berhasil dihapus.'); fetchSurat(); }
      else showToast('Gagal menghapus surat.', 'error');
    } catch (err) { showToast('Terjadi kesalahan.', 'error'); }
    setLoading(false);
  };

  const deleteMutasi = async (id) => {
    if (!(await window.confirmAsync("Apakah Anda yakin ingin menghapus mutasi ini secara permanen?"))) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/pkl/mutasi/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${currentUser?.authToken}` }
      });
      if (res.ok) { showToast('Data mutasi berhasil dihapus.'); fetchMutasi(); }
      else showToast('Gagal menghapus mutasi.', 'error');
    } catch (err) { showToast('Terjadi kesalahan.', 'error'); }
    setLoading(false);
  };

  // Computed stats
  const suratPending = suratList.filter(s => s.status === 'pending').length;
  const suratAcc     = suratList.filter(s => s.status === 'acc_hubin').length;
  const mutasiPending = mutasiList.filter(m => m.final_status === 'pending').length;
  const mutasiAcc    = mutasiList.filter(m => m.final_status === 'acc').length;

  const suratStats = [
    { label: 'Total Surat',   value: suratList.length,  icon: FileText,   iconBg: 'bg-blue-100',    iconColor: 'text-blue-600' },
    { label: 'Menunggu ACC',  value: suratPending,       icon: AlertCircle,iconBg: 'bg-amber-100',   iconColor: 'text-amber-600' },
    { label: 'Sudah di-ACC',  value: suratAcc,           icon: CheckCircle,iconBg: 'bg-emerald-100', iconColor: 'text-emerald-600' },
  ];

  const mutasiStats = [
    { label: 'Total Mutasi',  value: mutasiList.length,  icon: GitMerge,   iconBg: 'bg-blue-100',    iconColor: 'text-blue-600' },
    { label: 'Menunggu',      value: mutasiPending,       icon: AlertCircle,iconBg: 'bg-amber-100',   iconColor: 'text-amber-600' },
    { label: 'Disetujui',     value: mutasiAcc,           icon: CheckCircle,iconBg: 'bg-emerald-100', iconColor: 'text-emerald-600' },
    { label: 'Ditolak',       value: mutasiList.filter(m => m.final_status === 'rejected').length, icon: XCircle, iconBg: 'bg-red-100', iconColor: 'text-red-600' },
  ];

  const tabs = [
    { 
      id: "surat", 
      label: suratPending > 0 ? `Surat Pengantar (${suratPending})` : "Surat Pengantar",
      icon: FileInput 
    },
    { 
      id: "mutasi", 
      label: mutasiPending > 0 ? `Permohonan Mutasi (${mutasiPending})` : "Permohonan Mutasi",
      icon: RefreshCw 
    },
    { 
      id: "kunjungan", 
      label: "Kunjungan Guru", 
      icon: MapPin 
    }
  ].filter(t => t.id !== "surat" || canViewSurat);

  return (
    <div className="space-y-4">
      <PageHeader 
        icon={FileText}
        title="Administrasi PKL"
        description="Kelola permohonan surat pengantar dan mutasi PKL dari siswa"
        tabs={tabs}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      />

      {/* ── SURAT TAB ── */}
      {activeTab === "surat" && canViewSurat && (
        <div className="space-y-4">
          <div className="grid grid-cols-3 gap-3">
            {suratStats.map(s => <StatCard key={s.label} {...s} />)}
          </div>

          {/* Settings Card */}
          <div className="ui-card p-5 space-y-4">
            <div className="flex items-center justify-between cursor-pointer" onClick={() => setIsSettingsOpen(!isSettingsOpen)}>
              <div className="flex items-center gap-2">
                <FileText className="text-[var(--ui-primary)]" size={18} />
                <h3 className="font-bold text-slate-800 text-sm">Konfigurasi Format Nomor Surat Otomatis</h3>
              </div>
              <span className="text-xs text-[var(--ui-primary)] font-bold hover:underline">
                {isSettingsOpen ? "Sembunyikan" : "Tampilkan Pengaturan"}
              </span>
            </div>

            {isSettingsOpen && (
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4 pt-2 border-t border-slate-100">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5">Format Template</label>
                  <input 
                    type="text" 
                    value={formatTemplate} 
                    onChange={e => updateNumberingSetting('suratFormat', e.target.value)}
                    placeholder="{INDEX}/PKL-SMK/{MONTH}/{YEAR}" 
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-xs font-semibold focus:outline-none focus:border-[var(--ui-primary)]"
                  />
                  <div className="flex flex-wrap gap-1 mt-1.5">
                    {['{INDEX}', '{MONTH}', '{YEAR}'].map(tag => (
                      <button key={tag} type="button" onClick={() => updateNumberingSetting('suratFormat', formatTemplate + tag)} className="text-[9px] font-bold bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded-[var(--ui-radius-small)] hover:bg-slate-200 transition-colors">
                        {tag}
                      </button>
                    ))}
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5">Nomor Urut Berikutnya</label>
                  <input 
                    type="text" 
                    inputMode="numeric"
                    value={nextIndex} 
                    onChange={e => updateNumberingSetting('suratNextIndex', parseInt(e.target.value.replace(/[^0-9]/g, '')) || 1)}
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-xs font-semibold focus:outline-none focus:border-[var(--ui-primary)]"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5">Digit Padding</label>
                  <select 
                    value={padding} 
                    onChange={e => updateNumberingSetting('suratPadding', parseInt(e.target.value) || 3)}
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-xs font-semibold focus:outline-none focus:border-[var(--ui-primary)]"
                  >
                    <option value="1">1 (e.g. 1)</option>
                    <option value="2">2 (e.g. 01)</option>
                    <option value="3">3 (e.g. 001)</option>
                    <option value="4">4 (e.g. 0001)</option>
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5">Format Bulan</label>
                  <select 
                    value={monthStyle} 
                    onChange={e => updateNumberingSetting('suratMonthStyle', e.target.value)}
                    className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-xs font-semibold focus:outline-none focus:border-[var(--ui-primary)]"
                  >
                    <option value="romawi">Romawi (e.g. VII)</option>
                    <option value="angka">Angka (e.g. 07)</option>
                  </select>
                </div>

                <div className="md:col-span-4 bg-slate-50 border border-slate-150 p-3 rounded-[var(--ui-radius-small)] flex items-center justify-between text-xs">
                  <div>
                    <span className="font-bold text-slate-500">Pratinjau Nomor Selanjutnya: </span>
                    <span className="font-black text-slate-800 font-mono bg-white px-2 py-1 border-none rounded-[var(--ui-radius-small)] ml-2">
                      {generateFormattedNumber(formatTemplate, nextIndex, padding, monthStyle)}
                    </span>
                  </div>
                </div>
              </div>
            )}
          </div>

          {suratList.length === 0 ? (
            <div className="ui-card p-10 border-dashed text-center">
              <FileText size={28} className="mx-auto text-slate-300 mb-2" />
              <p className="text-slate-500 font-medium text-sm">Tidak ada permohonan surat.</p>
            </div>
          ) : (
            <div className="space-y-3">
              {suratList.map(surat => (
                <div key={surat.id} className="ui-card p-4 flex flex-col md:flex-row gap-4 items-start justify-between">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <h3 className="font-bold text-slate-800 truncate">{surat.nama_perusahaan || surat.pt_name_temp}</h3>
                      {surat.status === "stempel_selesai"
                        ? <span className="shrink-0 text-[10px] bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-[var(--ui-radius-small)] font-bold flex items-center gap-1"><CheckCircle size={10}/> Distempel (Selesai)</span>
                        : surat.status === "acc_hubin"
                          ? <span className="shrink-0 text-[10px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-[var(--ui-radius-small)] font-bold flex items-center gap-1"><AlertCircle size={10}/> Menunggu Stempel</span>
                          : <span className="shrink-0 text-[10px] bg-amber-100 text-amber-700 px-2 py-0.5 rounded-[var(--ui-radius-small)] font-bold">Pending</span>}
                    </div>
                    <p className="text-xs text-slate-500 mb-3">
                      Diajukan: {new Date(surat.created_at).toLocaleString("id-ID", { day:"2-digit", month:"short", year:"numeric", hour:"2-digit", minute:"2-digit" })}
                    </p>
                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                      {surat.students?.map((s, i) => (
                        <div key={i} className="bg-slate-50 border-none p-2 rounded-[var(--ui-radius-small)] text-xs">
                          <span className="font-bold text-slate-700 block truncate">{s.nama}</span>
                          <span className="text-slate-400">{s.nis} – {s.kelas}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="flex flex-col gap-2 shrink-0 md:min-w-[140px]">
                    {surat.status === "pending" && !readOnly && (
                      <button
                        disabled={loading}
                        onClick={() => accSurat(surat.id)}
                        className="w-full shrink-0 bg-[var(--ui-primary)] text-white px-4 py-2 rounded-[var(--ui-radius-small)] text-sm font-bold hover:opacity-90 transition-opacity disabled:opacity-50 shadow-sm"
                      >
                        ACC & Beri Nomor
                      </button>
                    )}
                    {surat.status === "acc_hubin" && !readOnly && (
                      <button
                        disabled={loading}
                        onClick={() => validasiStempel(surat.id)}
                        className="w-full shrink-0 bg-emerald-500 text-white px-4 py-2 rounded-[var(--ui-radius-small)] text-sm font-bold hover:bg-emerald-600 transition-colors disabled:opacity-50 shadow-sm"
                      >
                        Validasi Stempel
                      </button>
                    )}
                    {!readOnly && (
                      <button disabled={loading} onClick={() => deleteSurat(surat.id)} className="w-full bg-red-100 text-red-600 font-bold py-2 rounded-[var(--ui-radius-small)] text-xs hover:bg-red-200 transition-colors disabled:opacity-50 flex items-center justify-center gap-1 mt-auto shadow-sm">
                        <Trash2 size={14} /> Hapus
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ── MUTASI TAB ── */}
      {activeTab === "mutasi" && (
        <div className="space-y-4">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            {mutasiStats.map(s => <StatCard key={s.label} {...s} />)}
          </div>

          {isHubinOrAdmin && (
            <div className="bg-[var(--ui-primary)]/10 border border-[var(--ui-primary)]/20 text-[var(--ui-primary)] p-3 rounded-[var(--ui-radius-small)] flex gap-3 text-xs font-medium">
              <AlertCircle size={16} className="shrink-0 mt-0.5" />
              <span>Sebagai HUBIN, Anda memiliki hak <strong>ACC Mutlak (Override)</strong>. Jika Anda menyetujui mutasi, status akan langsung menjadi Disetujui Final.</span>
            </div>
          )}

          {mutasiList.length === 0 ? (
            <div className="ui-card p-10 border-dashed text-center">
              <RefreshCw size={28} className="mx-auto text-slate-300 mb-2" />
              <p className="text-slate-500 font-medium text-sm">Tidak ada permohonan mutasi.</p>
            </div>
          ) : (
            <div className="space-y-3">
              {mutasiList.map(mutasi => (
                <div key={mutasi.id} className="ui-card overflow-hidden">
                  <div className="flex flex-col md:flex-row gap-0">
                    {/* Kiri: detail mutasi */}
                    <div className="flex-1 p-4">
                      <div className="mb-3">
                        <p className="font-bold text-slate-800">{mutasi.student_name}</p>
                        <p className="text-xs text-slate-500">{mutasi.nis} • Kelas {mutasi.class_name}</p>
                      </div>

                      <div className="flex items-center gap-3 bg-slate-50 p-3 rounded-[var(--ui-radius-small)] border-none mb-3">
                        <div className="flex-1 min-w-0">
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">Lokasi Lama</p>
                          <p className="font-semibold text-slate-700 text-sm leading-tight truncate">{mutasi.old_pt_name || "–"}</p>
                        </div>
                        <RefreshCw size={16} className="text-slate-300 shrink-0" />
                        <div className="flex-1 min-w-0 text-right">
                          <p className="text-[10px] font-bold text-[var(--ui-primary)] uppercase tracking-wider mb-0.5">Lokasi Baru</p>
                          <p className="font-semibold text-[var(--ui-primary)] text-sm leading-tight truncate">{mutasi.new_pt_name || mutasi.new_pt_name_temp}</p>
                        </div>
                      </div>

                      <div>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">Alasan Pindah</p>
                        <p className="text-xs text-slate-700 italic bg-amber-50 p-2.5 rounded-[var(--ui-radius-small)] border border-amber-100">"{mutasi.alasan}"</p>
                      </div>
                    </div>

                    {/* Kanan: status approval */}
                    <div className="w-full md:w-56 shrink-0 bg-slate-50 border-t md:border-t-0 md:border-l border-slate-200 p-4 flex flex-col justify-between">
                      <div>
                        <p className="text-[10px] font-black text-slate-600 uppercase tracking-wider text-center border-b border-slate-200 pb-2 mb-3">Status Persetujuan</p>

                        {mutasi.final_status === 'acc' ? (
                          <div className="bg-emerald-100 text-emerald-800 p-2.5 rounded-[var(--ui-radius-small)] text-center font-bold text-sm mb-3">
                            <CheckCircle size={20} className="mx-auto mb-1 opacity-80" />
                            Disetujui Final
                          </div>
                        ) : mutasi.final_status === 'rejected' ? (
                          <div className="bg-red-100 text-red-800 p-2.5 rounded-[var(--ui-radius-small)] text-center font-bold text-sm mb-3">
                            <XCircle size={20} className="mx-auto mb-1 opacity-80" />
                            Ditolak Final
                          </div>
                        ) : (
                          <div className="space-y-1.5 mb-3">
                            {[
                              { label: 'Wali Kelas', val: mutasi.acc_walas },
                              { label: 'Pembimbing', val: mutasi.acc_pembimbing },
                              { label: 'Kaprog',     val: mutasi.acc_kaprog },
                              { label: 'HUBIN',      val: mutasi.acc_hubin, highlight: true },
                            ].map(({ label, val, highlight }) => (
                              <div key={label} className="flex justify-between items-center text-xs font-semibold">
                                <span className={highlight ? 'text-[var(--ui-primary)]' : 'text-slate-600'}>{label}</span>
                                {val === 'acc'      ? <CheckCircle size={14} className="text-emerald-500" />
                                : val === 'rejected' ? <XCircle size={14} className="text-red-500" />
                                :                     <span className="text-slate-300 text-[10px]">Pending</span>}
                              </div>
                            ))}
                          </div>
                        )}
                      </div>

                      <div className="flex flex-col gap-2 shrink-0 md:mt-0 md:min-w-[120px]">
                        {mutasi.final_status === 'pending' && !readOnly && (
                          <>
                            <button
                              disabled={loading}
                              onClick={() => accMutasi(mutasi.id, 'acc')}
                              className="w-full bg-emerald-500 text-white font-bold py-2 rounded-[var(--ui-radius-small)] text-xs hover:bg-emerald-600 transition-colors disabled:opacity-50 shadow-sm"
                            >
                              ACC
                            </button>
                            <button
                              disabled={loading}
                              onClick={() => accMutasi(mutasi.id, 'rejected')}
                              className="w-full bg-amber-500 text-white font-bold py-2 rounded-[var(--ui-radius-small)] text-xs hover:bg-amber-600 transition-colors disabled:opacity-50 shadow-sm"
                            >
                              Tolak
                            </button>
                          </>
                        )}
                        {!readOnly && (
                          <button disabled={loading} onClick={() => deleteMutasi(mutasi.id)} className="w-full bg-red-100 text-red-600 font-bold py-2 rounded-[var(--ui-radius-small)] text-xs hover:bg-red-200 transition-colors disabled:opacity-50 flex items-center justify-center gap-1 mt-auto shadow-sm">
                            <Trash2 size={14} /> Hapus
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ── KUNJUNGAN GURU TAB ── */}
      {activeTab === "kunjungan" && (
        <div className="ui-card p-6 space-y-4">
          <h2 className="font-bold text-slate-800 text-lg flex items-center gap-2">
            <MapPin className="text-[var(--ui-primary)]" /> Riwayat Kunjungan Guru PKL
          </h2>
          <p className="text-sm text-slate-500">Data hasil tracking GPS dan foto kunjungan guru ke perusahaan tempat siswa PKL.</p>

          <div className="overflow-x-auto mt-4">
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-4 py-3 font-bold">Waktu</th>
                  <th className="px-4 py-3 font-bold">Nama Guru</th>
                  <th className="px-4 py-3 font-bold">Lokasi GPS</th>
                  <th className="px-4 py-3 font-bold">Radius (m)</th>
                  <th className="px-4 py-3 font-bold">Catatan</th>
                  <th className="px-4 py-3 font-bold">Foto</th>
                </tr>
              </thead>
              <tbody>
                <tr className="border-b border-slate-100 hover:bg-slate-50/50">
                  <td className="px-4 py-3">{new Date().toLocaleString('id-ID')}</td>
                  <td className="px-4 py-3 font-bold text-slate-700">Ahmad Guru</td>
                  <td className="px-4 py-3 text-xs font-mono text-slate-500">-6.234839, 106.989254</td>
                  <td className="px-4 py-3 font-bold text-emerald-600">12m <span className="text-[10px] bg-emerald-100 px-1 rounded-[var(--ui-radius-small)]">Valid</span></td>
                  <td className="px-4 py-3 text-slate-600">Siswa berkinerja baik.</td>
                  <td className="px-4 py-3">
                    <button className="flex items-center gap-1 text-xs font-bold text-[var(--ui-primary)] bg-[var(--ui-primary)]/10 px-2 py-1 rounded-[var(--ui-radius-small)]">
                      <Camera size={12}/> Lihat Foto
                    </button>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ACC & Beri Nomor Modal */}
      <Modal 
        isOpen={accModal.isOpen} 
        onClose={() => setAccModal({ isOpen: false, suratId: null, formattedNumber: "" })} 
        title="ACC & Beri Nomor Surat Pengantar"
        maxWidth="max-w-md"
      >
        <form onSubmit={handleAccConfirm} className="space-y-4">
          <div className="bg-[var(--ui-primary)]/5 p-4 rounded-[var(--ui-radius-small)] border border-[var(--ui-primary)]/10 text-center">
            <p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">Nomor Surat Pengantar Otomatis</p>
            <p className="text-lg font-black text-[var(--ui-primary)] font-mono">{accModal.formattedNumber}</p>
          </div>

          <div className="space-y-1.5">
            <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest">Sesuaikan Nomor Surat (Opsional)</label>
            <input 
              type="text" 
              required
              value={accModal.formattedNumber} 
              onChange={e => setAccModal(prev => ({ ...prev, formattedNumber: e.target.value }))}
              className="w-full px-3 py-2.5 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-xs font-black text-slate-800 focus:outline-none focus:border-[var(--ui-primary)] focus:bg-white"
            />
            <p className="text-[10px] text-slate-400">Anda dapat mengubah nomor di atas secara manual jika terdapat pengecualian.</p>
          </div>

          <div className="flex justify-end gap-2 pt-2">
            <Button 
              type="button" 
              variant="secondary" 
              onClick={() => setAccModal({ isOpen: false, suratId: null, formattedNumber: "" })}
              disabled={loading}
            >
              Batalkan
            </Button>
            <Button 
              type="submit" 
              variant="primary"
              disabled={loading || !accModal.formattedNumber}
            >
              {loading ? "Memproses..." : "ACC & Simpan"}
            </Button>
          </div>
        </form>
      </Modal>

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
};

export default KelolaAdministrasiPKL;

import { useState, useMemo, useEffect } from "react";
import { FileBarChart2, FileSpreadsheet, Calendar } from "lucide-react";
import * as XLSX from "xlsx";
import useAuthStore from "../../../store/monitoring/authStore";
import { Search, Filter, Download, Trash2, CheckCircle2, Clock, ChevronLeft, ChevronRight, AlertCircle } from 'lucide-react';
import { PageHeader } from '../../../components/monitoring/ui/index.js';


/**
 * admin/LaporanAdmin.jsx
 * Halaman laporan — ekspor data kehadiran & jurnal per periode.
 * Dilengkapi dengan pagination (20 per halaman) dan pencarian.
 */






const LAPORAN_TYPES = [
  { key: "kehadiran", label: "Laporan Kehadiran", desc: "Rekap hadir/absen/izin per siswa", icon: Calendar },
  { key: "jurnal",    label: "Laporan Jurnal",    desc: "Daftar jurnal harian beserta status validasi", icon: FileBarChart2 },
  { key: "rekap_guru", label: "Rekap per Guru",   desc: "Statistik bimbingan per guru pembimbing", icon: FileSpreadsheet },
];

const PAGE_SIZE = 20;

const LaporanAdmin = ({ students = [], teachers = [] }) => {
  const user = useAuthStore(state => state.user);
  const isAdmin = user?.role === "admin" || user?.role === "superadmin";
  const [selectedType, setSelectedType] = useState("kehadiran");
  const [filterJurusan, setFilterJurusan] = useState("Semua");
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [generating, setGenerating] = useState(false);
  const [pklStudentsMapping, setPklStudentsMapping] = useState([]);
  const [dataJurnal, setDataJurnal] = useState([]);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = "success") => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  // Reset page saat tab/filter/search berubah
  useEffect(() => { setCurrentPage(1); }, [selectedType, filterJurusan, searchTerm]);

  useEffect(() => {
    const token = JSON.parse(sessionStorage.getItem("school_schedule_session_v1"))?.authToken;
    // Fetch logbooks
    fetch("/api/pkl/logbooks", { headers: { Authorization: `Bearer ${token}` } })
    .then(res => res.json()).then(data => { if(data.ok) setDataJurnal(data.data); }).catch(() => {});

    fetch("/api/monitoring/pkl-students", { headers: { Authorization: `Bearer ${token}` } })
    .then(res => res.json()).then(data => { if (data.ok && data.data) setPklStudentsMapping(data.data); }).catch(() => {});
  }, []);

  const mappedSiswa = useMemo(() => {
    return pklStudentsMapping.map(m => {
      const baseStudent = students.find(s => s.nis === m.nis) || {};
      return {
        ...m,
        nama: baseStudent.name || '-',
        kelas: baseStudent.class_name || '-',
        jurusan: baseStudent.class_name ? baseStudent.class_name.split(' ')[1] : 'Umum',
        totalHadir: m.total_hadir || 0,
        totalAbsen: m.total_absen || 0,
        totalIzin: m.total_izin || 0,
        totalSakit: m.total_sakit || 0,
        totalHariKerja: (m.total_hadir || 0) + (m.total_absen || 0) + (m.total_izin || 0) + (m.total_sakit || 0),
        persenKehadiran: ((m.total_hadir || 0) + (m.total_absen || 0) + (m.total_izin || 0) + (m.total_sakit || 0)) > 0
          ? Math.round(((m.total_hadir || 0) / ((m.total_hadir || 0) + (m.total_absen || 0) + (m.total_izin || 0) + (m.total_sakit || 0))) * 100)
          : 0,
        guruPembimbingId: m.teacher_code
      };
    });
  }, [pklStudentsMapping, students]);


  const handleDeleteLog = async (nis) => {
    if(await window.confirmAsync('Yakin ingin menghapus data PKL siswa ini? Data absensi dan log akan ikut terhapus.')) {
      setPklStudentsMapping(prev => prev.filter(s => s.nis !== nis));
      const token = JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken;
      try {
        const res = await fetch('/api/pkl/students/' + nis, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        if (res.ok) showToast("Data PKL siswa berhasil dihapus.");
        else showToast("Gagal menghapus data PKL.", "error");
      } catch {
        showToast("Terjadi kesalahan sistem.", "error");
      }
    }
  };

  const handleExport = async () => {
    setGenerating(true);
    await new Promise(r => setTimeout(r, 800));

    let wb = XLSX.utils.book_new();
    let ws, sheetName;

    if (selectedType === 'kehadiran') {
      const rows = mappedSiswa
        .filter(s => filterJurusan === 'Semua' || s.jurusan === filterJurusan)
        .map(s => ({
          'NIS': s.nis,
          'Nama Siswa': s.nama,
          'Kelas': s.kelas,
          'Jurusan': s.jurusan,
          'Total Hadir': s.totalHadir,
          'Total Absen': s.totalAbsen,
          'Total Izin': s.totalIzin,
          'Total Hari Kerja': s.totalHariKerja,
          'Persentase Kehadiran': `${s.persenKehadiran}%`,
        }));
      ws = XLSX.utils.json_to_sheet(rows);
      sheetName = 'Laporan Kehadiran';
    } else if (selectedType === 'jurnal') {
      const rows = dataJurnal.map(j => {
        const s = mappedSiswa.find(x => x.nis === j.student_nis);
        return {
          'Nama Siswa': s?.nama || '-',
          'Kelas': s?.kelas || '-',
          'Tanggal': j.date,
          'Kegiatan': j.activity,
          'Kendala': j.problems,
          'Solusi': j.solutions,
          'Jam Masuk': j.time_in,
          'Jam Keluar': j.time_out,
          'Status': j.status,
          'Catatan Guru': j.notes || '-',
        };
      });
      ws = XLSX.utils.json_to_sheet(rows);
      sheetName = 'Laporan Jurnal';
    } else {
      const rows = teachers.map(g => {
        const siswaGuru = mappedSiswa.filter(s => s.guruPembimbingId === g.code);
        const rataHadir = siswaGuru.length
          ? (siswaGuru.reduce((a, s) => a + s.persenKehadiran, 0) / siswaGuru.length).toFixed(1)
          : '-';
        return {
          'Nama Guru': g.name,
          'Jurusan': g.preferredMajor,
          'Kategori': g.type,
          'Jumlah Siswa Bimbingan': siswaGuru.length,
          'Rata-rata Kehadiran Siswa': rataHadir + (rataHadir !== '-' ? '%' : ''),
        };
      });
      ws = XLSX.utils.json_to_sheet(rows);
      sheetName = 'Rekap Per Guru';
    }

    XLSX.utils.book_append_sheet(wb, ws, sheetName);
    XLSX.writeFile(wb, `PKL_${sheetName.replace(/\s/g, '_')}_${new Date().toISOString().slice(0,10)}.xlsx`);
    setGenerating(false);
  };  const jurusanOptions = useMemo(() => {
    return ["Semua", ...Array.from(new Set(mappedSiswa.map(s => s.jurusan))).filter(Boolean)];
  }, [mappedSiswa]);

  // === Filter + Pagination ===
  const filteredSiswa = useMemo(() => {
    let data = mappedSiswa.filter(s => filterJurusan === "Semua" || s.jurusan === filterJurusan);
    if (searchTerm.trim()) {
      const q = searchTerm.toLowerCase();
      data = data.filter(s => s.nama?.toLowerCase().includes(q) || String(s.nis).includes(q));
    }
    return data;
  }, [mappedSiswa, filterJurusan, searchTerm]);

  const filteredJurnal = useMemo(() => {
    let data = dataJurnal.filter(j => {
      const s = mappedSiswa.find(x => x.nis === j.student_nis);
      return filterJurusan === "Semua" || (s && s.jurusan === filterJurusan);
    });
    if (searchTerm.trim()) {
      const q = searchTerm.toLowerCase();
      data = data.filter(j => {
        const s = mappedSiswa.find(x => x.nis === j.student_nis);
        return s?.nama?.toLowerCase().includes(q) ||
          (j.activity || j.kegiatan || "").toLowerCase().includes(q);
      });
    }
    return data;
  }, [dataJurnal, mappedSiswa, filterJurusan, searchTerm]);

  const filteredGuru = useMemo(() => {
    let data = teachers.filter(g => filterJurusan === "Semua" || g.preferredMajor === filterJurusan || g.preferredMajor === "Semua");
    if (searchTerm.trim()) {
      const q = searchTerm.toLowerCase();
      data = data.filter(g => g.name?.toLowerCase().includes(q));
    }
    return data;
  }, [teachers, filterJurusan, searchTerm]);

  // Aktif dataset berdasarkan tab
  const activeData = selectedType === "kehadiran" ? filteredSiswa
    : selectedType === "jurnal" ? filteredJurnal
    : filteredGuru;

  const totalPages = Math.max(1, Math.ceil(activeData.length / PAGE_SIZE));
  const safePage = Math.min(currentPage, totalPages);
  const pagedData = activeData.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  // Legacy aliases untuk render
  const previewSiswa = selectedType === "kehadiran" ? pagedData : [];
  const previewJurnal = selectedType === "jurnal" ? pagedData : [];
  const previewGuru = selectedType === "rekap_guru" ? pagedData : [];

  const tabs = LAPORAN_TYPES.map(t => ({
    id: t.key,
    label: t.label,
    icon: t.icon
  }));

  return (
    <div className="space-y-6 animate-fade-in">
      <PageHeader
        icon={FileBarChart2}
        title="Monitoring PKL"
        description="Pantau aktivitas, absensi, lokasi, dan laporan."
        tabs={tabs}
        activeTab={selectedType}
        onTabChange={setSelectedType}
      />

      <div className="flex flex-col 2xl:flex-row gap-6 w-full items-start">
        {/* Left Sidebar */}
        <div className="w-full 2xl:w-64 flex-shrink-0 flex flex-col space-y-4">
          <div className="ui-card overflow-hidden">
            <div className="p-4 border-b border-slate-100 bg-slate-50/50">
              <h3 className="font-bold text-slate-800 text-sm">Filter Data</h3>
            </div>
            <div className="p-4 space-y-4">
              {/* Search */}
              <div>
                <label className="flex items-center gap-2 text-xs font-semibold text-slate-600 mb-2">
                  <Search size={14} /> Cari
                </label>
                <div className="relative">
                  <Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    type="text"
                    placeholder={selectedType === "rekap_guru" ? "Nama guru..." : "Nama / NIS..."}
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="w-full pl-8 pr-3 py-2 text-xs rounded-lg border border-slate-200 bg-white focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)]/30"
                  />
                </div>
              </div>
              {/* Jurusan filter */}
              <div>
                <label className="flex items-center gap-2 text-xs font-semibold text-slate-600 mb-2">
                  <Filter size={14} /> Jurusan
                </label>
                <div className="flex flex-wrap gap-2">
                  {jurusanOptions.map(j => (
                    <button key={j} onClick={() => setFilterJurusan(j)}
                      className={`px-3 py-1.5 text-xs font-semibold rounded-[var(--ui-radius-small)] transition-all ${
                        filterJurusan === j
                        ? "bg-slate-800 text-white shadow-sm"
                        : "bg-white border-none text-slate-600 hover:border-slate-400"
                      }`}>{j}</button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="flex-1 bg-slate-50 border-none rounded-[var(--ui-radius-small)] p-5 flex flex-col justify-center items-center text-center opacity-80 min-h-[120px]">
            <h4 className="font-bold text-slate-800 text-sm mb-1">Total: {activeData.length} data</h4>
            <p className="text-xs text-slate-500">Hal {safePage} dari {totalPages}</p>
          </div>
        </div>

      {/* Right Content: Preview */}
      <div className="ui-card flex-1 flex flex-col">
          <div className="px-5 py-4 border-b border-slate-200 flex items-center justify-between bg-white z-10 shrink-0">
            <div>
              <h2 className="font-bold text-slate-800 text-lg">Pratinjau Data</h2>
              <p className="text-xs text-slate-400 mt-0.5">
                {activeData.length} {selectedType === "kehadiran" ? "siswa" : selectedType === "jurnal" ? "jurnal" : "guru"}
                {activeData.length > PAGE_SIZE && ` — hal ${safePage}/${totalPages}`}
              </p>
            </div>
          <button onClick={handleExport} disabled={generating}
            className="px-4 py-2 bg-emerald-600 hover:opacity-90 text-white text-sm font-semibold rounded-[var(--ui-radius-small)] transition-all flex items-center gap-1.5 disabled:opacity-60 disabled:cursor-not-allowed">
            {generating ? <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Download size={16} />}
            {generating ? 'Memproses...' : 'Ekspor Excel'}
          </button>
        </div>

        <div className="flex-1 overflow-auto custom-scrollbar">
          {selectedType === 'kehadiran' && (
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-slate-50 shadow-sm z-10">
                <tr className="text-[11px] font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200">
                  <th className="px-5 py-3 text-left font-bold">Siswa</th>
                  <th className="px-5 py-3 text-center font-bold">Hadir</th>
                  <th className="px-5 py-3 text-center font-bold">Izin / Sakit</th>
                  <th className="px-5 py-3 text-center font-bold">Alpa</th>
                  <th className="px-5 py-3 text-center font-bold">Persentase</th>
                  {isAdmin && <th className="px-5 py-3 text-center font-bold">Aksi</th>}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {previewSiswa.length === 0 ? (
                  <tr><td colSpan={isAdmin ? 6 : 5} className="px-5 py-8 text-center text-slate-400 text-sm">Tidak ada data siswa untuk jurusan ini.</td></tr>
                ) : previewSiswa.map(s => (
                  <tr key={s.nis} className="hover:bg-slate-50/50 border-b border-slate-50 last:border-0">
                    <td className="px-5 py-3">
                      <p className="font-bold text-slate-800">{s.nama}</p>
                      <p className="text-xs text-slate-500 mt-0.5">{s.nis} - {s.kelas}</p>
                    </td>
                    <td className="px-5 py-3 text-center font-bold text-emerald-600">{s.totalHadir || 0}</td>
                    <td className="px-5 py-3 text-center font-bold text-amber-500">{(s.totalIzin || 0) + (s.totalSakit || 0)}</td>
                    <td className="px-5 py-3 text-center font-bold text-red-500">{s.totalAbsen || 0}</td>
                    <td className="px-5 py-3 text-center">
                      <span className={`px-2 py-1 rounded-[var(--ui-radius-small)] text-xs font-bold ${s.persenKehadiran >= 80 ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                        {s.persenKehadiran || 0}%
                      </span>
                    </td>
                    {isAdmin && (
                      <td className="px-5 py-3 text-center">
                        <button onClick={() => handleDeleteLog(s.nis)} className="p-1.5 text-red-600 hover:bg-red-50 rounded-[var(--ui-radius-small)] transition-colors inline-flex items-center justify-center cursor-pointer">
                          <Trash2 size={14} />
                        </button>
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          {selectedType === 'jurnal' && (
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-slate-50 shadow-sm z-10">
                <tr className="text-[11px] font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200">
                  <th className="px-5 py-3 text-left font-bold">Tanggal</th>
                  <th className="px-5 py-3 text-left font-bold">Siswa</th>
                  <th className="px-5 py-3 text-left font-bold">Kegiatan</th>
                  <th className="px-5 py-3 text-center font-bold">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {previewJurnal.length === 0 ? (
                  <tr><td colSpan="4" className="px-5 py-8 text-center text-slate-400 text-sm">Tidak ada data jurnal.</td></tr>
                ) : previewJurnal.map(j => {
                  const s = mappedSiswa.find(x => x.nis === j.student_nis) || {};
                  return (
                    <tr key={j.id} className="hover:bg-slate-50/50 border-b border-slate-50 last:border-0">
                      <td className="px-5 py-3 text-xs font-medium text-slate-600 whitespace-nowrap">{j.date || j.tanggal}</td>
                      <td className="px-5 py-3">
                        <p className="font-bold text-slate-800">{s.nama || 'Siswa Unknown'}</p>
                        <p className="text-xs text-slate-500">{s.kelas || '-'}</p>
                      </td>
                      <td className="px-5 py-3 text-xs text-slate-700 line-clamp-2 max-w-xs">{j.activity || j.kegiatan}</td>
                      <td className="px-5 py-3 text-center">
                        {j.status === 'approved' ? (
                           <span className="inline-flex items-center gap-1 px-2 py-1 bg-emerald-100 text-emerald-700 rounded-[var(--ui-radius-small)] text-[10px] font-bold"><CheckCircle2 size={12}/> Acc</span>
                        ) : j.status === 'pending' ? (
                           <span className="inline-flex items-center gap-1 px-2 py-1 bg-amber-100 text-amber-700 rounded-[var(--ui-radius-small)] text-[10px] font-bold"><Clock size={12}/> Pending</span>
                        ) : (
                           <span className="inline-flex items-center gap-1 px-2 py-1 bg-slate-100 text-slate-700 rounded-[var(--ui-radius-small)] text-[10px] font-bold">Review</span>
                        )}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          )}

          {selectedType === 'rekap_guru' && (
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-slate-50 shadow-sm z-10">
                <tr className="text-[11px] font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200">
                  <th className="px-5 py-3 text-left font-bold">Guru Pembimbing</th>
                  <th className="px-5 py-3 text-left font-bold">Jurusan</th>
                  <th className="px-5 py-3 text-center font-bold">Siswa Bimbingan</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {previewGuru.length === 0 ? (
                  <tr><td colSpan="3" className="px-5 py-8 text-center text-slate-400 text-sm">Tidak ada data guru pembimbing.</td></tr>
                ) : previewGuru.map(g => {
                  const siswaBimbingan = mappedSiswa.filter(s => s.guruPembimbingId === g.code).length;
                  return (
                    <tr key={g.code} className="hover:bg-slate-50/50 border-b border-slate-50 last:border-0">
                      <td className="px-5 py-3 font-bold text-slate-800 flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-xs uppercase">{g.name?.substring(0,2) || 'G'}</div>
                        {g.name}
                      </td>
                      <td className="px-5 py-3 text-xs font-semibold text-slate-600">{g.preferredMajor}</td>
                      <td className="px-5 py-3 text-center">
                        <span className="inline-flex items-center justify-center min-w-[2rem] px-1.5 py-0.5 bg-blue-50 text-blue-600 rounded-[var(--ui-radius-small)] text-xs font-bold border border-blue-100">
                          {siswaBimbingan}
                        </span>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          )}
        </div>

        {/* Pagination Controls */}
        {totalPages > 1 && (
          <div className="px-5 py-3 border-t border-slate-100 bg-white flex items-center justify-between gap-4 shrink-0">
            <p className="text-xs text-slate-500">
              {(safePage - 1) * PAGE_SIZE + 1}–{Math.min(safePage * PAGE_SIZE, activeData.length)} dari {activeData.length} data
            </p>
            <div className="flex items-center gap-2">
              <button
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={safePage <= 1}
                className="p-1.5 rounded-lg border border-slate-200 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronLeft size={16} className="text-slate-600" />
              </button>
              <span className="text-xs font-bold text-slate-700 px-2">{safePage} / {totalPages}</span>
              <button
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={safePage >= totalPages}
                className="p-1.5 rounded-lg border border-slate-200 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronRight size={16} className="text-slate-600" />
              </button>
            </div>
          </div>
        )}
      </div>
      </div>
      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
};

export default LaporanAdmin;

import { useState, useMemo, useEffect, useRef } from 'react';
import { UserCheck, Wand2, Users, CheckCircle2, AlertTriangle, Building2 } from 'lucide-react';
import usePenugasanStore from '../../../store/monitoring/penugasanStore';
import useAuthStore from '../../../store/monitoring/authStore';
import { getDatabaseSnapshot } from '../../../utils/dataSource';
import { ChevronDown, Info, Search, X, Badge, Edit2, ChevronLeft, ChevronRight } from 'lucide-react';
import { PageHeader, StatCard, Avatar } from '../../../components/monitoring/ui/index.js';


/**
 * admin/PenugasanGuru.jsx
 * HUBIN menugaskan guru ke siswa ?" manual atau auto-assign.
 * Tampilan dikelompokkan per Perusahaan/Lokasi untuk kemudahan Bulk Assign.
 */












const ClickPicker = ({ value, onChange, options, placeholder = "Pilih..." }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const ref = useRef(null);

  useEffect(() => {
    const handleOutsideClick = (e) => {
      if (ref.current && !ref.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, []);

  const filteredOptions = options.filter(opt => 
    opt.label.toLowerCase().includes(search.toLowerCase())
  );

  const selectedOpt = options.find(o => String(o.value) === String(value));

  return (
    <div className="relative" ref={ref}>
      <button
        type="button"
        onClick={() => { setIsOpen(!isOpen); setSearch(''); }}
        className="w-full text-left px-3 py-2 border-none bg-slate-50 hover:bg-white rounded-[var(--ui-radius-small)] text-xs font-bold flex justify-between items-center transition-colors focus:outline-[var(--ui-primary)] cursor-pointer"
      >
        <span className={selectedOpt ? "text-slate-800 font-bold" : "text-slate-400"}>
          {selectedOpt ? selectedOpt.label : placeholder}
        </span>
        <ChevronDown size={14} className="text-slate-400" />
      </button>

      {isOpen && (
        <div className="absolute z-[60] mt-1 w-full bg-white border-none rounded-[var(--ui-radius-small)] shadow-sm max-h-60 overflow-hidden flex flex-col">
          <div className="p-2 border-b border-slate-100 bg-slate-50 shrink-0">
            <input
              type="text"
              autoFocus
              placeholder="Cari..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full px-2.5 py-1.5 text-xs border-none rounded-[var(--ui-radius-small)] focus:outline-none focus:ring-1 focus:ring-[var(--ui-primary)] focus:border-[var(--ui-primary)]"
            />
          </div>
          <div className="overflow-y-auto flex-1 py-1 custom-scrollbar">
            {filteredOptions.length === 0 ? (
              <div className="px-3 py-2 text-xs text-slate-400 text-center">Tidak ditemukan</div>
            ) : (
              filteredOptions.map(opt => (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => {
                    onChange(opt.value);
                    setIsOpen(false);
                  }}
                  className={`w-full text-left px-3 py-2 text-xs font-semibold hover:bg-slate-50 transition-colors flex items-center justify-between border-none cursor-pointer ${
                    String(opt.value) === String(value) ? 'bg-[var(--ui-primary)]/5 text-[var(--ui-primary)] font-bold' : 'text-slate-700 bg-transparent'
                  }`}
                >
                  <span>{opt.label}</span>
                  {String(opt.value) === String(value) && (
                    <span className="w-1.5 h-1.5 rounded-[var(--ui-radius-small)] bg-[var(--ui-primary)]"></span>
                  )}
                </button>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const PenugasanGuru = ({ teachers = [], students = [], readOnly }) => {
  const [locations, setLocations] = useState([]);
  const [editingRows, setEditingRows] = useState(new Set());
  const [selectedStudents, setSelectedStudents] = useState(new Set());
  const authToken = useAuthStore(state => state.user?.authToken);
  const [eligibleClass, setEligibleClass] = useState("XII");

  useEffect(() => {
    // Load eligibleClass from local appSettings
    const localSnapshot = getDatabaseSnapshot() || {};
    const localSettings = localSnapshot.appSettings || {};
    setEligibleClass(localSettings.eligibleClass || "XII");
  }, [authToken]);

  const toggleSelectStudent = (siswaId) => {
    setSelectedStudents(prev => {
      const next = new Set(prev);
      if (next.has(siswaId)) next.delete(siswaId);
      else next.add(siswaId);
      return next;
    });
  };

  const toggleSelectAll = (locId) => {
    const studentsInCompany = studentsByCompany[locId] || [];
    const allSelected = studentsInCompany.length > 0 && studentsInCompany.every(s => selectedStudents.has(s.uniqueId));

    setSelectedStudents(prev => {
      const next = new Set(prev);
      studentsInCompany.forEach(s => {
        if (allSelected) next.delete(s.uniqueId);
        else next.add(s.uniqueId);
      });
      return next;
    });
  };

  const {
    assignments, getSiswaUnassigned, getLoadPerGuru, getSisaKapasitas,
    kapasitasGuru, assignManual, unassign, generateAutoAssign, applyPreview, cancelPreview,
    previewAssignments, autoAssignResult,
  } = usePenugasanStore();


  const [activeTab, setActiveTab]       = useState('manual');
  const [autoMode, setAutoMode]         = useState('incremental');
  const [confirmDialog, setConfirmDialog] = useState(null);

  // Filtering & Search state
  const [searchQuery, setSearchQuery] = useState('');
  const [filterKelas, setFilterKelas] = useState('Semua');
  const [filterJurusan, setFilterJurusan] = useState('Semua');

  // Pagination state
  const [pages, setPages] = useState({}); // { [locId]: currentPage }
  const ITEMS_PER_PAGE = 10;

  const [config, setConfig] = useState({
    prioritasWaliKelas: true,
    pemerataanArea: true,
    kapasitasGlobal: 5
  });

  // Map student fields properly from DB format
  const mappedStudents = useMemo(() => {
    return students.filter(s => {
      const kelasStr = s.kelas || s.class_name || '';
      return kelasStr.toUpperCase().startsWith(eligibleClass.toUpperCase());
    }).map(s => {
      const kelasStr = s.kelas || s.class_name || '';
      const jurusanStr = s.jurusan || s.major || (kelasStr.includes(' ') ? kelasStr.split(' ')[1] : 'Umum');
      return {
        ...s,
        uniqueId: s.id || s.nis, // Fallback to NIS if ID is undefined
        namaFix: s.nama || s.name || '',
        kelasFix: kelasStr,
        jurusanFix: jurusanStr,
      };
    });
  }, [students, eligibleClass]);

  const load      = getLoadPerGuru(teachers);
  const sisaKap   = getSisaKapasitas(teachers);
  const unassigned = mappedStudents.filter(s => !assignments[s.uniqueId]);

  // Fetch locations once
  useEffect(() => {
    fetch('/api/pkl/locations')
      .then(res => res.json())
      .then(res => { if (res.ok) setLocations(res.data); })
      .catch(console.error);
  }, []);

  const handleAutoGenerate = () => {
    const hasExisting = Object.keys(assignments).length > 0;
    if (autoMode === 'full' && hasExisting) {
      setConfirmDialog('full');
      return;
    }
    generateAutoAssign(teachers, mappedStudents, locations, {}, config, autoMode);
  };

  const handleApply = () => {
    applyPreview();
    setConfirmDialog(null);
  };

  // Options for filter
  const kelasOptions = useMemo(() => ['Semua', ...Array.from(new Set(mappedStudents.map(s => s.kelasFix))).filter(Boolean)], [mappedStudents]);
  const jurusanOptions = useMemo(() => ['Semua', ...Array.from(new Set(mappedStudents.map(s => s.jurusanFix))).filter(Boolean)], [mappedStudents]);

  // Filter students based on search/filters
  const filteredStudents = useMemo(() => {
    return mappedStudents.filter(s => {
      const matchSearch = s.namaFix.toLowerCase().includes(searchQuery.toLowerCase()) || (s.nis && String(s.nis).includes(searchQuery));
      const matchKelas = filterKelas === 'Semua' || s.kelasFix === filterKelas;
      const matchJurusan = filterJurusan === 'Semua' || s.jurusanFix === filterJurusan;
      return matchSearch && matchKelas && matchJurusan;
    });
  }, [mappedStudents, searchQuery, filterKelas, filterJurusan]);

  // Group filtered students by perusahaan
  const studentsByCompany = useMemo(() => {
    const groups = {};
    filteredStudents.forEach(s => {
      const locId = s.perusahaanId || s.lokasiId || 'unassigned';
      if (!groups[locId]) groups[locId] = [];
      groups[locId].push(s);
    });
    return groups;
  }, [filteredStudents]);

  const setPage = (locId, pageNum) => {
    setPages(prev => ({ ...prev, [locId]: pageNum }));
  };

  const handleBulkAssign = (locId, guruId) => {
    if (!guruId) return;
    const studentsInCompany = studentsByCompany[locId] || [];
    const selectedInCompany = studentsInCompany.filter(s => selectedStudents.has(s.uniqueId));
    const targetStudents = selectedInCompany.length > 0 ? selectedInCompany : studentsInCompany;

    targetStudents.forEach(s => {
      assignManual(s.uniqueId, guruId);
    });

    if (selectedInCompany.length > 0) {
      setSelectedStudents(prev => {
        const next = new Set(prev);
        selectedInCompany.forEach(s => next.delete(s.uniqueId));
        return next;
      });
    }
  };

  const handleDeleteSelected = (locId) => {
    const studentsInCompany = studentsByCompany[locId] || [];
    const selectedInCompany = studentsInCompany.filter(s => selectedStudents.has(s.uniqueId));
    selectedInCompany.forEach(s => unassign(s.uniqueId));

    setSelectedStudents(prev => {
      const next = new Set(prev);
      selectedInCompany.forEach(s => next.delete(s.uniqueId));
      return next;
    });
  };

  // Optimize Teacher Options by memoizing them per major
  const teacherOptionsCache = useMemo(() => {
    const cache = {};
    jurusanOptions.forEach(major => {
      if (major === 'Semua') return;

      const options = teachers.map(g => {
        const isMatch = major && (g.jurusan || g.major || g.preferredMajor) === major;
        return {
          value: String(g.code),
          label: `${g.nama || g.name} ${isMatch ? '(Rekomendasi)' : ''} - (${load[g.code] || 0}/${kapasitasGuru[g.code] || 5})`,
          disabled: (sisaKap[g.code] || 5) <= 0,
          isMatch
        };
      });

      options.sort((a, b) => b.isMatch - a.isMatch);
      cache[major] = [{ value: "", label: "-- Pilih Guru --" }, ...options];
    });

    // Default fallback when major is undefined or not in cache
    const defaultOptions = teachers.map(g => ({
      value: String(g.code),
      label: `${g.nama || g.name} - (${load[g.code] || 0}/${kapasitasGuru[g.code] || 5})`,
      disabled: (sisaKap[g.code] || 5) <= 0,
      isMatch: false
    }));
    cache['default'] = [{ value: "", label: "-- Pilih Guru --" }, ...defaultOptions];

    return cache;
  }, [teachers, jurusanOptions, load, kapasitasGuru, sisaKap]);

  const getTeacherOptions = (targetJurusan) => {
    if (!targetJurusan || !teacherOptionsCache[targetJurusan]) return teacherOptionsCache['default'];
    return teacherOptionsCache[targetJurusan];
  };

  const stats = [
    { label: 'Total Siswa', value: mappedStudents.length, icon: Users, iconBg: 'bg-[var(--ui-primary)]/10', iconColor: 'text-[var(--ui-primary)]' },
    { label: 'Sudah Ditugaskan', value: mappedStudents.length - unassigned.length, icon: CheckCircle2, iconBg: 'bg-emerald-100', iconColor: 'text-emerald-600' },
    { label: 'Belum Ditugaskan', value: unassigned.length, icon: AlertTriangle, iconBg: 'bg-amber-100', iconColor: 'text-amber-600' },
  ];

  const tabs = [
    { id: 'manual', label: 'Berdasarkan Perusahaan', icon: Building2 },
    ...(readOnly ? [] : [{ id: 'auto', label: 'Auto-Assign', icon: Wand2 }]),
  ];

  return (
    <div className="space-y-4">
      <PageHeader 
        icon={UserCheck}
        title="Penugasan Guru Pembimbing"
        description="Tugaskan guru ke siswa secara manual per perusahaan atau otomatis."
        tabs={tabs}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      />

      <div className="grid grid-cols-3 gap-3">
        {stats.map(s => <StatCard key={s.label} {...s} />)}
      </div>

      {/* ── MANUAL TAB (BY COMPANY) ── */}
      {activeTab === 'manual' && (
        <div className="space-y-4">
          <div className="bg-blue-50 border border-blue-200 text-blue-700 p-4 rounded-[var(--ui-radius-small)] flex gap-3 text-sm">
            <Info className="flex-shrink-0" size={18} />
            <p>Anda sekarang dapat menugaskan satu pembimbing untuk semua siswa di dalam satu perusahaan sekaligus. Cukup pilih guru di dropdown utama perusahaan.</p>
          </div>

          {/* Filters - Click Based pills */}
          <div className="ui-card p-4 space-y-3">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input
                type="text"
                placeholder="Cari nama atau NIS siswa..."
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border-none rounded-[var(--ui-radius-small)] text-sm focus:border-[var(--ui-primary)] focus:ring-1 focus:ring-[var(--ui-primary)] outline-none"
              />
            </div>
            <div className="flex flex-col gap-3 pt-1 border-t border-slate-100">
              <div className="flex flex-wrap items-center gap-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest min-w-[70px]">Kelas:</span>
                <div className="flex flex-wrap gap-1.5">
                  {kelasOptions.map(k => (
                    <button
                      key={k}
                      type="button"
                      onClick={() => setFilterKelas(k)}
                      className={`px-3 py-1 rounded-[var(--ui-radius-small)] text-xs font-bold transition-all border cursor-pointer ${
                        filterKelas === k
                          ? 'bg-[var(--ui-primary)] border-[var(--ui-primary)] text-white shadow-sm'
                          : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                      }`}
                    >
                      {k === 'Semua' ? 'Semua Kelas' : k}
                    </button>
                  ))}
                </div>
              </div>
              <div className="flex flex-wrap items-center gap-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest min-w-[70px]">Jurusan:</span>
                <div className="flex flex-wrap gap-1.5">
                  {jurusanOptions.map(j => (
                    <button
                      key={j}
                      type="button"
                      onClick={() => setFilterJurusan(j)}
                      className={`px-3 py-1 rounded-[var(--ui-radius-small)] text-xs font-bold transition-all border cursor-pointer ${
                        filterJurusan === j
                          ? 'bg-[var(--ui-primary)] border-[var(--ui-primary)] text-white shadow-sm'
                          : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                      }`}
                    >
                      {j === 'Semua' ? 'Semua Jurusan' : j}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {Object.entries(studentsByCompany).map(([locId, compStudents]) => {
            const currentPage = pages[locId] || 1;
            const totalPages = Math.ceil(compStudents.length / ITEMS_PER_PAGE);

            // Pagination slice
            const paginatedStudents = compStudents.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

            const locName = locId === 'unassigned' ? 'Belum Memiliki Lokasi PKL' : 
                            (locations.find(l => String(l.id) === String(locId))?.nama_perusahaan || locations.find(l => String(l.id) === String(locId))?.nama || 'Perusahaan Tidak Diketahui');

            // Derive a common major to recommend teachers
            const commonMajor = compStudents[0]?.jurusanFix;

            // Check if all students in this company have the same teacher
            const allAssignedTo = compStudents.length > 0 ? assignments[compStudents[0].uniqueId] : null;
            const isUniformlyAssigned = allAssignedTo && compStudents.every(s => assignments[s.uniqueId] === allAssignedTo);

            return (
              <div key={locId} className="ui-card overflow-hidden">
                {/* Header Perusahaan */}
                <div className="bg-slate-50 px-5 py-3 border-b border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                  <div className="flex items-center gap-3">
                    {!readOnly && (
                    <input 
                      type="checkbox"
                      checked={compStudents.length > 0 && compStudents.every(s => selectedStudents.has(s.uniqueId))}
                      onChange={() => toggleSelectAll(locId)}
                      className="w-4 h-4 text-[var(--ui-primary)] rounded-[var(--ui-radius-small)] border-slate-300 focus:ring-[var(--ui-primary)]"
                    />
                    )}
                    <div className="w-10 h-10 rounded-full bg-[var(--ui-primary)]/10 flex items-center justify-center text-[var(--ui-primary)]">
                      <Building2 size={20} />
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-800">{locName}</h3>
                      <p className="text-xs text-slate-500">{compStudents.length} Siswa</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    {!readOnly && compStudents.some(s => selectedStudents.has(s.uniqueId)) && (
                      <button
                        onClick={() => handleDeleteSelected(locId)}
                        className="flex items-center gap-2 px-3 py-1.5 text-xs font-semibold text-rose-600 bg-rose-50 border border-rose-200 rounded-[var(--ui-radius-small)] hover:bg-rose-100 transition-colors"
                      >
                        <X size={14} />
                        Hapus Terpilih
                      </button>
                    )}
                    {!readOnly && (
                    <div className="w-[250px]">
                      <ClickPicker
                        value={isUniformlyAssigned ? allAssignedTo : ''}
                        onChange={val => handleBulkAssign(locId, val)}
                        options={getTeacherOptions(commonMajor)}
                        placeholder="Pilih Guru Pembimbing"
                      />
                    </div>
                    )}
                  </div>
                </div>

                {/* List Siswa Selalu Terbuka */}
                <div className="divide-y divide-slate-100">
                  {paginatedStudents.map((s, index) => {
                    const assigned = assignments[s.uniqueId];
                    return (
                      <div key={s.uniqueId} className="flex items-center gap-4 px-6 py-3">
                        {!readOnly && (
                        <input 
                          type="checkbox"
                          checked={selectedStudents.has(s.uniqueId)}
                          onChange={() => toggleSelectStudent(s.uniqueId)}
                          className="w-4 h-4 text-[var(--ui-primary)] rounded-[var(--ui-radius-small)] border-slate-300 focus:ring-[var(--ui-primary)]"
                        />
                        )}
                        <div className="w-8 text-center text-xs font-bold text-slate-400">
                          {(currentPage - 1) * ITEMS_PER_PAGE + index + 1}
                        </div>
                        <Avatar name={s.namaFix} size="sm" />
                        <div className="flex-1 min-w-0">
                          <p className="font-semibold text-slate-800 text-sm">{s.namaFix}</p>
                          <p className="text-xs text-slate-400">{s.nis ? `${s.nis} · ` : ''}{s.kelasFix}</p>
                        </div>
                        <Badge variant={s.jurusanFix} label={s.jurusanFix} withDot={false} />
                        <div className="flex items-center gap-2">
                          <div className="w-[220px]">
                            {assigned && !editingRows.has(s.uniqueId) ? (
                              <div className="flex items-center justify-between border border-emerald-200 bg-emerald-50 px-3 py-2 rounded-[var(--ui-radius-small)] min-h-9">
                                <span className="text-xs font-semibold text-emerald-800 truncate pr-2">
                                  {teachers.find(g => String(g.code) === String(assigned))?.nama || teachers.find(g => String(g.code) === String(assigned))?.name || assigned}
                                </span>
                                {!readOnly && (
                                  <div className="flex gap-2">
                                    <button
                                      type="button"
                                      onClick={() => setEditingRows(prev => new Set([...prev, s.uniqueId]))}
                                      className="text-emerald-600 hover:text-emerald-800 transition-colors"
                                      title="Edit Penugasan"
                                    >
                                      <Edit2 size={14} />
                                    </button>
                                    <button
                                      type="button"
                                      onClick={() => unassign(s.uniqueId)}
                                      className="text-rose-500 hover:text-rose-700 transition-colors"
                                      title="Hapus Penugasan"
                                    >
                                      <X size={14} />
                                    </button>
                                  </div>
                                )}
                              </div>
                            ) : (
                              <>
                                {readOnly ? (
                                  <span className="text-[11px] text-slate-400 italic">Belum ditugaskan</span>
                                ) : (
                                  <ClickPicker
                                    value={assigned ? String(assigned) : ''}
                                    onChange={val => {
                                      if (val === '') unassign(s.uniqueId);
                                      else assignManual(s.uniqueId, val);

                                      if (val !== '') {
                                        setEditingRows(prev => {
                                          const next = new Set(prev);
                                          next.delete(s.uniqueId);
                                          return next;
                                        });
                                      }
                                    }}
                                    options={getTeacherOptions(s.jurusanFix)}
                                    placeholder="Pilih Guru Pembimbing"
                                  />
                                )}
                              </>
                            )}
                          </div>
                          <span className="w-5 h-5 flex-shrink-0">
                            {assigned ? <CheckCircle2 size={18} className="text-emerald-500" /> : null}
                          </span>
                        </div>
                      </div>
                    );
                  })}

                  {/* Pagination Controls */}
                  {totalPages > 1 && (
                    <div className="px-6 py-3 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
                      <p className="text-xs text-slate-500">
                        Menampilkan {((currentPage - 1) * ITEMS_PER_PAGE) + 1} - {Math.min(currentPage * ITEMS_PER_PAGE, compStudents.length)} dari {compStudents.length} siswa
                      </p>
                      <div className="flex items-center gap-1">
                        <button
                          disabled={currentPage === 1}
                          onClick={() => setPage(locId, currentPage - 1)}
                          className="p-1.5 rounded-[var(--ui-radius-small)] hover:bg-slate-200 text-slate-500 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                        >
                          <ChevronLeft size={16} />
                        </button>
                        <span className="text-xs font-semibold px-2 text-slate-700">Halaman {currentPage} / {totalPages}</span>
                        <button
                          disabled={currentPage === totalPages}
                          onClick={() => setPage(locId, currentPage + 1)}
                          className="p-1.5 rounded-[var(--ui-radius-small)] hover:bg-slate-200 text-slate-500 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                        >
                          <ChevronRight size={16} />
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            );
          })}

          {Object.keys(studentsByCompany).length === 0 && (
            <div className="ui-card text-center py-10">
              <p className="text-slate-500 font-medium">Tidak ada siswa yang cocok dengan filter pencarian.</p>
            </div>
          )}
        </div>
      )}

      {/* ── AUTO ASSIGN TAB ── */}
      {activeTab === 'auto' && (
        <div className="space-y-4">
          {/* Info algoritma */}
          <div className="flex items-start gap-3 bg-[var(--ui-primary)]/10 border border-[var(--ui-primary)]/20 rounded-[var(--ui-radius-small)] p-3">
            <Info size={15} className="text-[var(--ui-primary)] mt-0.5 flex-shrink-0" />
            <div className="text-xs text-[var(--ui-primary)] space-y-1">
              <p className="font-bold mb-1">Algoritma Auto-Assign:</p>
              <p>1. Filter berdasarkan <strong>kesamaan jurusan</strong> (soft constraint)</p>
              <p>2. Prioritas guru dengan <strong>kapasitas sisa terbanyak</strong></p>
              <p>3. Jika kapasitas sama: pilih guru dengan <strong>jarak lebih dekat</strong> ke lokasi perusahaan siswa</p>
              <p>4. Jika jarak sama: urutan <strong>alfabetis nama guru</strong></p>
            </div>
          </div>

          {/* Mode selector */}
          <div className="ui-card p-4">
            <p className="text-sm font-bold text-slate-800 mb-3">Pengaturan Algoritma</p>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-5 pb-5 border-b border-slate-100">
              <label className="flex items-start gap-3 cursor-pointer group">
                <div className="relative flex items-center justify-center mt-0.5">
                  <input type="checkbox" className="peer sr-only" 
                    checked={config.prioritasWaliKelas} 
