                className="flex-1 py-2.5 bg-amber-500 text-white rounded-[var(--ui-radius-small)] text-sm font-bold hover:bg-amber-600">
                Ya, Lanjutkan
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

