                          />
                          {mode.label}
                        </div>
                        {isActive && (
                          <CheckCircle2
                            size={16}
                            className="text-[var(--ui-primary)]"
                          />
                        )}
                      </div>
                      <p className="text-slate-500 font-medium mt-2 text-xs leading-relaxed">
                        {mode.description}
                      </p>
                    </button>
                  );
                })}
              </div>

              {attendanceSettings.mode === "qr" && (
                <div className="grid grid-cols-1 xl:grid-cols-[1fr_auto] gap-4 items-center bg-slate-50 border-none rounded-[var(--ui-radius-small)] -[1.35rem] p-4">
                  <div>
                    <h4 className="text-sm font-black text-slate-800">
                      QR Absensi Hari Ini
                    </h4>
                    <p className="text-xs text-slate-500 font-medium mt-1">
                      Kode berubah setiap hari dan mengikuti koordinat sekolah. Guru bisa scan atau memasukkan kode yang sama.
                    </p>
                    <p className="mt-2 text-[10px] font-black uppercase tracking-widest text-slate-400 break-all">
                      {attendanceQrPayload}
                    </p>
                  </div>
                  <div className="bg-white p-3 rounded-[var(--ui-radius-card)] border-none shadow-sm">
                    {attendanceQrDataUrl ? (
                      <img
                        src={attendanceQrDataUrl}
                        alt="QR Absensi Hari Ini"
                        className="w-40 h-40 rounded-[var(--ui-radius-small)]"
                      />
                    ) : (
                      <div className="w-40 h-40 rounded-[var(--ui-radius-small)] bg-slate-100 flex items-center justify-center text-slate-400 text-xs font-bold">
                        QR belum siap
                      </div>
                    )}
                  </div>
                </div>
              )}
              <p className="text-[10px] text-slate-500 font-bold">
                Gunakan Google Maps untuk mendapatkan titik koordinat Latitude dan Longitude sekolah Anda secara akurat.
              </p>
            </div>
          )}

          {canManageAttendance && (
            <div className="bg-white border-none rounded-[var(--ui-radius-card)] shadow-sm p-6 flex flex-col gap-5">
              <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                <div>
                  <h3 className="text-xl font-black text-slate-800">
                    Jam Absensi Fleksibel
                  </h3>
                  <p className="text-sm text-slate-500 font-medium mt-1">
                    Buat mode pagi-siang, siang-sore, pagi-sore, atau multi sesi sesuai kebijakan sekolah.
                  </p>
                </div>
                <Button
                  type="button"
                  onClick={addAttendanceSession}
                  className="rounded-[var(--ui-radius-small)] px-4 py-2.5 text-xs shadow-sm"
                >
                  <Plus size={14} /> Tambah Sesi
                </Button>
              </div>
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-3">
                {(attendanceSessions || []).map((session) => (
                  <article
                    key={session.id}
                    className="rounded-[var(--ui-radius-small)] border-none bg-slate-50 p-4 space-y-3"
                  >
                    <div className="grid grid-cols-1 md:grid-cols-[1.2fr_0.6fr_0.6fr] gap-3">
                      <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                          Nama Sesi
                        </label>
                        <input
                          value={session.name || ""}
                          onChange={(e) =>
                            updateAttendanceSession(session.id, {
                              name: e.target.value
                            })
                          }
                          className="w-full border-none bg-white p-3 rounded-[var(--ui-radius-small)] text-sm font-bold"
                        />
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                          Tipe
                        </label>
                        <UISelect
                          value={session.type || "checkpoint"}
                          onChange={(e) =>
                            updateAttendanceSession(session.id, {
                              type: e.target.value
                            })
                          }
                          className="w-full border-none bg-white p-3 rounded-[var(--ui-radius-small)] text-sm font-bold"
                        >
                          {ATTENDANCE_SESSION_TYPES.map((type) => (
                            <option key={type.value} value={type.value}>
                              {type.label}
                            </option>
                          ))}
                        </UISelect>
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                          Target Pengguna
                        </label>
                        <UISelect
                          value={session.targetRole || "semua"}
                          onChange={(e) =>
                            updateAttendanceSession(session.id, {
                              targetRole: e.target.value
                            })
                          }
                          className="w-full border-none bg-white p-3 rounded-[var(--ui-radius-small)] text-sm font-bold"
                        >
                          <option value="semua">Semua</option>
                          <option value="guru">Guru</option>
                          <option value="karyawan">Karyawan</option>
                          <option value="siswa">Siswa</option>
                        </UISelect>
                      </div>
                    </div>
                    <div className="grid grid-cols-3 gap-2">
                      <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                          Jam Buka
                        </label>
                        <input
                          type="time"
                          value={session.openTime || ""}
                          onChange={(e) =>
                            updateAttendanceSession(session.id, {
                              openTime: e.target.value
                            })
                          }
                          className="w-full border-none bg-white p-2 rounded-[var(--ui-radius-small)] text-xs font-bold"
                        />
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                          Jam Tutup
                        </label>
                        <input
                          type="time"
                          value={session.closeTime || ""}
                          onChange={(e) =>
                            updateAttendanceSession(session.id, {
                              closeTime: e.target.value
                            })
                          }
                          className="w-full border-none bg-white p-2 rounded-[var(--ui-radius-small)] text-xs font-bold"
                        />
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                          Telat Laporan
                        </label>
                        <input
                          type="time"
                          value={session.lateAfter || ""}
                          onChange={(e) =>
                            updateAttendanceSession(session.id, {
                              lateAfter: e.target.value
                            })
                          }
                          className="w-full border-none bg-white p-2 rounded-[var(--ui-radius-small)] text-xs font-bold"
                        />
                      </div>
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 mb-2 block">
                        Hari Aktif
                      </label>
                      <div className="flex flex-wrap gap-2">
                        {(days || []).map((day) => {
                          const activeDays = Array.isArray(session.activeDays)
                            ? session.activeDays
                            : [];
                          const checked = activeDays.includes(day);
                          return (
                            <button
                              key={day}
                              type="button"
                              onClick={() => {
                                const nextDays = checked
                                  ? activeDays.filter((item) => item !== day)
                                  : [...activeDays, day];
                                updateAttendanceSession(session.id, {
                                  activeDays: nextDays
                                });
                              }}
                              className={`px-3 py-1.5 rounded-[var(--ui-radius-small)] border text-[11px] font-black transition-all ${checked ? "bg-[var(--ui-primary)] text-white border-[var(--ui-primary)]" : "bg-white text-slate-500 border-slate-200"}`}
                            >
                              {day}
                            </button>
                          );
                        })}
                      </div>
                    </div>
                    <div className="flex justify-between items-center gap-3 pt-2 border-t border-slate-200">
                      <p className="text-[10px] font-bold text-slate-400">
                        Contoh: {session.openTime} - {session.closeTime}
                        {session.lateAfter
                          ? `, terlambat setelah ${session.lateAfter}`
                          : ""}
                      </p>
                      <button
                        type="button"
                        onClick={() => removeAttendanceSession(session.id)}
                        className="p-2 rounded-[var(--ui-radius-small)] bg-white border-none text-slate-400 hover:text-red-600"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </article>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {attendanceSubTab === "corrections" && canReviewAttendance && (
        <div className="flex flex-col gap-6 w-full animate-in fade-in duration-300">
          {hasFeature("attendanceCorrections") && canReviewAttendance && (
            <section className="bg-white border-none rounded-[var(--ui-radius-card)] shadow-sm p-6">
              <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3 mb-5">
                <div>
                  <h2 className="text-xl font-black text-slate-800 tracking-tight">
                    Koreksi Absensi
                  </h2>
                  <p className="text-sm text-slate-500 font-medium">
                    Tinjau pengajuan koreksi dari guru sebelum masuk ke rekap.
                  </p>
                </div>
                <span className="w-fit px-3 py-1.5 rounded-[var(--ui-radius-small)] bg-amber-50 text-amber-700 border border-amber-200 text-[10px] font-black uppercase tracking-widest">
                  {pendingAttendanceCorrections.length} Menunggu
                </span>
              </div>

              {sortedAttendanceCorrections.length === 0 ? (
                <div className="rounded-[var(--ui-radius-small)] border border-dashed border-slate-300 bg-slate-50 p-6 text-center">
                  <CheckCircle2
                    size={36}
                    className="mx-auto mb-2 text-slate-300"
                  />
                  <p className="text-sm font-bold text-slate-500">
                    Belum ada pengajuan koreksi absensi.
                  </p>
                </div>
              ) : (
                <div className="grid grid-cols-1 xl:grid-cols-2 gap-3">
                  {sortedAttendanceCorrections.map((request) => {
                    const reviewStatus = request.statusReview || "pending";
                    const statusClass =
                      reviewStatus === "approved"
                        ? "bg-emerald-50 text-emerald-700 border-emerald-200"
                        : reviewStatus === "rejected"
                          ? "bg-red-50 text-red-700 border-red-200"
                          : "bg-amber-50 text-amber-700 border-amber-200";
                    return (
                      <article
                        key={request.id}
                        className="rounded-[var(--ui-radius-small)] border-none bg-slate-50 p-4"
                      >
                        <div className="flex items-start justify-between gap-3">
                          <div>
                            <div className="flex flex-wrap items-center gap-2">
                              <h3 className="font-black text-slate-800">
                                {request.teacherName ||
                                  getTeacherName(request.teacherCode)}
                              </h3>
                              <span className="px-2.5 py-1 rounded-[var(--ui-radius-small)] bg-white text-slate-500 border-none text-[10px] font-black uppercase">
                                {request.teacherCode}
                              </span>
                              <span
                                className={`px-2.5 py-1 rounded-[var(--ui-radius-small)] border text-[10px] font-black uppercase ${statusClass}`}
                              >
                                {reviewStatus === "approved"
                                  ? "Disetujui"
                                  : reviewStatus === "rejected"
                                    ? "Ditolak"
                                    : "Menunggu"}
                              </span>
                            </div>
                            <p className="mt-2 text-xs font-bold text-slate-500">
                              {request.date} · {request.time || "-"} ·{" "}
                              {request.sessionName || "Tanpa sesi"} · Status diminta: {request.status || "-"}
                            </p>
                            <p className="mt-3 text-sm font-semibold text-slate-700 leading-relaxed">
                              {request.note || "Tidak ada alasan tertulis."}
                            </p>
                            {request.reviewedBy && (
                              <p className="mt-2 text-[10px] font-bold text-slate-400">
                                Ditinjau oleh {request.reviewedBy}
                              </p>
                            )}
                          </div>
                        </div>
                        {reviewStatus === "pending" &&
                          activeUserRole !== "kepsek" && (
                            <div className="mt-4 flex flex-col sm:flex-row gap-2">
                              <Button
                                type="button"
                                onClick={() =>
                                  handleReviewAttendanceCorrection(
                                    request,
                                    "approved",
                                  )
                                }
                                className="flex-1 rounded-[var(--ui-radius-small)] py-2.5 text-xs shadow-sm"
                              >
                                <CheckCircle2 size={14} /> Setujui
                              </Button>
                              <Button
                                type="button"
                                variant="danger"
                                onClick={() =>
                                  handleReviewAttendanceCorrection(
                                    request,
                                    "rejected",
                                  )
                                }
                                className="flex-1 rounded-[var(--ui-radius-small)] py-2.5 text-xs shadow-sm"
                              >
                                <X size={14} /> Tolak
                              </Button>
                            </div>
                          )}
                      </article>
                    );
                  })}
                </div>
              )}
            </section>
          )}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import * as XLSX from 'xlsx';
import useAuthStore from '../../../store/monitoring/authStore.js';
import { useAppStore } from '../../../store/useAppStore.js';
import { ShieldCheck, RefreshCw, Download, CheckCircle2, Clock, CalendarIcon, AlertCircle } from 'lucide-react';
import { CustomSelect } from '../../../components/CustomSelect.jsx';


export default function TabAbsensiGuru() {
  const user = useAuthStore(state => state.user);
  const authToken = user?.authToken;

  const [loading, setLoading] = useState(false);
  const [data, setData] = useState(null);
  const [daysInMonth, setDaysInMonth] = useState(31);
  const [filter, setFilter] = useState({
    month: new Date().getMonth() + 1,
    year: new Date().getFullYear(),
  });

  const academicCalendarRaw = useAppStore(state => state.academicCalendar);
  const calendarCategoriesRaw = useAppStore(state => state.calendarCategories);
  const academicCalendar = academicCalendarRaw || [];
  const calendarCategories = calendarCategoriesRaw || [];

  const months = [
    { value: 1, label: "Januari" },
    { value: 2, label: "Februari" },
    { value: 3, label: "Maret" },
    { value: 4, label: "April" },
    { value: 5, label: "Mei" },
    { value: 6, label: "Juni" },
    { value: 7, label: "Juli" },
    { value: 8, label: "Agustus" },
    { value: 9, label: "September" },
    { value: 10, label: "Oktober" },
    { value: 11, label: "November" },
    { value: 12, label: "Desember" }
  ];

  const years = Array.from({ length: 5 }, (_, i) => ({
    value: new Date().getFullYear() - 2 + i,
    label: String(new Date().getFullYear() - 2 + i)
  }));

  const fetchData = async () => {
    if (!authToken) return;
    setLoading(true);
    try {
      const res = await fetch("/api/hikvision/report/matrix", {
        method: 'POST',
        headers: {
          "Authorization": `Bearer ${authToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ ...filter, type: 'guru' })
      });
      const json = await res.json();
      if (json.ok && Array.isArray(json.data)) {
        const teacherCode = String(user?.code || user?.username || "").trim().toLowerCase();
        const record = json.data.find(item => 
          String(item.nis).trim().toLowerCase() === teacherCode
        );
        setData(record || {
          nis: user?.code || user?.username,
          name: user?.name || "Guru",
          class_name: "guru",
          total_hadir: 0,
          total_terlambat: 0,
          total_izin: 0,
          total_sakit: 0,
          total_alpa: 0,
          days: {}
        });
        setDaysInMonth(json.daysInMonth || 31);
      }
    } catch (err) {
      console.error("Gagal memuat absensi fingerprint:", err);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, [filter.month, filter.year, authToken]); // eslint-disable-line react-hooks/exhaustive-deps

  const getDayName = (dayNum) => {
    try {
      const date = new Date(filter.year, filter.month - 1, dayNum);
      return date.toLocaleDateString('id-ID', { weekday: 'long' });
    } catch {
      return '';
    }
  };

  const handleExportExcel = () => {
    if (!data) return;

    const rows = Array.from({ length: daysInMonth }, (_, i) => i + 1).map(dayNum => {
      const dayName = getDayName(dayNum);
      const log = data.days?.[dayNum];
      const hasScan = log && (log.in || log.out);

      const checkDateStr = `${filter.year}-${String(filter.month).padStart(2, "0")}-${String(dayNum).padStart(2, "0")}`;
      const isHoliday = academicCalendar.some(evt => {
        const start = evt.dateStart;
        const end = evt.dateEnd || evt.dateStart;
        if (checkDateStr >= start && checkDateStr <= end) {
          const cat = calendarCategories.find(c => c.id === evt.categoryId);
          const catName = cat ? String(cat.name).toLowerCase() : "";
          const title = String(evt.title).toLowerCase();
          return catName.includes("libur") || title.includes("libur");
        }
        return false;
      });
      const isWeekend = dayName === "Sabtu" || dayName === "Minggu";

      let statusText = "";
      if (hasScan) {
        if (["Izin", "Sakit", "Dinas Luar", "Alpa"].includes(log.in)) {
          statusText = log.in;
        } else {
          statusText = log.isLate ? "Terlambat" : "Hadir";
        }
      } else {
        const today = new Date();
        const isFutureDay = 
          filter.year > today.getFullYear() || 
          (filter.year === today.getFullYear() && filter.month > today.getMonth() + 1) || 
          (filter.year === today.getFullYear() && filter.month === today.getMonth() + 1 && dayNum > today.getDate());

        const isToday = 
          filter.year === today.getFullYear() && 
          filter.month === today.getMonth() + 1 && 
          dayNum === today.getDate();

        if (isFutureDay) {
          statusText = "-";
        } else if (isToday) {
          statusText = "Belum Absen";
        } else if (isWeekend || isHoliday) {
          statusText = "Libur";
        } else {
          statusText = "Alpa";
        }
      }

      return {
        'Tanggal': `${dayNum}-${filter.month}-${filter.year}`,
        'Hari': dayName,
        'Jam Masuk': (hasScan && log.in && !["Izin", "Sakit", "Dinas Luar", "Alpa"].includes(log.in)) ? log.in : "-",
        'Jam Pulang': (hasScan && log.out && !["Izin", "Sakit", "Dinas Luar", "Alpa"].includes(log.in)) ? log.out : "-",
        'Status': statusText,
        'Keterangan/Alasan': log?.in && ["Izin", "Sakit", "Dinas Luar"].includes(log.in) ? log.in : ""
      };
    });

    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.json_to_sheet(rows);
    XLSX.utils.book_append_sheet(wb, ws, 'Absensi');

    const wscols = [
      {wch: 12}, // Tanggal
      {wch: 10}, // Hari
      {wch: 12}, // Jam Masuk
      {wch: 12}, // Jam Pulang
      {wch: 15}, // Status
      {wch: 25}  // Keterangan
    ];
    ws['!cols'] = wscols;

    const mLabel = months.find(m => m.value === filter.month)?.label || "";
    const fileName = `Absensi_${String(user?.name || "GURU").replace(/\s/g, '_')}_${mLabel}_${filter.year}.xlsx`;
    XLSX.writeFile(wb, fileName);
  };

  // Get index of the first day of the month (0 = Sunday, 1 = Monday, etc.)
  const firstDayIndex = new Date(filter.year, filter.month - 1, 1).getDay();

  // Calculate personal metrics safely
  const totalHadir = data ? Object.values(data.days).filter(d => d.in && d.in !== "Izin" && d.in !== "Sakit" && d.in !== "Alpa" && d.in !== "Dinas Luar" && !d.isLate).length : 0;
  const totalTerlambat = data ? Object.values(data.days).filter(d => d.isLate).length : 0;
  const totalIzinSakit = data ? Object.values(data.days).filter(d => ["Izin", "Sakit", "Dinas Luar"].includes(d.in)).length : 0;
  const totalAlpa = data ? Object.values(data.days).filter(d => d.in === "Alpa").length : 0;

  return (
    <div className="space-y-5 w-full animate-in fade-in slide-in-from-bottom-4 duration-300">

      {/* Header Info */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 bg-white p-4 md:p-6 rounded-[var(--ui-radius-card)] shadow-sm border border-slate-100">
        <div className="min-w-0 flex-1">
          <h2 className="text-base md:text-xl font-black text-slate-800 flex items-center gap-2 truncate">
            <ShieldCheck className="text-emerald-500 shrink-0" size={20} />
            <span className="truncate">Riwayat Absensi Fingerprint Guru</span>
          </h2>
          <p className="text-[11px] md:text-sm text-slate-500 font-semibold mt-1 leading-normal">
            Data kehadiran ditarik langsung dari mesin fingerprint sekolah.
          </p>
        </div>

        {/* Filters */}
        <div className="flex items-center gap-2 w-full sm:w-auto shrink-0">
          <div className="flex-1 sm:w-40 min-w-0">
            <CustomSelect
              value={filter.month}
              options={months}
              onChange={(val) => setFilter(prev => ({ ...prev, month: Number(val) }))}
            />
          </div>
          <div className="w-24 sm:w-28 min-w-0">
            <CustomSelect
              value={filter.year}
              options={years}
              onChange={(val) => setFilter(prev => ({ ...prev, year: Number(val) }))}
            />
          </div>
          <button 
            onClick={fetchData}
            disabled={loading}
            className="p-3 bg-slate-50 border border-slate-200 hover:bg-slate-100 active:scale-95 text-slate-600 rounded-xl transition-all shrink-0"
            title="Muat Ulang"
          >
            <RefreshCw size={16} className={loading ? "animate-spin" : ""} />
          </button>
          <button 
            onClick={handleExportExcel}
            disabled={loading || !data}
            className="px-4 py-2.5 bg-emerald-600 hover:opacity-90 text-white font-bold text-xs rounded-xl transition-all shrink-0 flex items-center gap-1.5 shadow-sm cursor-pointer border-none disabled:opacity-50"
            title="Unduh Rekap Excel"
          >
            <Download size={14} />
            <span className="hidden sm:inline">Ekspor Excel</span>
          </button>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4">
        <div className="bg-white p-3 rounded-[var(--ui-radius-card)] border border-slate-100 shadow-sm flex flex-col justify-between h-20 md:h-24 md:p-5">
          <div className="flex items-center justify-between">
            <span className="text-[9px] md:text-[10px] font-black uppercase tracking-wider text-slate-400 truncate">Tepat Waktu</span>
            <CheckCircle2 size={16} className="text-emerald-500 shrink-0" />
          </div>
          <div>
            <h4 className="text-lg md:text-2xl font-black text-emerald-600 leading-none">
              {totalHadir} <span className="text-xs font-bold text-slate-400">Hari</span>
            </h4>
          </div>
        </div>

        <div className="bg-white p-3 rounded-[var(--ui-radius-card)] border border-slate-100 shadow-sm flex flex-col justify-between h-20 md:h-24 md:p-5">
          <div className="flex items-center justify-between">
            <span className="text-[9px] md:text-[10px] font-black uppercase tracking-wider text-slate-400 truncate">Terlambat</span>
            <Clock size={16} className="text-amber-500 shrink-0" />
          </div>
          <div>
            <h4 className="text-lg md:text-2xl font-black text-amber-600 leading-none">
              {totalTerlambat} <span className="text-xs font-bold text-slate-400">Kali</span>
            </h4>
          </div>
        </div>

        <div className="bg-white p-3 rounded-[var(--ui-radius-card)] border border-slate-100 shadow-sm flex flex-col justify-between h-20 md:h-24 md:p-5">
          <div className="flex items-center justify-between">
            <span className="text-[9px] md:text-[10px] font-black uppercase tracking-wider text-slate-400 truncate">Izin / Sakit</span>
            <CalendarIcon size={16} className="text-blue-500 shrink-0" />
          </div>
          <div>
            <h4 className="text-lg md:text-2xl font-black text-blue-600 leading-none">
              {totalIzinSakit} <span className="text-xs font-bold text-slate-400">Hari</span>
            </h4>
          </div>
        </div>

        <div className="bg-white p-3 rounded-[var(--ui-radius-card)] border border-slate-100 shadow-sm flex flex-col justify-between h-20 md:h-24 md:p-5">
          <div className="flex items-center justify-between">
            <span className="text-[9px] md:text-[10px] font-black uppercase tracking-wider text-slate-400 truncate">Alpa</span>
            <AlertCircle size={16} className="text-red-500 shrink-0" />
          </div>
          <div>
            <h4 className="text-lg md:text-2xl font-black text-red-600 leading-none">
              {totalAlpa} <span className="text-xs font-bold text-slate-400">Hari</span>
            </h4>
          </div>
        </div>
      </div>

      {/* Calendar Grid Container */}
      <div className="bg-white rounded-[var(--ui-radius-card)] border border-slate-100 shadow-sm overflow-hidden p-3 md:p-5 space-y-4">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b pb-3 border-slate-100">
          <h3 className="text-sm font-bold text-slate-800">Kalender Absensi Bulan {months.find(m => m.value === filter.month)?.label} {filter.year}</h3>
          <span className="text-[10px] font-extrabold px-2.5 py-1 bg-slate-100 text-slate-600 rounded-full uppercase tracking-wider self-start sm:self-auto truncate max-w-full">
            {user?.name || "GURU"} ({user?.code})
          </span>
        </div>

        {loading ? (
          <div className="p-20 text-center text-slate-400 font-bold flex flex-col items-center justify-center gap-3">
            <RefreshCw className="animate-spin text-slate-300" size={32} />
            <span>Menarik data fingerprint...</span>
          </div>
        ) : (
          <div className="space-y-2.5">
            {/* Days of Week Headers */}
            <div className="grid grid-cols-7 gap-1 md:gap-2 text-center border-b border-slate-50 pb-2">
              {["Min", "Sen", "Sel", "Rab", "Kam", "Jum", "Sab"].map((d, idx) => (
                <div key={d} className={`text-[10px] md:text-xs font-black uppercase py-1 ${idx === 0 || idx === 6 ? 'text-rose-500' : 'text-slate-400'}`}>
                  {d}
                </div>
              ))}
            </div>

            {/* Calendar Grid Cells */}
            <div className="grid grid-cols-7 gap-1 md:gap-2">
              {/* Empty placeholder cells for offset */}
              {Array.from({ length: firstDayIndex }).map((_, idx) => (
                <div 
                  key={`empty-${idx}`} 
                  className="bg-slate-50/20 rounded-lg aspect-square md:aspect-[1.15] border border-dashed border-slate-100"
                />
              ))}

              {/* Day cells */}
              {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(dayNum => {
                const dayName = getDayName(dayNum);
                const log = data?.days?.[dayNum];
                const hasScan = log && (log.in || log.out);

                const today = new Date();
                const isFutureDay = 
                  filter.year > today.getFullYear() || 
                  (filter.year === today.getFullYear() && filter.month > today.getMonth() + 1) || 
                  (filter.year === today.getFullYear() && filter.month === today.getMonth() + 1 && dayNum > today.getDate());

                const isToday = 
                  filter.year === today.getFullYear() && 
                  filter.month === today.getMonth() + 1 && 
                  dayNum === today.getDate();

                const checkDateStr = `${filter.year}-${String(filter.month).padStart(2, "0")}-${String(dayNum).padStart(2, "0")}`;
                const isHoliday = academicCalendar.some(evt => {
                  const start = evt.dateStart;
                  const end = evt.dateEnd || evt.dateStart;
                  if (checkDateStr >= start && checkDateStr <= end) {
                    const cat = calendarCategories.find(c => c.id === evt.categoryId);
                    const catName = cat ? String(cat.name).toLowerCase() : "";
                    const title = String(evt.title).toLowerCase();
                    return catName.includes("libur") || title.includes("libur");
                  }
                  return false;
                });

                let cardClass = "bg-white border-slate-100 hover:border-slate-300";
                let statusDotClass = "bg-slate-200";
                let statusText = "";
                let isWeekend = dayName === "Sabtu" || dayName === "Minggu";

                if (hasScan) {
                  if (["Izin", "Sakit", "Dinas Luar", "Alpa"].includes(log.in)) {
                    statusText = log.in;
                    cardClass = log.in === "Alpa" ? "bg-red-50/60 border-red-100 text-red-800" : "bg-blue-50/60 border-blue-100 text-blue-800";
                    statusDotClass = log.in === "Alpa" ? "bg-red-500" : "bg-blue-500";
                  } else {
                    statusText = log.isLate ? "Terlambat" : "Hadir";
                    cardClass = log.isLate ? "bg-amber-50/60 border-amber-100 text-amber-800" : "bg-emerald-50/60 border-emerald-100 text-emerald-800";
                    statusDotClass = log.isLate ? "bg-amber-500" : "bg-emerald-500";
                  }
                } else if (isFutureDay) {
                  statusText = "-";
                  cardClass = "bg-slate-50/30 border-slate-100 text-slate-300";
                  statusDotClass = "bg-slate-100";
                } else if (isToday) {
                  statusText = "Belum Absen";
                  cardClass = "bg-white border-slate-200 text-slate-400";
                  statusDotClass = "bg-slate-300";
                } else if (isWeekend || isHoliday) {
                  statusText = "Libur";
                  cardClass = "bg-slate-50/70 border-slate-100 text-slate-400";
                  statusDotClass = "bg-slate-300";
                } else {
                  statusText = "Alpa";
                  cardClass = "bg-red-50/30 border-red-50/50 text-red-500";
                  statusDotClass = "bg-red-400";
                }

                return (
                  <div 
                    key={dayNum} 
                    className={`min-h-[56px] md:min-h-[72px] p-1 md:p-2.5 rounded-lg border flex flex-col justify-between transition-all hover:shadow-sm relative ${cardClass}`}
                    title={`Hari ${dayName}, ${dayNum} - Status: ${statusText}`}
                  >
                    {/* Header: Date Number & Status indicator dot */}
                    <div className="flex items-center justify-between w-full">
                      <span className={`text-[10px] md:text-sm font-black ${isWeekend || isHoliday ? 'text-rose-500/80' : 'text-slate-700'}`}>
                        {dayNum}
                      </span>
                      <span className={`w-1 h-1 md:w-1.5 md:h-1.5 rounded-full shrink-0 ${statusDotClass}`} />
                    </div>

                    {/* Footer: Scan Times or Status Label */}
                    <div className="w-full flex flex-col min-w-0 items-center justify-center leading-none">
                      {hasScan && !["Izin", "Sakit", "Dinas Luar", "Alpa"].includes(log.in) ? (
                        <>
                          {log.in && (
                            <span className="text-[7.5px] md:text-[9.5px] font-extrabold text-emerald-600 truncate w-full text-center">
                              {log.in.substring(0, 5)}
                            </span>
                          )}
                          {log.out && (
                            <span className="text-[7.5px] md:text-[9.5px] font-extrabold text-slate-500 truncate w-full text-center mt-0.5">
                              {log.out.substring(0, 5)}
                            </span>
                          )}
                        </>
                      ) : (
                        <div className="w-full flex flex-col items-center gap-0.5 min-w-0">
                          <span className="text-[7.5px] md:text-[9px] font-black uppercase tracking-tight truncate w-full text-center">
                            {statusText}
                          </span>
                          {log?.gdrive_url && (
                            <a
                              href={log.gdrive_url}
                              target="_blank"
                              rel="noreferrer"
                              onClick={(e) => e.stopPropagation()}
                              className="text-[7.5px] text-blue-600 hover:underline font-bold bg-white/60 px-1 rounded border border-blue-200 mt-0.5 text-center truncate max-w-full"
                            >
                              Lihat Surat
                            </a>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { CalendarDays } from 'lucide-react';
import { Search, BookOpen, FileDown, Upload, List, Plus, Calendar, Edit2, Trash2, ChevronLeft, ChevronRight } from 'lucide-react';
import { PageHeader, Button } from '../../../components/monitoring/ui/index.js';


export default function TabAkademik(props) {
  const [currentMonth, setCurrentMonth] = React.useState(new Date().getMonth());
  const [currentYear, setCurrentYear] = React.useState(new Date().getFullYear());

  const [selectStart, setSelectStart] = React.useState(null);
  const [selectEnd, setSelectEnd] = React.useState(null);

  const normalizeText = (value) => String(value ?? "").trim().replace(/\s+/g, " ").toLowerCase();

  React.useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === "Escape") {
        setSelectStart(null);
        setSelectEnd(null);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  const { academicCalendar, calendarSearchTerm, calendarCategories, setCalendarSearchTerm, openAcademicCalendarGuide, downloadMasterTemplate, openModal, setActiveTab, formatCalendarDateRange, handleRemoveCalendarEventSafe, setFormData } = props;

  const todayDate = new Date();
  todayDate.setHours(0, 0, 0, 0);

  const sortedCalendar = [...academicCalendar].sort(
    (a, b) => new Date(a.dateStart) - new Date(b.dateStart)
  );

  const filteredCalendar = sortedCalendar.filter((evt) => {
    if (!calendarSearchTerm.trim()) return true;
    const catName =
      calendarCategories.find((cat) => cat.id === evt.categoryId)?.name ||
      "";
    return normalizeText(
      `${evt.title || ""} ${evt.description || ""} ${catName} ${evt.dateStart || ""} ${evt.dateEnd || ""}`
    ).includes(normalizeText(calendarSearchTerm));
  });

  const upcomingCalendar = sortedCalendar
    .filter((evt) => {
      const endDate = new Date(
        `${(evt.dateEnd || evt.dateStart || "").slice(0, 10)}T23:59:59`
      );
      return !Number.isNaN(endDate.getTime()) && endDate >= todayDate;
    })
    .slice(0, 3);

  const startOfMonth = new Date(currentYear, currentMonth, 1);
  const endOfMonth = new Date(currentYear, currentMonth + 1, 0);

  const thisMonthEvents = sortedCalendar.filter((evt) => {
    const startDate = new Date(
      `${(evt.dateStart || "").slice(0, 10)}T00:00:00`
    );
    const endDate = new Date(
      `${(evt.dateEnd || evt.dateStart || "").slice(0, 10)}T23:59:59`
    );
    return (
      !Number.isNaN(startDate.getTime()) &&
      !Number.isNaN(endDate.getTime()) &&
      startDate <= endOfMonth &&
      endDate >= startOfMonth
    );
  });

  const monthNames = [
    "Januari", "Februari", "Maret", "April", "Mei", "Juni",
    "Juli", "Agustus", "September", "Oktober", "November", "Desember"
  ];

  const firstDayOfMonth = new Date(currentYear, currentMonth, 1).getDay();
  const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const calendarCells = [];
  for (let i = 0; i < firstDayOfMonth; i++) {
    calendarCells.push(null);
  }
  for (let d = 1; d <= daysInCurrentMonth; d++) {
    calendarCells.push(d);
  }

  const getCategoryColor = (catColor) => {
    switch (catColor) {
      case "rose":
      case "red":
        return { bg: "bg-red-500 text-white", border: "border-red-600", lightBg: "bg-red-100/90 text-red-800" };
      case "amber":
      case "orange":
        return { bg: "bg-amber-500 text-white", border: "border-amber-600", lightBg: "bg-amber-100/90 text-amber-800" };
      case "yellow":
        return { bg: "bg-yellow-400 text-slate-800", border: "border-yellow-500", lightBg: "bg-yellow-100 text-yellow-800" };
      case "emerald":
      case "green":
        return { bg: "bg-emerald-500 text-white", border: "border-emerald-600", lightBg: "bg-emerald-100/90 text-emerald-800" };
      case "blue":
      case "sky":
        return { bg: "bg-blue-500 text-white", border: "border-blue-600", lightBg: "bg-blue-100/90 text-blue-800" };
      case "purple":
        return { bg: "bg-purple-500 text-white", border: "border-purple-600", lightBg: "bg-purple-100/90 text-purple-800" };
      default:
        return { bg: "bg-slate-500 text-white", border: "border-slate-600", lightBg: "bg-slate-100 text-slate-800" };
    }
  };

  return (
    <div className="flex flex-col gap-6 h-full w-full animate-in fade-in duration-300 relative z-10">
      <PageHeader
        title="Kalender Akademik"
        description="Atur dan kelola agenda kegiatan sekolah. Tambah manual atau import langsung dari Excel."
        icon={CalendarDays}
      >
        <div className="flex items-center gap-2 bg-white/10 px-3 py-1 rounded-[var(--ui-radius-small)] backdrop-blur-sm border border-white/10">
          <div className="flex items-center gap-1.5 border-r border-white/10 pr-2.5">
            <span className="text-[9px] font-black uppercase tracking-wider text-white/70">
              Total Agenda:
            </span>
            <span className="text-xs font-black text-white bg-white/15 px-1.5 py-0.5 rounded-[var(--ui-radius-small)]">
              {academicCalendar.length}
            </span>
          </div>
          <div className="flex items-center gap-1.5 border-r border-white/10 pr-2.5">
            <span className="text-[9px] font-black uppercase tracking-wider text-emerald-300">
              Mendatang:
            </span>
            <span className="text-xs font-black text-emerald-400 bg-emerald-500/15 px-1.5 py-0.5 rounded-[var(--ui-radius-small)]">
              {upcomingCalendar.length}
            </span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="text-[9px] font-black uppercase tracking-wider text-amber-300">
              Bulan Ini:
            </span>
            <span className="text-xs font-black text-amber-400 bg-amber-500/15 px-1.5 py-0.5 rounded-[var(--ui-radius-small)]">
              {thisMonthEvents.length}
            </span>
          </div>
        </div>
      </PageHeader>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 items-start">
        {/* Left Column: Agenda List & Filters */}
        <div className="xl:col-span-2 ui-card p-5 md:p-6 flex flex-col gap-5">
          {/* Actions & Search */}
          <div className="flex flex-col lg:flex-row gap-3 lg:items-center justify-between">
            <div className="relative flex-1 max-w-md">
              <Search
                size={16}
                className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400"
              />
              <input
                type="text"
                value={calendarSearchTerm}
                onChange={(e) => setCalendarSearchTerm(e.target.value)}
                className="w-full border-none rounded-[var(--ui-radius-small)] bg-slate-50 pl-10 pr-4 py-2.5 text-sm font-bold text-slate-800 placeholder:text-slate-400 focus:outline-none focus:bg-white focus:border-[var(--ui-primary)] shadow-sm transition-all"
                placeholder="Cari judul, kategori, atau tanggal..."
              />
            </div>
            <div className="flex flex-wrap gap-2">
              <Button
                variant="secondary"
                onClick={openAcademicCalendarGuide}
                className="px-3.5 py-2 rounded-[var(--ui-radius-small)] text-xs shadow-sm bg-white hover:bg-slate-50"
              >
                <BookOpen size={14} className="mr-1.5 inline" /> Panduan
              </Button>
              <Button
                variant="secondary"
                onClick={downloadMasterTemplate}
                className="px-3.5 py-2 rounded-[var(--ui-radius-small)] text-xs shadow-sm bg-white hover:bg-slate-50"
              >
                <FileDown size={14} className="mr-1.5 inline" /> Template
              </Button>
              <Button
                variant="secondary"
                onClick={() => openModal("bulk", "add")}
                className="px-3.5 py-2 rounded-[var(--ui-radius-small)] text-xs shadow-sm bg-white hover:bg-slate-50"
              >
                <Upload size={14} className="mr-1.5 inline" /> Import
              </Button>
              <Button
                variant="secondary"
                onClick={() => setActiveTab("kategori_kalender")}
                className="px-3.5 py-2 rounded-[var(--ui-radius-small)] text-xs shadow-sm bg-white hover:bg-slate-50"
              >
                <List size={14} className="mr-1.5 inline" /> Kategori
              </Button>
              <Button
                variant="primary"
                onClick={() => {
                  setFormData({
                    title: "",
                    categoryId: calendarCategories[0]?.id || "",
                    dateStart: new Date().toISOString().split("T")[0],
                    dateEnd: new Date().toISOString().split("T")[0],
                    description: ""
                  });
                  openModal("event_kalender", "add");
                }}
                className="px-4 py-2 rounded-[var(--ui-radius-small)] text-xs shadow-sm font-black"
              >
                <Plus size={14} className="mr-1.5 inline" /> Tambah Agenda
              </Button>
            </div>
          </div>

          <div className="bg-slate-50/50 border-none rounded-[var(--ui-radius-small)] p-4 sm:p-6 min-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredCalendar.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-center py-16">
                <div className="w-16 h-16 bg-white border-none text-slate-300 rounded-[var(--ui-radius-small)] flex items-center justify-center mb-4 shadow-sm">
                  <CalendarDays size={28} />
                </div>
                <h3 className="text-lg font-black text-slate-700">
                  Tidak ada agenda
                </h3>
                <p className="text-sm font-medium text-slate-500 mt-2 max-w-sm">
                  {calendarSearchTerm.trim()
                    ? "Coba kata kunci lain atau hapus filter pencarian."
                    : "Belum ada agenda akademik yang ditambahkan. Mulai dengan menambah agenda baru."}
                </p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {filteredCalendar.map((evt) => {
                  const cat = calendarCategories.find(
                    (c) => c.id === evt.categoryId
                  );
                  const isUpcoming =
                    new Date(
                      `${(evt.dateStart || "").slice(0, 10)}T00:00:00`
                    ) >= new Date(new Date().setHours(0, 0, 0, 0));

                  const colors = getCategoryColor(cat?.color);

                  return (
                    <div
                      key={evt.id}
                      className="group relative bg-white border-none rounded-[var(--ui-radius-card)] p-5 hover:shadow-md hover:border-slate-350 transition-all flex flex-col justify-between"
                    >
                      <div>
                        <div className="flex items-start justify-between gap-3 mb-3">
                          <span
                            className={`px-2.5 py-1 rounded-[var(--ui-radius-small)] border text-[9px] font-black uppercase tracking-widest ${colors.lightBg}`}
                          >
                            {cat?.name || "Tanpa Kategori"}
                          </span>
                          {isUpcoming && (
                            <span className="flex h-2.5 w-2.5 rounded-full bg-emerald-500 ring-4 ring-emerald-500/20"></span>
                          )}
                        </div>

                        <h3 className="text-sm font-black text-slate-800 leading-tight line-clamp-2">
                          {evt.title}
                        </h3>
                        <p className="text-xs font-medium text-slate-500 mt-2 line-clamp-3">
                          {evt.description || "Tidak ada deskripsi rinci."}
                        </p>
                      </div>

                      <div className="mt-4 pt-4 border-t border-slate-100 flex items-center justify-between">
                        <div className="flex items-center gap-1.5 text-[10px] font-bold text-slate-600 bg-slate-50 px-2 py-1 rounded-[var(--ui-radius-small)] border-none">
                          <Calendar size={12} className="text-slate-400" />
                          {formatCalendarDateRange(
                            evt.dateStart,
                            evt.dateEnd
                          )}
                        </div>

                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button
                            onClick={() =>
                              openModal("event_kalender", "edit", evt)
                            }
                            className="p-1.5 text-slate-400 hover:text-[var(--ui-primary)] hover:bg-[var(--ui-primary)]/10 rounded-[var(--ui-radius-small)] transition-colors"
                          >
                            <Edit2 size={14} />
                          </button>
                          <button
                            onClick={() =>
                              handleRemoveCalendarEventSafe(evt.id)
                            }
                            className="p-1.5 text-slate-400 hover:text-red-650 hover:bg-red-50 rounded-[var(--ui-radius-small)] transition-colors"
                          >
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Right Column: Interactive Monthly Calendar Grid */}
        <div className="ui-card p-5 md:p-6 flex flex-col gap-4 bg-white border border-slate-200/60 shadow-sm rounded-[var(--ui-radius-card)]">
          {/* Calendar Header with Navigation */}
          <div className="flex items-center justify-between pb-3 border-b border-slate-100">
            <button
              type="button"
              onClick={() => {
                if (currentMonth === 0) {
                  setCurrentMonth(11);
                  setCurrentYear((prev) => prev - 1);
                } else {
                  setCurrentMonth((prev) => prev - 1);
                }
              }}
              className="p-1.5 text-slate-500 hover:text-slate-800 hover:bg-slate-100 rounded-md transition-colors"
            >
              <ChevronLeft size={16} />
            </button>
            <span className="text-xs font-black text-slate-800 uppercase tracking-widest">
              {monthNames[currentMonth]} {currentYear}
            </span>
            <button
              type="button"
              onClick={() => {
                if (currentMonth === 11) {
                  setCurrentMonth(0);
                  setCurrentYear((prev) => prev + 1);
                } else {
                  setCurrentMonth((prev) => prev + 1);
                }
              }}
              className="p-1.5 text-slate-500 hover:text-slate-800 hover:bg-slate-100 rounded-md transition-colors"
            >
              <ChevronRight size={16} />
            </button>
          </div>

          {selectStart && (
            <div className="bg-amber-50 border border-amber-100 rounded-lg p-2.5 flex items-center justify-between text-xs font-bold text-amber-800 animate-in fade-in duration-200">
              <span className="flex items-center gap-1.5">
                <span className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-ping"></span>
                Pilih tanggal akhir range kegiatan
              </span>
              <button 
                type="button"
                onClick={() => { setSelectStart(null); setSelectEnd(null); }} 
                className="text-[10px] font-black uppercase tracking-wider bg-amber-200 hover:bg-amber-300 text-amber-900 border-none px-2.5 py-1 rounded transition-colors cursor-pointer"
              >
                Batal
              </button>
            </div>
          )}

          {/* Grid Layout */}
          <div className="overflow-hidden border border-slate-150 rounded-[var(--ui-radius-small)] bg-white shadow-xs">
            {/* Days of Week Header */}
            <div className="grid grid-cols-7 border-b border-slate-150 bg-slate-50/70 text-center font-bold text-[10px] text-slate-500 py-2 uppercase tracking-wider">
              <div className="text-red-500">Min</div>
              <div>Sen</div>
              <div>Sel</div>
              <div>Rab</div>
              <div>Kam</div>
              <div>Jum</div>
              <div>Sab</div>
            </div>

            {/* Grid Cells */}
            <div className="grid grid-cols-7 bg-slate-150 gap-[1px]">
              {calendarCells.map((dayNum, idx) => {
                if (dayNum === null) {
                  return <div key={`empty-${idx}`} className="bg-slate-50/40 p-2 min-h-[48px]"></div>;
                }

                const dateStr = `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;

                // Find events matching this day
                const dayEvents = sortedCalendar.filter((evt) => {
                  const start = evt.dateStart;
                  const end = evt.dateEnd || evt.dateStart;
                  return dateStr >= start && dateStr <= end;
                });

                // Check if in active range selection
                let isSelectedRange = false;
                if (selectStart && selectEnd) {
                  const minSel = selectStart < selectEnd ? selectStart : selectEnd;
                  const maxSel = selectStart > selectEnd ? selectStart : selectEnd;
                  isSelectedRange = dateStr >= minSel && dateStr <= maxSel;
                }

                const dayOfWeek = idx % 7;
                const isSunday = dayOfWeek === 0;

                let cellBg = "bg-white";
                let textClass = isSunday ? "text-red-500 font-bold" : "text-slate-800 font-semibold";
                let tooltip = "";
                let roundingClass = "rounded-none";

                if (dayEvents.length > 0) {
                  const firstEvt = dayEvents[0];
                  const cat = calendarCategories.find((c) => c.id === firstEvt.categoryId);
                  const colors = getCategoryColor(cat?.color);

                  cellBg = colors.lightBg;
                  tooltip = dayEvents.map((e) => e.title).join(", ");

                  // Calculate start/end segment to draw continuous horizontal blocks exactly like in the user's reference
                  const startStr = firstEvt.dateStart;
                  const endStr = firstEvt.dateEnd || firstEvt.dateStart;
                  const isStart = dateStr === startStr;
                  const isEnd = dateStr === endStr;

                  if (isStart && isEnd) {
                    roundingClass = "rounded-[var(--ui-radius-small)]";
                  } else if (isStart) {
                    roundingClass = "rounded-l-[var(--ui-radius-small)]";
                  } else if (isEnd) {
                    roundingClass = "rounded-r-[var(--ui-radius-small)]";
                  }
                }

                return (
                  <div
                    key={dayNum}
                    onClick={() => {
                      if (selectStart) {
                        const minDate = selectStart < dateStr ? selectStart : dateStr;
                        const maxDate = selectStart > dateStr ? selectStart : dateStr;
                        setFormData({
                          title: "",
                          categoryId: calendarCategories[0]?.id || "",
                          dateStart: minDate,
                          dateEnd: maxDate,
                          description: ""
                        });
                        openModal("event_kalender", "add");
                        setSelectStart(null);
                        setSelectEnd(null);
                      } else {
                        if (dayEvents.length > 0) {
                          openModal("event_kalender", "edit", dayEvents[0]);
                        } else {
                          setSelectStart(dateStr);
                          setSelectEnd(dateStr);
                        }
                      }
                    }}
                    onMouseEnter={() => {
                      if (selectStart) {
                        setSelectEnd(dateStr);
                      }
                    }}
                    title={tooltip || (selectStart ? "Klik untuk memilih batas akhir range" : "Klik untuk pilih awal range tanggal")}
                    className={`p-2 min-h-[48px] flex flex-col justify-between hover:bg-slate-50 cursor-pointer transition-colors relative select-none ${cellBg} ${roundingClass} ${isSelectedRange ? 'outline outline-2 outline-offset-[-2px] outline-red-500 z-20 bg-red-50/10' : ''}`}
                  >
                    <span className={`text-xs ${textClass}`}>{dayNum}</span>
                    {dayEvents.length > 0 && (
                      <div className="w-full text-[7px] font-black uppercase tracking-wide truncate opacity-85 mt-1 block">
                        {dayEvents[0].title}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Legend helper */}
          <div className="mt-2 pt-2 border-t border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-2">Legenda Kategori</span>
            <div className="flex flex-wrap gap-2">
              {calendarCategories.map(cat => {
                const colors = getCategoryColor(cat.color);
                return (
                  <span key={cat.id} className={`px-2 py-0.5 rounded-[var(--ui-radius-small)] text-[9px] font-bold border ${colors.lightBg}`}>
                    {cat.name}
                  </span>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

