                                          activeColor:
                                            "bg-amber-500 text-white shadow-sm"
                                        },
                                        {
                                          val: "edit",
                                          label: "Edit",
                                          activeColor:
                                            "bg-blue-500 text-white shadow-sm"
                                        },
                                        {
                                          val: "otomatis",
                                          label: "Auto",
                                          activeColor:
                                            "bg-emerald-600 text-white shadow-sm"
                                        },
                                      ].map((opt) => (
                                        <button
                                          key={opt.val}
                                          type="button"
                                          title={
                                            opt.label === "Off"
                                              ? "Nonaktifkan Akses"
                                              : opt.label === "Auto"
                                                ? "Otomatis (Bawaan Role)"
                                                : `Hak Akses ${opt.label}`
                                          }
                                          onClick={() => {
                                            if (value === opt.val) return;
                                            if (
                                              !ensureDatabaseReadyForWrite(
                                                "mengubah hak akses",
                                              )
                                            )
                                              return;
                                            let nextObj = {};
                                            if (Array.isArray(allowedTabs)) {
                                              allowedTabs.forEach(
                                                (t) =>
                                                  (nextObj[t] = "otomatis"),
                                              );
                                            } else {
                                              nextObj = { ...allowedTabs };
                                            }
                                            nextObj[tab] = opt.val;
                                            updateRolePermissions({
                                              [roleKey]: nextObj
                                            });
                                          }}
                                          className={`px-2 py-1 text-[9px] font-black uppercase tracking-wider rounded-[var(--ui-radius-small)] transition-all flex-1 text-center min-w-[36px] ${value === opt.val
                                              ? opt.activeColor
                                              : "text-slate-400 hover:text-slate-600 hover:bg-slate-200/50"
                                            }`}
                                        >
                                          {opt.label}
                                        </button>
                                      ))}
                                    </div>
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                          );
                        })}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        );
}

import { useState } from 'react';
import { Lock } from 'lucide-react';
import { PageHeader } from '../../../components/monitoring/ui/index.js';


export default function TabKeamanan(props) {
  const { currentUser, teachers, setTeachers, staffs, setStaffs, adminUser, setAdminUser, syncAuthSnapshotNow, saveDatabaseNow, showNotification } = props;
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  const handleChangePassword = async (e) => {
    e.preventDefault();
    if (!newPassword.trim()) {
      if (showNotification) showNotification("Sandi baru tidak boleh kosong!", "warning");
      return;
    }

    // 1. Validate length: 6 to 12 characters
    if (newPassword.length < 6 || newPassword.length > 12) {
      if (showNotification) showNotification("Panjang password harus antara 6 hingga 12 karakter!", "warning");
      return;
    }

    if (newPassword !== confirmPassword) {
      if (showNotification) showNotification("Konfirmasi sandi tidak cocok!", "warning");
      return;
    }

    // 2. Validate same as previous password
    let currentPasswordHash = "";
    if (currentUser?.role === "admin" || currentUser?.role === "superadmin") {
      currentPasswordHash = adminUser?.password || "";
    } else {
      const matchedTeacher = teachers?.find((t) => t.code === currentUser?.code);
      if (matchedTeacher) {
        currentPasswordHash = matchedTeacher.password || "";
      } else {
        const matchedStaff = staffs?.find((s) => s.code === currentUser?.code);
        if (matchedStaff) {
          currentPasswordHash = matchedStaff.password || "";
        }
      }
    }

    if (currentPasswordHash) {
      try {
        const { verifyPassword } = await import("../../../utils/auth.js");
        const isSame = await verifyPassword(newPassword, currentPasswordHash);
        if (isSame) {
          if (showNotification) showNotification("Tidak bisa menggunakan password yang sama dengan sebelumnya!", "warning");
          return;
        }
      } catch (err) {
        console.error("Failed to verify previous password hash:", err);
      }
    }

    const { hashPassword } = await import("../../../utils/auth.js");
    const passwordHash = await hashPassword(newPassword);

    try {
      if (currentUser?.role === "admin" || currentUser?.role === "superadmin") {
        const updatedAdmin = { ...adminUser, password: passwordHash };
        if (syncAuthSnapshotNow) await syncAuthSnapshotNow(updatedAdmin, teachers, "menyimpan profil admin");
        if (saveDatabaseNow) await saveDatabaseNow({ adminUser: updatedAdmin }, "menyimpan profil admin");
        if (setAdminUser) setAdminUser(updatedAdmin);
        if (showNotification) showNotification("Sandi Admin berhasil diubah!", "success");
      } else if (teachers && teachers.some((t) => t.code === currentUser?.code)) {
        const nextTeachers = teachers.map((t) => t.code === currentUser.code ? { ...t, password: passwordHash } : t);
        if (saveDatabaseNow) await saveDatabaseNow({ teachers: nextTeachers }, "mengubah password guru");
        if (setTeachers) setTeachers(nextTeachers);
        if (showNotification) showNotification("Sandi Anda berhasil diubah!", "success");
      } else if (staffs && staffs.some((s) => s.code === currentUser?.code)) {
        const nextStaffs = staffs.map((s) => s.code === currentUser.code ? { ...s, password: passwordHash } : s);
        if (saveDatabaseNow) await saveDatabaseNow({ staffs: nextStaffs }, "mengubah password karyawan");
        if (setStaffs) setStaffs(nextStaffs);
        if (showNotification) showNotification("Sandi Anda berhasil diubah!", "success");
      } else {
        if (showNotification) showNotification("Pengguna tidak ditemukan dalam database.", "warning");
        return;
      }
      setNewPassword("");
      setConfirmPassword("");
    } catch (err) {
      console.error(err);
      if (showNotification) showNotification("Gagal mengubah kata sandi.", "danger");
    }
  };

  return (
    <div className="flex flex-col gap-5 w-full animate-in fade-in duration-300 relative z-10">
      <PageHeader
        title="Keamanan Akun"
        description="Ubah kata sandi login Anda secara berkala untuk menjaga keamanan akun Anda."
        icon={Lock}
      />

      <div className="bg-white rounded-[var(--ui-radius-card)] p-6 shadow-sm border-none">
        <div className="flex items-center gap-3 border-b border-slate-100 pb-4 mb-5">
          <div className="w-10 h-10 rounded-[var(--ui-radius-small)] bg-[var(--ui-primary)]/10 text-[var(--ui-primary)] flex items-center justify-center">
            <Lock size={20} />
          </div>
          <div>
            <h3 className="font-black text-slate-800 text-base tracking-tight">Ubah Kata Sandi</h3>
            <p className="text-[11px] font-bold text-slate-400 mt-0.5">Silakan isi form di bawah ini untuk mengubah kata sandi Anda</p>
          </div>
        </div>

        {/* Password Policy Banner */}
        <div className="bg-slate-50 border border-slate-100 rounded-xl p-4 mb-6 text-xs text-slate-600 space-y-1.5 max-w-md">
          <p className="font-black uppercase tracking-widest text-[9px] text-slate-550 mb-2 flex items-center gap-1.5">
            <Lock size={12} className="text-[var(--ui-primary)]" /> Kebijakan Keamanan Password:
          </p>
          <div className="flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-[var(--ui-primary)]" />
            <span className="font-semibold text-slate-700">Panjang Karakter:</span> Minimal 6 hingga 12 karakter.
          </div>
          <div className="flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-[var(--ui-primary)]" />
            <span className="font-semibold text-slate-700">Keunikan:</span> Tidak bisa menggunakan password yang sama dengan sebelumnya.
          </div>
        </div>

        <form onSubmit={handleChangePassword} className="max-w-md space-y-4">
          <div>
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-1.5 ml-1">Sandi Baru</label>
            <input
              type="password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              placeholder="Masukkan sandi baru"
              className="w-full border border-slate-200 bg-slate-50 p-3.5 rounded-[var(--ui-radius-small)] text-sm font-semibold focus:bg-white focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)]/15"
              required
            />
          </div>
          <div>
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-1.5 ml-1">Konfirmasi Sandi Baru</label>
            <input
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="Konfirmasi sandi baru"
              className="w-full border border-slate-200 bg-slate-50 p-3.5 rounded-[var(--ui-radius-small)] text-sm font-semibold focus:bg-white focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)]/15"
              required
            />
          </div>
          <button
            type="submit"
            className="px-6 py-3 bg-[var(--ui-primary)] text-white font-black text-xs rounded-[var(--ui-radius-small)] shadow-sm hover:opacity-90 transition-opacity cursor-pointer border-none"
          >
            Simpan Kata Sandi
          </button>
        </form>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Clock } from 'lucide-react';
import { isSuperAdminRole } from '../../../utils/constants.js';
import { Search, BookOpen } from 'lucide-react';
import { PageHeader, Button } from '../../../components/monitoring/ui/index.js';


export default function TabKetersediaan({
  currentUser,
  teachers,
  teacherAvailability,
  setTeacherAvailability,
  days,
  openModal,
  tabSubtitles
}) {
  const [searchTerm, setSearchTerm] = useState("");

  const normalizeText = (t) => String(t || "").trim().toLowerCase();
  const sameText = (a, b) => normalizeText(a) === normalizeText(b);

  const canViewAllAvailability = isSuperAdminRole(currentUser.role) || currentUser.role === "waka";
  const availabilitySearch = normalizeText(searchTerm);

  const visibleAvailabilityTeachers = teachers
    .filter(
      (teacher) =>
        canViewAllAvailability ||
        sameText(teacher.code, currentUser.code),
    )
    .filter(
      (teacher) =>
        !availabilitySearch ||
        normalizeText(
          `${teacher.code || ""} ${teacher.name || ""} ${teacher.type || ""} ${teacher.preferredMajor || ""} ${teacher.preferredGrade || ""}`,
        ).includes(availabilitySearch),
    );

  const teachersWithSubjectsCount = teachers.filter((teacher) => {
    const entry = teacherAvailability[teacher.code] || { subjects: [] };
    return Array.isArray(entry.subjects) && entry.subjects.length > 0;
  }).length;

  const teachersWithDaysCount = teachers.filter((teacher) => {
    const entry = teacherAvailability[teacher.code] || { days: [] };
    return Array.isArray(entry.days) && entry.days.length > 0;
  }).length;

  const toggleTeacherDay = (teacherCode, day) => {
    setTeacherAvailability((prev) => {
      const next = { ...prev };
      const entry = next[teacherCode] || { days: [], subjects: [] };
      const currentDays = Array.isArray(entry.days) ? entry.days : [];
      next[teacherCode] = {
        ...entry,
        days: currentDays.includes(day)
          ? currentDays.filter((item) => item !== day)
          : Array.from(new Set([...currentDays, day]))
      };
      return next;
    });
  };

  const setTeacherDays = (teacherCode, nextDays) => {
    setTeacherAvailability((prev) => {
      const entry = prev[teacherCode] || { days: [], subjects: [] };
      return { ...prev, [teacherCode]: { ...entry, days: nextDays } };
    });
  };

  return (
    <div className="flex flex-col gap-4 w-full animate-in fade-in duration-300 relative z-10">
      <PageHeader 
        title="Ketersediaan Guru"
        description={tabSubtitles["ketersediaan"]}
        icon={Clock}
      />
      <section className="bg-white border-none rounded-[var(--ui-radius-card)] shadow-sm p-4 md:p-5">
        <div className="mt-4 grid grid-cols-2 lg:grid-cols-4 gap-3">
          {[
            {
              label: "Guru tampil",
              value: visibleAvailabilityTeachers.length,
              tone: "bg-slate-50 text-slate-700"
            },
            {
              label: "Sudah isi mapel",
              value: teachersWithSubjectsCount,
              tone: "bg-emerald-50 text-emerald-700"
            },
            {
              label: "Sudah isi hari",
              value: teachersWithDaysCount,
              tone: "bg-[var(--ui-primary)]/10 text-blue-700"
            },
            {
              label: "Total hari aktif",
              value: days.length,
              tone: "bg-amber-50 text-amber-700"
            },
          ].map((item) => (
            <div
              key={item.label}
              className={`rounded-[var(--ui-radius-small)] border-none p-3 ${item.tone}`}
            >
              <div className="text-2xl font-black">{item.value}</div>
              <div className="text-[10px] font-black uppercase tracking-widest opacity-70">
                {item.label}
              </div>
            </div>
          ))}
        </div>
      </section>

      <section className="grid grid-cols-1 xl:grid-cols-[320px_minmax(0,1fr)] gap-4">
        <aside className="bg-white border-none rounded-[var(--ui-radius-control)] shadow-sm p-4 h-fit xl:sticky xl:top-4">
          <h4 className="font-black text-slate-800 text-sm">
            Cara Penggunaan
          </h4>
          <div className="flex flex-col gap-2.5 mt-4">
            {[
              [
                "1",
                "Cari Guru",
                "Gunakan pencarian bila data guru banyak.",
              ],
              [
                "2",
                "Isi mapel",
                "Klik Ubah Mapel untuk daftar kompetensi.",
              ],
              [
                "3",
                "Centang hari",
                "Klik pill hari sampai aktif berwarna hijau.",
              ],
            ].map(([step, title, desc]) => (
              <div
                key={step}
                className="flex gap-3 rounded-[var(--ui-radius-small)] bg-slate-50 border-none p-3"
              >
                <div className="w-7 h-7 rounded-[var(--ui-radius-small)] bg-[var(--ui-primary)] text-white flex items-center justify-center text-xs font-black shrink-0">
                  {step}
                </div>
                <div>
                  <p className="text-xs font-black text-slate-800">
                    {title}
                  </p>
                  <p className="text-[11px] font-bold text-slate-500 mt-0.5 leading-relaxed">
                    {desc}
                  </p>
                </div>
              </div>
            ))}
          </div>
          <div className="mt-4 relative">
            <Search
              size={14}
              className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
            />
            <input
              type="text"
              value={searchTerm}
              onChange={(event) => setSearchTerm(event.target.value)}
              placeholder="Cari nama, kode, kategori..."
              className="w-full border-none bg-slate-50 pl-9 pr-3 py-2.5 rounded-[var(--ui-radius-small)] text-xs font-bold focus:bg-white focus:outline-[var(--ui-primary)]"
            />
          </div>
        </aside>

        <div className="grid grid-cols-1 2xl:grid-cols-2 gap-3">
          {visibleAvailabilityTeachers.length === 0 ? (
            <div className="rounded-[var(--ui-radius-small)] border border-dashed border-slate-200 bg-white p-6 text-center text-sm font-bold text-slate-400">
              Tidak ada guru yang cocok dengan pencarian.
            </div>
          ) : (
            visibleAvailabilityTeachers.map((t) => {
              const avail = teacherAvailability[t.code] || {
                days: [],
                subjects: [] };
              const activeDays = Array.isArray(avail.days)
                ? avail.days
                : [];
              const subjectsList = Array.isArray(avail.subjects)
                ? avail.subjects
                : [];
              return (
                <article
                  key={t.code}
                  className="bg-white border-none rounded-[var(--ui-radius-control)] shadow-sm p-4"
                >
                  <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3">
                    <div className="min-w-0">
                      <div className="flex flex-wrap items-center gap-2">
                        <h4 className="font-black text-slate-800 text-base truncate">
                          {t.name}
                        </h4>
                        <span className="px-2 py-1 rounded-[var(--ui-radius-small)] bg-slate-50 border-none text-[10px] font-black text-slate-500">
                          {t.code}
                        </span>
                      </div>
                      <p className="mt-1 text-[11px] font-bold text-slate-500">
                        {t.type || "Guru Umum"} - Target{" "}
                        {t.targetWeeklyJp || 0} JP/minggu
                      </p>
                    </div>
                    <Button
                      onClick={() =>
                        openModal("ketersediaan_mapel", "edit", t)
                      }
                      variant="secondary"
                      className="text-xs px-3 py-2 min-h-9"
                    >
                      <BookOpen size={14} /> Ubah Mapel
                    </Button>
                  </div>

                  <div className="mt-4 rounded-[var(--ui-radius-small)] bg-slate-50 border-none p-3">
                    <div className="flex items-center justify-between gap-2 mb-2">
                      <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                        Mapel Kompetensi
                      </p>
                      <span
                        className={`text-[10px] font-black px-2 py-0.5 rounded-[var(--ui-radius-small)] ${subjectsList.length ? "bg-emerald-100 text-emerald-700" : "bg-red-50 text-red-600"}`}
                      >
                        {subjectsList.length || 0} mapel
                      </span>
                    </div>
                    <div className="flex flex-wrap gap-1.5">
                      {subjectsList.length > 0 ? (
                        subjectsList.map((subject) => (
                          <span
                            key={subject}
                            className="bg-white border border-[var(--ui-primary)]/15 text-[var(--ui-primary)] text-[10px] px-2.5 py-1 rounded-[var(--ui-radius-small)] font-black"
                          >
                            {subject}
                          </span>
                        ))
                      ) : (
                        <span className="text-xs text-red-500 font-bold">
                          Belum ada mapel. Klik Ubah Mapel.
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="mt-4">
                    <div className="flex items-center justify-between gap-2 mb-2">
                      <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                        Hari Tersedia
                      </p>
                      <div className="flex gap-1">
                        <button
                          type="button"
                          onClick={() =>
                            setTeacherDays(t.code, [...days])
                          }
                          className="px-2 py-1 rounded-[var(--ui-radius-small)] bg-emerald-50 text-emerald-700 text-[10px] font-black border border-emerald-100"
                        >
                          Semua
                        </button>
                        <button
                          type="button"
                          onClick={() => setTeacherDays(t.code, [])}
                          className="px-2 py-1 rounded-[var(--ui-radius-small)] bg-white text-slate-500 text-[10px] font-black border-none"
                        >
                          Kosong
                        </button>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-2">
                      {days.map((day) => {
                        const checked = activeDays.includes(day);
                        return (
                          <button
                            key={day}
                            type="button"
                            onClick={() => toggleTeacherDay(t.code, day)}
                            className={`rounded-[var(--ui-radius-small)] border px-3 py-2 text-xs font-black transition-all ${checked ? "bg-[var(--ui-primary)] text-white border-[var(--ui-primary)] shadow-sm" : "bg-slate-50 text-slate-500 border-slate-200 hover:bg-white"}`}
                          >
                            {day}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                </article>
              );
            })
          )}
        </div>
      </section>
    </div>
  );
}

