import React from 'react';
import { base64ToBlobUrl } from '../../../utils/fileHelper.js';
import { Upload, FileText, Download, RefreshCw, BookOpen, BookOpenText, ChevronRight, Edit2, Trash2, Eye, X } from 'lucide-react';
import { Button } from '../../../components/monitoring/ui/index.js';
import { UISelect } from '../../../components/ui.jsx';


export default function TabSilabusGuru(props) {
  const { 
    syllabuses, currentUser, subjects, selectedTeacherSilabusSubject, selectedTeacherSilabusId, syllabusCategories, 
    newSyllabusSubject, setNewSyllabusSubject, setNewSyllabusTitle, newSyllabusTitle, newSyllabusCategory, 
    setNewSyllabusCategory, newSyllabusGrade, setNewSyllabusGrade, newSyllabusSemester, setNewSyllabusSemester, 
    newSyllabusObjectives, setNewSyllabusObjectives, newSyllabusMaterials, setNewSyllabusMaterials, newSyllabusNotes, 
    setNewSyllabusNotes, ensureDatabaseReadyForWrite, addSyllabus, setSelectedTeacherSilabusSubject, 
    setSelectedTeacherSilabusId, showNotification, openTeacherGuide, downloadTeacherTemplate, openModal, 
    handleRemoveSyllabusSafe,
    availableSubjects = [], availableClasses = [], myDocuments = [], fetchData, activeYear, authToken, handleDelete
  } = props;
  const [newSyllabusPdf, setNewSyllabusPdf] = React.useState(null);
  const fileInputRef = React.useRef(null);
  const [previewDoc, setPreviewDoc] = React.useState(null);

  const handlePreviewPdf = (doc) => {
    const blobUrl = base64ToBlobUrl(doc.file_url);
    setPreviewDoc({
      url: blobUrl,
      title: doc.nama_dokumen
    });
  };

  const [uploadMode, setUploadMode] = React.useState('manual'); // 'manual' | 'file'
  const [uploadForm, setUploadForm] = React.useState({
    mapel: '',
    kelas: 'X',
    semester: 'Ganjil',
    file_url: '',
    nama_dokumen: ''
  });
  const [isUploading, setIsUploading] = React.useState(false);

  const handlePdfUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const ext = file.name.substring(file.name.lastIndexOf('.')).toLowerCase();
    if (ext !== '.pdf') {
      showNotification("Hanya file dengan ekstensi .pdf yang diperbolehkan!", "error");
      e.target.value = '';
      return;
    }

    if (file.type !== "application/pdf") {
      showNotification("Hanya file PDF yang diperbolehkan!", "error");
      e.target.value = '';
      return;
    }
    if (file.size > 2 * 1024 * 1024) {
      showNotification("File terlalu besar! Batas maksimal ukuran PDF adalah 2MB agar tetap ringan.", "error");
      e.target.value = '';
      return;
    }
    const reader = new FileReader();
    reader.onload = (event) => {
      setNewSyllabusPdf({
        name: file.name,
        size: file.size,
        base64: event.target.result
      });
    };
    reader.readAsDataURL(file);
  };

  React.useEffect(() => {
    if (availableSubjects && availableSubjects.length > 0) {
      setUploadForm(prev => {
        if (prev.mapel && availableSubjects.includes(prev.mapel)) return prev;
        return { ...prev, mapel: availableSubjects[0] };
      });
    }
  }, [availableSubjects]);

  const handleFileUploadChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Check file extension
    const ext = file.name.substring(file.name.lastIndexOf('.')).toLowerCase();
    if (ext !== '.pdf') {
      showNotification(`Ekstensi file ${ext} tidak diizinkan. Hanya file .pdf yang diperbolehkan.`, 'error');
      e.target.value = '';
      return;
    }

    // Check file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
      showNotification('File terlalu besar. Maksimal ukuran file adalah 5MB.', 'error');
      e.target.value = '';
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setUploadForm(prev => ({ ...prev, file_url: reader.result, nama_dokumen: file.name }));
    };
    reader.readAsDataURL(file);
  };

  const handleUploadFileSubmit = async (e) => {
    e.preventDefault();
    if (!uploadForm.file_url) return showNotification('Pilih file Modul Ajar terlebih dahulu.', 'error');
    if (!activeYear) return showNotification('Tahun Ajaran aktif tidak terdeteksi.', 'error');
    if (!uploadForm.mapel) return showNotification('Pilih Mata Pelajaran.', 'error');
    if (!uploadForm.kelas) return showNotification('Pilih Tingkat Kelas.', 'error');
    if (!uploadForm.semester) return showNotification('Pilih Semester.', 'error');

    setIsUploading(true);
    try {
      const res = await fetch('/api/modul-ajar-guru', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${authToken}` },
        body: JSON.stringify({
          action: 'upload',
          teacher_code: currentUser.code || 'guru',
          teacher_name: currentUser.name || 'Guru',
          nama_dokumen: uploadForm.nama_dokumen,
          file_url: uploadForm.file_url,
          tahun_ajaran: activeYear,
          mapel: uploadForm.mapel,
          kelas: uploadForm.kelas,
          semester: uploadForm.semester
        })
      });
      const data = await res.json();
      if (data.ok) {
        showNotification('Modul Ajar berhasil diunggah!');
        setUploadForm({ 
          nama_dokumen: '', 
          file_url: '', 
          mapel: availableSubjects[0] || '',
          kelas: 'X',
          semester: 'Ganjil'
        });
        // Clear input element
        const fileInput = document.getElementById('upload-file-input');
        if (fileInput) fileInput.value = '';
        if (fetchData) fetchData();
      } else {
        showNotification(data.error || 'Gagal mengunggah', 'error');
      }
    } catch (e) {
      console.error(e);
      showNotification('Terjadi kesalahan saat mengunggah', 'error');
    } finally {
      setIsUploading(false);
    }
  };

  const { ...allProps } = props;
  // Destructure specific props as needed in the component

  const mySyllabuses = syllabuses
    .filter((s) => s.teacherCode === currentUser.code)
    .sort((a, b) =>
      `${a.subjectName || ""} ${a.title || ""}`.localeCompare(
        `${b.subjectName || ""} ${b.title || ""}`,
        "id",
        { sensitivity: "base" },
      ),
    );
  const uniqueSubjects = Array.from(new Set(subjects.map((s) => s.name)));
  const subjectsToUse = availableSubjects.length > 0 ? availableSubjects : uniqueSubjects;
  const myGroupedSyllabuses = mySyllabuses.reduce((acc, item) => {
    const key = item.subjectName || "Tanpa Mata Pelajaran";
    if (!acc[key]) acc[key] = [];
    acc[key].push(item);
    return acc;
  }, {});
  const mySubjectNames = Object.keys(myGroupedSyllabuses).sort((a, b) =>
    a.localeCompare(b, "id", { sensitivity: "base" }),
  );
  const activeTeacherSubject = mySubjectNames.includes(
    selectedTeacherSilabusSubject,
  )
    ? selectedTeacherSilabusSubject
    : mySubjectNames[0] || "";
  const activeTeacherMeetings = activeTeacherSubject
    ? myGroupedSyllabuses[activeTeacherSubject] || []
    : [];
  const activeTeacherSilabus =
    activeTeacherMeetings.find(
      (item) => item.id === selectedTeacherSilabusId,
    ) ||
    activeTeacherMeetings[0] ||
    null;
  const activeTeacherIndex = activeTeacherSilabus
    ? Math.max(
      activeTeacherMeetings.findIndex(
        (item) => item.id === activeTeacherSilabus.id,
      ),
      0,
    )
    : -1;
  const activeTeacherCategory = activeTeacherSilabus
    ? syllabusCategories?.find(
      (c) => c.id === activeTeacherSilabus.categoryId,
    )
    : null;
  const nextTeacherMeetingNumber =
    (newSyllabusSubject
      ? myGroupedSyllabuses[newSyllabusSubject]?.length || 0
      : activeTeacherMeetings.length) + 1;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Form (Manual or File Upload) */}
