            <PageHeader 
              title="Kustomisasi Tampilan Web"
              description="Personalisasi identitas, warna, dan informasi sekolah Anda."
              icon={MonitorSmartphone}
              tabs={[
                { id: "fitur", label: "Fitur", icon: Settings },
