                    {[
                      { id: "umum", label: "Identitas Utama", icon: LayoutTemplate },
                      { id: "layanan", label: "Menu Layanan", icon: Grid },
                      { id: "footer", label: "Informasi Jurusan", icon: GraduationCap },
