                      )}
                      <button type="button" onClick={autoFixContrast} className="text-[10px] font-bold bg-slate-100 text-slate-600 px-3 py-1.5 rounded-[var(--ui-radius-small)] hover:bg-slate-200 w-full mt-1 border-none cursor-pointer">Perbaiki Kontras</button>
