                              <button type="button" onClick={() => setCustomThemePresets(customThemePresets.filter((x) => x.name !== p.name))} className="text-[10px] font-bold px-2 py-1 rounded-[var(--ui-radius-small)] bg-red-50 text-red-600 hover:bg-red-100 border border-red-100 cursor-pointer">Hapus</button>
