import { useState, useEffect, useMemo, useCallback } from 'react';
import { MessageSquare } from 'lucide-react';
import useAuthStore from '../../store/monitoring/authStore.js';
import * as XLSX from 'xlsx';
import { Link } from 'react-router-dom';
import { X, AlertCircle, Plus, Users, Search, ChevronRight, Download, Calendar, Edit2, Trash2, CheckCircle2 } from 'lucide-react';
import { CustomSelect } from '../../components/CustomSelect.jsx';
import { Button, PageHeader } from '../../components/monitoring/ui/index.js';
import { PaginationControls } from '../../components/ui/PaginationControls.jsx';


const JENIS_CATATAN = [
  { value: 'umum', label: 'Catatan Umum', color: 'bg-slate-100 text-slate-700 border-slate-200' },
  { value: 'akademik', label: 'Akademik', color: 'bg-blue-100 text-blue-700 border-blue-200' },
  { value: 'perilaku', label: 'Perilaku', color: 'bg-amber-100 text-amber-700 border-amber-200' },
  { value: 'prestasi', label: 'Prestasi', color: 'bg-emerald-100 text-emerald-700 border-emerald-200' },
  { value: 'kesehatan', label: 'Kesehatan', color: 'bg-rose-100 text-rose-700 border-rose-200' },
  { value: 'konseling', label: 'Konsultasi', color: 'bg-purple-100 text-purple-700 border-purple-200' },
];

const getJenisInfo = (val) => JENIS_CATATAN.find(j => j.value === val) || JENIS_CATATAN[0];

// Modal Form Catatan Walikelas
function CatatanModal({ catatan, students = [], riwayatPoin = [], walasClass, onSave, onClose }) {
  const [form, setForm] = useState({
    id: catatan?.id || null,
    siswa_nis: catatan?.siswa_nis || '',
    siswa_name: catatan?.siswa_name || '',
    tanggal: catatan?.tanggal || new Date().toISOString().split('T')[0],
    jenis_catatan: catatan?.jenis_catatan || 'umum',
    isi_catatan: catatan?.isi_catatan || '',
    tindak_lanjut: catatan?.tindak_lanjut || '',
    poin_pelanggaran_id: catatan?.poin_pelanggaran_id || null,
    kelas: catatan?.kelas || walasClass || '',
  });
  const [saving, setSaving] = useState(false);
  const [showPoinPicker, setShowPoinPicker] = useState(false);

  // Filter poin milik siswa yang dipilih
  const siswaRiwayatPoin = useMemo(() => {
    if (!form.siswa_nis) return [];
    return riwayatPoin.filter(p => String(p.siswa_nis) === String(form.siswa_nis));
  }, [riwayatPoin, form.siswa_nis]);

  const handleSelectSiswa = (nis) => {
    const siswa = students.find(s => s.nis === nis || String(s.nis) === String(nis));
    setForm({
      ...form,
      siswa_nis: nis,
      siswa_name: siswa ? (siswa.namaSiswa || siswa.name || '') : ''
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.siswa_nis || !form.isi_catatan) {
      alert('Siswa dan isi catatan wajib diisi!');
      return;
    }
    setSaving(true);
    await onSave(form);
    setSaving(false);
  };

  const studentOptions = useMemo(() => {
    return students.map(s => ({
      value: String(s.nis),
      label: `${s.namaSiswa || s.name} (${s.nis})`
    }));
  }, [students]);

  const selectedPoin = form.poin_pelanggaran_id
    ? siswaRiwayatPoin.find(p => p.id === form.poin_pelanggaran_id)
    : null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white rounded-[var(--ui-radius-small)] shadow-sm w-full max-w-xl overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-200">
        <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50 shrink-0">
          <div>
            <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm">
              <MessageSquare size={16} className="text-violet-500" />
              {form.id ? 'Edit Catatan' : 'Tambah Catatan Wali Kelas'}
            </h3>
            {walasClass && <p className="text-[11px] font-semibold text-slate-500 mt-0.5">Kelas {walasClass}</p>}
          </div>
          <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-600 bg-transparent hover:bg-slate-100 rounded-[var(--ui-radius-small)] border-none cursor-pointer transition-colors">
            <X size={16} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-3.5 overflow-y-auto">
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2">
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                Siswa <span className="text-rose-500">*</span>
              </label>
              <CustomSelect
                options={studentOptions}
                value={form.siswa_nis ? String(form.siswa_nis) : ''}
                onChange={handleSelectSiswa}
                placeholder="Pilih atau cari siswa..."
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Tanggal</label>
              <input
                type="date"
                value={form.tanggal}
                onChange={e => setForm({ ...form, tanggal: e.target.value })}
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:outline-[var(--ui-primary)] focus:bg-white transition-all"
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Jenis Catatan</label>
              <select
                value={form.jenis_catatan}
                onChange={e => setForm({ ...form, jenis_catatan: e.target.value })}
                className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none focus:outline-[var(--ui-primary)] focus:bg-white transition-all"
              >
                {JENIS_CATATAN.map(j => <option key={j.value} value={j.value}>{j.label}</option>)}
              </select>
            </div>
          </div>

          <div>
            <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
              Isi Catatan / Hasil Diskusi <span className="text-rose-500">*</span>
            </label>
            <textarea
              rows={3}
              placeholder="Contoh: Hari ini saya memanggil siswa untuk mendiskusikan penurunan nilai pada mapel Matematika. Siswa mengaku kesulitan dengan materi aljabar..."
              value={form.isi_catatan}
              onChange={e => setForm({ ...form, isi_catatan: e.target.value })}
              className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:outline-[var(--ui-primary)] focus:bg-white transition-all resize-none"
              required
            />
          </div>

          <div>
            <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Tindak Lanjut (Opsional)</label>
            <textarea
              rows={2}
              placeholder="Rencana atau langkah tindak lanjut yang akan dilakukan..."
              value={form.tindak_lanjut}
              onChange={e => setForm({ ...form, tindak_lanjut: e.target.value })}
              className="w-full px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:outline-[var(--ui-primary)] focus:bg-white transition-all resize-none"
            />
          </div>

          {/* Koneksi ke Riwayat Poin */}
          {form.siswa_nis && siswaRiwayatPoin.length > 0 && (
            <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                <Link size={12} className="inline mr-1" />
                Kaitkan dengan Riwayat Pelanggaran (Opsional)
              </label>
              {selectedPoin ? (
                <div className="flex items-center gap-2 p-2 bg-amber-50 border border-amber-200 rounded-[var(--ui-radius-small)]">
                  <AlertCircle size={14} className="text-amber-600 shrink-0" />
                  <span className="text-xs font-semibold text-amber-800 flex-1">{selectedPoin.tindakan_nama} — {selectedPoin.poin} poin</span>
                  <button type="button" onClick={() => setForm({ ...form, poin_pelanggaran_id: null })} className="p-1 bg-transparent border-none cursor-pointer text-amber-500 hover:text-amber-700">
                    <X size={13} />
                  </button>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => setShowPoinPicker(!showPoinPicker)}
                  className="text-xs font-bold text-violet-600 hover:text-violet-800 border border-violet-200 hover:border-violet-300 bg-violet-50 hover:bg-violet-100 px-3 py-1.5 rounded-[var(--ui-radius-small)] transition-colors cursor-pointer"
                >
                  + Pilih riwayat pelanggaran siswa ini
                </button>
              )}

              {showPoinPicker && !selectedPoin && (
                <div className="mt-2 border border-slate-200 rounded-[var(--ui-radius-small)] overflow-hidden max-h-40 overflow-y-auto bg-white">
                  {siswaRiwayatPoin.map(p => (
                    <button
                      key={p.id}
                      type="button"
                      onClick={() => { setForm({ ...form, poin_pelanggaran_id: p.id }); setShowPoinPicker(false); }}
                      className="w-full text-left px-3 py-2 text-xs font-medium hover:bg-amber-50 border-b border-slate-100 last:border-0 cursor-pointer bg-transparent border-l-0 border-r-0 border-t-0 transition-colors"
                    >
                      <span className="font-bold text-slate-700">{p.tindakan_nama}</span>
                      <span className="text-amber-600 ml-2">{p.poin} poin</span>
                      <span className="text-slate-400 ml-2">{p.tanggal_kejadian ? new Date(p.tanggal_kejadian).toLocaleDateString('id-ID') : ''}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="pt-4 flex justify-end gap-3 border-t border-slate-100 shrink-0">
            <Button type="button" variant="outline" onClick={onClose} className="rounded-[var(--ui-radius-small)]">Batal</Button>
            <Button type="submit" disabled={saving} className="rounded-[var(--ui-radius-small)] bg-violet-600 hover:opacity-90">
              {saving ? 'Menyimpan...' : (form.id ? 'Update Catatan' : 'Simpan Catatan')}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

// Panel detail siswa
function SiswaCatatanPanel({ siswa, catatan = [], poin = [], onClose, onAddCatatan }) {
  const totalPoin = poin.reduce((sum, p) => sum + (parseInt(p.poin) || 0), 0);
  const catatanSiswa = catatan.filter(c => String(c.siswa_nis) === String(siswa?.nis));
  const poinSiswa = poin.filter(p => String(p.siswa_nis) === String(siswa?.nis));

  return (
    <div className="ui-card overflow-hidden border border-violet-100">
      <div className="px-4 py-3 bg-violet-600 flex items-center justify-between">
        <div>
          <h3 className="font-bold text-white text-xs">{siswa?.namaSiswa || siswa?.name}</h3>
          <p className="text-violet-200 text-[10px]">NIS: {siswa?.nis} · {siswa?.class_name}</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="text-right">
            <p className="text-white/70 text-[9px] uppercase font-bold">Total Poin</p>
            <p className={`font-black text-base ${totalPoin >= 100 ? 'text-red-300' : totalPoin >= 50 ? 'text-amber-300' : 'text-white'}`}>{totalPoin}</p>
          </div>
          <button onClick={onClose} className="p-1.5 bg-white/20 hover:bg-white/30 rounded-[var(--ui-radius-small)] border-none cursor-pointer text-white transition-colors">
            <X size={14} />
          </button>
        </div>
      </div>

      {/* Riwayat Poin Pelanggaran */}
      {poinSiswa.length > 0 && (
        <div className="p-3.5 border-b border-slate-100 bg-amber-50/20">
          <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-wider mb-2 flex items-center gap-1">
            <AlertCircle size={11} className="text-amber-500" /> Riwayat Pelanggaran
          </h4>
          <div className="space-y-1.5 max-h-32 overflow-y-auto">
            {poinSiswa.slice(0, 5).map(p => (
              <div key={p.id} className="flex items-center justify-between text-[11px] bg-amber-50/80 px-2 py-1 rounded-[var(--ui-radius-small)]">
                <span className="font-semibold text-slate-700">{p.tindakan_nama}</span>
                <span className="font-black text-amber-700 ml-2">{p.poin > 0 ? `+${p.poin}` : p.poin} poin</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Catatan Walikelas */}
      <div className="p-3.5">
        <div className="flex items-center justify-between mb-3">
          <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-wider flex items-center gap-1">
            <MessageSquare size={11} className="text-violet-500" /> Catatan Wali Kelas ({catatanSiswa.length})
          </h4>
          <button
            onClick={() => onAddCatatan(siswa)}
            className="flex items-center gap-1 text-[11px] font-bold text-violet-600 hover:text-violet-800 border border-violet-200 hover:border-violet-400 px-2 py-1 rounded-[var(--ui-radius-small)] bg-violet-50 hover:bg-violet-100 cursor-pointer transition-colors"
          >
            <Plus size={10} /> Tambah
          </button>
        </div>
        <div className="space-y-2 max-h-48 overflow-y-auto">
          {catatanSiswa.length === 0 ? (
            <p className="text-[11px] text-slate-400 text-center py-3">Belum ada catatan untuk siswa ini</p>
          ) : catatanSiswa.map(c => {
            const jenis = getJenisInfo(c.jenis_catatan);
            return (
              <div key={c.id} className="p-3 bg-slate-50 rounded-[var(--ui-radius-small)] border border-slate-100">
                <div className="flex items-center justify-between mb-1">
                  <span className={`text-[9px] font-black px-2 py-0.5 rounded-full border ${jenis.color}`}>{jenis.label}</span>
                  <span className="text-[9px] text-slate-400">{new Date(c.tanggal).toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })}</span>
                </div>
                <p className="text-[11px] text-slate-700 leading-relaxed">{c.isi_catatan}</p>
                {c.tindak_lanjut && (
                  <p className="text-[10px] text-slate-500 mt-1 italic">📌 {c.tindak_lanjut}</p>
                )}
                {c.poin_pelanggaran_id && (
                  <span className="inline-flex items-center gap-1 mt-1 text-[9px] font-bold text-amber-700 bg-amber-50 px-2 py-0.5 rounded border border-amber-100">
                    <Link size={8} /> Terkait pelanggaran
                  </span>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

export default function CatatanWaliKelas({ students = [], classes = [] }) {
  const user = useAuthStore(state => state.user);
  const authToken = user?.authToken;
  const role = user?.role || '';
  const isWalas = user?.isWalas;
  const walasClass = user?.walasClass || '';
  const teacherCode = user?.code || user?.id || '';
  const isKesiswaan = ['admin', 'superadmin'].includes(role) || (role === 'waka' && (user?.division || "").toLowerCase() === 'kesiswaan');
  const canAdd = isWalas || isKesiswaan;

  const [catatanList, setCatatanList] = useState([]);
  const [riwayatPoin, setRiwayatPoin] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [activeModal, setActiveModal] = useState(null);
  const [selectedSiswa, setSelectedSiswa] = useState(null);
  const [search, setSearch] = useState('');
  const [filterKelas, setFilterKelas] = useState(() => walasClass || 'all');
  const [filterJenis, setFilterJenis] = useState('all');
  const [toast, setToast] = useState(null);
  const [catatanPage, setCatatanPage] = useState(1);
  const [catatanPerPage, setCatatanPerPage] = useState(20);

  const showToast = (msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const fetchCatatan = useCallback(async () => {
    if (!authToken) return;
    setIsLoading(true);
    try {
      const params = new URLSearchParams();
      if (!isKesiswaan && walasClass) params.set('kelas', walasClass);
      if (filterJenis !== 'all') params.set('jenis', filterJenis);
      const res = await fetch(`/api/kesiswaan/catatan-walikelas?${params}`, {
        headers: { Authorization: `Bearer ${authToken}` }
      });
      const data = await res.json();
      if (data.ok) setCatatanList(data.data || []);
    } catch (e) { console.error(e); }
    setIsLoading(false);
  }, [authToken, isKesiswaan, walasClass, filterJenis]);

  const fetchRiwayatPoin = useCallback(async () => {
    if (!authToken) return;
    try {
      const res = await fetch('/api/kedisiplinan/riwayat', {
        headers: { Authorization: `Bearer ${authToken}` }
      });
      const data = await res.json();
      if (data.ok) setRiwayatPoin(data.data || []);
    } catch (e) { console.error(e); }
  }, [authToken]);

  useEffect(() => { fetchCatatan(); fetchRiwayatPoin(); }, [fetchCatatan, fetchRiwayatPoin]);

  const handleSave = async (form) => {
    try {
      const res = await fetch('/api/kesiswaan/catatan-walikelas', {
        method: 'POST',
        headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(form)
      });
      const data = await res.json();
      if (data.ok) {
        showToast('Catatan berhasil disimpan!');
        setActiveModal(null);
        fetchCatatan();
      } else {
        showToast(data.error || 'Gagal menyimpan catatan', 'error');
      }
    } catch (e) {
      showToast('Gagal menghubungi server', 'error');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Hapus catatan ini?')) return;
    try {
      await fetch('/api/kesiswaan/catatan-walikelas', {
        method: 'POST',
        headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delete', id })
      });
      showToast('Catatan dihapus');
      fetchCatatan();
    } catch (e) { showToast('Gagal menghapus', 'error'); }
  };

  // Daftar siswa kelas walikelas
  const siswaKelas = useMemo(() => {
    const targetKelas = isWalas ? walasClass : (filterKelas !== 'all' ? filterKelas : null);
    let result = students;
    if (targetKelas) result = result.filter(s => s.class_name === targetKelas);
    if (search) result = result.filter(s => (s.namaSiswa || s.name || '').toLowerCase().includes(search.toLowerCase()) || String(s.nis).includes(search));
    return result;
  }, [students, walasClass, isWalas, filterKelas, search]);

  const filteredCatatan = useMemo(() => {
    return catatanList.filter(c => {
      const matchSearch = !search || (c.siswa_name || '').toLowerCase().includes(search.toLowerCase()) || String(c.siswa_nis).includes(search);
      const matchKelas = filterKelas === 'all' || !filterKelas || c.kelas === filterKelas;
      const matchJenis = filterJenis === 'all' || c.jenis_catatan === filterJenis;
      return matchSearch && matchKelas && matchJenis;
    });
  }, [catatanList, search, filterKelas, filterJenis]);

  const classOptions = useMemo(() => [
    { value: 'all', label: 'Semua Kelas' },
    ...classes.map(c => ({ value: c.name, label: c.name }))
  ], [classes]);

  const exportExcel = () => {
    const data = filteredCatatan.map(c => ({
      Tanggal: new Date(c.tanggal).toLocaleDateString('id-ID'),
      Kelas: c.kelas || '',
      Siswa: c.siswa_name || c.siswa_nis,
      NIS: c.siswa_nis,
      'Jenis Catatan': getJenisInfo(c.jenis_catatan).label,
      'Isi Catatan': c.isi_catatan,
      'Tindak Lanjut': c.tindak_lanjut || '',
      'Walikelas': c.teacher_name || c.teacher_code,
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Catatan Walikelas');
    XLSX.writeFile(wb, `Catatan_Walikelas_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  // Stats
  const statsByJenis = useMemo(() => {
    const stats = {};
    JENIS_CATATAN.forEach(j => { stats[j.value] = 0; });
    catatanList.forEach(c => { if (stats[c.jenis_catatan] !== undefined) stats[c.jenis_catatan]++; });
    return stats;
  }, [catatanList]);

  return (
    <div className="flex flex-col gap-4 w-full animate-in fade-in duration-300">
      <PageHeader
        title="Catatan Wali Kelas"
        icon={MessageSquare}
        description="Pencatatan kegiatan monitoring dan konsultasi walikelas dengan siswa binaannya."
      />

      {/* Stat Pills */}
      <div className="flex flex-wrap gap-2">
        {JENIS_CATATAN.map(j => (
          <button
            key={j.value}
            onClick={() => setFilterJenis(filterJenis === j.value ? 'all' : j.value)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-[var(--ui-radius-small)] text-xs font-bold border transition-all cursor-pointer ${filterJenis === j.value ? j.color + ' border-current shadow-sm' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'}`}
          >
            {j.label}
            <span className="font-black">{statsByJenis[j.value] || 0}</span>
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* Kiri: Daftar Siswa (untuk walikelas) */}
        {(isWalas || isKesiswaan) && (
          <div className="ui-card overflow-hidden">
            <div className="px-4 py-2.5 border-b border-slate-100 bg-slate-50/50">
              <h3 className="font-bold text-slate-800 text-xs flex items-center gap-2">
                <Users size={14} className="text-violet-500" />
                Siswa Binaan {walasClass && `— ${walasClass}`}
              </h3>
            </div>
            <div className="p-3">
              <div className="relative mb-2.5">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="text"
                  placeholder="Cari siswa..."
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  className="w-full pl-8 pr-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-xs font-medium focus:outline-none focus:outline-[var(--ui-primary)] focus:bg-white transition-all"
                />
              </div>
              {!isWalas && (
                <div className="mb-1">
                  <CustomSelect
                    options={classOptions}
                    value={filterKelas}
                    onChange={v => setFilterKelas(v)}
                    placeholder="Filter Kelas"
                  />
                </div>
              )}
            </div>
            <div className="overflow-y-auto max-h-[360px] divide-y divide-slate-100/70">
              {siswaKelas.length === 0 ? (
                <p className="text-xs text-slate-400 text-center py-8">Tidak ada siswa ditemukan</p>
              ) : siswaKelas.map(siswa => {
                const siswaCatatan = catatanList.filter(c => String(c.siswa_nis) === String(siswa.nis));
                const siswaPoin = riwayatPoin.filter(p => String(p.siswa_nis) === String(siswa.nis));
                const totalPoin = siswaPoin.reduce((sum, p) => sum + (parseInt(p.poin) || 0), 0);
                const isSelected = selectedSiswa?.nis === siswa.nis;

                return (
                  <button
                    key={siswa.nis}
                    onClick={() => setSelectedSiswa(isSelected ? null : siswa)}
                    className={`w-full text-left px-4 py-2.5 hover:bg-violet-50 cursor-pointer border-none bg-transparent transition-colors ${isSelected ? 'bg-violet-50 border-l-2 border-l-violet-500' : ''}`}
                  >
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="font-bold text-slate-800 text-xs">{siswa.namaSiswa || siswa.name}</p>
                        <p className="text-[10px] text-slate-500">{siswa.nis}</p>
                      </div>
                      <div className="flex items-center gap-2">
                        {siswaCatatan.length > 0 && (
                          <span className="text-[9px] font-bold bg-violet-100 text-violet-700 px-1.5 py-0.5 rounded-full">
                            {siswaCatatan.length}
                          </span>
                        )}
                        {totalPoin >= 50 && (
                          <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${totalPoin >= 100 ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>
                            {totalPoin}p
                          </span>
                        )}
                        <ChevronRight size={12} className="text-slate-300" />
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Kanan: Panel Siswa atau Tabel Catatan */}
        <div className={`${isWalas || isKesiswaan ? 'lg:col-span-2' : 'lg:col-span-3'} flex flex-col gap-4`}>

          {/* Panel detail siswa (saat diklik) */}
          {selectedSiswa && (
            <SiswaCatatanPanel
              siswa={selectedSiswa}
              catatan={catatanList}
              poin={riwayatPoin}
              onClose={() => setSelectedSiswa(null)}
              onAddCatatan={(siswa) => setActiveModal({ siswa_nis: String(siswa.nis), siswa_name: siswa.namaSiswa || siswa.name, kelas: walasClass || siswa.class_name })}
            />
          )}

          {/* Tabel Semua Catatan */}
          <div className="ui-card overflow-hidden">
            <div className="px-5 py-3 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between">
              <h3 className="font-bold text-slate-800 text-xs flex items-center gap-2">
                <MessageSquare size={14} className="text-violet-500" />
                {selectedSiswa ? `Catatan untuk ${selectedSiswa.namaSiswa || selectedSiswa.name}` : 'Semua Catatan'}
                <span className="text-[11px] text-slate-400 font-normal">({filteredCatatan.length} catatan)</span>
              </h3>
              <div className="flex gap-2">
                {canAdd && (
                  <button
                    onClick={() => setActiveModal({ kelas: walasClass })}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-violet-600 text-white rounded-[var(--ui-radius-small)] text-xs font-bold hover:bg-violet-700 border-none cursor-pointer transition-all shadow-xs"
                  >
                    <Plus size={12} /> Tambah Catatan
                  </button>
                )}
                <button onClick={exportExcel} className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 text-slate-600 rounded-[var(--ui-radius-small)] text-xs font-bold hover:bg-slate-50 cursor-pointer transition-colors">
                  <Download size={12} /> Export
                </button>
              </div>
            </div>

            {isLoading ? (
              <div className="p-10 text-center text-slate-400 text-xs">Memuat catatan...</div>
            ) : filteredCatatan.length === 0 ? (
              <div className="p-10 text-center">
                <MessageSquare size={36} className="mx-auto text-violet-200 mb-3" />
                <h3 className="font-bold text-slate-500 text-xs">Belum Ada Catatan</h3>
                <p className="text-[11px] text-slate-400 mt-1">
                  {canAdd ? 'Klik tombol "+ Tambah Catatan" untuk mulai mencatat.' : 'Tidak ada catatan walikelas yang tersedia.'}
                </p>
              </div>
            ) : (
            <>
              <div className="divide-y divide-slate-100">
                {filteredCatatan
                  .slice((catatanPage - 1) * catatanPerPage, catatanPage * catatanPerPage)
                  .map(c => {
                  const jenis = getJenisInfo(c.jenis_catatan);
                  return (
                    <div key={c.id} className="p-4 hover:bg-slate-50/50 transition-colors">
                      <div className="flex items-start gap-4">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap mb-1.5">
                            <span className="font-bold text-slate-800 text-xs">{c.siswa_name || c.siswa_nis}</span>
                            <span className="text-slate-300 text-xs">·</span>
                            <span className="text-[10px] font-semibold text-slate-400">{c.kelas}</span>
                            <span className={`text-[9px] font-black px-2 py-0.5 rounded-full border ${jenis.color}`}>{jenis.label}</span>
                            {c.poin_pelanggaran_id && (
                              <span className="text-[9px] font-bold bg-amber-50 text-amber-700 border border-amber-100 px-1.5 py-0.5 rounded-full flex items-center gap-0.5">
                                <Link size={8} /> Terkait poin
                              </span>
                            )}
                          </div>
                          <p className="text-xs text-slate-700 leading-relaxed">{c.isi_catatan}</p>
                          {c.tindak_lanjut && (
                            <p className="text-[11px] text-slate-500 mt-1.5 bg-slate-50 px-2.5 py-1 rounded-[var(--ui-radius-small)] border-l-2 border-violet-400">
                              📌 <span className="font-semibold text-slate-600">Tindak Lanjut:</span> {c.tindak_lanjut}
                            </p>
                          )}
                          <div className="flex items-center gap-3 mt-2 text-[10px] text-slate-400">
                            <span className="flex items-center gap-1">
                              <Calendar size={10} /> {new Date(c.tanggal).toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
                            </span>
                            <span>oleh {c.teacher_name || c.teacher_code}</span>
                          </div>
                        </div>
                        <div className="flex gap-1 shrink-0 self-center">
                          <button onClick={() => setActiveModal(c)} className="p-1.5 text-slate-400 hover:text-blue-600 bg-transparent hover:bg-blue-50 rounded-[var(--ui-radius-small)] border-none cursor-pointer transition-colors">
                            <Edit2 size={12} />
                          </button>
                          <button onClick={() => handleDelete(c.id)} className="p-1.5 text-slate-400 hover:text-red-600 bg-transparent hover:bg-red-50 rounded-[var(--ui-radius-small)] border-none cursor-pointer transition-colors">
                            <Trash2 size={12} />
                          </button>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
              <PaginationControls
                currentPage={catatanPage}
                totalItems={filteredCatatan.length}
                itemsPerPage={catatanPerPage}
                onPageChange={(p) => { setCatatanPage(p); }}
                onItemsPerPageChange={(v) => { setCatatanPerPage(v); setCatatanPage(1); }}
              />
            </>
            )}
          </div>
        </div>
      </div>

      {/* Modal */}
      {activeModal && (
        <CatatanModal
          catatan={activeModal}
          students={siswaKelas.length > 0 ? siswaKelas : students.filter(s => !walasClass || s.class_name === walasClass)}
          riwayatPoin={riwayatPoin}
          walasClass={walasClass}
          onSave={handleSave}
          onClose={() => setActiveModal(null)}
        />
      )}

      {/* Toast */}
      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-sm font-semibold text-xs flex items-center gap-2 animate-in slide-in-from-bottom-5 ${toast.type === 'error' ? 'bg-red-600 text-white' : 'bg-emerald-600 text-white'}`}>
          <CheckCircle2 size={14} /> {toast.msg}
        </div>
      )}
    </div>
  );
}

import { useState, useMemo, useEffect, useCallback } from 'react';
import useAuthStore from '../../store/monitoring/authStore.js';
import { useAppStore } from '../../store/useAppStore.js';
import { loadInitialState } from '../../utils/state.js';
import * as XLSX from 'xlsx';
import { MonitorDot, Download, AlertOctagon, ShieldAlert, TrendingUp, Search, Users, Printer, BookOpen, History, Trash2, MessageSquare, AlertCircle, CheckCircle2 } from 'lucide-react';
import { CustomSelect } from '../../components/CustomSelect.jsx';
import { Button } from '../../components/monitoring/ui/index.js';
import { PaginationControls } from '../../components/ui/PaginationControls.jsx';
import { Modal } from '../../components/ui.jsx';


export default function DashboardBPBK({ students = [], classes = [] }) {
  const { kedisiplinanSettings } = useAppStore();
  const limit = kedisiplinanSettings?.batasPoinSiswaBermasalah || 100;
  const [riwayat, setRiwayat] = useState([]);
  const [konseling, setKonseling] = useState([]);

  const [search, setSearch] = useState("");
  const [filterClass, setFilterClass] = useState("all");

  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(20);

  const authToken = useAuthStore(state => state.user?.authToken);
  const [isLoading, setIsLoading] = useState(false);

  const [masterPoints, setMasterPoints] = useState([]);
  const [isAddingViolation, setIsAddingViolation] = useState(false);
  const [formViolation, setFormViolation] = useState({ tindakan_id: '', catatan: '', tanggal_kejadian: new Date().toISOString().split('T')[0] });

  const [selectedStudent, setSelectedStudent] = useState(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [formKonseling, setFormKonseling] = useState({ jenis_kasus: '', tindak_lanjut: '', catatan_konseling: '' });

  // For Printing SP
  const [spData, setSpData] = useState(null);
  const [toast, setToast] = useState(null);

  const appSettings = useMemo(() => {
    const defaults = { 
      useKopSuratGambar: false,
      kopSuratGambar: "",
      kopSuratLogo: "", 
      kopSuratBaris1: "", 
      kopSuratBaris2: "", 
      kopSuratBaris3: "", 
      primaryColor: "var(--ui-primary)" 
    };
    return { ...defaults, ...loadInitialState("appSettings", defaults) };
  }, []);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const fetchData = useCallback(async () => {
    if (!authToken) return;
    setIsLoading(true);
    try {
      const [resRiwayat, resKonseling, resMaster] = await Promise.all([
         fetch("/api/kedisiplinan/riwayat", { headers: { "Authorization": `Bearer ${authToken}` } }),
         fetch("/api/kedisiplinan/konseling", { headers: { "Authorization": `Bearer ${authToken}` } }),
         fetch("/api/kedisiplinan/master", { headers: { "Authorization": `Bearer ${authToken}` } })
      ]);
      const dataRiwayat = await resRiwayat.json();
      const dataKonseling = await resKonseling.json();
      const dataMaster = await resMaster.json();
      if (dataRiwayat.ok) setRiwayat(dataRiwayat.data || []);
      if (dataKonseling.ok) setKonseling(dataKonseling.data || []);
      if (dataMaster.ok) setMasterPoints(dataMaster.data || []);
    } catch (e) {
      console.error(e);
    }
    setIsLoading(false);
  }, [authToken]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  useEffect(() => {
    setCurrentPage(1);
  }, [search, filterClass]);

  const studentPoints = useMemo(() => {
    const map = {};
    students.forEach(s => {
      map[s.nis] = { ...s, total_poin: 0, catatan_terakhir: '-' };
    });
    riwayat.forEach(r => {
      if (map[r.siswa_nis]) {
        const isPrestasi = r.jenis?.toLowerCase() === 'prestasi';
        map[r.siswa_nis].total_poin += (r.poin || 0) * (isPrestasi ? -1 : 1);
        if (map[r.siswa_nis].catatan_terakhir === '-') {
          map[r.siswa_nis].catatan_terakhir = r.tindakan_nama;
        }
      }
    });
    // Ensure points are never negative for display
    Object.keys(map).forEach(nis => {
      map[nis].total_poin = Math.max(0, map[nis].total_poin);
    });
    return Object.values(map);
  }, [students, riwayat]);

  const filteredStudents = useMemo(() => {
    return studentPoints.filter(s => {
      const studentName = s.namaSiswa || s.name || '';
      const mClass = filterClass === "all" || s.class_name === filterClass;
      const mSearch = search === "" || studentName.toLowerCase().includes(search.toLowerCase()) || String(s.nis).toLowerCase().includes(search.toLowerCase());
      return mClass && mSearch;
    }).sort((a, b) => b.total_poin - a.total_poin);
  }, [studentPoints, search, filterClass]);

  const totalPages = Math.max(1, Math.ceil(filteredStudents.length / itemsPerPage));
  const safePage = Math.max(1, Math.min(currentPage, totalPages));
  const paginatedStudents = filteredStudents.slice((safePage - 1) * itemsPerPage, safePage * itemsPerPage);

  const openDetail = (s) => {
    setSelectedStudent(s);
    setShowDetailModal(true);
  };

  const saveKonseling = async (e) => {
    e.preventDefault();
    if (!authToken || !selectedStudent) return;
    try {
      const res = await fetch("/api/kedisiplinan/konseling", {
        method: "POST",
        headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({ siswa_nis: selectedStudent.nis, ...formKonseling })
      });
      if (res.ok) {
        showToast('Catatan konseling tersimpan.');
        setFormKonseling({ jenis_kasus: '', tindak_lanjut: '', catatan_konseling: '' });
        fetchData();
      }
    } catch (e) {
      console.error(e);
      showToast('Gagal menyimpan konseling', 'error');
    }
  };

  const saveViolation = async (e) => {
    e.preventDefault();
    if (!authToken || !selectedStudent || !formViolation.tindakan_id) return;

    const selectedMaster = masterPoints.find(m => String(m.id) === String(formViolation.tindakan_id));
    if (!selectedMaster) return;

    try {
      const res = await fetch("/api/kedisiplinan/riwayat", {
        method: "POST",
        headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          siswa_nis: selectedStudent.nis,
          tindakan_id: selectedMaster.id,
          tindakan_nama: selectedMaster.nama_tindakan,
          poin: selectedMaster.nilai_poin,
          jenis: selectedMaster.jenis,
          catatan: formViolation.catatan,
          tanggal_kejadian: formViolation.tanggal_kejadian
        })
      });
      if (res.ok) {
        showToast('Poin pelanggaran/prestasi berhasil ditambahkan.');
        setFormViolation({ tindakan_id: '', catatan: '', tanggal_kejadian: new Date().toISOString().split('T')[0] });
        setIsAddingViolation(false);

        // Refresh local points instantly
        const updatedRiwayatRes = await fetch("/api/kedisiplinan/riwayat", { headers: { "Authorization": `Bearer ${authToken}` } });
        const updatedRiwayat = await updatedRiwayatRes.json();
        if (updatedRiwayat.ok) {
          setRiwayat(updatedRiwayat.data || []);
          const newRiwayat = updatedRiwayat.data || [];
          const newTotal = newRiwayat.filter(r => r.siswa_nis === selectedStudent.nis).reduce((sum, r) => {
            const isPrestasi = r.jenis?.toLowerCase() === 'prestasi';
            return sum + (r.poin || 0) * (isPrestasi ? -1 : 1);
          }, 0);
          setSelectedStudent(prev => ({ ...prev, total_poin: Math.max(0, newTotal) }));
        }
        fetchData();
      }
    } catch (e) {
      console.error(e);
      showToast('Gagal menambahkan poin', 'error');
    }
  };

  const deleteKonseling = async (id) => {
    if (!await window.confirmAsync('Hapus catatan konseling ini?')) return;
    try {
      const res = await fetch("/api/kedisiplinan/konseling", {
        method: "POST",
        headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({ action: "delete", id })
      });
      if (res.ok) { showToast('Catatan konseling dihapus.'); fetchData(); }
    } catch (e) {
      console.error(e);
    }
  };

  const deleteRiwayat = async (id) => {
    if (!await window.confirmAsync('Hapus riwayat pelanggaran ini? Data poin siswa akan dikurangi kembali.')) return;
    try {
      const res = await fetch("/api/kedisiplinan/riwayat", {
        method: "POST",
        headers: { "Authorization": `Bearer ${authToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({ action: "delete", id })
      });
      if (res.ok) { 
        showToast('Riwayat pelanggaran dihapus.'); 

        const updatedRiwayatRes = await fetch("/api/kedisiplinan/riwayat", { headers: { "Authorization": `Bearer ${authToken}` } });
        const updatedRiwayat = await updatedRiwayatRes.json();
        if (updatedRiwayat.ok) {
          setRiwayat(updatedRiwayat.data || []);
          const newRiwayat = updatedRiwayat.data || [];
          const newTotal = newRiwayat.filter(r => r.siswa_nis === selectedStudent.nis).reduce((sum, r) => {
            const isPrestasi = r.jenis?.toLowerCase() === 'prestasi';
            return sum + (r.poin || 0) * (isPrestasi ? -1 : 1);
          }, 0);
          setSelectedStudent(prev => ({ ...prev, total_poin: Math.max(0, newTotal) }));
        }
        fetchData(); 
      }
    } catch (e) {
      console.error(e);
    }
  };

  const getStatusInfo = (poin) => {
    if (poin >= limit) return { label: "Kritis (DO)", type: "SP3", color: "bg-red-100 text-red-700" };
    if (poin >= Math.round(limit * 0.5)) return { label: "Peringatan 2", type: "SP2", color: "bg-amber-100 text-amber-700" };
    if (poin >= Math.round(limit * 0.2)) return { label: "Peringatan 1", type: "SP1", color: "bg-yellow-100 text-yellow-700" };
    return { label: "Aman", type: "Aman", color: "bg-slate-100 text-slate-700" };
