  const exportExcel = () => {
    const ws = XLSX.utils.json_to_sheet(filteredStudents.map(s => ({
      NIS: s.nis,
      Nama: s.namaSiswa || s.name,
      Kelas: s.class_name,
      "Total Poin": s.total_poin,
      "Pelanggaran Terakhir": s.catatan_terakhir
