  // Stat Cards
  const totalPantauan = studentPoints.filter(s => s.total_poin >= Math.round(limit * 0.2)).length;
  const totalKritis = studentPoints.filter(s => s.total_poin >= limit).length;
  const thisMonth = new Date().toISOString().slice(0, 7); // YYYY-MM
  const logsThisMonth = riwayat.filter(r => r.tanggal_kejadian.startsWith(thisMonth)).length;

