import { useState, useMemo, useEffect, useCallback } from 'react';
import { ShieldAlert, AlertTriangle, Clock, FileText } from 'lucide-react';
import useAuthStore from '../../store/monitoring/authStore.js';
import { CheckCircle2, Check, User, Search, X, History, ChevronRight, Trash2 } from 'lucide-react';
import { Button } from '../../components/monitoring/ui/index.js';
import { CustomSelect } from '../../components/CustomSelect.jsx';


const getViolationStyle = (poin) => {
  if (poin >= 20) return { icon: ShieldAlert, color: 'text-red-600', bg: 'bg-red-100' };
  if (poin >= 10) return { icon: AlertTriangle, color: 'text-orange-500', bg: 'bg-orange-50' };
  if (poin >= 5) return { icon: Clock, color: 'text-amber-500', bg: 'bg-amber-50' };
  return { icon: FileText, color: 'text-slate-500', bg: 'bg-slate-50' };
};

export default function PanelPiket({ students = [], classes = [] }) {
  const [search, setSearch] = useState("");
  const [filterClass, setFilterClass] = useState("all");

  // Selected students for POS operations
  const [selectedStudents, setSelectedStudents] = useState([]);
  const [selectedViolations, setSelectedViolations] = useState([]);

  const authToken = useAuthStore(state => state.user?.authToken);
  const [toast, setToast] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [confirmViolation, setConfirmViolation] = useState(false);
  const [history, setHistory] = useState([]);

  const [violations, setViolations] = useState([]);
  const [piketHariIni, setPiketHariIni] = useState(false);
  const [checkingPiket, setCheckingPiket] = useState(true);

  const todayName = useMemo(() => {
    const dayIdx = new Date().getDay();
    const days = ["Minggu", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu"];
    return days[dayIdx];
  }, []);

  // Fetch history
  const fetchHistory = useCallback(async () => {
    try {
      const res = await fetch("/api/kedisiplinan/riwayat", {
        headers: { "Authorization": `Bearer ${authToken}` }
      });
      const data = await res.json();
      if (data.ok) {
        // Filter only today's input from Piket
        const today = new Date().toISOString().split('T')[0];
        const piketHistory = (data.data || []).filter(r => r.tanggal_kejadian.startsWith(today) && r.catatan === 'Input Cepat Panel Piket');
        setHistory(piketHistory);
      }
    } catch (e) {
      console.error("Failed to fetch history", e);
    }
  }, [authToken]);

  const fetchMasterPoin = useCallback(async () => {
    try {
      const res = await fetch("/api/kedisiplinan/master", { headers: { "Authorization": `Bearer ${authToken}` } });
      const data = await res.json();
      if (data.ok && data.data) {
        setViolations(data.data.filter(v => v.jenis.toLowerCase() === 'pelanggaran'));
      }
    } catch (e) {
      console.error("Failed to fetch master poin", e);
    }
  }, [authToken]);

  useEffect(() => {
    fetchHistory();
    fetchMasterPoin();

    const checkTodayPiket = async () => {
      try {
        const res = await fetch("/api/kedisiplinan/jadwal", {
          headers: { "Authorization": `Bearer ${authToken}` }
        });
        const data = await res.json();
        if (data.ok && Array.isArray(data.data)) {

          const storageUser = localStorage.getItem('school_schedule_session_v1') || sessionStorage.getItem('school_schedule_session_v1');
          if (storageUser) {
            const userObj = JSON.parse(storageUser);
            const myCode = userObj?.code || userObj?.id;

            if (myCode) {
              let isOnDuty = false;
              data.data.forEach(s => {
                if (String(s.hari).toLowerCase() === todayName.toLowerCase()) {
                  let ids = s.guru_ids;
                  if (typeof ids === "string") {
                    try {
                      ids = JSON.parse(ids);
                    } catch {
                      // ignore parse error
                    }
                  }
                  if (Array.isArray(ids) && ids.some(id => String(id).trim().toLowerCase() === String(myCode).trim().toLowerCase())) {
                    isOnDuty = true;
                  }
                }
              });
              setPiketHariIni(isOnDuty);
            }
          }
        }
      } catch (e) {
        console.error(e);
      } finally {
        setCheckingPiket(false);
      }
    };
    checkTodayPiket();
  }, [authToken, fetchHistory, fetchMasterPoin]);

  // Filter students for left panel
  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const studentName = s.namaSiswa || s.name || '';
      const matchSearch = studentName.toLowerCase().includes(search.toLowerCase()) || String(s.nis).includes(search);
      const matchClass = filterClass === 'all' || s.class_name === filterClass;
      return matchSearch && matchClass;
    }).slice(0, 50); // Limit to 50 for performance
  }, [students, search, filterClass]);

  const toggleStudent = (student) => {
    setSelectedStudents(prev => {
      const exists = prev.find(s => s.nis === student.nis);
      if (exists) return prev.filter(s => s.nis !== student.nis);
      return [...prev, student];
    });
  };

  const toggleViolation = (violation) => {
    setSelectedViolations(prev => {
      const exists = prev.find(v => v.id === violation.id);
      if (exists) return prev.filter(v => v.id !== violation.id);
      return [...prev, violation];
    });
  };

  const showToast = (message, type = "success") => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const submitViolation = async () => {
    if (selectedStudents.length === 0) {
       showToast("Pilih minimal 1 siswa terlebih dahulu!", "error");
       return;
    }
    if (selectedViolations.length === 0) {
       showToast("Pilih minimal 1 pelanggaran!", "error");
       return;
    }
    setIsSubmitting(true);

    try {
      let promises = [];
      selectedStudents.forEach(student => {
         selectedViolations.forEach(violation => {
            const payload = {
              siswa_nis: student.nis,
              tindakan_id: violation.id,
              tindakan_nama: violation.nama_tindakan,
              poin: violation.nilai_poin,
              jenis: violation.jenis,
              catatan: 'Input Cepat Panel Piket'
            };
            promises.push(
               fetch("/api/kedisiplinan/riwayat", {
                 method: "POST",
                 headers: {
                   "Content-Type": "application/json",
                   "Authorization": `Bearer ${authToken}`
                 },
                 body: JSON.stringify(payload)
               })
            );
         });
      });

      const results = await Promise.all(promises);
      const allOk = results.every(res => res.ok);

      if (allOk) {
         showToast("Berhasil menyimpan pelanggaran & mengirim WA!", "success");

         const violationsStr = selectedViolations.map(v => v.nama_tindakan).join(', ');
         const totalPoin = selectedViolations.reduce((sum, v) => sum + v.nilai_poin, 0);

         // Trigger WA notifications asynchronously
         selectedStudents.forEach(student => {
            const phone = student.phone || student.wa_ortu;
            if (phone) {
               fetch("/api/whatsapp/send", {
                 method: "POST",
                 headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
                 body: JSON.stringify({
                   phone: phone,
                   message: `[INFO KEDISIPLINAN]\nNama: ${student.namaSiswa || student.name}\nPelanggaran: ${violationsStr}\nPoin Tambahan: +${totalPoin}\n\nMohon kerjasamanya untuk membimbing putra/putri Bapak/Ibu. Terima kasih.`,
                   trigger_type: 'kedisiplinan_cepat'
                 })
               }).catch(e => console.error("WA Trigger error", e));
            }
         });

         setSelectedStudents([]); // Clear selection after success
         setSelectedViolations([]); // Clear selected violations
         fetchHistory(); // Refresh history
         setConfirmViolation(false); // Close modal
      } else {
         showToast("Ada kesalahan saat menyimpan beberapa data.", "error");
      }
    } catch (e) {
      console.error(e);
      showToast("Gagal terhubung ke server.", "error");
    } finally {
      setIsSubmitting(false);
    }
  };

  const deleteHistory = async (id) => {
    if (!await window.confirmAsync("Hapus riwayat pelanggaran ini? Data poin siswa akan dikurangi kembali.")) return;
    try {
      const res = await fetch("/api/kedisiplinan/riwayat", {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${authToken}` },
        body: JSON.stringify({ action: "delete", id })
      });
      if (res.ok) {
        showToast("Riwayat pelanggaran berhasil dihapus", "success");
        fetchHistory();
      }
    } catch (e) {
      console.error(e);
      showToast("Gagal menghapus riwayat", "error");
    }
  };

  return (
    <div className="flex flex-col gap-4 w-full animate-in fade-in duration-300 relative z-10 h-full">
      {!piketHariIni && !checkingPiket && (
        <div className="bg-amber-50/70 border border-amber-200/80 rounded-2xl p-4 flex items-start gap-3 text-amber-800 animate-in fade-in duration-300 shadow-sm">
          <AlertTriangle className="text-amber-500 shrink-0 mt-0.5" size={18} />
          <div className="flex flex-col">
            <span className="text-[12px] font-black leading-tight">Tidak ada jadwal piket pada hari {todayName}</span>
            <span className="text-[10px] font-bold text-amber-600 mt-1">
              Anda tetap dapat mengakses menu piket, mendata siswa, dan menginput poin pelanggaran.
            </span>
          </div>
        </div>
      )}
      <div className="flex flex-col lg:flex-row gap-6 flex-1 min-h-0">
      {/* Toast Notification */}
      {toast && (
        <div className={`fixed top-4 right-4 z-50 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-sm border flex items-center gap-3 transition-all ${
          toast.type === "success" ? "bg-emerald-50 border-emerald-200 text-emerald-800" : "bg-red-50 border-red-200 text-red-800"
        }`}>
          {toast.type === "success" ? <CheckCircle2 size={20} className="text-emerald-500"/> : <AlertTriangle size={20} className="text-red-500"/>}
          <p className="font-bold text-sm">{toast.message}</p>
        </div>
      )}

      {/* Confirmation Modal */}
      {confirmViolation && (
         <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
            <div className="bg-white rounded-[var(--ui-radius-small)] shadow-sm w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-200">
               <div className="p-6">
                  <div className="w-12 h-12 rounded-full bg-amber-100 flex items-center justify-center mb-4 mx-auto">
                     <ShieldAlert size={24} className="text-amber-600" />
                  </div>
                  <h3 className="text-xl font-black text-slate-800 text-center mb-2">Konfirmasi Tindakan</h3>
                  <p className="text-slate-500 text-center text-sm mb-6">
                     Anda akan menyimpan <strong className="text-slate-700">{selectedViolations.length} pelanggaran</strong> untuk <strong className="text-slate-700">{selectedStudents.length} siswa</strong>. Notifikasi WhatsApp akan <strong className="text-red-500">langsung dikirimkan</strong> ke orang tua masing-masing siswa (jika nomor terdaftar). Lanjutkan?
                  </p>

                  <div className="bg-slate-50 rounded-[var(--ui-radius-small)] p-3 text-xs text-slate-600 mb-2 border-none max-h-[80px] overflow-y-auto">
                     <span className="font-bold text-slate-700 block mb-1">Daftar Pelanggaran ({selectedViolations.reduce((sum, v) => sum + v.nilai_poin, 0)} Poin):</span>
                     {selectedViolations.map(v => v.nama_tindakan).join(", ")}
                  </div>

                  <div className="bg-slate-50 rounded-[var(--ui-radius-small)] p-3 text-xs text-slate-600 mb-6 border-none max-h-[80px] overflow-y-auto">
                     <span className="font-bold text-slate-700 block mb-1">Daftar Siswa:</span>
                     {selectedStudents.map(s => s.namaSiswa || s.name).join(", ")}
                  </div>

                  <div className="flex gap-3">
                     <Button 
                        variant="outline"
                        onClick={() => setConfirmViolation(false)}
                        disabled={isSubmitting}
                        className="flex-1 rounded-[var(--ui-radius-small)]"
                     >
                        Batal
                     </Button>
                     <Button 
                        onClick={() => submitViolation()}
                        disabled={isSubmitting}
                        className="flex-1 rounded-[var(--ui-radius-small)] flex items-center justify-center gap-2"
                     >
                        {isSubmitting ? (
                           <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                        ) : (
                           <><Check size={16}/> Ya, Kirim & Simpan</>
                        )}
                     </Button>
                  </div>
               </div>
            </div>
         </div>
      )}

      {/* LEFT PANEL: Student Selector */}
      <div className="w-full lg:w-1/3 ui-card flex flex-col overflow-hidden">
         <div className="p-4 border-b border-slate-100 bg-slate-50">
            <h2 className="font-bold text-slate-800 mb-3 flex items-center gap-2">
               <User size={18} className="text-[var(--ui-primary)]"/> Pilih Siswa
            </h2>
            <div className="space-y-3">
               <div className="relative">
                 <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                 <input 
                   type="text"
                   placeholder="Cari nama atau NIS..."
                   value={search}
                   onChange={(e) => setSearch(e.target.value)}
                   className="w-full pl-9 pr-4 py-2 bg-white border-none rounded-[var(--ui-radius-small)] text-sm font-medium focus:outline-none focus:border-[var(--ui-primary)]"
                 />
               </div>
               <div className="w-full">
                  <CustomSelect 
                     options={[{value: 'all', label: 'Semua Kelas'}, ...(classes || []).map(c => ({value: c.name, label: c.name}))]}
                     value={filterClass}
                     onChange={setFilterClass}
                  />
               </div>
            </div>
         </div>
         <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {filteredStudents.map(student => {
               const isSelected = selectedStudents.some(s => s.nis === student.nis);
               return (
                  <button 
                     key={student.nis}
                     onClick={() => toggleStudent(student)}
                     className={`w-full text-left px-3 py-2.5 rounded-[var(--ui-radius-small)] flex items-center justify-between transition-colors ${
                        isSelected ? 'bg-[var(--ui-accent)] text-white font-bold shadow-sm' : 'hover:bg-slate-50'
                     }`}
                  >
                     <div>
                        <div className="text-sm">{student.namaSiswa || student.name}</div>
                        <div className="text-[10px] opacity-70 font-semibold">{student.nis} • {student.class_name}</div>
                     </div>
                     {isSelected && <Check size={16} />}
                  </button>
               );
            })}
            {filteredStudents.length === 0 && (
               <div className="text-center py-8 text-slate-400 text-sm">Siswa tidak ditemukan</div>
            )}
         </div>
      </div>

      {/* RIGHT PANEL: Quick Action POS */}
      <div className="w-full lg:w-2/3 flex flex-col gap-6 h-[calc(100vh-160px)]">
         {/* Selected Tray */}
         <div className="ui-card p-4">
            <div className="flex items-center justify-between mb-3">
               <h2 className="font-bold text-slate-800 flex items-center gap-2">
                  <CheckCircle2 size={18} className="text-emerald-600"/> Terpilih ({selectedStudents.length})
               </h2>
               {selectedStudents.length > 0 && (
                  <button onClick={() => setSelectedStudents([])} className="text-xs text-red-500 hover:underline font-bold">Kosongkan</button>
               )}
            </div>

            <div className="min-h-[80px] p-3 bg-slate-50 border-none rounded-[var(--ui-radius-small)] flex flex-wrap gap-2">
               {selectedStudents.length === 0 ? (
                  <div className="w-full h-full flex items-center justify-center text-slate-400 text-sm italic">
                     Belum ada siswa yang dipilih. Cari & klik siswa di panel kiri.
                  </div>
               ) : (
                  selectedStudents.map(student => (
                     <span key={student.nis} className="inline-flex items-center gap-1.5 px-3 py-1 bg-white border-none rounded-[var(--ui-radius-small)] text-xs font-bold text-slate-700 shadow-sm">
                        {student.namaSiswa || student.name}
                        <button onClick={() => toggleStudent(student)} className="text-slate-400 hover:text-red-500"><X size={12}/></button>
                     </span>
                  ))
               )}
            </div>
         </div>

         {/* POS Action Grid */}
         <div className="ui-card p-6 flex-shrink-0 overflow-y-auto" style={{ maxHeight: '50%' }}>
            <h2 className="font-bold text-slate-800 mb-1 flex items-center gap-2">
               <ShieldAlert size={18} className="text-[var(--ui-primary)]"/> Input Pelanggaran Cepat
            </h2>
            <p className="text-sm text-slate-500 mb-6">Pilih siswa di atas, lalu klik pelanggaran di bawah ini (bisa pilih lebih dari 1).</p>

            <div className="grid grid-cols-2 lg:grid-cols-3 gap-4 mb-6">
               {violations.length === 0 ? (
                  <div className="col-span-full py-8 text-center text-slate-500 italic border border-dashed border-slate-200 rounded-[var(--ui-radius-small)]">
                     Belum ada master poin pelanggaran. Silakan tambahkan di menu Master Poin Kedisiplinan.
                  </div>
               ) : (
                  violations.map(v => {
                     const style = getViolationStyle(v.nilai_poin);
                     const Icon = style.icon;
                     const isSelected = selectedViolations.some(sv => sv.id === v.id);
                     return (
                        <button 
                           key={v.id}
                           disabled={selectedStudents.length === 0 || isSubmitting}
                           onClick={() => toggleViolation(v)}
                           className={`flex flex-col items-center justify-center p-4 rounded-xl border text-center transition-all ${
                              selectedStudents.length === 0 
                              ? 'opacity-50 cursor-not-allowed border-slate-200 bg-slate-50 grayscale' 
                              : isSelected 
                                 ? 'border-[var(--ui-primary)] bg-[var(--ui-primary)]/5 shadow-sm' 
                                 : 'border-slate-200 hover:border-[var(--ui-primary)] cursor-pointer bg-white'
                           }`}
                        >
                           <div className={`p-3 rounded-[var(--ui-radius-small)] mb-3 ${style.bg} ${isSelected ? 'ring-2 ring-[var(--ui-primary)] ring-offset-2' : ''}`}>
                              <Icon size={24} className={style.color} />
                           </div>
                           <h3 className={`text-sm font-bold leading-tight mb-1 ${isSelected ? 'text-[var(--ui-primary)]' : 'text-slate-700'}`}>{v.nama_tindakan}</h3>
                           <span className={`text-[10px] font-black px-2 py-0.5 rounded-[var(--ui-radius-small)] ${isSelected ? 'text-white bg-red-500' : 'text-red-500 bg-red-50'}`}>+{v.nilai_poin} POIN</span>
                        </button>
                     );
                  })
               )}
            </div>

            <div className="flex justify-end pt-4 border-t border-slate-100">
               <Button 
                  onClick={() => setConfirmViolation(true)}
                  disabled={selectedStudents.length === 0 || selectedViolations.length === 0 || isSubmitting}
                  className="rounded-[var(--ui-radius-small)] flex items-center justify-center gap-2"
               >
                  <CheckCircle2 size={18} /> Simpan & Kirim Pesan
               </Button>
            </div>
         </div>

         {/* History Section */}
         <div className="ui-card p-6 flex flex-col flex-1 overflow-hidden">
            <h2 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
               <History size={18} className="text-[var(--ui-primary)]"/> Riwayat Input Hari Ini
            </h2>
            {history.length === 0 ? (
               <div className="text-center py-6 text-slate-400 text-sm italic bg-slate-50 rounded-[var(--ui-radius-small)] border border-dashed border-slate-200">
                  Belum ada pelanggaran yang diinput hari ini.
               </div>
            ) : (
               <div className="space-y-2 flex-1 overflow-y-auto pr-2">
                  {history.map(item => {
                     const student = students.find(s => s.nis === item.siswa_nis);
                     const studentName = student ? (student.namaSiswa || student.name) : item.siswa_nis;
                     return (
                        <div key={item.id} className="flex justify-between items-center p-3 border-none bg-slate-50 rounded-[var(--ui-radius-small)]">
                           <div>
                              <div className="font-bold text-slate-700 text-sm flex items-center gap-2">
                                 {studentName} <ChevronRight size={12} className="text-slate-400"/> <span className="text-red-600">{item.tindakan_nama}</span>
                              </div>
                              <div className="text-[10px] text-slate-500 font-semibold mt-0.5">
                                 {new Date(item.tanggal_kejadian).toLocaleTimeString('id-ID', {hour: '2-digit', minute:'2-digit'})} WIB • Oleh: {item.pelapor_nama}
                              </div>
                           </div>
                           <div className="flex items-center gap-3">
                              <span className="text-xs font-black text-red-500 bg-white border border-red-100 px-2.5 py-1 rounded-[var(--ui-radius-small)] shadow-sm">
                                 +{item.poin}
                              </span>
                              <button onClick={() => deleteHistory(item.id)} className="text-slate-300 hover:text-red-500 transition-colors p-1" title="Hapus Riwayat">
                                 <Trash2 size={16}/>
                              </button>
                           </div>
                        </div>
                     );
                  })}
               </div>
            )}
         </div>
         </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo, useCallback } from 'react';
import useAuthStore from '../../store/monitoring/authStore.js';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import { loadInitialState } from '../../utils/state.js';
import { FileSpreadsheet, Download, Search, Users, FileText, TrendingUp, AlertOctagon, Trophy, Printer, X } from 'lucide-react';
import { Button } from '../../components/monitoring/ui/index.js';
import { CustomSelect } from '../../components/CustomSelect.jsx';
import { PaginationControls } from '../../components/ui/PaginationControls.jsx';


export default function RekapKedisiplinan({ classes = [], students = [] }) {
  const [riwayat, setRiwayat] = useState([]);
  const [absensi, setAbsensi] = useState([]);
  const [toast, setToast] = useState(null);
  const authToken = useAuthStore(state => state.user?.authToken);
  const [isLoading, setIsLoading] = useState(false);
  const [filterBulan, setFilterBulan] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [filterKelas, setFilterKelas] = useState("all");
  const [searchSiswa, setSearchSiswa] = useState('');
  const [selectedStudentForRapor, setSelectedStudentForRapor] = useState(null);
  const [raporPaperSize, setRaporPaperSize] = useState('A4'); // 'A4' | 'F4'
  const [activeSection, setActiveSection] = useState('siswa');
  const [siswaPage, setSiswaPage] = useState(1);
  const [siswaPerPage, setSiswaPerPage] = useState(20);
  const [lbPage, setLbPage] = useState(1);
  const [lbPerPage, setLbPerPage] = useState(20);

  const appSettings = useMemo(() => {
    const defaults = { 
      useKopSuratGambar: false,
      kopSuratGambar: "",
      kopSuratLogo: "", 
      kopSuratBaris1: "", 
      kopSuratBaris2: "", 
      kopSuratBaris3: "", 
      primaryColor: "var(--ui-primary)" 
    };
    return { ...defaults, ...loadInitialState("appSettings", defaults) };
  }, []);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const fetchData = useCallback(async () => {
    if (!authToken) return;
    setIsLoading(true);
    try {
      const [resRiwayat, resAbsensi] = await Promise.all([
        fetch("/api/kedisiplinan/riwayat", { headers: { "Authorization": `Bearer ${authToken}` } }),
        fetch("/api/kedisiplinan/absensi", { headers: { "Authorization": `Bearer ${authToken}` } })
      ]);
      const dataRiwayat = await resRiwayat.json();
      const dataAbsensi = await resAbsensi.json();
      if (dataRiwayat.ok) setRiwayat(dataRiwayat.data || []);
      if (dataAbsensi.ok) setAbsensi(dataAbsensi.data || []);
    } catch (e) {
      console.error(e);
      showToast('Gagal memuat data rekap', 'error');
    }
    setIsLoading(false);
  }, [authToken]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const filteredRiwayat = useMemo(() => {
    return riwayat.filter(r => {
      const student = students.find(s => s.nis === r.siswa_nis);
      const mBulan = filterBulan === "" || r.tanggal_kejadian.startsWith(filterBulan);
      const mKelas = filterKelas === "all" || (student && student.class_name === filterKelas);
      return mBulan && mKelas;
    });
  }, [riwayat, filterBulan, filterKelas, students]);

  const filteredAbsensi = useMemo(() => {
    return absensi.filter(a => {
      const student = students.find(s => s.nis === a.siswa_nis);
      const mBulan = filterBulan === "" || a.tanggal.startsWith(filterBulan);
      const mKelas = filterKelas === "all" || (student && student.class_name === filterKelas);
      return mBulan && mKelas;
    });
  }, [absensi, filterBulan, filterKelas, students]);

  // Aggregate student score
  const studentScores = useMemo(() => {
    const map = {};
    riwayat.forEach(r => {
      if (!map[r.siswa_nis]) {
        map[r.siswa_nis] = 0;
      }
      const isPrestasi = r.jenis?.toLowerCase() === 'prestasi';
      map[r.siswa_nis] += r.poin * (isPrestasi ? -1 : 1);
    });
    return map;
  }, [riwayat]);

  // Aggregate student attendance
  const studentAttendance = useMemo(() => {
    const map = {};
    absensi.forEach(a => {
      if (!map[a.siswa_nis]) {
        map[a.siswa_nis] = { hadir: 0, sakit: 0, izin: 0, alpa: 0 };
      }
      if (a.status === 'Sakit') map[a.siswa_nis].sakit += 1;
      else if (a.status === 'Izin') map[a.siswa_nis].izin += 1;
      else if (a.status === 'Alpa' || a.status === 'Belum Scan') map[a.siswa_nis].alpa += 1;
      else map[a.siswa_nis].hadir += 1;
    });
    return map;
  }, [absensi]);

  // Filtered Students List
  const filteredStudentsList = useMemo(() => {
    const list = students.filter(s => {
      const mKelas = filterKelas === "all" || s.class_name === filterKelas;
      const nameVal = s.name || s.nama || s.namaSiswa || "";
      const mSearch = !searchSiswa.trim() || 
        nameVal.toLowerCase().includes(searchSiswa.toLowerCase()) || 
        String(s.nis).includes(searchSiswa);
      return mKelas && mSearch;
    });

    // Sort alphabetically by name
    return list.sort((a, b) => {
      const nameA = a.name || a.nama || a.namaSiswa || "";
      const nameB = b.name || b.nama || b.namaSiswa || "";
      return nameA.localeCompare(nameB);
    });
  }, [students, filterKelas, searchSiswa]);

  // Leaderboard of top violations
  const leaderboard = useMemo(() => {
    const map = {};
    filteredRiwayat.forEach(r => {
      if (!map[r.siswa_nis]) {
        const student = students.find(s => s.nis === r.siswa_nis);
        map[r.siswa_nis] = {
          nis: r.siswa_nis,
          name: student ? (student.name || student.nama || student.namaSiswa) : r.siswa_nis,
          class_name: student ? student.class_name : 'Unknown',
          total_poin: 0,
          kasus_count: 0
        };
      }
      const isPrestasi = r.jenis?.toLowerCase() === 'prestasi';
      map[r.siswa_nis].total_poin += r.poin * (isPrestasi ? -1 : 1);
      map[r.siswa_nis].kasus_count += 1;
    });
    Object.keys(map).forEach(nis => {
      map[nis].total_poin = Math.max(0, map[nis].total_poin);
    });
    const all = Object.values(map).sort((a, b) => b.total_poin - a.total_poin);
    if (!searchSiswa.trim()) return all.slice(0, 15);
    return all.filter(lb =>
      lb.name.toLowerCase().includes(searchSiswa.toLowerCase()) ||
      lb.nis.includes(searchSiswa)
    );
  }, [filteredRiwayat, students, searchSiswa]);

  const classStats = useMemo(() => {
    const map = {};
    classes.forEach(c => {
      map[c.name] = { class_name: c.name, poin: 0, alpa: 0, sakit: 0, izin: 0, total_students: 0, avg_score: 100 };
    });

    // Count students per class
    students.forEach(s => {
      if (s.class_name && map[s.class_name]) {
        map[s.class_name].total_students += 1;
      }
    });

    filteredRiwayat.forEach(r => {
      const student = students.find(s => s.nis === r.siswa_nis);
      if (student && map[student.class_name]) {
        const isPrestasi = r.jenis?.toLowerCase() === 'prestasi';
        map[student.class_name].poin += r.poin * (isPrestasi ? -1 : 1);
      }
    });

    Object.keys(map).forEach(clsName => {
      map[clsName].poin = Math.max(0, map[clsName].poin);
    });

    filteredAbsensi.forEach(a => {
      const student = students.find(s => s.nis === a.siswa_nis);
      if (student && map[student.class_name]) {
        if (a.status === 'Alpa') map[student.class_name].alpa += 1;
        if (a.status === 'Sakit') map[student.class_name].sakit += 1;
        if (a.status === 'Izin') map[student.class_name].izin += 1;
      }
    });

    // Calculate average score per class
    Object.keys(map).forEach(clsName => {
      const cls = map[clsName];
      if (cls.total_students > 0) {
        let totalScoreSum = 0;
        const clsStudents = students.filter(s => s.class_name === clsName);
        clsStudents.forEach(stud => {
          const deductions = studentScores[stud.nis] || 0;
          totalScoreSum += Math.max(0, 100 - deductions);
        });
        cls.avg_score = Math.round(totalScoreSum / cls.total_students);
      }
    });

    return Object.values(map).sort((a, b) => b.poin - a.poin);
  }, [filteredRiwayat, filteredAbsensi, classes, students, studentScores]);

  const exportExcel = () => {
    const wb = XLSX.utils.book_new();

    // Prepare Students Recap sheet
    const studentsRecapData = filteredStudentsList.map((s, idx) => {
      const name = s.name || s.nama || s.namaSiswa || "";
      const att = studentAttendance[s.nis] || { hadir: 0, sakit: 0, izin: 0, alpa: 0 };
      const score = Math.max(0, 100 - (studentScores[s.nis] || 0));
      return {
        "No": idx + 1,
        "NIS": s.nis,
        "Nama Siswa": name,
        "Kelas": s.class_name || "-",
        "Hadir": att.hadir,
        "Sakit": att.sakit,
        "Izin": att.izin,
        "Alpa": att.alpa,
        "Skor Kredit": score
      };
    });

    const wsStudents = XLSX.utils.json_to_sheet(studentsRecapData);
    XLSX.utils.book_append_sheet(wb, wsStudents, "Rekap_Siswa");

    const wsClassStats = XLSX.utils.json_to_sheet(classStats.map(cs => ({
      "Kelas": cs.class_name,
      "Total Poin Pelanggaran": cs.poin,
      "Rata-rata Skor Kredit": cs.avg_score,
      "Total Alpa": cs.alpa,
      "Total Sakit": cs.sakit,
      "Total Izin": cs.izin
    })));
    XLSX.utils.book_append_sheet(wb, wsClassStats, "Rekap_Kelas");

    XLSX.writeFile(wb, `Rekap_Kehadiran_Skor_Kredit_Siswa_${filterBulan || 'Semua'}.xlsx`);
    showToast('Rekap Excel berhasil diunduh!');
  };

  const printRaporPDF = (student, size = 'A4', action = 'download') => {
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: size === 'A4' ? 'a4' : [215, 330]
    });

    const pageWidth = size === 'A4' ? 210 : 215;
    const studentName = student.name || student.nama || student.namaSiswa || "";
    const studentClass = student.class_name || student.kelas || "";
    const studentNis = student.nis || student.code || "";

    let yPos = 20;

    // Header Kop Surat
    if (appSettings.useKopSuratGambar && appSettings.kopSuratGambar) {
      doc.addImage(appSettings.kopSuratGambar, 'PNG', 15, 10, pageWidth - 30, 30);
      yPos = 46;
    } else if (appSettings.kopSuratLogo) {
      doc.addImage(appSettings.kopSuratLogo, 'PNG', 15, 10, 25, 25);
      doc.setFont("Helvetica", "bold");
      doc.setFontSize(10);
      doc.text(appSettings.kopSuratBaris1 || "", pageWidth / 2, 16, { align: "center" });
      doc.setFontSize(14);
      doc.text(appSettings.kopSuratBaris2 || "", pageWidth / 2, 22, { align: "center" });
      doc.setFontSize(18);
      doc.text(appSettings.kopSuratBaris3 || "", pageWidth / 2, 29, { align: "center" });
      doc.setLineWidth(1);
      doc.line(15, 38, pageWidth - 15, 38);
      doc.setLineWidth(0.1);
      yPos = 46;
    } else {
      yPos = 30;
    }

    doc.setFont("Helvetica", "bold");
    doc.setFontSize(14);
    doc.text("RAPOR KINERJA & KEDISIPLINAN SISWA", pageWidth / 2, yPos, { align: "center" });

    doc.setFontSize(10);
    doc.setFont("Helvetica", "normal");
    const yr = filterBulan ? filterBulan.substring(0, 4) : new Date().getFullYear();
    doc.text(`Tahun Ajaran: ${yr} / ${parseInt(yr) + 1}`, pageWidth / 2, yPos + 5, { align: "center" });
    if (!appSettings.kopSuratLogo && !appSettings.useKopSuratGambar) {
      doc.line(15, yPos + 8, pageWidth - 15, yPos + 8);
    }

    yPos += 16;

    // Student Info Block
    doc.setFont("Helvetica", "bold");
    doc.text("IDENTITAS SISWA", 15, yPos);
    doc.setFont("Helvetica", "normal");

    doc.text(`Nama Siswa`, 15, yPos + 6);
    doc.text(`: ${studentName}`, 45, yPos + 6);
    doc.text(`NIS`, 15, yPos + 11);
    doc.text(`: ${studentNis}`, 45, yPos + 11);

    const studentPoints = studentScores[studentNis] || 0;
    const finalScore = Math.max(0, 100 - studentPoints);

    doc.text(`Skor Awal: 100`, 15, yPos + 16);
    doc.text(`Poin Pelanggaran: ${studentPoints}`, 15, yPos + 21);

    doc.setFont("Helvetica", "bold");
    doc.text(`Total Skor Akhir: ${finalScore}`, 15, yPos + 26);
    doc.setFont("Helvetica", "normal");

    yPos += 36;

    // 1. Kehadiran Section
    doc.setFont("Helvetica", "bold");
    doc.text("I. REKAPITULASI KEHADIRAN", 15, yPos);
    doc.setFont("Helvetica", "normal");

    let sakit = 0, izin = 0, alpa = 0, hadir = 0;
    absensi.forEach(a => {
      if (a.siswa_nis === studentNis) {
        if (a.status === 'Sakit') sakit++;
        else if (a.status === 'Izin') izin++;
        else if (a.status === 'Alpa' || a.status === 'Belum Scan') alpa++;
        else hadir++;
      }
    });

    doc.rect(15, yPos + 4, pageWidth - 30, 16);
    doc.line(15, yPos + 12, pageWidth - 15, yPos + 12);

    const colWidth = (pageWidth - 30) / 4;
    doc.line(15 + colWidth, yPos + 4, 15 + colWidth, yPos + 20);
    doc.line(15 + colWidth * 2, yPos + 4, 15 + colWidth * 2, yPos + 20);
    doc.line(15 + colWidth * 3, yPos + 4, 15 + colWidth * 3, yPos + 20);

    doc.setFont("Helvetica", "bold");
    doc.text("Hadir", 15 + colWidth / 2, yPos + 9, { align: "center" });
    doc.text("Sakit", 15 + colWidth * 1.5, yPos + 9, { align: "center" });
    doc.text("Izin", 15 + colWidth * 2.5, yPos + 9, { align: "center" });
    doc.text("Alpa", 15 + colWidth * 3.5, yPos + 9, { align: "center" });

    doc.setFont("Helvetica", "normal");
    doc.text(`${hadir} hari`, 15 + colWidth / 2, yPos + 17, { align: "center" });
    doc.text(`${sakit} hari`, 15 + colWidth * 1.5, yPos + 17, { align: "center" });
    doc.text(`${izin} hari`, 15 + colWidth * 2.5, yPos + 17, { align: "center" });
    doc.text(`${alpa} hari`, 15 + colWidth * 3.5, yPos + 17, { align: "center" });

    yPos += 28;
    // 2. SKOR KREDIT
    doc.setFont("Helvetica", "bold");
    doc.text("II. SKOR KREDIT KEDISIPLINAN", 15, yPos);
    doc.setFont("Helvetica", "normal");

    const studentCases = riwayat.filter(r => r.siswa_nis === studentNis);
    let currentY = yPos + 4;

    doc.setFillColor(245, 245, 245);
    doc.rect(15, currentY, pageWidth - 30, 8, 'F');
    doc.rect(15, currentY, pageWidth - 30, 8, 'D');
    doc.setFont("Helvetica", "bold");
    doc.text("No", 18, currentY + 5.5);
    doc.text("Tanggal", 28, currentY + 5.5);
    doc.text("Tindakan Pelanggaran", 60, currentY + 5.5);
    doc.text("Poin", pageWidth - 25, currentY + 5.5, { align: "right" });

    currentY += 8;
    doc.setFont("Helvetica", "normal");

    studentCases.forEach((c, idx) => {
      const isPrestasi = c.jenis?.toLowerCase() === 'prestasi';
      doc.rect(15, currentY, pageWidth - 30, 8);
      doc.text(String(idx + 1), 18, currentY + 5.5);
      const dateStr = c.tanggal_kejadian ? new Date(c.tanggal_kejadian).toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' }) : "-";
      doc.text(dateStr, 28, currentY + 5.5);
      doc.text(String(c.tindakan_nama || c.tindakan || c.keterangan || (isPrestasi ? "Penghargaan Prestasi" : "Pelanggaran")).substring(0, 45), 60, currentY + 5.5);
      doc.text(isPrestasi ? `+${c.poin}` : `-${c.poin}`, pageWidth - 25, currentY + 5.5, { align: "right" });
      currentY += 8;
    });

    let curY = currentY;
    if (curY > (size === 'A4' ? 240 : 270)) {
      doc.addPage();
      curY = 20;
    }

    curY += 20;
    doc.text("Wali Kelas", 40, curY, { align: "center" });
    doc.text("Guru BK / Konselor", pageWidth - 40, curY, { align: "center" });

    curY += 20;
    doc.text("( ......................................... )", 40, curY, { align: "center" });
    doc.text("( ......................................... )", pageWidth - 40, curY, { align: "center" });

    if (action === 'download') {
      doc.save(`Rapor_Kinerja_${studentName.replace(/\s+/g, '_')}.pdf`);
      showToast('PDF berhasil diunduh!');
    } else {
      doc.autoPrint();
      window.open(doc.output('bloburl'), '_blank');
      showToast('Jendela cetak dibuka!');
    }
    setSelectedStudentForRapor(null);
  };

  return (
    <div className="space-y-4 relative animate-in fade-in duration-300">
      {/* Toolbar */}
      <div className="ui-card p-4 md:p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 relative">
        <div>
          <h3 className="font-bold text-slate-800 text-sm flex items-center gap-2">
            <FileSpreadsheet size={16} className="text-[var(--ui-primary)]" />
            Rekap Pelanggaran &amp; Absensi Siswa
          </h3>
          <p className="text-xs text-slate-500 font-medium mt-1">
            Ekspor rekapitulasi poin pelanggaran kesiswaan dan statistik kehadiran bulanan ke file Excel.
          </p>
        </div>
        <Button onClick={exportExcel} className="flex items-center gap-2 shrink-0">
          <Download size={14} /> Ekspor Excel
        </Button>
      </div>

      {/* Navigation Tabs */}
      <div className="flex border-b border-slate-200">
        <button
          type="button"
          onClick={() => setActiveSection('siswa')}
          className={`px-4 py-2 text-xs font-bold transition-all border-b-2 cursor-pointer ${
            activeSection === 'siswa' 
              ? 'border-[var(--ui-primary)] text-[var(--ui-primary)] font-black' 
              : 'border-transparent text-slate-500 hover:text-slate-800'
          }`}
        >
          Data Per Siswa
        </button>
        <button
          type="button"
          onClick={() => setActiveSection('kelas')}
          className={`px-4 py-2 text-xs font-bold transition-all border-b-2 cursor-pointer ${
            activeSection === 'kelas' 
              ? 'border-[var(--ui-primary)] text-[var(--ui-primary)] font-black' 
              : 'border-transparent text-slate-500 hover:text-slate-800'
          }`}
        >
          Data Per Kelas
        </button>
        <button
          type="button"
          onClick={() => setActiveSection('leaderboard')}
          className={`px-4 py-2 text-xs font-bold transition-all border-b-2 cursor-pointer ${
            activeSection === 'leaderboard' 
              ? 'border-[var(--ui-primary)] text-[var(--ui-primary)] font-black' 
              : 'border-transparent text-slate-500 hover:text-slate-800'
          }`}
        >
          Peringkat Pelanggaran (Leaderboard)
        </button>
      </div>

      {/* Filter Bar */}
      <div className="ui-card p-4 flex flex-col md:flex-row gap-4 items-center">
        <div className="relative flex-1 min-w-[180px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
          <input
            value={searchSiswa}
            onChange={e => setSearchSiswa(e.target.value)}
            placeholder="Cari nama / NIS siswa..."
            className="w-full pl-9 pr-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)]/30"
          />
        </div>
        <div>
          <input
            type="month"
            value={filterBulan}
            onChange={e => setFilterBulan(e.target.value)}
            className="px-3 py-2 bg-slate-50 border-none rounded-[var(--ui-radius-small)] text-sm font-semibold focus:outline-none"
          />
        </div>
        <div className="w-56">
          <CustomSelect
            options={[{ value: 'all', label: 'Semua Kelas' }, ...classes.map(c => ({ value: c.name, label: c.name }))]}
            value={filterKelas}
            onChange={setFilterKelas}
            placeholder="Filter Kelas"
          />
        </div>
        {isLoading && <span className="text-sm text-slate-400 font-medium animate-pulse">Memuat...</span>}
      </div>

      {/* ── TAB 1: DATA PER SISWA ── */}
      {activeSection === 'siswa' && (
        <div className="ui-card flex flex-col overflow-hidden">
          <div className="p-4 border-b border-slate-100 flex items-center gap-2 bg-slate-50/50">
            <Users size={18} className="text-[var(--ui-primary)]" />
            <h2 className="font-bold text-slate-800 flex-1">Data Kinerja & Skor Kredit Per Siswa</h2>
            <span className="text-xs text-slate-500">{filteredStudentsList.length} siswa</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-[11px] text-slate-500 uppercase bg-white border-b border-slate-150">
                <tr>
                  <th className="px-4 py-3 font-bold text-center w-12">No</th>
                  <th className="px-4 py-3 font-bold">Siswa</th>
                  <th className="px-4 py-3 font-bold text-center">Hadir</th>
                  <th className="px-4 py-3 font-bold text-center">Izin</th>
                  <th className="px-4 py-3 font-bold text-center">Sakit</th>
                  <th className="px-4 py-3 font-bold text-center">Alpa</th>
                  <th className="px-4 py-3 font-bold text-center">Skor Kredit</th>
                  <th className="px-4 py-3 font-bold text-center w-28">Rapor</th>
                </tr>
              </thead>
              <tbody>
                {filteredStudentsList.length === 0 ? (
                  <tr>
                    <td colSpan="8" className="text-center py-8 text-slate-400">
                      Siswa tidak ditemukan atau belum ada data.
                    </td>
                  </tr>
                ) : (
                  filteredStudentsList
                    .slice((siswaPage - 1) * siswaPerPage, siswaPage * siswaPerPage)
                    .map((s, idx) => {
                    const name = s.name || s.nama || s.namaSiswa || "";
                    const att = studentAttendance[s.nis] || { hadir: 0, sakit: 0, izin: 0, alpa: 0 };
                    const score = Math.max(0, 100 - (studentScores[s.nis] || 0));
                    const globalIdx = (siswaPage - 1) * siswaPerPage + idx;
                    return (
                      <tr key={s.nis} className="border-b border-slate-50 hover:bg-slate-50/50 transition-colors">
                        <td className="px-4 py-3 text-center text-slate-400 font-bold">{globalIdx + 1}</td>
                        <td className="px-4 py-3">
                          <p className="font-bold text-slate-800">{name}</p>
                          <p className="text-[10px] text-slate-450 font-bold">{s.nis} • {s.class_name || "-"}</p>
                        </td>
                        <td className="px-4 py-3 text-center font-bold text-emerald-600">{att.hadir}</td>
                        <td className="px-4 py-3 text-center font-bold text-blue-600">{att.izin}</td>
                        <td className="px-4 py-3 text-center font-bold text-amber-600">{att.sakit}</td>
                        <td className="px-4 py-3 text-center font-bold text-red-500">{att.alpa}</td>
                        <td className="px-4 py-3 text-center">
                          <span className={`px-2.5 py-1 rounded-[var(--ui-radius-small)] font-black text-xs ${
                            score >= 85 ? 'bg-emerald-50 text-emerald-700' : score >= 70 ? 'bg-amber-50 text-amber-700' : 'bg-red-50/60 text-red-600'
                          }`}>
                            {score} Poin
                          </span>
                        </td>
                        <td className="px-4 py-3 text-center">
                          <div className="flex gap-2 justify-center">
                            <Button variant="outline" size="sm" onClick={() => setSelectedStudentForRapor(s)} className="text-[11px] font-bold">
                              <FileText size={14} className="mr-1.5"/> Rapor PDF
                            </Button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
          <PaginationControls
            currentPage={siswaPage}
            totalItems={filteredStudentsList.length}
            itemsPerPage={siswaPerPage}
            onPageChange={setSiswaPage}
            onItemsPerPageChange={(v) => { setSiswaPerPage(v); setSiswaPage(1); }}
          />
        </div>
      )}

      {/* ── TAB 2: DATA PER KELAS ── */}
      {activeSection === 'kelas' && (
        <div className="ui-card flex flex-col overflow-hidden">
          <div className="p-4 border-b border-slate-100 flex items-center gap-2 bg-slate-50/50">
            <TrendingUp size={18} className="text-[var(--ui-primary)]" />
            <h2 className="font-bold text-slate-800">Statistik Pelanggaran &amp; Absensi Per Kelas</h2>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-[10px] text-slate-500 uppercase bg-white border-b border-slate-150">
                <tr>
                  <th className="px-4 py-3 font-bold">Kelas</th>
                  <th className="px-4 py-3 font-bold text-center text-red-600">Total Poin Pelanggaran</th>
                  <th className="px-4 py-3 font-bold text-center text-[var(--ui-primary)]">Rata-rata Skor Kredit</th>
                  <th className="px-4 py-3 font-bold text-center text-amber-600">Total Alpa</th>
                  <th className="px-4 py-3 font-bold text-center text-blue-600">Total Sakit</th>
                  <th className="px-4 py-3 font-bold text-center text-green-600">Total Izin</th>
                </tr>
              </thead>
              <tbody>
                {classStats.length === 0 ? (
                  <tr>
                    <td colSpan="6" className="text-center py-8 text-slate-400">
                      Tidak ada data kelas.
                    </td>
                  </tr>
                ) : (
                  classStats.map(cs => (
                    <tr key={cs.class_name} className="border-b border-slate-50 hover:bg-slate-50/50">
                      <td className="px-4 py-3 font-bold text-slate-800">{cs.class_name}</td>
                      <td className="px-4 py-3 text-center font-bold text-red-600 bg-red-50/20">{cs.poin}</td>
                      <td className="px-4 py-3 text-center font-black text-[var(--ui-primary)] bg-blue-50/20">{cs.avg_score} / 100</td>
                      <td className="px-4 py-3 text-center font-bold text-slate-600">{cs.alpa}</td>
                      <td className="px-4 py-3 text-center font-bold text-slate-600">{cs.sakit}</td>
                      <td className="px-4 py-3 text-center font-bold text-slate-600">{cs.izin}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ── TAB 3: LEADERBOARD ── */}
      {activeSection === 'leaderboard' && (
        <div className="ui-card flex flex-col overflow-hidden">
          <div className="p-4 border-b border-slate-100 flex items-center gap-2 bg-slate-50/50">
            <AlertOctagon size={18} className="text-red-500" />
            <h2 className="font-bold text-slate-800 flex-1">Top Siswa Pelanggaran Tertinggi</h2>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-[11px] text-slate-500 uppercase bg-white border-b border-slate-150">
                <tr>
                  <th className="px-4 py-3 font-bold text-center w-12">No</th>
                  <th className="px-4 py-3 font-bold">Siswa</th>
                  <th className="px-4 py-3 font-bold text-center">Total Poin</th>
                  <th className="px-4 py-3 font-bold text-center">Kasus</th>
                  <th className="px-4 py-3 font-bold text-center w-28">Rapor</th>
                </tr>
              </thead>
              <tbody>
                {leaderboard.length === 0 ? (
                  <tr>
                    <td colSpan="5" className="text-center py-8 text-slate-400">
                      Tidak ada data pelanggaran untuk filter ini.
                    </td>
                  </tr>
                ) : (
                  leaderboard
                    .slice((lbPage - 1) * lbPerPage, lbPage * lbPerPage)
                    .map((lb, idx) => {
                    const globalIdx = (lbPage - 1) * lbPerPage + idx;
                    return (
                    <tr key={lb.nis} className="border-b border-slate-50 hover:bg-slate-50/50">
                      <td className="px-4 py-3 text-center">
                        {!searchSiswa && globalIdx === 0 ? <Trophy size={16} className="text-amber-500 mx-auto" /> : <span className="text-slate-400 font-bold">{globalIdx + 1}</span>}
                      </td>
                      <td className="px-4 py-3">
                        <p className="font-bold text-slate-800">{lb.name}</p>
                        <p className="text-[10px] text-slate-500 font-semibold">{lb.class_name}</p>
                      </td>
                      <td className="px-4 py-3 text-center font-bold text-red-600">{lb.total_poin}</td>
                      <td className="px-4 py-3 text-center font-bold text-slate-600">{lb.kasus_count}</td>
                      <td className="px-4 py-3 text-center">
                        <div className="flex justify-center gap-2">
                          <button
                            onClick={() => setSelectedStudentForRapor(lb)}
                            className="flex items-center justify-center gap-1.5 px-2.5 py-1.5 bg-rose-50 text-rose-600 border border-rose-200 hover:bg-rose-100 rounded text-xs font-bold transition-all mx-auto cursor-pointer"
                          >
                            <Printer size={12} /> Cetak
                          </button>
                        </div>
                      </td>
                    </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
          <PaginationControls
            currentPage={lbPage}
            totalItems={leaderboard.length}
            itemsPerPage={lbPerPage}
            onPageChange={setLbPage}
            onItemsPerPageChange={(v) => { setLbPerPage(v); setLbPage(1); }}
          />
        </div>
      )}

      {/* Modal Cetak Rapor */}
      {selectedStudentForRapor && (
        <div className="fixed inset-0 z-[999] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-[var(--ui-radius-small)] shadow-lg w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-4 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-800 flex items-center gap-2">
                <FileText size={16} className="text-rose-500" />
                Cetak Rapor Kinerja Siswa
              </h3>
              <button type="button" onClick={() => setSelectedStudentForRapor(null)} className="text-slate-400 hover:text-slate-600 cursor-pointer">
                <X size={18} />
              </button>
            </div>
            <div className="p-4 space-y-4">
              <div className="p-3 bg-slate-50 rounded-lg text-xs space-y-1">
                <p className="text-slate-500 font-semibold">Nama Siswa:</p>
                <p className="font-bold text-slate-800 text-sm">{selectedStudentForRapor.name || selectedStudentForRapor.nama || selectedStudentForRapor.namaSiswa}</p>
                <p className="text-slate-600">Kelas: {selectedStudentForRapor.class_name || selectedStudentForRapor.kelas || "-"}</p>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 mb-2 uppercase tracking-wider">Pilih Ukuran Kertas</label>
                <div className="grid grid-cols-2 gap-3">
                  <button type="button" onClick={() => setRaporPaperSize('A4')}
                    className={`py-3 text-center rounded-[var(--ui-radius-small)] font-bold text-sm border transition-all cursor-pointer ${
                      raporPaperSize === 'A4' ? 'bg-rose-50 text-rose-600 border-rose-500' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                    }`}>
                    A4 (Standar)
                  </button>
                  <button type="button" onClick={() => setRaporPaperSize('F4')}
                    className={`py-3 text-center rounded-[var(--ui-radius-small)] font-bold text-sm border transition-all cursor-pointer ${
                      raporPaperSize === 'F4' ? 'bg-rose-50 text-rose-600 border-rose-500' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                    }`}>
                    F4 (Folio/HVS)
                  </button>
                </div>
              </div>
              <div className="pt-2 flex flex-col justify-end gap-2">
                <div className="flex gap-2 w-full">
                  <Button 
                    type="button" 
                    variant="outline"
                    onClick={() => printRaporPDF(selectedStudentForRapor, raporPaperSize, 'download')}
                    className="flex-1 text-[11px] bg-red-50 text-red-600 border-red-200 hover:bg-red-600 hover:text-white"
                  >
                    <Download size={14} className="mr-1.5"/> Unduh PDF
                  </Button>
                  <Button 
                    type="button" 
                    onClick={() => printRaporPDF(selectedStudentForRapor, raporPaperSize, 'print')}
                    className="flex-1 text-[11px] bg-[var(--ui-primary)] text-white hover:bg-[var(--ui-primary)]/90"
                  >
                    <Printer size={14} className="mr-1.5"/> Cetak
                  </Button>
                </div>
                <Button type="button" onClick={() => setSelectedStudentForRapor(null)} className="w-full bg-slate-100 text-slate-600 hover:bg-slate-200 border-none mt-1">
                  Batal
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'} z-[9999]`}>
          {toast.message}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useMemo, useCallback } from 'react';
import useAuthStore from '../../store/monitoring/authStore.js';
import * as XLSX from 'xlsx';
import { Trophy, FileSpreadsheet, Plus, Award, TrendingUp, Search, MapPin, Building, Calendar, Edit2, Trash2, AlertCircle, CheckCircle2 } from 'lucide-react';
import { Button } from '../../components/monitoring/ui/index.js';
import { CustomSelect } from '../../components/CustomSelect.jsx';
import { Modal } from '../../components/ui.jsx';


export default function RiwayatPrestasi({ students = [], classes = [] }) {
  const [prestasiList, setPrestasiList] = useState([]);
  const [search, setSearch] = useState("");
  const [filterTingkat, setFilterTingkat] = useState("all");
  const [filterKelas, setFilterKelas] = useState("all");

  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const [formData, setFormData] = useState({
    siswa_nis: "",
    nama_prestasi: "",
    peringkat: "",
    tingkat: "Kabupaten/Kota",
    penyelenggara: "",
    tanggal_prestasi: new Date().toISOString().slice(0, 10),
    keterangan: ""
  });

  const authToken = useAuthStore(state => state.user?.authToken);

  const fetchPrestasi = useCallback(async () => {
    if (!authToken) return;
    setIsLoading(true);
    try {
      const res = await fetch("/api/kesiswaan/prestasi", {
        headers: { "Authorization": `Bearer ${authToken}` }
      });
      const data = await res.json();
      if (data.ok) {
        setPrestasiList(data.data || []);
      }
    } catch (e) {
      console.error("Gagal mengambil data prestasi:", e);
    }
    setIsLoading(false);
  }, [authToken]);

  useEffect(() => {
    fetchPrestasi();
  }, [fetchPrestasi]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!authToken) return;
    try {
      const body = { ...formData };
      if (isEditing) {
        body.id = isEditing;
      }
      const res = await fetch("/api/kesiswaan/prestasi", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${authToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify(body)
      });
      if (res.ok) {
        showToast(isEditing ? 'Prestasi berhasil diperbarui!' : 'Prestasi berhasil dicatat!');
        setShowModal(false);
        setFormData({
          siswa_nis: "",
          nama_prestasi: "",
          peringkat: "",
          tingkat: "Kabupaten/Kota",
          penyelenggara: "",
          tanggal_prestasi: new Date().toISOString().slice(0, 10),
          keterangan: ""
        });
        setIsEditing(null);
        fetchPrestasi();
      } else {
        showToast('Gagal menyimpan data prestasi.', 'error');
      }
    } catch (e) {
      console.error(e);
    }
  };

  const handleEdit = (item) => {
    setIsEditing(item.id);
    setFormData({
      siswa_nis: item.siswa_nis,
      nama_prestasi: item.nama_prestasi,
      peringkat: item.peringkat || "",
      tingkat: item.tingkat || "Kabupaten/Kota",
      penyelenggara: item.penyelenggara || "",
      tanggal_prestasi: item.tanggal_prestasi ? item.tanggal_prestasi.slice(0, 10) : new Date().toISOString().slice(0, 10),
      keterangan: item.keterangan || ""
    });
    setShowModal(true);
  };

  const handleDelete = async (id) => {
    if (!await window.confirmAsync('Hapus data prestasi ini secara permanen?')) return;
    try {
      const res = await fetch("/api/kesiswaan/prestasi", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${authToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ action: "delete", id })
      });
      if (res.ok) {
        showToast('Prestasi berhasil dihapus.');
        fetchPrestasi();
      } else {
        showToast('Gagal menghapus data.', 'error');
      }
    } catch (e) {
      console.error(e);
      showToast('Terjadi kesalahan saat menghapus.', 'error');
    }
  };

  const getStudentInfo = useCallback((nis) => {
    const student = students.find(s => String(s.nis) === String(nis));
    return student ? {
      name: student.namaSiswa || student.name || 'Tidak Diketahui',
      class_name: student.class_name || '-'
    } : { name: 'Tidak Diketahui', class_name: '-' };
  }, [students]);

  const filteredPrestasi = useMemo(() => {
    return prestasiList.filter(item => {
      const sInfo = getStudentInfo(item.siswa_nis);
      const matchSearch = item.nama_prestasi.toLowerCase().includes(search.toLowerCase()) || 
                          sInfo.name.toLowerCase().includes(search.toLowerCase()) ||
                          String(item.siswa_nis).includes(search);
      const matchTingkat = filterTingkat === "all" || item.tingkat === filterTingkat;
      const matchKelas = filterKelas === "all" || sInfo.class_name === filterKelas;
      return matchSearch && matchTingkat && matchKelas;
    });
  }, [prestasiList, search, filterTingkat, filterKelas, getStudentInfo]);

  const stats = useMemo(() => {
    const total = prestasiList.length;
    const nasionalInternasional = prestasiList.filter(item => item.tingkat === "Nasional" || item.tingkat === "Internasional").length;

    const curMonth = new Date().toISOString().slice(0, 7); // YYYY-MM
    const bulanIni = prestasiList.filter(item => item.tanggal_prestasi && item.tanggal_prestasi.startsWith(curMonth)).length;

    return { total, nasionalInternasional, bulanIni };
  }, [prestasiList]);

  const exportExcel = () => {
    const data = filteredPrestasi.map((item, idx) => {
      const sInfo = getStudentInfo(item.siswa_nis);
      return {
        "No": idx + 1,
        "NIS": item.siswa_nis,
        "Nama Siswa": sInfo.name,
        "Kelas": sInfo.class_name,
        "Nama Prestasi": item.nama_prestasi,
        "Peringkat": item.peringkat,
        "Tingkat": item.tingkat,
        "Penyelenggara": item.penyelenggara,
        "Tanggal": item.tanggal_prestasi ? item.tanggal_prestasi.slice(0,10) : "",
        "Keterangan": item.keterangan
      };
    });
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Prestasi_Siswa");
    XLSX.writeFile(wb, `Riwayat_Prestasi_Siswa_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">

      {/* HEADER CARD */}
      <div className="ui-card flex flex-col md:flex-row justify-between items-start md:items-center gap-4 p-5">
        <div>
          <h3 className="font-bold text-slate-800 text-sm flex items-center gap-2">
            <Trophy size={18} className="text-amber-500" />
            Riwayat Prestasi & Penghargaan Siswa
          </h3>
          <p className="text-xs text-slate-500 font-medium mt-1">
            Catat dan dokumentasikan pencapaian siswa baik akademik maupun non-akademik di berbagai tingkatan.
          </p>
        </div>
        <div className="flex items-center gap-2 shrink-0 w-full md:w-auto justify-end">
          <button 
            onClick={exportExcel}
            className="flex items-center gap-2 px-4 py-2.5 bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 rounded-[var(--ui-radius-small)] font-bold text-xs shadow-sm cursor-pointer"
          >
            <FileSpreadsheet size={14}/> Export Laporan
          </button>
          <Button onClick={() => { setIsEditing(null); setShowModal(true); }} className="flex items-center gap-2">
            <Plus size={14}/> Tambah Prestasi
          </Button>
        </div>
      </div>

      {/* STAT CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="ui-card p-5 flex items-center gap-4 relative group">
          <div className="p-3 bg-amber-100 text-amber-600 rounded-[var(--ui-radius-small)]">
            <Trophy size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-0.5">Total Prestasi</p>
            <p className="text-2xl font-bold text-slate-800">{stats.total}</p>
            <p className="text-[11px] text-slate-400 font-medium">Seluruh tingkat kejuaraan</p>
          </div>
        </div>

        <div className="ui-card p-5 flex items-center gap-4 relative group">
          <div className="p-3 bg-emerald-100 text-emerald-600 rounded-[var(--ui-radius-small)]">
            <Award size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-0.5">Tingkat Nasional & Internasional</p>
            <p className="text-2xl font-bold text-slate-800">{stats.nasionalInternasional}</p>
            <p className="text-[11px] text-slate-400 font-medium">Kejuaraan skala besar</p>
          </div>
        </div>

        <div className="ui-card p-5 flex items-center gap-4 relative group">
          <div className="p-3 bg-blue-100 text-blue-600 rounded-[var(--ui-radius-small)]">
            <TrendingUp size={24} />
          </div>
          <div>
            <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-0.5">Prestasi Bulan Ini</p>
            <p className="text-2xl font-bold text-slate-800">{stats.bulanIni}</p>
            <p className="text-[11px] text-slate-400 font-medium">Bulan berjalan</p>
          </div>
        </div>
      </div>

      {/* FILTER & TABLE SECTION */}
      <div className="ui-card flex flex-col">

        {/* Filters */}
        <div className="p-4 border-b border-slate-100 flex flex-col md:flex-row gap-4 items-center bg-slate-50/50 rounded-t-[var(--ui-radius-card)]">
          <div className="relative flex-1 w-full md:w-auto">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input
              type="text"
              placeholder="Cari prestasi, nama siswa, atau NIS..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-white border-none rounded-[var(--ui-radius-small)] text-sm focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)]/20 transition-all font-medium"
            />
          </div>
          <div className="flex items-center gap-2 w-full md:w-auto">
            <CustomSelect
              options={[
                { value: 'all', label: 'Semua Tingkat' },
                { value: 'Kabupaten/Kota', label: 'Kabupaten/Kota' },
                { value: 'Provinsi', label: 'Provinsi' },
                { value: 'Nasional', label: 'Nasional' },
                { value: 'Internasional', label: 'Internasional' }
              ]}
              value={filterTingkat}
              onChange={setFilterTingkat}
              className="w-full md:w-48"
            />
            <CustomSelect
              options={[{ value: 'all', label: 'Semua Kelas' }, ...classes.map(c => ({ value: c.name, label: c.name }))]}
              value={filterKelas}
              onChange={setFilterKelas}
              className="w-full md:w-48"
            />
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 font-bold">Siswa & Kelas</th>
                <th className="px-6 py-4 font-bold">Nama Prestasi</th>
                <th className="px-6 py-4 font-bold text-center">Peringkat & Tingkat</th>
                <th className="px-6 py-4 font-bold">Penyelenggara & Tanggal</th>
                <th className="px-6 py-4 font-bold">Keterangan</th>
                <th className="px-6 py-4 font-bold text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr>
