    setTimeout(() => setToast(null), 3500);
  };

  // ──────────────────────────────────────────
  // Form handlers
  // ──────────────────────────────────────────
  const handleChange = (field, value) => {
    setForm((prev) => ({ ...prev, [field]: value }));
    if (errors[field]) setErrors((prev) => ({ ...prev, [field]: '' }));
  };

  const handlePhotoAdd = (e) => {
    const files = Array.from(e.target.files);
    if (photos.length + files.length > 5) {
      showToast('Maksimal 5 foto dokumentasi.', 'error');
      return;
    }
    const newPhotos = files.map((file) => ({
      id: Date.now() + Math.random(),
      file,
      preview: URL.createObjectURL(file),
    }));
    setPhotos((prev) => [...prev, ...newPhotos]);
  };

  const removePhoto = (id) => {
    setPhotos((prev) => {
      const removed = prev.find((p) => p.id === id);
      if (removed) URL.revokeObjectURL(removed.preview);
      return prev.filter((p) => p.id !== id);
    });
  };

  // ──────────────────────────────────────────
  // Validasi
  // ──────────────────────────────────────────
  const validate = () => {
    const errs = {};
    if (!form.kegiatan.trim() || form.kegiatan.trim().length < 20)
      errs.kegiatan = 'Deskripsi kegiatan minimal 20 karakter.';
    if (!form.kendala.trim())
      errs.kendala = 'Isi kolom kendala (tulis "Tidak ada" jika tidak ada).';
    if (!form.solusi.trim())
      errs.solusi = 'Isi kolom solusi.';
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const handleSubmit = async () => {
    if (!validate()) return;
    setIsSubmitting(true);
    try {
      const authToken = JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken;
      const res = await fetch('/api/pkl/logbooks/student', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${authToken}` },
        body: JSON.stringify(form)
      });
      const data = await res.json();
      if (data.ok) {
        setSubmitDone(true);
      } else {
        showToast(data.error || 'Gagal menyimpan logbook', 'error');
      }
    } catch {
      showToast('Terjadi kesalahan saat menyimpan', 'error');
    }
    setIsSubmitting(false);
  };

  // ──────────────────────────────────────────
  // Fitur Guard — blocked if disabled by admin
  // ──────────────────────────────────────────
  if (!isFiturAktif('jurnal')) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] px-6 text-center">
        <div className="w-20 h-20 rounded-full bg-slate-100 flex items-center justify-center mb-4">
          <Lock size={36} className="text-slate-400" />
        </div>
        <h2 className="text-xl font-extrabold text-slate-800 mb-2">Fitur Jurnal Dinonaktifkan</h2>
        <p className="text-sm text-slate-400 max-w-xs">
          Fitur jurnal sedang dinonaktifkan oleh Admin. Hubungi guru atau pihak sekolah untuk informasi lebih lanjut.
        </p>
      </div>
    );
  }

  // ──────────────────────────────────────────
  // Success State
  // ──────────────────────────────────────────
  if (submitDone) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] px-6 text-center">
        <div className="w-20 h-20 rounded-full bg-[var(--ui-primary)]/10 flex items-center justify-center mb-4">
          <CheckCircle2 size={40} className="text-[var(--ui-primary)]" />
        </div>
        <h2 className="text-xl font-extrabold text-slate-800 mb-2">Jurnal Tersimpan!</h2>
        <p className="text-sm text-slate-400 mb-4">
          Jurnal tanggal {new Date(form.tanggal).toLocaleDateString('id-ID', {
            day: 'numeric', month: 'long', year: 'numeric',
          })} berhasil dikirim.
        </p>
        <p className="text-xs text-slate-400 bg-amber-50 border border-amber-200 rounded-[var(--ui-radius-small)] px-4 py-3 max-w-xs">
          ⏳ Jurnal Anda sedang menunggu validasi dari Guru Pembimbing.
        </p>
        <button
          onClick={() => { setSubmitDone(false); setForm({ ...form, kegiatan: '', kendala: '', solusi: '' }); setPhotos([]); }}
          className="mt-6 text-sm font-semibold text-[var(--ui-primary)] hover:underline"
        >
          + Tulis Jurnal Lainnya
        </button>
      </div>
    );
  }

  return (
    <div className="px-4 pb-8 pt-4 max-w-3xl mx-auto w-full">
      {/* Header */}
      <div className="flex items-center gap-2.5 mb-5">
        <div className="w-10 h-10 bg-[var(--ui-primary)]/10 rounded-[var(--ui-radius-small)] flex items-center justify-center">
          <BookOpen size={20} className="text-[var(--ui-primary)]" />
        </div>
        <div>
          <h1 className="text-lg font-extrabold text-slate-800">Logbook Harian</h1>
          <p className="text-xs text-slate-400">Dokumentasikan kegiatan PKL Anda</p>
        </div>
      </div>

      <div className="space-y-4">
        {/* ─────── Tanggal & Jam ─────── */}
        <div className="bg-white border-none rounded-[var(--ui-radius-small)] p-4">
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">
            Waktu Kegiatan
          </p>
          <div className="grid grid-cols-3 gap-3">
            {/* Tanggal */}
            <div className="col-span-3">
              <label className="text-xs font-semibold text-gray-700 mb-1 flex items-center gap-1">
                <Calendar size={12} /> Tanggal
              </label>
              <input
                type="date"
                value={form.tanggal}
                max={todayStr}
                onChange={(e) => handleChange('tanggal', e.target.value)}
                className="w-full border-none rounded-[var(--ui-radius-small)] px-3 py-2.5 text-sm
                  focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)] focus:border-[var(--ui-primary)] transition-all"
              />
            </div>
            {/* Jam Masuk */}
            <div>
              <label className="text-xs font-semibold text-gray-700 mb-1 flex items-center gap-1">
                <Clock size={12} /> Jam Masuk
              </label>
              <input
                type="time"
                value={form.jamMasuk}
                onChange={(e) => handleChange('jamMasuk', e.target.value)}
                className="w-full border-none rounded-[var(--ui-radius-small)] px-3 py-2.5 text-sm
                  focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)] focus:border-[var(--ui-primary)] transition-all"
              />
            </div>
            {/* Jam Keluar */}
            <div className="col-span-2">
              <label className="text-xs font-semibold text-gray-700 mb-1 flex items-center gap-1">
                <Clock size={12} /> Jam Keluar
              </label>
              <input
                type="time"
                value={form.jamKeluar}
                onChange={(e) => handleChange('jamKeluar', e.target.value)}
                className="w-full border-none rounded-[var(--ui-radius-small)] px-3 py-2.5 text-sm
                  focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)] focus:border-[var(--ui-primary)] transition-all"
              />
            </div>
          </div>
        </div>

        {/* ─────── Deskripsi Kegiatan ─────── */}
        <div>
          <label className="text-sm font-bold text-slate-800 mb-1.5 block">
            Deskripsi Kegiatan Hari Ini *
          </label>
          <textarea
            rows={5}
            value={form.kegiatan}
            onChange={(e) => handleChange('kegiatan', e.target.value)}
            placeholder="Ceritakan secara detail kegiatan yang Anda lakukan hari ini. Contoh: Melakukan konfigurasi switch cisco, membantu instalasi server, dll..."
            className={`w-full border rounded-[var(--ui-radius-small)] px-4 py-3 text-sm resize-none
              focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)] transition-all
              ${errors.kegiatan ? 'border-danger bg-red-50' : 'border-slate-200'}`}
          />
          <div className="flex items-center justify-between mt-1">
            {errors.kegiatan ? (
              <p className="text-xs text-danger flex items-center gap-1">
                <AlertCircle size={11} /> {errors.kegiatan}
              </p>
            ) : (
              <p className="text-xs text-slate-400">{form.kegiatan.length} karakter</p>
            )}
            <p className="text-xs text-slate-400">Min. 20 karakter</p>
          </div>
        </div>

        {/* ─────── Kendala ─────── */}
        <div>
          <label className="text-sm font-bold text-slate-800 mb-1.5 block">
            Kendala yang Dihadapi *
          </label>
          <textarea
            rows={3}
            value={form.kendala}
            onChange={(e) => handleChange('kendala', e.target.value)}
            placeholder="Tuliskan kendala atau hambatan. Jika tidak ada, tulis 'Tidak ada kendala'."
            className={`w-full border rounded-[var(--ui-radius-small)] px-4 py-3 text-sm resize-none
              focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)] transition-all
              ${errors.kendala ? 'border-danger bg-red-50' : 'border-slate-200'}`}
          />
          {errors.kendala && (
            <p className="text-xs text-danger mt-1 flex items-center gap-1">
              <AlertCircle size={11} /> {errors.kendala}
            </p>
          )}
        </div>

        {/* ─────── Solusi ─────── */}
        <div>
          <label className="text-sm font-bold text-slate-800 mb-1.5 block">
            Solusi / Tindakan *
          </label>
          <textarea
            rows={3}
            value={form.solusi}
            onChange={(e) => handleChange('solusi', e.target.value)}
            placeholder="Bagaimana Anda mengatasi kendala di atas?"
            className={`w-full border rounded-[var(--ui-radius-small)] px-4 py-3 text-sm resize-none
              focus:outline-none focus:ring-2 focus:ring-[var(--ui-primary)] transition-all
              ${errors.solusi ? 'border-danger bg-red-50' : 'border-slate-200'}`}
          />
          {errors.solusi && (
            <p className="text-xs text-danger mt-1 flex items-center gap-1">
              <AlertCircle size={11} /> {errors.solusi}
            </p>
          )}
        </div>

        {/* ─────── Upload Foto Dokumentasi ─────── */}
        <div>
          <label className="text-sm font-bold text-slate-800 mb-1.5 block">
            Foto Dokumentasi{' '}
            <span className="text-slate-400 font-normal">(Opsional, maks 5 foto)</span>
          </label>

          {/* Photo grid */}
          {photos.length > 0 && (
            <div className="grid grid-cols-3 gap-2 mb-3">
              {photos.map((p) => (
                <div key={p.id} className="relative aspect-square">
                  <img
                    src={p.preview}
                    alt="dokumentasi"
                    className="w-full h-full object-cover rounded-[var(--ui-radius-small)]"
                  />
                  <button
                    onClick={() => removePhoto(p.id)}
                    className="absolute top-1 right-1 w-5 h-5 bg-black/60 rounded-full
                      flex items-center justify-center hover:bg-black/80 transition-colors"
                  >
                    <X size={11} className="text-white" />
                  </button>
                </div>
              ))}

              {/* Add more button (if less than 5) */}
              {photos.length < 5 && (
                <label className="aspect-square border-2 border-dashed border-slate-200 rounded-[var(--ui-radius-small)] flex flex-col items-center justify-center cursor-pointer
                  hover:border-[var(--ui-primary)] hover:bg-[var(--ui-primary)]/10 transition-all">
                  <input
                    type="file"
                    accept="image/*"
                    multiple
                    className="hidden"
                    onChange={handlePhotoAdd}
                  />
                  <ImagePlus size={20} className="text-gray-400 mb-1" />
                  <span className="text-[10px] text-slate-400">Tambah</span>
                </label>
              )}
            </div>
          )}

          {photos.length === 0 && (
            <label className="block cursor-pointer">
              <input
                type="file"
                accept="image/*"
                multiple
                className="hidden"
                onChange={handlePhotoAdd}
              />
              <div className="border-2 border-dashed border-slate-200 rounded-[var(--ui-radius-small)] p-8
                flex flex-col items-center justify-center text-center
                hover:border-[var(--ui-primary)] hover:bg-[var(--ui-primary)]/10 transition-all">
                <ImagePlus size={28} className="text-gray-400 mb-2" />
                <p className="text-sm font-medium text-gray-600">Tambahkan foto dokumentasi</p>
                <p className="text-xs text-slate-400 mt-0.5">Klik untuk memilih foto</p>
              </div>
            </label>
          )}
        </div>

        {/* ─────── Submit ─────── */}
        <button
          onClick={handleSubmit}
          disabled={isSubmitting}
          className={`w-full py-4 rounded-[var(--ui-radius-small)] font-extrabold text-base flex items-center
            justify-center gap-2 transition-all duration-200 mt-2
            ${isSubmitting
              ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
              : 'bg-gradient-to-r from-[var(--ui-primary)] to-[var(--ui-primary)] text-white shadow-md active:scale-95 hover:shadow-2xl'
            }`}
        >
          {isSubmitting ? (
            <><Loader2 size={18} className="animate-spin" /> Menyimpan Jurnal...</>
          ) : (
            <><CheckCircle2 size={18} /> Kirim Jurnal Hari Ini</>
          )}
        </button>
      </div>

      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle2 size={18} />} {toast.message}
        </div>
      )}
    </div>
  );
};

export default Logbook;

import { useState, useEffect, useCallback } from 'react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { PageHeader, EmptyState, StatCard } from '../../../components/monitoring/ui/index.js';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import useAuthStore from '../../../store/monitoring/authStore';
import { Loader2, CheckCircle2, Circle, Edit3, AlertCircle, Info, Navigation } from 'lucide-react';


/**
 * student/LokasiPKL.jsx
 * Siswa mengatur lokasi PKL mereka. Data disimpan di PostgreSQL melalui API.
 */





const PANDUAN_PENAMAAN = { format: "Contoh: PT. Nama Perusahaan - Nama Divisi/Cabang (jika ada)" };

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png',
});

const LokasiPKL = () => {
  const { user } = useAuthStore();
  const [lokasiAktif, setLokasiAktif] = useState(null);
  const [updateCount, setUpdateCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [coords, setCoords] = useState(null);
  const [namaLokasi, setNamaLokasi] = useState('');
  const [gettingGPS, setGettingGPS] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const fetchLokasi = useCallback(async () => {
    setLoading(true);
    try {
      const authToken = JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken;
      const res = await fetch('/api/monitoring/pkl-students', {
        headers: { 'Authorization': `Bearer ${authToken}` }
      });
      const data = await res.json();
      if (data.ok) {
        const me = data.data.find(s => s.nis === user?.username || s.nis === user?.nis);
        if (me && me.location_id) {
          setUpdateCount(me.location_update_count || 0);
          const locRes = await fetch('/api/pkl/locations');
          const locData = await locRes.json();
          if (locData.ok) {
            const loc = locData.data.find(l => l.id === me.location_id);
            if (loc) {
              setLokasiAktif({
                namaLokasi: loc.nama_perusahaan,
                lat: parseFloat(loc.lat),
                lng: parseFloat(loc.lng)
              });
              setShowForm(false);
            }
          }
        } else {
          setLokasiAktif(null);
          setShowForm(true);
        }
      }
    } catch (err) {
      console.error(err);
    }
    setLoading(false);
  }, [user]);

  useEffect(() => {
    if (user) {
      Promise.resolve().then(() => fetchLokasi());
    }
  }, [user, fetchLokasi]);

  const handleGetGPS = () => {
    setGettingGPS(true);
    if (!navigator.geolocation) {
      setGettingGPS(false);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        setGettingGPS(false);
      },
      () => {
        setGettingGPS(false);
      },
      { enableHighAccuracy: true }
    );
  };

  const namaValid = namaLokasi.trim().length >= 10;
  const canSubmit = coords && namaValid;

  const handleSubmit = async () => {
    if (!canSubmit) return;
    setSubmitting(true);
    try {
      const authToken = JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken;
      const res = await fetch('/api/pkl/student/location', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${authToken}` },
        body: JSON.stringify({ namaLokasi, lat: coords.lat, lng: coords.lng })
      });
      const data = await res.json();
      if (data.ok) {
        setDone(true);
        fetchLokasi();
      } else {
        showToast(data.error || 'Gagal menyimpan', 'error');
      }
    } catch {
      showToast('Terjadi kesalahan sistem', 'error');
    }
    setSubmitting(false);
  };

  if (loading) return <div className="p-8 flex justify-center"><Loader2 className="animate-spin text-slate-400" /></div>;

  return (
    <div className="p-4 md:p-0 space-y-4 md:space-y-6 max-w-3xl mx-auto w-full">
      <div>
        <h1 className="text-xl font-extrabold text-slate-800">Lokasi PKL Saya</h1>
        <p className="text-xs text-slate-400 mt-0.5">Atur dan perbarui lokasi tempat Anda menjalani PKL</p>
      </div>

      {lokasiAktif && (
        <div className="rounded-[var(--ui-radius-small)] border p-4 bg-[var(--ui-primary)]/10 border-[var(--ui-primary)]">
          <div className="flex items-start gap-3">
            <div className="w-9 h-9 rounded-[var(--ui-radius-small)] flex items-center justify-center flex-shrink-0 bg-[var(--ui-primary)]">
              <CheckCircle2 size={18} className="text-white" />
            </div>
            <div className="flex-1">
              <p className="font-bold text-sm mb-0.5 text-[var(--ui-primary)]">Lokasi Aktif</p>
              <p className="text-xs font-semibold text-slate-800 leading-snug">{lokasiAktif.namaLokasi}</p>
              <p className="text-[10px] text-slate-400 mt-1 font-mono">
                {lokasiAktif.lat.toFixed(5)}, {lokasiAktif.lng.toFixed(5)}
              </p>
            </div>
          </div>
          <div className="mt-3 rounded-[var(--ui-radius-small)] overflow-hidden h-36">
            <MapContainer center={[lokasiAktif.lat, lokasiAktif.lng]} zoom={15}
              style={{ height: '100%', width: '100%' }}
              scrollWheelZoom={false} zoomControl={false} dragging={false}>
              <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
              <Marker position={[lokasiAktif.lat, lokasiAktif.lng]} />
              <Circle center={[lokasiAktif.lat, lokasiAktif.lng]} radius={150}
                pathOptions={{ color: '#15803d', fillColor: '#15803d', fillOpacity: 0.1 }} />
            </MapContainer>
          </div>
        </div>
      )}

      {done && (
        <div className="flex items-center gap-3 bg-emerald-50 border border-emerald-200 rounded-[var(--ui-radius-small)] p-4">
          <CheckCircle2 size={18} className="text-emerald-600 flex-shrink-0" />
          <p className="text-sm font-semibold text-emerald-800">Lokasi berhasil disimpan!</p>
        </div>
      )}

      {!done && (
        <>
          {!showForm ? (
            <div className="space-y-3">
              <button onClick={() => setShowForm(true)} disabled={updateCount >= 2}
                className={`w-full flex items-center justify-center gap-2 py-3.5 text-white font-bold rounded-[var(--ui-radius-small)] transition-all shadow-sm active:scale-95 ${
                  updateCount >= 2 ? 'bg-slate-300 cursor-not-allowed' : 'bg-[var(--ui-primary)] hover:opacity-90'
                }`}>
                <Edit3 size={18} />
                Perbarui Lokasi GPS
              </button>
              {updateCount >= 2 && (
                <div className="bg-red-50 border border-red-200 text-red-700 text-xs px-3 py-2.5 rounded-[var(--ui-radius-small)] font-medium flex items-start gap-2">
                  <AlertCircle size={15} className="mt-0.5 shrink-0" />
                  Anda sudah mencapai batas maksimal (2x) mengubah lokasi. Hubungi Admin/Guru jika perlu memperbarui lokasi lagi.
                </div>
              )}
              {updateCount > 0 && updateCount < 2 && (
                <p className="text-[10px] text-center text-slate-400 font-medium">Anda memiliki sisa {2 - updateCount} kali kesempatan update lokasi.</p>
              )}
            </div>
          ) : (
            <div className="space-y-4 bg-white border-none rounded-[var(--ui-radius-small)] p-4">
              <div className="bg-sky-50 border border-sky-200 rounded-[var(--ui-radius-small)] p-3">
                <p className="text-xs font-bold text-sky-800 mb-1.5 flex items-center gap-1">
                  <Info size={12} /> Panduan Penamaan Lokasi
                </p>
                <p className="text-[10px] text-sky-700 font-mono mb-2">{PANDUAN_PENAMAAN.format}</p>
              </div>

              <div>
                <p className="text-sm font-bold text-slate-800 mb-2">1. Ambil Koordinat GPS</p>
                <button onClick={handleGetGPS} disabled={gettingGPS}
                  className={`w-full flex items-center justify-center gap-2 py-3 rounded-[var(--ui-radius-small)] text-sm font-bold
                    transition-all active:scale-95 ${coords
                      ? 'bg-emerald-50 border-2 border-emerald-400 text-emerald-700'
                      : 'bg-[var(--ui-primary)] text-white hover:opacity-90'
                    } disabled:opacity-60`}>
                  {gettingGPS ? <Loader2 size={16} className="animate-spin" /> :
                    coords ? <CheckCircle2 size={16} /> : <Navigation size={16} />}
                  {gettingGPS ? 'Mencari...' : coords ? 'Koordinat didapat' : 'Dapatkan Lokasi GPS'}
                </button>
              </div>

              <div>
                <p className="text-sm font-bold text-slate-800 mb-1.5">2. Nama Lokasi</p>
                <textarea rows={3} value={namaLokasi} onChange={e => setNamaLokasi(e.target.value)}
                  placeholder="PT Nama Perusahaan - Divisi/Departemen - Kota/Area"
                  className={`w-full border rounded-[var(--ui-radius-small)] px-3 py-2.5 text-sm resize-none
