const ValidasiJurnal = () => {
  const [filterStatus, setFilterStatus] = useState('pending');
  const [rejectModal, setRejectModal] = useState(null);
  const [jurnalList, setJurnalList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  useEffect(() => {
    fetch('/api/pkl/logbooks', {
      headers: { 'Authorization': `Bearer ${JSON.parse(sessionStorage.getItem('school_schedule_session_v1'))?.authToken}` }
    })
    .then(res => res.json())
    .then(data => {
      if(data.ok) setJurnalList(data.data);
      setLoading(false);
    })
    .catch(() => setLoading(false));
  }, []);

  const filtered = jurnalList.filter(j =>
    filterStatus === 'all' ? true : j.status === filterStatus
  );

  const pendingCount = jurnalList.filter(j => j.status === 'pending').length;

  const handleRejectClick = (jurnal, siswa, callback) => {
    setRejectModal({ jurnal, siswa, callback });
  };

  const handleRejectConfirm = (catatan) => {
    rejectModal?.callback?.(catatan);
    setRejectModal(null);
  };

  return (
    <div className="space-y-5">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-slate-800">Validasi Jurnal</h1>
        <p className="text-sm text-slate-400 mt-1">
          {loading ? 'Memuat jurnal...' : pendingCount > 0
            ? `${pendingCount} jurnal menunggu validasi Anda`
            : 'Semua jurnal sudah divalidasi 🎉'}
        </p>
      </div>

      {/* Filter tabs */}
      <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar">
        {[
          { key: 'pending', label: 'Pending', count: jurnalList.filter((j) => j.status === 'pending').length },
          { key: 'approved', label: 'Disetujui', count: jurnalList.filter((j) => j.status === 'approved').length },
          { key: 'revision', label: 'Revisi', count: jurnalList.filter((j) => j.status === 'revision').length },
          { key: 'all', label: 'Semua', count: jurnalList.length },
        ].map((tab) => (
          <button
            key={tab.key}
            onClick={() => setFilterStatus(tab.key)}
            className={[
              'flex items-center gap-2 px-4 py-2 rounded-[var(--ui-radius-card)] text-sm font-semibold whitespace-nowrap',
              'transition-all duration-150',
              filterStatus === tab.key
                ? 'bg-[var(--ui-primary)] text-white shadow-sm'
                : 'bg-white border-none text-gray-600 hover:border-[var(--ui-primary)] hover:text-[var(--ui-primary)]',
            ].join(' ')}
          >
            {tab.label}
            {tab.count > 0 && (
              <span className={`text-xs px-1.5 py-0.5 rounded-[var(--ui-radius-small)] font-bold
                ${filterStatus === tab.key ? 'bg-white/20 text-white' : 'bg-gray-100 text-gray-600'}`}>
                {tab.count}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Jurnal list */}
      <div className="space-y-3">
        {filtered.length === 0 ? (
          <EmptyState
            icon={BookOpen}
            title="Tidak ada jurnal"
            description={`Belum ada jurnal dengan status "${filterStatus}" saat ini.`}
          />
        ) : (
          filtered.map((j) => {
            const siswaObj = {
              nama: j.student_name || `Siswa ${j.student_nis || ""}`,
              kelas: j.class_name || "-"
            };
            return (
              <JurnalCard
                key={j.id}
                jurnal={j}
                siswa={siswaObj}
                showToast={showToast}
                onApprove={(id) => {
                  setJurnalList(prev => prev.map(item => item.id === id ? { ...item, status: 'approved' } : item));
                }}
                onReject={(jurnalItem, siswaItem, cb) => handleRejectClick(jurnalItem, siswaItem, cb)}
                onRejectSuccess={(id, catatan) => {
                  setJurnalList(prev => prev.map(item => item.id === id ? { ...item, status: 'revision', catatanGuru: catatan } : item));
                }}
              />
            );
          })
        )}
      </div>

      {/* Reject Modal */}
      {rejectModal && (
        <RejectModal
          jurnal={rejectModal.jurnal}
          siswa={rejectModal.siswa}
          onConfirm={handleRejectConfirm}
          onCancel={() => setRejectModal(null)}
        />
      )}
      {toast && (
        <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-[var(--ui-radius-small)] shadow-lg font-medium text-sm flex items-center gap-2 animate-in slide-in-from-bottom-5 text-white z-[100] ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
          {toast.message}
        </div>
      )}
    </div>
  );
};

export default ValidasiJurnal;

import { create } from 'zustand';

/**
 * authStore.js (Monitoring)
 * Reads from the shared unified session (sessionStorage 'school_schedule_session_v1').
 * Login/logout is handled by the central LandingPage — this store is read-only.
 */


const SESSION_KEY = 'school_schedule_session_v1';

const readSession = () => {
  try {
    const raw = sessionStorage.getItem(SESSION_KEY);
    const session = raw ? JSON.parse(raw) : null;
    if (session?.authToken && session?.role) return session;
    return null;
  } catch {
    return null;
  }
};

const useAuthStore = create((set, get) => ({
  user: readSession(),
  isLoggedIn: !!readSession(),

  // Sync from sessionStorage (call on mount)
  syncSession: () => {
    const session = readSession();
    set({ user: session, isLoggedIn: !!session });
  },

  logout: () => {
    sessionStorage.removeItem(SESSION_KEY);
    localStorage.removeItem(SESSION_KEY);
    set({ user: null, isLoggedIn: false });
    window.location.href = '/';
  },
}));

export default useAuthStore;

const PBKDF2_PREFIX = "pbkdf2-sha256:";
const LEGACY_SHA256_PREFIX = "sha256:";
const PBKDF2_ITERATIONS = 120000;
const textEncoder = new TextEncoder();

const toHex = (buffer) => Array.from(new Uint8Array(buffer), (byte) => byte.toString(16).padStart(2, "0")).join("");
const fromHex = (hex) => {
  const clean = String(hex || "").replace(/[^0-9a-f]/gi, "");
  const bytes = new Uint8Array(clean.length / 2);
  for (let i = 0; i < bytes.length; i += 1) {
    bytes[i] = Number.parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return bytes;
};

const getCrypto = () => {
  if (typeof globalThis !== "undefined" && globalThis.crypto) return globalThis.crypto;
  if (typeof window !== "undefined" && window.crypto) return window.crypto;
  if (typeof globalThis !== "undefined" && globalThis.process && globalThis.process.versions && globalThis.process.versions.node) {
    try {
      const req = new Function("return require")();
      const crypto = req("crypto");
      return crypto.webcrypto || crypto;
    } catch (e) {
      // ignore require failure in non-node envs
    }
  }
  return null;
};

const createSalt = () => {
  const salt = new Uint8Array(16);
  const cryptoObj = getCrypto();
  if (cryptoObj && typeof cryptoObj.getRandomValues === "function") {
    cryptoObj.getRandomValues(salt);
  } else {
    for (let i = 0; i < salt.length; i++) {
      salt[i] = Math.floor(Math.random() * 256);
    }
  }
  return toHex(salt);
};

export const isHashedPassword = (value) => typeof value === "string" && value.startsWith(LEGACY_SHA256_PREFIX) && value.length > LEGACY_SHA256_PREFIX.length;
const isPbkdf2Password = (value) => typeof value === "string" && value.startsWith(PBKDF2_PREFIX);
const isAnyPasswordHash = (value) => isHashedPassword(value) || isPbkdf2Password(value);

export const hashPassword = async (value) => {
  const plain = String(value ?? "");
  const cryptoObj = getCrypto();
  if (!cryptoObj || !cryptoObj.subtle) {
    console.warn("crypto.subtle not available. Using plaintext fallback.");
    return plain;
  }
  const saltHex = createSalt();
  const saltBytes = fromHex(saltHex);
  const key = await cryptoObj.subtle.importKey("raw", textEncoder.encode(plain), "PBKDF2", false, ["deriveBits"]);
  const derivedBits = await cryptoObj.subtle.deriveBits(
    { name: "PBKDF2", salt: saltBytes, iterations: PBKDF2_ITERATIONS, hash: "SHA-256" },
    key,
    256
  );
  return `${PBKDF2_PREFIX}${PBKDF2_ITERATIONS}:${saltHex}:${toHex(derivedBits)}`;
};

const verifyLegacyPassword = async (plain, stored) => {
  const cryptoObj = getCrypto();
  if (!cryptoObj || !cryptoObj.subtle) return false;
  const digest = await cryptoObj.subtle.digest("SHA-256", textEncoder.encode(String(plain ?? "")));
  return `${LEGACY_SHA256_PREFIX}${toHex(digest)}` === stored;
};

const verifyPbkdf2Password = async (plain, stored) => {
  const cryptoObj = getCrypto();
  if (!cryptoObj || !cryptoObj.subtle) return false;
  const [, iterationsRaw, saltHex, hashHex] = String(stored || "").split(":");
  const iterations = Number.parseInt(iterationsRaw, 10);
  if (!iterations || !saltHex || !hashHex) return false;
  const key = await cryptoObj.subtle.importKey("raw", textEncoder.encode(String(plain ?? "")), "PBKDF2", false, ["deriveBits"]);
  const derivedBits = await cryptoObj.subtle.deriveBits(
    { name: "PBKDF2", salt: fromHex(saltHex), iterations, hash: "SHA-256" },
    key,
    256
  );
  return toHex(derivedBits) === hashHex;
};

export const verifyPassword = async (plain, stored) => {
  const safeStored = String(stored ?? "");
  const cryptoObj = getCrypto();
  try {
    if (isPbkdf2Password(safeStored)) {
      if (!cryptoObj || !cryptoObj.subtle) {
        console.warn("crypto.subtle not available for PBKDF2 verification.");
        return false;
      }
      return await verifyPbkdf2Password(plain, safeStored);
    }
    if (isHashedPassword(safeStored)) {
      if (!cryptoObj || !cryptoObj.subtle) {
        console.warn("crypto.subtle not available for SHA-256 verification.");
        return false;
      }
      return await verifyLegacyPassword(plain, safeStored);
    }
  } catch (error) {
    console.error("Password verification failed:", error);
    return false;
  }
  return String(plain ?? "") === safeStored;
};

export const normalizeAdminUser = async (adminUser) => {
  const next = { ...adminUser };
  if (next.password && !isAnyPasswordHash(next.password)) next.password = await hashPassword(next.password);
  return next;
};

export const normalizeTeachers = async (teachers) => {
  const next = [];
  for (const teacher of teachers || []) {
    const item = { ...teacher };
    if (item.password && !isAnyPasswordHash(item.password)) item.password = await hashPassword(item.password);
    next.push(item);
  }
  return next;
};

