        return;
      }
      if (needsPhoto && !hasFeature("attendancePhoto")) {
        setPhotoError("Mode selfie sedang dinonaktifkan oleh admin.");
        return;
      }
      if (needsLocation) {
        if (!teacherLocation) {
          setLocationError("Lokasi belum ditemukan! Aktifkan GPS dan coba lagi.");
          return;
