      if (payload.schedule?.length) setSchedule(prev => mergeUniqueByKey(prev, payload.schedule, item => `${item.day}__${item.slotId}__${item.className}__${item.teacherCode || ""}__${item.subject || ""}`));
    } else if (type === "mapel") {
