        assignedSlot = slotsByFloor[targetFloor][pointerByFloor[targetFloor]++];
      } else {
        for (let f of ["1", "2", "3"]) {
          if (slotsByFloor[f] && pointerByFloor[f] < slotsByFloor[f].length) {
